(window.GIM_TP=window.GIM_TP||{})["Taanit.0"]={"from":0,"a":[[["מתני׳ \u0001מאימתי\u0002 מזכירין גבורות גשמים רבי אליעזר אומר מיום טוב הראשון של חג ר' יהושע אומר מיום טוב האחרון של חג","אמר לו ר' יהושע הואיל ואין הגשמים אלא סימן קללה בחג למה הוא מזכיר אמר לו ר' אליעזר אף אני לא אמרתי לשאול אלא להזכיר משיב הרוח ומוריד הגשם בעונתו אמר לו א\"כ לעולם יהא מזכיר","אין שואלין את הגשמים אלא סמוך לגשמים ר' יהודה אומר העובר לפני התיבה ביו\"ט האחרון של חג האחרון מזכיר הראשון אינו מזכיר ביו\"ט הראשון של פסח הראשון מזכיר האחרון אינו מזכיר","\u0001גמ׳\u0002 תנא היכא קאי דקתני מאימתי תנא התם קאי","דקתני מזכירין גבורות גשמים בתחיית המתים ושואלין בברכת השנים והבדלה בחונן הדעת וקתני מאימתי מזכירין גבורות גשמים","וליתני התם מ\"ש דשבקיה עד הכא","אלא תנא מראש השנה סליק דתנן ובחג נידונין על המים ואיידי דתנא ובחג נידונין על המים תנא מאימתי מזכירין גבורות גשמים","וליתני מאימתי מזכירין על הגשמים מאי גבורות גשמים א\"ר יוחנן מפני שיורדין בגבורה שנאמר (איוב ה, ט) עושה גדולות עד אין חקר ונפלאות עד אין מספר וכתיב (איוב ה, י) הנותן מטר על פני ארץ ושולח מים על פני חוצות","מאי משמע אמר רבה בר שילא אתיא חקר חקר מברייתו של עולם","כתיב הכא עושה גדולות עד אין חקר וכתיב התם (ישעיהו מ, כח) הלא ידעת אם לא שמעת אלהי עולם ה' בורא קצות הארץ לא ייעף ולא ייגע אין חקר לתבונתו וכתיב (תהלים סה, ז) מכין הרים בכחו נאזר בגבורה","ומנא לן דבתפלה דתניא (דברים יא, יג) לאהבה את ה' אלהיכם ולעבדו בכל לבבכם איזו היא עבודה שהיא בלב הוי אומר זו תפלה וכתיב בתריה (דברים יא, יד) ונתתי מטר ארצכם בעתו יורה ומלקוש","אמר ר' יוחנן ג' מפתחות בידו של הקב\"ה שלא נמסרו ביד שליח ואלו הן מפתח של גשמים מפתח של חיה מפתח של תחיית המתים","מפתח של גשמים דכתיב (דברים כח, יב) יפתח ה' לך את אוצרו הטוב את השמים לתת מטר ארצך בעתו מפתח של חיה מנין דכתיב ויזכור אלהים את רחל וישמע"],[[0,"מתני' מאימתי מזכירין גבורות גשמים","שאומר משיב הרוח ומוריד הגשם ובגמרא מפרש טעמא אמאי קרי ליה גבורות גשמים מפני שיורדין בגבורה שנאמר עושה גדולות וגו':"],[1,"סימן קללה בחג הן","כדאמרינן במס' סוכה בפרק הישן (סוכה דף כח:) מאימתי מותר לפנות משתסרח המקפה משל לעבד שבא למזוג כוס לרבו ושפך לו קיתון על פניו וא\"ל אי אפשי בשמושך כלומר כשהגשמים יורדין לסוכה הכל יוצאין ונראה שאין הקב\"ה חפץ שנשתמש לפניו ואמאי מתחילין להזכיר גבורות גשמים בחג ונראה שהוא מתפלל שיבא מטר בחג:"],[1,"לא אמרתי לשאול","שיתפלל על הגשמים בחג כגון ותן טל ומטר:"],[1,"אלא להזכיר","שמתחיל להזכיר בחג גבורות של מקום שמוריד גשמים:"],[1,"בעונתו","כלומר בזמנו:"],[1,"אם כן","ואמאי פוסק בפסח מלהזכיר:"],[3,"גמ' תנא היכא קאי","כלומר מדקתני מאימתי מכלל דפשיטא ליה להאי תנא דחייבים להזכיר והיכא חזינן דמחייב להזכיר:"],[3,"התם קאי","מזכירין גבורות גשמים כו' במסכת ברכות:"],[5,"(וליתני התם","במסכת ברכות סמוך דתני מזכירין ליתני מאימתי):"],[5,"מ\"ש דשבקיה עד הכא","כלומר האי דקתני הכא בסדר מועד מאימתי ליתני התם דקתני מזכירין במסכת ברכות היינו סדר זרעים:"],[5,"עד הכא","עד סדר מועד:"],[6,"אלא","לא תימא דהא דקתני מאימתי דהתם קאי דתנא מראש השנה סליק ששניהן בסדר אחד הן להכי לא מצי למימר מאי שנא דשבקיה עד הכא:"],[6,"(בחג","הוי דין על המים ומשום דתני מאימתי הוי דין על המים קתני נמי אימתי זמן הזכרה):"],[6,"ואיידי דתני בחג נידונין","כלומר אגב דתנא בחג נידונין על המים קסבר בנפשיה הואיל ונידונין בחג על המים ש\"מ בעינן להזכיר עניינא דמיא לרצויי על המים דליתו לברכה להכי קתני מאימתי מזכירין:"],[7,"כתיב עושה גדולות עד אין חקר","אלמא דכתיב חקר בגשמים וכתיב חקר בברייתו של עולם מה ברייתו של עולם כתיב ביה גבורה אף גשמים הוי כמאן דכתיב ביה גבורה:"],[11,"ואמר רבי יוחנן שלש מפתחות","היינו שלא נמסרו לשליח אחד ביחד:"],[12,"יפתח ה'","ולא שליח:"]],[[0,"","מתני' מאימתי. מיום טוב האחרון של חג. שמיני דלא יתבון בסוכה ואפילו האידנא אינו אלא מדרבנן משום ספיקא ואע\"ג דבקיאינן בקביעא דירחא גזרה שמא יחזור הדבר לקלקולו או משום מנהג אבותינו בידינו כדאי' פ\"ק דביצה (דף ד:) ולכן מדכרינן אבל כל שבעה לא שהגשמים בימי סוכה סימן קללה הן כדתנן פרק שני דסוכה (דף כח:) משל לעבד וכו':"],[1,"","אם כן. אם אתה אומר מזכירין אע\"פ שאין שואלין הואיל ומשמע בעונתו אף בקיץ יזכירו ומה אתה נותן סימן מי\"ט הראשון ור' אליעזר אומר בברייתא בגמרא כל הקיץ אם בא להזכיר מזכיר דלעולם בעונתו משמע מיהו עד השתא לא רמי עליה חובה אבל בי\"ט ראשון חובה לרצות לפני שאלה שכל הבא לבקש מקדים ומרצה ואסימן קללה לא קפדינן ורבי יהושע קפיד:"],[3,"","התם קאי. פירוש בסדר זרעים בברכות פרק אין עומדין (ברכות דף לג.) וליתני התם מאי שנא כו' כלומר אמאי תנא הכא במועד מאי דתני התם בסדר זרעים:"],[6,"","אלא תנא מראש השנה קא סליק. פירוש ור\"ה הויא בסדר מועד ואם תאמר ואכתי ליתני בסדר זרעים וי\"ל דהכא עיקר דאמר בחג נידונין על המים ואורחא דמילתא לרצות לפני שאלה לכך שביק עד הכא אבל בסדר זרעים אומרים מזכירין גבורות גשמים אפשר דמשמע לעולם כמו תחיית המתים או הבדלה בחונן הדעת:"],[7,"","וליתני מאימתי מזכירין גשמים מאי גבורות גשמים אמר ר' יוחנן שיורדין בגבורה. תימה התם בברכות פ' אין עומדין (שם) קתני כי הכא מזכירין גבורות גשמים ושואלין הגשמים וכו' אמאי לא קא מקשה כמו הכא וליתני מזכירין על הגשמים מאי גבורות ויש לומר שאני הכא דהוי עיקר סדר של גשמים באיזה זמן מתחילין לאומרו ומאימתי פוסקין מלאומרו ומשום הכי פריך הכא טפי מהתם:"],[9,"","וכתיב מכין הרים בכחו נאזר בגבורה. וזה גבי בריאת עולם וכי היכי דהאי חקר בבריאת העולם רוצה לומר בגבורות כמו כן הכא גבי גשמים האי חקר נמי רוצה לומר גבורות אכן יש להקשות אמאי נקט גבורות טפי מכח וכמו כן הוה ליה למימר מאימתי מזכירין כח גשמים או ליתני גדולות גשמים וי\"ל דמן הדין נקט גבורות משום טעמא דאיכא כח ואיכא גדולה אי נמי משום דהברכה מתחלת בגבורה להכי נקט גבורות:"],[11,"","שלשה מפתחות שלא נמסרו לשליח. וא\"ת והא אמרינן (סנהדרין דף קיג.) דמפתח הגשמים נמסרין לאליהו וכן מפתח של תחיית המתים וכן לאלישע דכתיב (מלכים א י״ז:כ״ג) ויאמר אליהו חי ה' וגו' דה\"נ אומר בפירקין דלקמן (תענית דף כג.) וי\"ל דהא דקאמר שלא נמסרו לשליח אינו ר\"ל שלא נמסרו מעולם דהא של תחיית המתים ושל גשמים נמסרו אלא לא נמסרו לשליח להיות לעולם ממונה עליהם:"],[12,"","וישמע אליה אלהים ויפתח את רחמה. פירוש שהוא בעצמו עשה וא\"ת מהכא משמע דליכא אלא שלשה מפתחות וא\"כ יש להקשות והא כתיב (ירמיהו נ׳:כ״ה) פתח ה' את אוצרו ויוצא את כלי זעמו ומשמע נמי שלא נמסרו לשליח וכמו ההיא וישמע אליה אלהים וגו' וא\"כ אמאי לא חשיב לה וי\"ל דלא חשיב כי אם אותן מפתחות של טובה ולהכי לא קא חשיב מפתח של זעם וא\"ת דמשמע מהאי קרא דפתח ה' שלא נמסר מפתח של זעם לשליח והא אמרינן (פסחים דף קיח.) יורקמי שר של ברד הוי וי\"ל מכלי זעם אחרינא קאמר שלא נמסרו לשליח אבל משום ברד לא דאותו של ברד נמסרו:"]]],[["אליה אלהים ויפתח את רחמה מפתח של תחיית המתים מנין דכתיב (יחזקאל לז, יג) וידעתם כי אני ה' בפתחי את קברותיכם","במערבא אמרי אף מפתח של פרנסה דכתיב (תהלים קמה, טז) פותח את ידך וגו' ור' יוחנן מאי טעמא לא קא חשיב להא אמר לך גשמים היינו פרנסה:","ר' אליעזר אומר מיום טוב הראשון של חג כו': איבעיא להו ר' אליעזר מהיכא גמיר לה מלולב גמר לה או מניסוך המים גמר לה","מלולב גמר לה מה לולב ביום אף הזכרה ביום או דלמא מניסוך המים גמר לה מה ניסוך המים מאורתא דאמר מר (במדבר כט, יח) ומנחתם ונסכיהם אפילו בלילה אף הזכרה מאורתא","תא שמע דאמר רבי אבהו לא למדה ר' אליעזר אלא מלולב איכא דאמרי ר' אבהו גמרא גמיר לה ואיכא דאמרי מתניתא שמיע ליה","מאי היא דתניא מאימתי מזכירין על הגשמים רבי אליעזר אומר משעת נטילת לולב ר' יהושע אומר משעת הנחתו","א\"ר אליעזר הואיל וארבעת מינין הללו אינן באין אלא לרצות על המים וכשם שארבע מינין הללו אי אפשר בהם בלא מים כך אי אפשר לעולם בלא מים","אמר לו ר' יהושע והלא גשמים בחג אינו אלא סימן קללה אמר לו ר' אליעזר אף אני לא אמרתי לשאול אלא להזכיר וכשם שתחיית המתים מזכיר כל השנה כולה ואינה אלא בזמנה כך מזכירים גבורות גשמים כל השנה ואינן אלא בזמנן לפיכך אם בא להזכיר כל השנה כולה מזכיר רבי אומר אומר אני משעה שמפסיק לשאלה כך מפסיק להזכרה","ר' יהודה בן בתירה אומר בשני בחג הוא מזכיר ר' עקיבא אומר בששי בחג הוא מזכיר ר' יהודה משום ר' יהושע אומר העובר לפני התיבה ביום טוב האחרון של חג האחרון מזכיר הראשון אינו מזכיר ביום טוב ראשון של פסח הראשון מזכיר האחרון אינו מזכיר","שפיר קאמר ליה ר\"א לרבי יהושע אמר לך רבי יהושע בשלמא תחיית המתים מזכיר דכולי יומא זמניה הוא","אלא גשמים כל אימת דאתיין זמנייהו היא והתנן יצא ניסן וירדו גשמים סימן קללה הם שנאמר (שמואל א יב, יז) הלא קציר חטים היום וגו'","ר' יהודה בן בתירה אומר בשני בחג הוא מזכיר מ\"ט דרבי יהודה בן בתירה דתניא רבי יהודה בן בתירה אומר","נאמר בשני (במדבר כט, ו) ונסכיהם ונאמר בששי ונסכיה ונאמר בשביעי כמשפטם","הרי מ\"ם יו\"ד מ\"ם הרי כאן מים מכאן רמז לניסוך המים מן התורה","ומאי שנא בשני דנקט דכי רמיזי להו בקרא בשני הוא דרמיזי הלכך בשני מדכרינן","רבי עקיבא אומר בששי בחג הוא מזכיר שנאמר בששי ונסכיה בשני ניסוכין הכתוב מדבר אחד ניסוך המים ואחד ניסוך היין","ואימא תרוייהו דחמרא סבר לה כר' יהודה בן בתירה דאמר רמיזי מיא"],[[0,"כי אני ה'","ולא שליח:"],[1,"פותח את ידך","ולא שליח:"],[1,"גשמים נמי היינו פרנסה","וכבר חשבנא ליה:"],[2,"מלולב גמר לה","שדומה ללולב שכשם שאי אפשר לאלו ארבע מינין בלא גשמים ובאין לרצות על המים כדאמרינן בסוכה כך אי אפשר לעולם בלא מים:"],[3,"מה לולב ביום","שמתחילין ליטול ביום ראשון אף הזכרה נמי ביום כלומר שאינן מזכירין בלילי יום טוב הראשון עד למחר:"],[3,"מה ניסוך המים מאורתא","כדאשכחן במס' סוכה (דף נא:) שממלאין הכלי מים לניסוך המים בלילה ויש ספרים דכתיב בהו דאמר מר ומנחתם ונסכיהם בלילה שמקריבין הקרבנות ביום יכולין להביא המנחות והנסכים בלילה אף האי ניסוך המים נמי יכול לנסך בלילה:"],[3,"אף הזכרה נמי מאורתא","שבלילי י\"ט הראשון קאמר ר' אליעזר שמתחילין להזכיר גבורות גשמים:"],[4,"גמרא גמיר לה","רבי אבהו דרבי אליעזר לא למדה אלא מלולב:"],[4,"מתניתין שמיע ליה","דרבי אליעזר גמר מלולב:"],[5,"משעת הנחתו","מיום שמברכין בו באחרונה דהיינו בשביעי:"],[6,"ארבעה מינין הללו","שבלולב ואתרוג:"],[7,"כך גשמים","יהא מזכיר כל השנה אפילו בימות החמה אם הוא רוצה יהא מזכיר:"],[7,"משעה שפוסק מלשאול","שבפסח פוסק מלומר ותן טל ומטר פוסק מלהזכיר גבורות גשמים והשתא לא מצית למימר אם בא להזכיר כל השנה כולה מזכיר אלא בימות החמה אינו מזכיר הואיל ואין זמנו אף בחג אינו מזכיר הואיל ולא סימן ברכה הן:"],[8,"האחרון","המתפלל תפלת מוסף:"],[8,"הראשון","המתפלל תפלת יוצר:"],[8,"אינו מזכיר","ושוב אין מזכירין:"],[9,"שפיר קאמר ליה ר' אליעזר לר' יהושע","דאמר כי היכי דמזכירין תחיית המתים כל השנה ואף על גב דלא מטא זימנייהו כך מזכירין גבורות גשמים אם רוצה כל השנה ובחג נמי אע\"ג דלאו סימן ברכה הן מזכירין הואיל ואין שואלין:"],[10,"כל אימת דאתיין זימנייהו הוא","וכיון דלאו זימניה הוא אין מזכירין והוא הדין בחג:"],[12,"בשני ונסכיהם","דסגי בנסכה וכיון דבשני אייתר מ\"ם לדרשה להכי מתחילין להזכיר בשני:"],[15,"בשני ניסוכין הכתוב מדבר","שני ניסוכין על קרבן אחד אבל ונסכיהם משמע הרבה דבקרבנות הרבה לכן לא הוה דריש רבי עקיבא מונסכיהם:"],[16,"סבר לה כרבי יהודה","דמ\"ם יו\"ד מ\"ם מרבה ניסוך המים:"]],[[2,"","איבעיא להו רבי אליעזר מהיכא גמיר לה מלולב גמיר מה לולב ביום וכו'. פי' ולולב הוי רצוי דמים וגדל על המים או דלמא מניסוך גמר לה פי' ונפקא מינה אי מלולב גמר לה אבל ניסוך המים סבירא ליה דלאו ביום ראשון הוא או מניסוך המים קא גמר לה דסבירא ליה דניסוך המים ביום ראשון הוא אי נמי דאי מלולב גמר הוה דווקא ביום שנאמר (ויקרא כ״ג:מ׳) ולקחתם לכם ביום אבל אי מנסוך הוה אפילו בלילה ולענין זה אהני דאמר מר ומנחתם ונסכיהם בלילה אף וכו' פירוש דאע\"ג דניסוך קרבנות לא הוי עד לאחר הקרבת קרבנותיהם ואם כן היאך קריבי נסכים בלילה רוצה לומר בלילה שניה והניסוך החג דהוי ממים מצי למהוי בלילה ראשונה ואע\"ג דאמרינן במסכת יומא בפ' בראשונה (יומא דף כו:) אמר רב ואיתימא ר' יוחנן אין מנסכים מים בחג אלא בתמיד של שחר וא\"כ לא הוי בלילה ראשונה דהא אינה אלא ביום יש לומר דאינו חייב לנסך אלא בתמיד של שחר מכל מקום אי בעי עביד ליה בליליא:"],[4,"","דאמר רבי אבהו לא למדה רבי אליעזר אלא מלולב. פירוש וסבירא ליה דניסוך לא הוי עד בשני:"],[5,"","משעת נטילת לולב. פירוש דהיינו תחילת יום ראשון של סוכות ורבי יהושע אומר משעת הנחתו פירוש לאורתא דמוצאי שביעי של סוכות שמניחין בו את הלולב:"],[7,"","משעה שמפסיקין לישאל. ותן טל ומטר בברכת השנים פוסקין מלהזכיר מוריד הגשם בתחיית המתים:"],[8,"","העובר לפני התיבה בי\"ט של חג האחרון מזכיר וכו'. פי' האחרון שמתפלל תפלת מוסף הראשון אינו מזכיר פירוש שמתפלל שחרית אינו מזכיר ובירושלמי קאמר אמאי אינו מזכיר מאורתא פירוש מתפלת ערבית ומשני דלית תמן כל עמא ולדכרו בצפרא פירוש בתפלת שחרית ומשני דהוו סברי דהוו מדכרו ליה מאורתא:"],[13,"","מים. מ\"ם מנסכיהם דכתיב בשני ויו\"ד דכתיב בששי ונסכיה ומ\"ם שבשביעי כתיב כמשפטם והוי מים טעמא דרבי עקיבא בששי ונסכיה דמשמע תרי נסכים הלכך בששי בחג הוא מזכיר גבורות גשמים:"]]],[["אי סבר לה כרבי יהודה בן בתירה נימא כוותיה קסבר רבי עקיבא כי כתיב ניסוך יתירא בששי הוא דכתיב","תניא ר' נתן אומר (במדבר כח, ז) בקדש הסך נסך שכר לה' בשני ניסוכין הכתוב מדבר אחד ניסוך המים ואחד ניסוך היין אימא תרוייהו דחמרא אם כן ליכתוב קרא או הסך הסך או נסך נסך מאי הסך נסך שמעת מינה חד דמיא וחד דחמרא","אלא הא דתנן ניסוך המים כל ז' מני אי ר' יהושע נימא חד יומא אי ר\"ע תרי יומי אי ר' יהודה ב\"ב שיתא יומי","לעולם ר' יהודה ב\"ב היא וס\"ל כר' יהודה דמתני' דתנן רבי יהודה אומר בלוג היה מנסך כל שמונה ומפיק ראשון ומעייל שמיני","ומאי שנא ראשון דלא דכי רמיזי מים בשני הוא דרמיזי שמיני נמי כי רמיזי מים בשביעי הוא דרמיזי","אלא רבי יהושע היא וניסוך המים כל שבעה הלכתא גמירי לה","דאמר ר' אמי א\"ר יוחנן משום ר' נחוניא איש בקעת בית חורתן עשר נטיעות ערבה וניסוך המים הלכה למשה מסיני:","רבי יהודה אומר משום רבי יהושע העובר לפני התיבה ביום טוב האחרון של חג האחרון מזכיר הראשון אינו מזכיר ביום טוב הראשון של פסח הראשון מזכיר האחרון אינו מזכיר:","הי רבי יהושע אילימא רבי יהושע דמתניתין הא אמר ביום טוב האחרון של חג הוא מזכיר","אלא ר' יהושע דברייתא האמר משעת הנחתו","ותו הא דתניא ר' יהודה אומר משום בן בתירה העובר לפני התיבה ביום טוב האחרון של חג האחרון מזכיר הי בן בתירה אילימא רבי יהודה בן בתירה הא אמר בשני בחג הוא מזכיר","אמר רב נחמן בר יצחק תהא ברבי יהושע בן בתירה זמנין דקרי ליה בשמיה וזימנין דקרי ליה בשמיה דאבא והא מקמי דליסמכוהו והא לבתר דליסמכוהו","תנא בטל וברוחות לא חייבו חכמים להזכיר ואם בא להזכיר מזכיר מ\"ט א\"ר חנינא לפי שאין נעצרין","וטל מנלן דלא מיעצר דכתיב (מלכים א יז, יג) ויאמר אליהו התשבי מתושבי גלעד אל אחאב חי ה' אלהי ישראל אשר עמדתי לפניו אם יהיה השנים האלה טל ומטר כי אם לפי דברי וכתיב (מלכים א יח, א) לך הראה אל אחאב ואתנה מטר על פני האדמה ואילו טל לא קאמר ליה מאי טעמא משום"],[[0,"אי סבר לה כר' יהודה","לימא כר\"י שיזכיר בשני:"],[0,"ניסוך יתירא בששי כתיב","כלומר ונסכיה דמרבי תרי ניסוכין כתיב בששי להכי אמר בששי מתחיל להזכיר ואהני מ\"ם יו\"ד מ\"ם מים דלא מצינו למימר תרוייהו דיין:"],[1,"או הסך הסך או נסך נסך","מדשני קרא בדיבוריה ש\"מ תרתי:"],[2,"אי ר\"ע תרי יומי הוו","ותו לא דהא אמר ונסכיה דהיינו בששי מרבה ניסוך המים:"],[3,"וסבר לה כר' יהודה דמתניתין","דאמר בלוג הוה מנסך כל שמנה לא סבר כוותיה במה דאמר כל שמונה מנסך אלא במה דאמר בשמיני מנסך וכיון דבשמיני מנסך משכחת לה לרבי יהודה [ב\"ב] דאמר בשני מתחילין לניסוך המים כל שבעה:"],[3,"דמפיק ראשון ומעייל שמיני","משיב בעל הגמרא מי מצי אמר רבי יהודה דבשמיני מנסך:"],[4,"מאי שנא","דקאמר דבראשון אינו מזכיר דכי רמיזי מיא בשני הוא דרמיזי דמונסכיהם מרבה ניסוך המים שמיני נמי מי מצי אמר דמנסך הא שביעי אמר רחמנא דמ\"ם יו\"ד מ\"ם מים כתיב בשביעי דסיום קראי דניסוך המים בשביעי כתיב כמשפטם ולא בשמיני:"],[5,"אלא ר' יהושע היא","דאמר משעת הנחתו [דהיינו בשביעי] מזכיר ואעפ\"כ סבר דניסוך המים כל שבעה דגמרא גמיר לה הלכה למשה מסיני דניסוך המים כל שבעה ודאי כר\"א אתי שפיר אבל כרבי יהודה בן בתירה וכר\"ע לא מיתוקמא אלא להכי לא מוקי לה כר' אליעזר דהא לא מיבעי אי ר' אליעזר סבירא ליה הכי דודאי לרבי אליעזר אתי שפיר והא דקא מוקים כר' יהושע רבותא קמשמע לן אבל כר\"י בן בתירה וכר\"ע לא מיתוקמא דרבי יהודה יליף מונאמר בשני ונסכיהם כו' אלמא דסבר דניסוך המים לא הוו אלא ו' ימים דאיהו לא מפיק ראשון ומעייל שמיני משום הני פירכא דפריך לעיל לא אתי כרבי יהודה ורבי עקיבא יליף מנסכיה שנאמר בששי אלמא דסבר דניסוך המים לא הוו אלא תרי יומי אבל כרבי יהושע מיתוקמא לפיכך אין מזכירין אלא ביו\"ט האחרון דגשמים בחג סימן קללה אבל ניסוך המים הוי כל שבעה דגמרא גמיר לה:"],[6,"עשר נטיעות","המפוזרות בתוך בית סאה חורשין כל בית סאה ערב שביעית עד ר\"ה אע\"ג דשאר שדות אין חורשין לפני שביעית ל' יום זה חורשין דהואיל אם אין חורשין סביבן מפסידין:"],[6,"וניסוך המים","כל שבעה:"],[7,"ר' יהודה אומר משום רבי יהושע העובר לפני התיבה בי\"ט האחרון של חג כו'","כעין אמר מר הוא כלומר אמרינן לעיל ר' יהודה אומר:"],[8,"הי רבי יהושע אילימא רבי יהושע דמתני' מיו\"ט האחרון הוא מזכיר","דראשון נמי המתפלל תפלת יוצר מזכיר ואילו הכא תני הראשון אינו מזכיר:"],[9,"האמר משעת הנחתו","דהיינו בשביעי והכא קתני יו\"ט האחרון של חג דהיינו בשמיני:"],[10,"ותו הא דתניא","במכילתא אחריתי ר' יהודה אומר משום בן בתירה העובר לפני התיבה בי\"ט אחרון של חג האחרון מזכיר הראשון אינו מזכיר:"],[11,"(אלא) אמר רב נחמן בר יצחק תהא","תרוייהו הא דבעית הי ר' יהושע והא דבעית הי בן בתירה ר' יהושע בן בתירה היא דהאי דקאמר ר' יהודה לעיל משום ר' יהושע והדר קאמר משום בן בתירה תהא תרוייהו ר' יהושע בן בתירה ולא קשיא זמנין קרו ליה בשמיה דאבוה בן בתירה וזמנין דקרו ליה בשמיה דידיה ר' יהושע:"],[11,"מקמי דליסמכוהו","לא הוה חשוב וקרו ליה בשמיה דאבוה והאי דקרו ליה בשמיה דנפשיה ר' יהושע היינו לבתר דסמכוהו:"],[12,"בטל וברוחות","משיב הרוח ומוריד הטל לא חייבוהו חכמים להזכיר אפילו בימות הגשמים:"],[12,"לפי שאינן נעצרין","שאלמלא הן אין העולם מתקיים והאי דאמרינן בתפלה משיב הרוח ומוריד הגשם לאו משום חיוב אלא חוק גשם הוא מזכיר דטל ורוחות מועילות לארץ לתקנה ולנגבה כדבסמוך זיקא דבתר מיטרא כמיטרא:"],[13,"ואילו טל לא קאמר","ואתנה טל ומטר אלא מטר בלבד:"]],[[2,"","אי רבי יהודה בן בתירה. דאמר בשני בחג הוא מזכיר שית יומי הוו א\"כ לא יהיה הניסוך כי אם ששה ימים:"],[6,"","עשר נטיעות. פירש\"י נטיעות מפוזרות בבית סאה חורש כל בית סאה בשבילן דכל נטיעה יונקת ודווקא מבית סאה היה צריך להם יכול לחרוש עד ר\"ה של שביעית דהוו שפיר אוקומי אילנא שרי אבל יותר מבית סאה אינו חורש אלא כדי צורכן דהואיל ומפוזרות ביותר מבית סאה קיימי שפיר ובפחות מיכן למה קיימי וליעקר קיימי ודוקא נטיעות אמר דחורשין בשבילן עד ראש השנה אבל אילנות אסור דאורייתא כל אלול ומדרבנן פסח ועצרת תקון בשדה הלבן עד פסח מותר אבל מפסח ולהלן אסור ושדה אילן עד עצרת מותר מכאן ואילך אסור:"],[6,"","ערבה. שמקיפין את המזבח וניסוך המים הלכה למשה מסיני כולהו:"],[12,"","בטל וברוחות לא חייבו חכמים להזכיר. משיב הרוח ומוריד הטל כו' לפיכך אין קפידא לומר מוריד הטל אפילו בימות החמה אך שלא יאמר מוריד הגשם והכי הלכתא ואם לא אמר בימות הגשמים כי אם מוריד הגשם ודילג משיב הרוח ומוריד הטל אין מחזירין:"],[13,"","ואילו טל לא מיעצר. ומ\"ה נראה דגבי גדעון (שופטים ו) כשאמר על הארץ יהיה טל ועל הגיזה יהיה חורב כתיב ויעש כן אבל כשאמר על הארץ יהיה חורב ועל הגזה יהיה טל כתיב ויהי כן כלומר דעל הגיזה היה הטל אבל לא כתיב ויעש כן משמע דעל הארץ היה טל דטל לא מיעצר ע\"כ בנוסח שלפני ועוד מצאתי כשאמרו על כל הארץ יהיה טל כתיב ויעש אלהים כן וכשאמר טל יהיה על הגיזה לבדה ועל כל הארץ יהיה חרב כתיב ויהי כן ולא הזכיר בזה הש\"י וטעמו אשר אומר כי הוא זה כי אין הש\"י מזכיר שמו על הרעה כי אם יהיה חורב על כל הארץ היתה רעת יושבי בה וכתיב (שמות כ) בכל המקום אשר אזכיר את שמי אבוא אליך וברכתיך אבל כשאמר על כל הארץ יהיה טל כתיב ויעש אלהים וכדומה לזה (בראשית א) ויקרא אלהים לאור יום ולחשך קרא לילה וגבי חשך לא הזכיר השם יתברך וכן בחמשה דברות אחרונות (שמות כ) מלא תרצח ואילך לא הזכיר הש\"י הכל הולך אל מקום אחד משל למלך שבנה דירה נאה והניח לצייר מגינו לפני כל חדרי הבית זולתי בית הכסא מקום הטינוף:"],[13,"","ויאמר אליהו התשבי מתושבי גלעד. לכך נקרא מתושבי גלעד לפי שהרגו ישראל אנשי יבש גלעד על מעשה פילגש בגבעה ולא נשאר ביבש גלעד כי אם מעט אנשים מן המיושבים בעיר כי כל השאר היו עם אספסוף לכך מעיד כי אליהו מן התושבים כך שמעתי מהר\"י טרוט\"י משם הר\"י בה\"ר יצחק ממלאון:"],[13,"","ואילו טל לא מיעצר. ומ\"ה נראה דגבי גדעון (שופטים ו) כשאמר על הארץ יהיה טל ועל הגיזה יהיה חורב כתיב ויעש כן אבל כשאמר על הארץ יהיה חורב ועל הגזה יהיה טל כתיב ויהי כן כלומר דעל הגיזה היה הטל אבל לא כתיב ויעש כן משמע דעל הארץ היה טל דטל לא מיעצר ע\"כ בנוסח שלפני ועוד מצאתי כשאמרו על כל הארץ יהיה טל כתיב ויעש אלהים כן וכשאמר טל יהיה על הגיזה לבדה ועל כל הארץ יהיה חרב כתיב ויהי כן ולא הזכיר בזה הש\"י וטעמו אשר אומר כי הוא זה כי אין הש\"י מזכיר שמו על הרעה כי אם יהיה חורב על כל הארץ היתה רעת יושבי בה וכתיב (שמות כ) בכל המקום אשר אזכיר את שמי אבוא אליך וברכתיך אבל כשאמר על כל הארץ יהיה טל כתיב ויעש אלהים וכדומה לזה (בראשית א) ויקרא אלהים לאור יום ולחשך קרא לילה וגבי חשך לא הזכיר השם יתברך וכן בחמשה דברות אחרונות (שמות כ) מלא תרצח ואילך לא הזכיר הש\"י הכל הולך אל מקום אחד משל למלך שבנה דירה נאה והניח לצייר מגינו לפני כל חדרי הבית זולתי בית הכסא מקום הטינוף:"]]],[["דלא מיעצר וכי מאחר דלא מיעצר אליהו אשתבועי למה ליה הכי קא\"ל אפילו טל דברכה נמי לא אתי וליהדריה לטל דברכה משום דלא מינכרא מילתא","(אלא) רוחות מנא לן דלא מיעצרי א\"ר יהושע בן לוי דאמר קרא (זכריה ב, י) כי כארבע רוחות השמים פרשתי אתכם נאם ה' מאי קאמר להו אילימא הכי קאמר להו הקב\"ה לישראל דבדרתינכו בארבע רוחי דעלמא אי הכי כארבע בארבע מיבעי ליה אלא הכי קאמר כשם שאי אפשר לעולם בלא רוחות כך א\"א לעולם בלא ישראל","א\"ר חנינא הלכך בימות החמה אמר משיב הרוח אין מחזירין אותו אמר מוריד הגשם מחזירין אותו","בימות הגשמים לא אמר משיב הרוח אין מחזירין אותו לא אמר מוריד הגשם מחזירין אותו ולא עוד אלא אפילו אמר מעביר הרוח ומפריח הטל אין מחזירין אותו","תנא בעבים וברוחות לא חייבו חכמים להזכיר ואם בא להזכיר מזכיר מ\"ט משום דלא מיעצרי","ולא מיעצרי והתני רב יוסף (דברים יא, יז) ועצר את השמים מן העבים ומן הרוחות אתה אומר מן העבים ומן הרוחות או אינו אלא מן המטר כשהוא אומר ולא יהיה מטר הרי מטר אמור הא מה אני מקיים ועצר את השמים מן העבים ומן הרוחות","קשיא רוחות ארוחות קשיא עבים אעבים עבים אעבים לא קשיא הא בחרפי הא באפלי","רוחות ארוחות לא קשיא הא ברוח מצויה הא ברוח שאינה מצויה רוח שאינה מצויה חזיא לבי דרי אפשר בנפוותא","תנא העבים והרוחות שניות למטר היכי דמי אמר עולא ואיתימא רבי יהודה דבתר מיטרא למימרא דמעליותא היא והכתיב (דברים כח, כד) יתן ה' את מטר ארצך אבק ועפר ואמר עולא ואיתימא רב יהודה זיקא דבתר מטרא","לא קשיא הא דאתא ניחא הא דאתא רזיא (ואי בעית אימא) הא דמעלה אבק הא דלא מעלה אבק","ואמר רב יהודה זיקא דבתר מיטרא כמיטרא עיבא דבתר מיטרא כמיטרא שימשא דבתר מיטרא כתרי מטרי למעוטי מאי למעוטי גילהי דליליא ושמשא דביני קרחי","אמר רבא מעלי תלגא לטורי כחמשה מטרי לארעא שנאמר (איוב לז, ו) כי לשלג יאמר הוא ארץ וגשם מטר וגשם מטרות עוזו","ואמר רבא תלגא לטורי מטרא רזיא לאילני מטרא ניחא לפירי"],[[0,"ולא מיעצר","לעולם אפילו באותן שנים:"],[0,"אישתבועי למה ליה","אם יהיה השנים האלה טל ומטר כי אם לפי דברי הא לא נעצר:"],[0,"אפילו טל דברכה","שיצמיח שום צמח:"],[0,"וליהדריה לטל דברכה","ולימא ואתנה טל ומטר:"],[0,"דלא מינכרא מילתא","דהא טל הוה מעיקרא ולא היה אחאב הרשע מודה בחזירה דטל של ברכה דאי הוה אומר ואתנה טל ומטר היה אחאב מקנטרו ואומר לו שלא נעצר:"],[1,"","אלא דמכניפנא לכו מד' רוחי עלמא לא גרסינן דהא פרשתי אתכם כתיב בקרא ואיכא למימר דגרס ליה והכי משתמע קרא כי מד' רוחות השמים שפרשתי אתכם משם אקבצכם ואריכות לשון בעלמא הוא דלא כתיב קיבוץ בקרא:"],[1,"כשם שא\"א לעולם בלא רוחות","שלא יתקיים מרוב הבל וחמימות:"],[1,"בלא ישראל","שאין העולם מתקיים אלא בשביל ישראל והכי אמר קרא כי כד' רוחות השמים פרשתי אתכם לרוחות העולם כדי שיתקיים שנאמר (ירמיהו לג) אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי:"],[2,"בימות החמה","מניסן עד החג:"],[2,"משיב הרוח אין מחזירין אותו","דבלאו הכי לא מיעצר:"],[2,"מוריד הגשם מחזירין אותו","דמיעצר וכיון דבעא אמיטרא לא התפלל תפלתו כהוגן וחוזר לראש הברכה ואומרה בלא מוריד הגשם לפי שהגשמים בקיץ סימן קללה הן מפני הקציר:"],[3,"מעביר הרוח","שלא ינשב:"],[3,"ומפריח הטל","שלא ירד:"],[3,"אין מחזירין אותו","דלא מיעצרי:"],[4,"בעבים","מקשר עבים:"],[5,"למימרא דלא מיעצרי","לפיכך לא חייבוהו להזכיר:"],[6,"בחרפי","עבים בכירות הבאים לפני המטר אינן עצורות:"],[6,"באפלי","הבאות מאוחרות לאחר המטר דשניות למטר הן כדלקמן ובהנהו כתיב ועצר וכיון דאין כולם נעצרות לא חייבו להזכיר:"],[7,"שאינה מצויה","כתיב ועצר ואפ\"ה לא חייבוהו להזכיר דסגי ליה במצויה רוחות לא מצי לתרוצי הא בחרפי הא באפלי דרוח בין במטר בין בלא מטר לא מיעצר כגון רוח מצויה:"],[7,"רוח שאינה מצויה נמי חזיא לבי דרי","לגורן לזרות הקשין מן התבואה ונחייב להזכיר:"],[7,"אפשר בנפוותא","וו\"ן בלע\"ז בנפה וכברה:"],[8,"שניות","כמעט שמועילות כמטר עצמו:"],[8,"מאי היא","אי זה עבים ורוחות קאמר דשניות למטר:"],[8,"אמר עולא ואיתימא רב יהודה דבתר מיטרא","עבים ורוחות שלאחר המטר:"],[8,"","זיקא ל\"ג הכא:"],[8,"","יתן ה' את מטר ארצך אבק ועפר וגו':"],[8,"זיקא דבתר מיטרא","שהרוח מעלה אבק אחר הגשמים ונדבק בתבואה:"],[9,"ה\"ג הא דאתא ניחא הא דאתא רזיא","כשירד בנחת אינו מעלה אבק:"],[9,"רזיא","בכח ולא גרסינן ואי בעית אימא הא והא כו' אלא ה\"ג הא דמעלה אבק הא דלא מעלה אבק והיינו הך:"],[10,"כמיטרא","שניות למטר כדקתני בתוספתא:"],[10,"למעוטי מאי","מאחר דכולהו כמיטרא מאי קמעטינן דהוי בתריה ולא הוי כמיטרא:"],[10,"גילהי דליליא","אישלושטר\"א בלע\"ז בגילהי הוה קאי במס' (פסחים דף יג.) ורוב גילהי בליליא שכיח:"],[10,"וביומא שמשא דביני קרחי","שבין העבים שנראה במקום אחד אורה ובמקום אחר מעונן כקרח שיש לו שערות במקום אחד וקרחה במקום אחר:"],[11,"מעלי תלגא לטורי","וכ\"ש לבקעה אלא הרים אין להם גשמים אלא שלג שהגשמים יורדין למטה ואין ההר שותה מהן ועוד שלג שבעמקים נמס והולך מפני החום ששולט שם כמים הוא אבל בהרים קרוי שלג:"],[11,"כחמשה מיטרי לארעא","דהכי משמע קרא כי לשלג יאמר הוא ארץ כשיאמר לשלג הוה ארץ הרי הוא כגשם מטר וגשם מטרות והרי יש כאן חמשה:"],[12,"מיטרא ניחא","שיורד בנחת יפה לפירות התבואה:"]],[[2,"","בימות החמה אמר משיב הרוח אין מחזירין אותו מוריד הגשם מחזירין אותו. אבל אם דילג שלא אמר לא גשם ולא טל אין מחזירין ובימות הגשמים לא אמר משיב הרוח אין מחזירין אותו לא אמר מוריד הגשם מחזירין אותו אכן אם אמר מוריד הטל בימות הגשמים אין מחזירין ואם ספק אם הזכיר אם לאו אם אינו זכור שלא אמר שום דבר בימות הגשמים כל ל' יום חזקה מה שהוא למוד הוא אומר ומחזירין מספק כל ל' יום וכן זכרנו ומי כמוך וכתוב לחיים שאומרים מן הכסה עד יום הכפורים מספק מחזירין ירושלמי בשם רבי חנינא היה שייך בגשם והזכיר טל אין מחזירין אותו בטל והזכיר של גשמים מחזירין אותו והתניא בטל וברוחות לא חייבו חכמים להזכיר ואם בא להזכיר מזכיר לא דמי ההוא דמצלי ומיקל לההוא דלא מצלי ולא מיקל ומפרש רבינו נתנאל טוב כשאינו מזכיר לא גשם ולא טל מכשהוא מזכיר גשם לפי שהגשמים סימן קללה בימות החמה היה שייך בטל לא הזכיר לא טל ולא גשם אין מחזירין אותו והדין להפך במוריד הגשם דאמר בירושלמי בגשם והזכיר של טל אין מחזירין אותו והתניא אם לא שאל בברכת השנים או שלא אמר גבורות גשמים מחזירין בההוא דלא הזכיר כלל לא טל ולא מטר ומשם הר\"ם שאין לומר בימות החמה משיב הרוח דהא אמר רבי חנינא בימות החמה אמר משיב הרוח אין מחזירין אותו מכלל דלכתחילה אין לאומרו ומשום הכי אמר הר\"י בשם א\"ז לעולם בין בימות החמה בין בימות הגשמים מוריד הטל דלעולם לא אתי לידי ספק אמר ספק לא אמר והיכא דלא מזכיר בגבורות מזכיר בשומע תפלה דהכי קאמר בירושלמי ומה שאלה שהיא מדוחק אומר בש\"ת הזכרה שהיא מרווח לא כ\"ש וכי היכי דשואלין בש\"ת הוא מזכיר בש\"ת ואפילו הזכיר קודם שומע תפלה אינו אומר עד שיגיע לש\"ת והיכא דלא אמר בשומע תפלה אי נזכר קודם שעקר רגליו חוזר לש\"ת ואי לא חוזר לראש בין לא אמר מוריד הגשם ובין לא אמר ותן טל ומטר (ומחזירין) וכן הפסק והני מילי ביחיד אבל שליח צבור פסק רבינו יהודה דאין מחזירין לפי דאין מחזירין שליח צבור אלא משום ג' דברים מתחיית המתים ומבונה ירושלים ומברכת ולמלשינים משום דנראה ככופר שמעתי מפי רבי שלמה לא דמי מצלי ומיקל למאן דלא מצלי ולא מיקל פירוש מיקל כמו מקלל כלומר שאין מחזירין אם לא אמר ותן טל ומטר:"],[6,"","הא בחרפי. פי' הא דאמר נעצרים היינו בחריפי כלומר בפירות המתבכרות וכו' אבל באפלי במאוחרות לא מיעצרי:"],[7,"","רוחות ארוחות לא קשיא הא ברוח וכו'. וה\"ה דמצי לשנויי הא בחריפי הא באפלי אלא שפיר קא משני ליה הא ברוח מצויה וכו':"],[8,"","שניות למטר. שניות במעלה כדאמרי אינשי משנה למלך:"],[9,"","הא דאתא ניחא. פי' כשיורדות בנחת חשובה כאן ברזיא כלומר בחוזק ואז אינה טובה:"],[10,"","גילהי דליליא. פי' זריחת הלילה שקורין לנישו\"ר בלע\"ז:"],[10,"","ושמשא דביני קרחי. פי' כמו דבר קרחה שמכאן ומכאן יורדין הגשמים והשמש זורח באמצע זה השמש לא מעלי:"]]],[["עורפילא אפילו לפרצידא דתותי קלא מהניא ליה מאי עורפילא עורו פילי ואמר רבא האי צורבא מרבנן דמי לפרצידא דתותי קלא דכיון דנבט נבט","ואמר רבא האי צורבא מרבנן דרתח אורייתא הוא דקא מרתחא ליה שנאמר (ירמיהו כג, כט) הלא כה דברי כאש נאם ה' ואמר רב אשי כל ת\"ח שאינו קשה כברזל אינו ת\"ח שנא' (ירמיהו כג, כט) וכפטיש יפוצץ סלע","א\"ל רבי אבא לרב אשי אתון מהתם מתניתו לה אנן מהכא מתנינן לה דכתיב (דברים ח, ט) ארץ אשר אבניה ברזל אל תקרי אבניה אלא בוניה אמר רבינא אפ\"ה מיבעי ליה לאיניש למילף נפשיה בניחותא שנאמר (קהלת יא, י) והסר כעס מלבך וגו'","א\"ר שמואל בר נחמני אמר רבי יונתן שלשה שאלו שלא כהוגן לשנים השיבוהו כהוגן לאחד השיבוהו שלא כהוגן ואלו הן אליעזר עבד אברהם ושאול בן קיש ויפתח הגלעדי","אליעזר עבד אברהם דכתיב (בראשית כד, יד) והיה הנערה אשר אומר אליה הטי נא כדך וגו' יכול אפי' חיגרת אפי' סומא השיבו כהוגן ונזדמנה לו רבקה","שאול בן קיש דכתיב (שמואל א יז, כה) והיה האיש אשר יכנו יעשרנו המלך עושר גדול ואת בתו יתן לו יכול אפי' עבד אפילו ממזר השיבו כהוגן ונזדמן לו דוד","יפתח הגלעדי דכתיב (שופטים יא, לא) והיה היוצא אשר יצא מדלתי ביתי וגו' יכול אפילו דבר טמא השיבו שלא כהוגן נזדמנה לו בתו","והיינו דקאמר להו נביא לישראל (ירמיהו ח, כב) הצרי אין בגלעד אם רופא אין שם","וכתיב (ירמיהו יט, ה) אשר לא צויתי ולא דברתי ולא עלתה על לבי","אשר לא צויתי זה בנו של מישע מלך מואב שנאמר (מלכים ב ג, כז) ויקח את בנו הבכור אשר ימלך תחתיו ויעלהו עולה ולא דברתי זה יפתח ולא עלתה על לבי זה יצחק בן אברהם","אמר רבי ברכיה אף כנסת ישראל שאלה שלא כהוגן והקב\"ה השיבה כהוגן שנא' (הושע ו, ג) ונדעה נרדפה לדעת את ה' כשחר נכון מוצאו ויבוא כגשם לנו","אמר לה הקב\"ה בתי את שואלת דבר שפעמים מתבקש ופעמים אינו מתבקש אבל אני אהיה לך דבר המתבקש לעולם שנאמר (הושע יד, ו) אהיה כטל לישראל","ועוד שאלה שלא כהוגן אמרה לפניו רבש\"ע (שיר השירים ח, ו) שימני כחותם על לבך כחותם על זרועך א\"ל הקב\"ה בתי את שואלת דבר שפעמים נראה ופעמים אינו נראה אבל אני אעשה לך דבר שנראה לעולם שנאמר (ישעיהו מט, טז) הן על כפים חקותיך:","אין שואלין את הגשמים כו': סברוה שאלה והזכרה חדא מילתא היא מאן תנא אמר רבא ר' יהושע היא דאמר משעת הנחתו","א\"ל אביי אפילו תימא רבי אליעזר שאלה לחוד והזכרה לחוד","ואיכא דאמרי לימא"],[[0,"עורפילא","גשמים דקים כך שמן כדלקמן:"],[0,"אפי' לפרצידא דתותי קלא","הגרעין שתחת גושה של קרקע:"],[0,"מהניא","שמתחיל לבצבץ ולעלות מיד:"],[0,"עורו פילי","שסותם סדקי הארץ ל\"א שמגדלת ומצמחת הגרעינין העומדין בסדקי הקרקע:"],[0,"צורבא מרבנן","בחור חריף כמו ביעי דצריבן במסכת ביצה (דף ז.) תלמיד חכם זקן לא קרי צורבא אלא ההוא מרבנן קרי ליה:"],[0,"כיון דנבט נבט","שמתחיל לבצבץ ולעלות עולה למעלה כך תלמיד חכם כיון שיצא שמו הולך וגדל למעלה:"],[1,"אורייתא מרתחא ליה","שיש לו רוחב לב מתוך תורתו ומשים ללבו יותר משאר בני אדם וקמ\"ל דחייבין לדונו לכף זכות:"],[1,"כאש","שמחמם כל גופו:"],[1,"ברזל","קפדנים וקשים כברזל:"],[2,"בוניה","תלמידי חכמים מקיימי עולם בבניניהו:"],[3,"שלשה שאלו כו'","משום דרבי ברכיה מיירי בגשמים לקמן נקט לה:"],[4,"ובנות אנשי העיר יוצאות והיה הנערה","משמע הנערה היוצאה תחילה מן העיר ויאמר לה השקיני לה היה מנחש:"],[4,"אפי' חיגרת אפי' סומא","לפי שלא פירש בשאילתו ואפשר שתהיה בעלת מום ולא יבין בה אליעזר ויקחנה:"],[4,"(אלא) השיבוהו כהוגן","וזימנו לו רבקה:"],[6,"דבר טמא","כלב או חזיר:"],[7,"והיינו דאמר להו נביא כו'","מדגלי ביה קרא ואמר הצרי אין בגלעד [אלמא דלא הוי ניחא קמי שמיא כדאמרינן הצרי אין בגלעד] פנחס היה שם והיה יכול להתיר נדרו אלא שלא רצה יפתח לילך אצלו והוא לא רצה לבוא אצל יפתח בבראשית רבה:"],[8,"וכתיב אשר לא צויתי","בירמיה כתיב בפרשת בקבוק ובנו את במות (התופת אשר בגיא בן הנם) לשרוף את (בנותיהם ואת) בניהם באש אשר לא [צויתי ולא] דברתי ולא עלתה על לבי שלא תאמרו הלא צוה כמו כן הקב\"ה ליפתח ומישע ואברהם כי מעולם לא צויתי למישע לשרוף את בנו באש דכתיב ויקח את בנו הבכור אשר ימלך תחתיו ויעלהו עולה על החומה ולשמים נתכוון כסבור היה לרצות להקב\"ה והאי דכתיב על שרפו עצמות מלך אדום לשיד מילתא אחרינא הוא ולא דברתי ליפתח מימים ימימה ותהי חק בישראל ובתרגום מזכיר פנחס לגנאי ויפתח לגנאי אלמא לא היה הקב\"ה רוצה בבתו שהרי מזכירם לגנאי לפי שלא הלכו זה אצל זה לבטל הנדר:"],[9,"ה\"ג ולא עלתה על לבי זה יצחק בן אברהם","כלומר שאע\"פ שצויתי לו מעולם לא עלתה על לבי לשחוט בנו אלא לנסותו מפני קטיגורו היינו שטן כדאמר בסנהדרין בהנחנקין (סנהדרין דף פט:) ויהי אחר הדברים האלה אחר דבריו של שטן וכו' ואית דלא גרסינן האי ולא עלתה על לבי דטעי בקרא אחרינא דלא כתב אלא אשר לא צויתי ולא דברתי (ירמיהו ז׳:ל״א פסוק כב) ובפרשת בקבוק כתיב כל הני שלשה אשר לא צויתי ולא דברתי ולא עלתה על לבי. בתנחומא אשר לא צויתי זו בתו של יפתח אע\"פ שצויתי לו תורה ומצות מצוה זו לא צויתי עליו ולא דברתי זה בנו של מישע מלך מואב והלא מישע נכרי הוא ולא חולין הוא לי לדבר עמו אפילו דיבור בעלמא. ובאגדה קא חשיב כלב בהדייהו אשר יכה את קרית ספר ולכדה וגו' ורבי יונתן דלא חשיב ליה דבגמרא פשיט ליה להאי קרא בהלכות שנשתכחו בימי אבלו של משה כדאמרינן בתמורה (דף טז.) ואין לחוש שתשרה רוח הקדש על עבד ועל ממזר כדאמרינן בנדרים (דף לח.) שאין שכינה שורה כו' מפי רבי. וגדעון ששאל למנוע טל מעל הארץ ובגזה לבדה יהיה אין זה שלא כהוגן ומה תקלה יש אם יחסר העולם טל לילה אחת לבד מפי רבי:"],[10,"ויבוא כגשם לנו","פעמים אינו מתבקש שהוא סימן קללה בקיץ:"],[11,"דבר המתבקש לעולם","טל אפילו בימות החמה:"],[12,"פעמים נראה","כשהוא ערום נראה זרועו וכנגד לבו ואינו נראה כשהוא לבוש והכף נראית כל שעה שהיד נראית לעינים וי\"ל על כפים על השמים צורת אדם שהוא בכסא וכן נשא לבבנו אל כפים (איכה ג׳:מ״א) מפי רבי:"],[13,"ה\"ג סברוה שאלה והזכרה חדא מילתא היא","כלומר הא דקתני אין שואלין את הגשמים היינו אין מזכירין את הגשמים:"],[13,"ומאן תנא","דאמר סמוך לימות הגשמים מזכירין אבל לא קודם לכן:"],[13,"רבי יהושע היא","דאמר משעת הנחת לולב הוא מזכיר דהיינו יום שמיני וזהו סמוך לגשמים דמן החג ואילך הוא זמן גשמים:"]],[[0,"עורפילא","היינו גשם דק אפילו לפרצידא דתותי קלא מהניא פי' פרצידא זו גרעין שהוא מתחת האבן היינו כמו חטה שמתחת הקרקע:"],[0,"מאי עורפילא עורו פילי","פי' מעוררן ומצמיחן פילי פי' אותן העומדים בסדקי הארץ:"],[3,"שלשה שאלו שלא כהוגן","אליעזר שאול ויפתח וא\"ת אמאי לא חשיב כלב בן יפונה שאמר אשר יכה את קרית ספר ולכדה ונתתי לו את עכסה בתי לאשה אמאי לא פריך כמו הכא יכול ממזר או עבד וי\"ל דהא דקאמר כלב שיתן לו הקב\"ה כל מי שיכול לחזור אותן הלכות ששכחו בימי אבלו של משה אתן לו עכסה בתי וי\"מ דלכך נקראת עכסה שכל הרואה אותה כועס על אשתו וזהו ודאי משום צניעות יתירא דקא חזו בה והיה סומך דזכותה וזכות דידיה מסתייע דלא מזדווגין לה אלא כפי מעשיה כדאיתא בסוטה (דף ב.) דאין מזווגין וכו':"],[4,"יכול אפי' חיגרת או סומא","תימה אמאי לא נקט הכא גבי אליעזר עבד אברהם כמו דקאמר גבי שאול בסמוך יכול אפי' ממזרת או שפחה וכו' ואמר רש\"י משום דגבי אליעזר לא שייך עדיין ממזרת דהא לא נתנה תורה אי נמי דגבי אשה לא דייק עלמא אלא ליופי וא\"ת היכי קאמר דשאל אליעזר שלא כהוגן והא לא אמר אלא אשר אומר אליה הטי נא כדך ואם יראה שתהא חיגרת או סומא לא יאמר לה וי\"ל דה\"פ יכול אפילו חיגרת ואפילו סומא יכול אפי' חיגרת שיהיה לה אפילו רגל של עץ והוא לא יהא רואה או סומא כגון שיש לה עינים יפים ואינה רואה כלל:"],[7,"והייינו דקאמר להו נביא לישראל הצרי אין בגלעד אם רופא אין שם","כלומר להתיר נדרו ליפתח והא הוה פנחס ואמאי לא הלך יפתח אצלו להתיר נדרו אלא מתוך גסות רוחו אמר לא אלך אצלו שאני שופט ונגיד אלא יבא אצלי ופנחס אמר ליתי גבאי דאנא נביא ועל ידי תהא פטורה שהייתי שורה ומתיר הנדר ופוטר אותה ולבסוף נענשו שניהם יפתח נענש שנפלו אבריו קודם מיתה כדכתיב ויקבר בערי גלעד ופנחס נענש דכתיב לפנים היה ה' עמו:"]]],[["רבי יהושע היא דאמר משעת הנחתו אמר רבא אפילו תימא רבי אליעזר שאלה לחוד והזכרה לחוד:","רבי יהודה אומר העובר לפני התיבה כו':","ורמינהו עד מתי שואלין את הגשמים ר' יהודה אומר עד שיעבור הפסח ר' מאיר אומר עד שיעבור ניסן","אמר רב חסדא לא קשיא כאן לשאול כאן להזכיר מישאל שאיל ואזיל להזכיר ביו\"ט הראשון פסיק","אמר עולא הא דרב חסדא קשיא (משלי י, כו) כחומץ לשינים וכעשן לעינים ומה במקום שאינו שואל מזכיר במקום ששואל אינו דין שיהא מזכיר","אלא אמר עולא תרי תנאי אליבא דר' יהודה","רב יוסף אמר מאי עד שיעבור הפסח עד שיעבור שליח צבור ראשון היורד ביו\"ט ראשון של פסח","א\"ל אביי שאלה ביו\"ט מי איכא","א\"ל אין שואל מתורגמן וכי מתורגמן שואל דבר שאינו צריך לצבור אלא מחוורתא כדעולא","רבה אמר מאי עד שיעבור הפסח עד שיעבור זמן שחיטת הפסח וכתחילתו כן סופו מה תחילתו מזכיר אע\"פ שאינו שואל אף סופו מזכיר אע\"פ שאינו שואל","א\"ל אביי בשלמא תחילתו מזכיר הזכרה נמי ריצוי שאלה היא אלא סופו מאי ריצוי שאלה איכא אלא מחוורתא כדעולא","א\"ר אסי א\"ר יוחנן הלכה כר' יהודה א\"ל ר' זירא לר' אסי ומי אמר רבי יוחנן הכי והתנן בשלשה במרחשוון שואלין את הגשמים רבן גמליאל אומר בשבעה בו וא\"ר אלעזר הלכה כרבן גמליאל","א\"ל גברא אגברא קא רמית איבעית אימא לא קשיא כאן לשאול כאן להזכיר","והאמר ר' יוחנן במקום ששואל מזכיר ההוא להפסקה איתמר והאמר ר' יוחנן התחיל להזכיר מתחיל לשאול פסק מלשאול פוסק מלהזכיר","אלא לא קשיא הא לן הא להו מאי שנא לדידן דאית לן פירי בדברא לדידהו נמי אית להו עולי רגלים","כי קא\"ר יוחנן בזמן שאין בית המקדש קיים השתא דאתית להכי הא והא לדידהו ולא קשיא כאן בזמן שבית המקדש קיים כאן בזמן שאין בית המקדש קיים","ואנן דאית לן תרי יומי היכי עבדינן אמר רב מתחיל במוספין ופוסק במנחה ערבית ושחרית וחוזר במוספין","אמר להו שמואל פוקו ואמרו ליה לאבא אחר שעשיתו קודש תעשהו חול אלא אמר שמואל מתחיל במוספין ובמנחה ופוסק ערבית ושחרית וחוזר ומתחיל במוספין"],[[0,"הכי גרסינן ואיכא דאמרי לימא ר' יהושע היא אפי' תימא רבי אליעזר כו'","ולא גרסינן סברוה שאלה לחוד והזכרה לחוד דהא לא משתמע ממתני':"],[2,"עד אימתי שואלין את הגשמים","בסוף ימות הגשמים:"],[2,"עד שיעבור הפסח","דאמרינן כל חולו של מועד ותן טל ומטר:"],[2,"עד שיצא ניסן","וכדמפיק טעמא במתני':"],[3,"הכי גרסינן אמר רב חסדא כאן לשאול כאן להזכיר מישאיל שאיל ואזיל והזכרה ביו\"ט ראשון פוסק","לשאול שואל והולך עד שיעבור הפסח כדקתני עד מתי שואלין כו' להזכיר אינו מזכיר אלא בתפלת יוצר של יו\"ט ראשון:"],[4,"במקום שאינו שואל","ביו\"ט האחרון של חג שאינו מתפלל תפלתו תפלת חול דאין שאלה אלא בברכת השנים:"],[4,"מזכיר","גבורות גשמים כדאמר רבי יהודה האחרון מזכיר:"],[4,"במקום שהוא שואל","בחולו של מועד של פסח:"],[5,"תרי תנאי","חד אמר עד שיעבור הפסח שואלין כל שכן שמזכירין וחד אמר שאלה עד הפסח והזכרה שיכול להזכיר ביו\"ט מזכיר ביו\"ט הראשון של פסח בתפלת יוצר ובמוספין פוסק:"],[6,"רב יוסף אמר","האי דקתני עד אימתי שואלין עד שיעבור כו' ה\"ק עד שיעבור שליח צבור כו' והיינו כאידך רבי יהודה דמתני' דאמר הראשון מזכיר האחרון אינו מזכיר:"],[7,"שאלה ביו\"ט מי איכא","וכי מתפלל הוא תפלת חול שאתה אומר עד שיעבור הפסח דהיינו זמן שליח צבור של תפלת יו\"ט הראשון של פסח:"],[8,"אמר ליה אין שאלה דמתורגמן","בדרשה שהוא דורש אומר ברכת שאלה לבדה:"],[8,"דבר שאינו צריך לצבור","דכיון דזמן הפסקה הוא לאו אורח ארעא למישאל בצבור דבר שאינו צריך:"],[9,"עד שיעבור זמן שחיטת פסח","חצות יום דארבעה עשר עד שיעבור חצות דהיינו כל תפלת יוצר ואשמעינן ר' יהודה דבמנחה דערבי פסחים אע\"ג דמצלינן תפלת חול מפסיקינן ולא יאמר ותן טל ומטר ואע\"ג דמדכרינן עד למחר במוספין פוסק השאלה בתפלת מנחה של ערב יו\"ט הראשון והזכרה שיכול להזכיר ביום טוב מזכיר עד תפלת מוסף של יום טוב הראשון:"],[9,"כתחילתו","שהוא מזכיר תחלה ביום טוב אחרון של חג ואינו שואל עד לאחר החג כך בסופו אינו שואל במנחה ערב יו\"ט הראשון ומזכיר עד מוסף של יו\"ט ראשון והכא ליכא למיפרך שאלה ביו\"ט מי איכא:"],[10,"דהזכרה נמי צורך שאלה היא","שמרצה תחילה לפי שא\"א לו לשאול ביו\"ט וכיון דאיכא שאלה אבתריה מזכיר הוא לרצויי בעלמא:"],[10,"אבל סופו","למה הוא מזכיר הואיל ואינו צריך לשאול מכאן ואילך הא כיון דאפסקת מאתמול גלית אדעתך דלא ניחא לך בהו ואמאי מזכיר:"],[11,"הלכה כרבי יהודה","דאמר העובר לפני התיבה וכו':"],[11,"מי אמר רבי יוחנן הכי","דהלכה כרבי יהודה דמזכיר ביו\"ט האחרון:"],[11,"בשלשה במרחשון","הכי קים להו דהוה זמן גשמים כו':"],[11,"הלכה כרבן גמליאל","דאינו שואל עד שבעה במרחשון וקא ס\"ד דבמקום שהוא שואל מזכיר עד דמשני לקמן:"],[12,"כאן לשאול","בשבעה במרחשון:"],[12,"כאן להזכיר","מיו\"ט האחרון ור' יוחנן אית ליה דרבי אלעזר:"],[13,"והא א\"ר יוחנן במקום ששואל מזכיר","במקום שאינו שואל אינו מזכיר והיכי א\"ר יוחנן דהלכה כר' יהודה שמזכיר ביו\"ט האחרון הא ליכא שאלה דאין אומר ברכת השנים ביו\"ט:"],[13,"להפסקה איתמר","דכשהוא מפסיק לשאלה בערב הפסח פוסק נמי להזכרה דהכי משמע במקום ששואל מזכיר:"],[13,"והא תרוייהו איתמר","התחלה והפסקה:"],[13,"יתחיל לשאול","דהיינו בחול שיכול לשאול:"],[13,"פסק מלשאול","בערב הפסח פוסק מלהזכיר אלמא לא סבירא ליה כרבי יהודה והיכי אמר הלכה כמותו:"],[14,"הא לן והא להו","לבני בבל שיש לנו תבואה ופירות בשדה כל תשרי אין מזכירין עד שבעה במרחשון ושם שואלים כדאמר רבי יוחנן מתחיל להזכיר מתחיל לשאול:"],[14,"והא להו","לבני ארץ ישראל דקוצרין בניסן ואוספין בתשרי מזכירין בי\"ט האחרון כרבי יהודה דאמר רב אסי הלכה כמותו:"],[14,"בדברא","מדבר כלומר בשדות:"],[14,"אית להו עולי רגלים","ואם ירדו להן גשמים קשה להן בחזירתן:"],[15,"אלא כי א\"ר יוחנן","הלכה כר' יהודה דמזכיר מיו\"ט האחרון כו' בזמן שאין בהמ\"ק קיים וליכא עולי רגלים מזכיר:"],[15,"כאן בזמן שבית המקדש קיים","דאיכא עולי רגלים אינו מזכיר עד ז' במרחשון:"],[16,"אנן דאית לן תרי יומי","שני ימים טובים אחרונים שמיני ספק שביעי ותשיעי ספק שמיני לרבי יהודה דאמר מיו\"ט האחרון באיזה מהן מזכיר:"],[16,"מתחיל במוסף","של שמיני ספק שביעי דשמא יו\"ט האחרון הוא:"],[16,"ופוסק במנחה","שמא שביעי חול הוא ואין זמן הזכרה עד מוסף של מחר:"],[16,"ופוסק נמי בערבית ושחרית","של תשיעי ספק שמיני:"],[17,"לאבא","חברי:"],[17,"לאחר שעשיתו קודש","לשמיני ספק שביעי שהזכרת בו גבורות גשמים כרבי יהודה מיו\"ט האחרון:"],[17,"תעשהו חול","בתמיה: שמפסיק במנחה של אותו היום:"],[17,"ופוסק ערבית ושחרית","דלאו היינו תפלה של אותו היום:"]],[[11,"","ואמר ר' אלעזר הלכה כר\"ג דאמר דאין שואלין עד שבעה וכו'. פירוש ואת אמרת הלכה כר' יהודה בהא דקאמר במתני' רבי יהודה אומר העובר לפני התיבה בי\"ט האחרון של חג האחרון מזכיר והראשון אינו מזכיר ומדמינן לעיל שאלה להזכרה דפריך ורמינהו עד מתי שואלין את הגשמים עד שיעבור וכו' ומשני גברא אגברא וכו':"],[13,"","והא אמר רבי יוחנן במקום ששואלין הגשמים מזכיר. ומשני ההוא להפסקה פי' דבמקום שמפסיק מלשאול מפסיק מלהזכיר אבל מתחיל קודם להזכיר וטעמא הוי דהזכרה הוה ריצוי שאלה ומש\"ה ליכא חששא אם מזכיר קודם:"],[14,"","הא לן. פירוש לבני בבל עד לאחר שבעה במרחשון דאית להו פירי בדברא ובארץ ליכא חששא דהא יכולים פירותיהן להיות יבשים בלא הולכה למדבר:"],[14,"","והא להו. כי המתחיל להזכיר יתחיל לשאול:"]]],[["רבא אמר כיון שהתחיל שוב אינו פוסק וכן אמר רב ששת כיון שהתחיל שוב אינו פוסק","ואף רב הדר ביה דאמר רב חננאל אמר רב מונה עשרים ואחד יום כדרך שמונה עשרה ימים מר\"ה עד יוה\"כ ומתחיל וכיון שהתחיל שוב אינו פוסק והלכתא כיון שהתחיל שוב אינו פוסק:","\u0001מתני׳\u0002 עד מתי שואלין את הגשמים ר' יהודה אומר עד שיעבור הפסח ר' מאיר אומר עד שיצא ניסן שנאמר (יואל ב, כג) ויורד לכם גשם יורה ומלקוש בראשון:","\u0001גמ׳\u0002 א\"ל רב נחמן לר' יצחק יורה בניסן יורה במרחשון הוא (דתנן) יורה במרחשון ומלקוש בניסן א\"ל הכי אמר רבי יוחנן בימי יואל בן פתואל נתקיים מקרא זה דכתיב ביה (יואל א, ד) יתר הגזם אכל הארבה וגו' אותה שנה יצא אדר ולא ירדו גשמים ירדה להם רביעה ראשונה באחד בניסן","אמר להם נביא לישראל צאו וזרעו אמרו לו מי שיש לו קב חטים או קבים שעורין יאכלנו ויחיה או יזרענו וימות אמר להם אעפ\"כ צאו וזרעו נעשה להם נס ונתגלה להם מה שבכתלין ומה שבחורי נמלים","יצאו וזרעו שני ושלישי ורביעי וירדה להם רביעה שניה בחמשה בניסן הקריבו עומר בששה עשר בניסן נמצאת תבואה הגדילה בששה חדשים גדילה באחד עשר יום נמצא עומר הקרב מתבואה של ששה חדשים קרב מתבואה של אחד עשר יום","ועל אותו הדור הוא אומר (תהלים קכו, ה) הזורעים בדמעה ברנה יקצרו הלך ילך ובכה נושא משך הזרע וגו' מאי הלך ילך ובכה נושא משך וגו' א\"ר יהודה שור כשהוא חורש הולך ובוכה ובחזירתו אוכל חזיז מן התלם וזהו בא יבא ברנה","מאי נושא אלומותיו א\"ר חסדא ואמרי לה במתניתא תנא קנה זרת שיבולת זרתים","א\"ל רב נחמן לר' יצחק מאי דכתיב (מלכים ב ח, א) כי קרא ה' לרעב וגם בא אל הארץ שבע שנים בהנך שבע שנים מאי אכול","א\"ל הכי אמר רבי יוחנן שנה ראשונה אכלו מה שבבתים שניה אכלו מה שבשדות שלישית בשר בהמה טהורה רביעית בשר בהמה טמאה חמישית בשר שקצים ורמשים ששית בשר בניהם ובנותיהם שביעית בשר זרועותיהם לקיים מה שנאמר (ישעיהו ט, יט) איש בשר זרועו יאכלו","וא\"ל רב נחמן לר' יצחק מאי דכתיב (הושע יא, ט) בקרבך קדוש ולא אבוא בעיר משום דבקרבך קדוש לא אבוא בעיר א\"ל הכי א\"ר יוחנן אמר הקב\"ה לא אבוא בירושלים של מעלה עד שאבוא לירושלים של מטה","ומי איכא ירושלים למעלה אין דכתיב (תהלים קכב, ג) ירושלם הבנויה כעיר שחוברה לה יחדיו","וא\"ל רב נחמן לר' יצחק מאי דכתיב (ירמיהו י, ח) ובאחת יבערו ויכסלו מוסר הבלים עץ הוא א\"ל הכי א\"ר יוחנן אחת היא שמבערת רשעים בגיהנם מאי היא ע\"ז כתיב הכא מוסר הבלים עץ הוא וכתיב התם (ירמיהו י, טו) הבל המה מעשה תעתועים","וא\"ל רב נחמן לר' יצחק מ\"ד (ירמיהו ב, יג) כי שתים רעות עשה עמי תרתין הוא דהוו עשרין וארבע שביקא להו א\"ל הכי א\"ר יוחנן אחת שהיא"],[[0,"רבא אמר כיון שהתחיל","בשמיני ספק שביעי שוב אינו פוסק:"],[1,"הדר ביה","ממאי דאמר פוסק:"],[1,"מונה כ\"א יום","מראש השנה עד שמיני ספק שביעי של חג כדרך שמונה מר\"ה עד יוה\"כ י' ימים שמתחיל למנות מיום ראשון של ר\"ה ומזכיר מכאן ואילך וזהו שמזכיר בשמיני ספק שביעי שהוא כ\"ב שוב אינו פוסק והא דמתחילין אנו למנות מיום א' דהא דאנו עושין ב' ימים לאו משום ספק דשמא עיברו לאלול דהא אנן בקיאינן בקביעא דירחא אלא משום דמנהג אבותינו בידינו ל\"א מונה כ\"א יום כדרך שמונה כו' כלומר אם עיברו אלול לא יחשוב מיום ראשון של ר\"ה כ\"א יום שאם כן לא ימצאו בידו אלא כ' וכלים ביום טוב שביעי יום נטילת ערבה אלא מיום שמתחילין למנות עשרה ימים לעשות בעשירי יוה\"כ יתחיל למנות באלו שבכך לא יטעה שיום הכפורים יום אחד לבד וידע מהיכן התחילו למנות לו וביום שכלין כ\"א דהיינו ביום טוב אחרון מתחיל להזכיר וכיון שהתחיל שוב אינו פוסק:"],[3,"א\"ל רב נחמן לרב יצחק יורה בניסן הוא","דכתיב ויורד לכם גשם מורה ומלקוש בראשון בתמיה:"],[3,"והא במרחשון הוא","כדתניא לקמן ובספרי הוא:"],[3,"יורה ומלקוש","מפרש לקמן:"],[3,"אמר ליה","ודאי במרחשון הוא ומקרא זה בימי יואל בן פתואל נתקיים שיורה ומלקוש היה בראשון ע\"י נס שהיה רעב שבע שנים דכתיב כי קרא ה' לרעב וגם בא אל הארץ שבע שנים וכתיב יתר הגזם אכל הארבה וגו':"],[3,"הכי גרסינן יצא אדר ולא ירדו גשמים","ולא זרעו רוב אדר לא גרסינן:"],[3,"רביעה ראשונה","התחלת גשמים ולקמן (תענית דף ו:) מפרש רביעה שמרביע את הארץ:"],[4,"או יזרענו וימות","ברעב קודם שתגדל התבואה החדשה שלא יהיה לו מה יאכל:"],[4,"נעשה להם נס כו'","והיינו דכתיב ושלמתי לכם את השנים אשר אכל הארבה וגו':"],[4,"נתגלה להם תבואה שבחורי נמלים ומה שבכתלים","שאצרו העכברים:"],[5,"יצאו וזרעו","וזרעו מה שבידם:"],[5,"שני","בניסן ושלישי ורביעי ומה שמצאו אכלו ולאחר שזרעו ירדו להם גשמים בה' בניסן והקריבו עומר בט\"ז בניסן מאותה תבואה חדשה:"],[5,"הגדילה בששה חדשים","מתשרי ועד ניסן:"],[5,"בי\"א יום","מחמשה בניסן עד ט\"ז בו:"],[6,"הזורעים בדמעה ברנה יקצורו","שלא היה להן מה לאכול:"],[6,"מאי הלך ילך ובכה","אם לבני אדם כבר נאמר הזורעים בדמעה ברנה יקצורו אלא על השור הכתוב אומר:"],[6,"בהליכתו","לחרוש התלם:"],[6,"ובחזירתו אוכל חזיז","שחת מן התלם שזרעו בהליכתן שכשהוא זורע מיד מתחלת ליגדל:"],[7,"מאי בא יבוא ברנה נושא אלומותיו","אם מפני התבואה שיש להם לאכול הרי כבר אמור ברנה יקצורו:"],[7,"שבולת זרתים","זהו נס גדול מה שאין כן דרך כל תבואה שהקנה פי שלשה וארבעה בשבולת:"],[8,"כי קרא ה' לרעב","בימי יהורם בן אחאב נאמר:"],[9,"מה שבשדות","ספיחים ומה שנשתייר בשדות:"],[9,"אכלו בשר בניהם","מקצתם:"],[10,"משום דבקרבך קדוש","שאתה מטיב מעשיך לא יבא הקב\"ה בעיר:"],[10,"לא אבא בירושלים כו'","והכי קאמר עד שיהא בקרבך קדוש למטה דהיינו ירושלים לא אבוא בעיר שלמעלה:"],[11,"ירושלים הבנויה כעיר שחוברה לה יחדיו","ירושלים שלמטה תהא בנויה כעיר שחוברה לה שהיא כיוצא בה חבירתה ודוגמתה מכלל דאיכא ירושלים אחריתי והיכן אם לא למעלה:"],[12,"ובאחת יבערו ויכסלו מוסר הבלים עץ הוא","אי לאו גזרה שוה היה משמע אטומים כעץ לקבל מוסר ולשוא היו לוקין:"],[12,"באחת","עבירה שהן עושין יתבערו הכסילים רשעים:"],[13,"עשרים וארבע שביקא להו","בתמיה בפרשת התשפוט (יחזקאל כב) כ\"ד עבירות שעברו ל\"א שעברו על כ\"ד ספרים:"]],[[0,"","רבא אמר כיון שהתחיל שוב אינו פוסק. כלומר כיון שהתחיל ביום ראשון של אחרונים שוב אינו פוסק וכן הפסק:"],[3,"","יורה במרחשון הוא. פי' אקרא דכתיב ויורד לכם גשם מורה ומלקוש בראשון פריך דמתני' אפשר לתרץ דאמלקוש קסמיך אבל ביורה מודה דבמרחשון:"],[6,"","ובחזירתו אוכל חזיז מן התלם וכו' וקשיא הא דקאמר לעיל נמצא הגדילה בששה חדשים גדילה באחד עשר יום הוה ליה למימר גדילה בתליסר ובי\"ד יומי שהרי מיד מתחלת ליגדל ושמא י\"ל דלכל המאוחרת שנזרעה בשלישית קאמר נמצא גדילה בי\"א יום וצ\"ע:"],[10,"","לא אבוא בעיר. פירוש בעיר ר\"ל בעיר ממש וי\"מ פשטיה דקרא בעיר בשנאה כלומר לא אבוא בשנאה ועיר הוי ל' שנאה כמו ומלאו פני תבל ערים (ישעיהו יד):"]]],[["שקולה כשתים ומאי ניהו ע\"ז דכתיב (ירמיהו ב, יג) כי שתים רעות עשה עמי אותי עזבו מקור מים חיים לחצוב להם בארות בארות נשברים וכתיב בהו (ירמיהו ב, י) כי עברו איי כתיים וראו וקדר שלחו והתבוננו מאד וגו' ההימיר גוי אלהים והמה לא אלהים ועמי המיר כבודו בלא יועיל","תנא כותיים עובדים לאש וקדריים עובדין למים ואע\"פ שיודעים שהמים מכבין את האש לא המירו אלהיהם ועמי המיר כבודי בלא יועיל","וא\"ל רב נחמן לר' יצחק מ\"ד (שמואל א ח, א) ויהי כאשר זקן שמואל ומי סיב שמואל כולי האי והא בר נ\"ב הוה דאמר מר מת בנ\"ב שנה זהו מיתתו של שמואל הרמתי","א\"ל הכי א\"ר יוחנן זקנה קפצה עליו דכתיב (שמואל א טו, יא) נחמתי כי המלכתי את שאול אמר לפניו רבש\"ע שקלתני כמשה ואהרן דכתיב (תהלים צט, ו) משה ואהרן בכהניו ושמואל בקוראי שמו מה משה ואהרן לא בטלו מעשה ידיהם בחייהם אף אני לא יתבטל מעשה ידי בחיי","אמר הקב\"ה היכי אעביד לימות שאול לא קא שביק שמואל לימות שמואל אדזוטר מרנני אבתריה לא לימות שאול ולא לימות שמואל כבר הגיעה מלכות דוד ואין מלכות נוגעת בחברתה אפילו כמלא נימא","אמר הקב\"ה אקפיץ עליו זקנה היינו דכתיב (שמואל א כב, ו) ושאול יושב בגבעה תחת האשל ברמה וכי מה ענין גבעה אצל רמה אלא לומר לך מי גרם לשאול שישב בגבעה שתי שנים ומחצה תפלתו של שמואל הרמתי","ומי מידחי גברא מקמי גברא אין דא\"ר שמואל בר נחמני א\"ר (יוחנן) מ\"ד (הושע ו, ה) על כן חצבתי בנביאים הרגתים באמרי פי במעשיהם לא נאמר אלא באמרי פי אלמא מידחי גברא מקמי גברא","רב נחמן ור' יצחק הוו יתבי בסעודתא א\"ל רב נחמן לר' יצחק לימא מר מילתא א\"ל הכי א\"ר יוחנן אין מסיחין בסעודה שמא יקדים קנה לושט ויבא לידי סכנה","בתר דסעוד א\"ל הכי א\"ר יוחנן יעקב אבינו לא מת א\"ל וכי בכדי ספדו ספדנייא וחנטו חנטייא וקברו קברייא א\"ל מקרא אני דורש שנאמר (ירמיהו ל, י) ואתה אל תירא עבדי יעקב נאם ה' ואל תחת ישראל כי הנני מושיעך מרחוק ואת זרעך מארץ שבים מקיש הוא לזרעו מה זרעו בחיים אף הוא בחיים","א\"ר יצחק כל האומר רחב רחב מיד נקרי א\"ל רב נחמן אנא אמינא ולא איכפת לי א\"ל כי קאמינא ביודעה ובמכירה (ובמזכיר את שמה)","כי הוו מיפטרי מהדדי א\"ל ליברכן מר אמר ליה אמשול לך משל למה\"ד לאדם שהיה הולך במדבר והיה רעב ועיף וצמא ומצא אילן שפירותיו מתוקין וצילו נאה ואמת המים עוברת תחתיו אכל מפירותיו ושתה ממימיו וישב בצילו","וכשביקש לילך אמר אילן אילן במה אברכך אם אומר לך שיהו פירותיך מתוקין הרי פירותיך מתוקין שיהא צילך נאה הרי צילך נאה שתהא אמת המים עוברת תחתיך הרי אמת המים עוברת תחתיך אלא יהי רצון שכל נטיעות שנוטעין ממך"],[[0,"ששקולה כשתים","דכותיים וקדריים כדמפרש שהרעו משניהן לא הבינו מהן דכותיים וקדרים אע\"פ שיראתם פחותה לא רצו להמיר ועמי המירו באחר ולא עוד אלא בלא יועיל:"],[2,"והאמר מר","במועד קטן (דף כח.) זו מיתתו של שמואל הרמתי ולא כרת היא במסכת שמחות (פ\"ג) מפרש מת בכך שנים זו היא מיתת כרת בכך וכך זו היא מיתת אסכרה:"],[2,"ימיו של שמואל נ\"ב שנה","דכתיב עד יגמל הנער וגו' דשיבירי\"ר בלע\"ז וכ\"ד חדשים נקרא תינוק וכתיב (שמואל א א׳:כ״ב) וישב שם עד עולם עולמו של לוי חמשים שנה שנאמר (במדבר ח׳:כ״ה) ומבן חמשים שנה ישוב מצבא העבודה (בבכורות) ירושלמי ובסדר עולם תמצא כשני דפין תוספת על זה:"],[3,"קפצה","הלבין שערו:"],[3,"נחמתי","ורצה הקב\"ה להורגו מיד:"],[3,"שקלתני כמשה ואהרן דכתיב משה ואהרן בכהניו ושמואל בקוראי שמו וגו'","שוין הן:"],[3,"מעשה ידיהן","יהושע אף הוא היה תלמידו של אהרן כדאמרי' בעירובין (דף נד:) יצא משה ושנה להן אהרן פירקו:"],[4,"כי זוטר","בחור:"],[4,"מרנני כולי עלמא אבתריה","דאמרי מדמית זוטר שמא ח\"ו עבירה היתה בו:"],[5,"וכי מה ענין גבעת בנימין אצל רמה","בהר אפרים:"],[5,"שישב ב' שנים ומחצה","כדמפרש בסדר עולם שמלך מחצית שנת עשתי עשרה ושנים עשרה ושלשה עשר ושמואל מת בתוך שנת שלש עשרה לסוף שמונה חדשים:"],[6,"מי מידחי גברא כו'","דאידחי שמואל מקמי דוד:"],[6,"במעשיהם לא נאמר","דמשמע בעבור חטא:"],[6,"אלא באמרי פי","מפני דבר שגזרתי כגון האי מעשה דשמואל:"],[7,"ה\"ג לימא לן מר מידי","ולא גרסינן חד לחבריה:"],[7,"שמא יקדים קנה","כשיוציא הקול נפתח אותו כובע שעל פי הקנה ונכנס בו המאכל ומסתכן ולפיכך לא אומר לך כלום מאכל ומשתה הולך דרך הושט:"],[8,"לא מת","אלא חי הוא לעולם:"],[8,"בכדי","וכי בחנם ספדו ספדיא וחנטו חנטיא דכתיב ביה (בראשית נ) ויחנטו (אותו) ויספדו (לו):"],[8,"מקרא אני דורש","והאי דחנטו חנטיא סבורים היו שמת:"],[8,"מה זרעו בחיים","כשהוא מקבץ את ישראל מארץ שבים החיים הוא מקבץ שהן בשבי שהמתים אינן בשבי:"],[8,"אף הוא בחיים","שיביאנו בגולה כדי לגאול את בניו לעיניו כמו שמצינו במצרים וירא ישראל וגו' ודרשינן ישראל סבא ודחנטו חנטיא נדמה להם שמת אבל חי היה:"],[9,"כל האומר רחב רחב מיד נקרי","נעשה בעל קרי:"],[9,"לא איכפת לי","איני חושש:"],[9,"ביודעה","היינו נמי מכירה:"],[10,"כי הוה מיפטר","רב נחמן מרב יצחק:"],[10,"ופירותיו מתוקין","לרעב:"],[10,"והיה צילו נאה","שזה צריך לאדם עייף לנוח תחתיו:"],[10,"ואמת המים","לצמא:"]],[[2,"","ומי סיב שמואל והא בר נ\"ב שנין הוה וכו'. ועתה (אפי') חיי שמואל נ\"ב שנה שהרי בשנה ראשונה שהיה עלי ממונה לכ\"ג נולד שמואל כדכתיב (שמואל א א׳:ט׳) ועלי יושב כלומר אותו יום נתיישב ונתמנה ועלי היה נביא ושופט ארבעים שנה כדמפרש בקרא ושמואל היה נביא ושופט י' שנים קודם מלכות שאול כדאיתא בסדר עולם נמצא שהיה שמואל בן מ\"ט שנה כשפסק מלהיות שופט וחצי שנה שבשנה ראשונה שהיה עלי נביא נולד ותרתין שנין ופלגא דשאול המלך הרי נ\"ב שנין ולהכי קא פריך ומי סיב ומורי ש\"י חשיב הני ארבעים שנה דעלי קודם שנשבה הארון ובאותו יום שנשבה מת כדכתיב ויהי כהזכירו ארון האלהים ויפול אחורנית ותשבר מפרקתו וגו' והארון היה בבית אבינדב בגבעה עשרים שנה כדכתיב (שמואל א ז׳:ב׳) וירבו הימים ויהיו עשרים שנה וינהו כל בית ישראל אחרי ה' ומיד כשמלך דוד בירושלים דהיינו לאחר כשמלך בחברון שבע שנים ומחצה הביאו לשם צא וחשוב ארבעים שחיה עלי עם עשרים שנה שהיה הארון בבית אבינדב היינו ששים נמצא שהיה ששים שנה משנולד שמואל עד שבא הארון בירושלים אע\"ג דנולד בשנה הראשונה א\"כ נכי לפחות חצי שנה דהריון אותן שבעה חדשים היה הארון בשדה פלשתים דלא קא חשיב ומלי' להנהו דשעת הריון נמצא שהיה שמונה שנים ממיתת שמואל עד שבא הארון לירושלים שהרי היה ששה חדשים ממיתת שמואל קודם שמשחו דוד למלך בחברון ומלך שם שבע שנים ומחצה ומיד מלך בירושלים והביא הארון ועתה הסר שמונה שנים מן ששים שנים שהיה משנולד שמואל עד הבאת הארון וישאר נ\"ב שנים:"],[8,"","יעקב אבינו לא מת. וכן משמע דכתיב ויגוע ולא כתיב וימת כדמפרש בסוטה (דף יג.) גבי מעשה דחושים:"],[9,"","ביודעה ומכירה קאמינא. פי' ביודעה שבא עליה ומכירה שראה אותה:"]]],[["יהיו כמותך אף אתה במה אברכך אם בתורה הרי תורה אם בעושר הרי עושר אם בבנים הרי בנים אלא יהי רצון שיהו צאצאי מעיך כמותך:","ת\"ר יורה שמורה את הבריות להטיח גגותיהן ולהכניס את פירותיהן ולעשות כל צרכיהן דבר אחר שמרוה את הארץ ומשקה עד תהום שנאמר (תהלים סה, יא) תלמיה רוה נחת גדודיה ברביבים תמוגגנה צמחה תברך דבר אחר יורה שיורד בנחת ואינו יורד בזעף","או אינו יורה אלא שמשיר את הפירות ומשטיף את הזרעים ומשטיף את האילנות ת\"ל מלקוש מה מלקוש לברכה אף יורה לברכה או אינו מלקוש אלא שמפיל את הבתים ומשבר את האילנות ומעלה את הסקאין ת\"ל יורה מה יורה לברכה אף מלקוש לברכה","ויורה גופיה מנלן דכתיב (יואל ב, כג) ובני ציון גילו ושמחו בה' אלהיכם כי נתן לכם את המורה לצדקה ויורד לכם גשם מורה ומלקוש בראשון:","ת\"ר יורה במרחשון ומלקוש בניסן אתה אומר יורה במרחשון ומלקוש בניסן או אינו אלא יורה בתשרי ומלקוש באייר ת\"ל בעתו","מלקוש אמר רב נהילאי בר אידי אמר שמואל דבר שמל קשיותיהן של ישראל דבי ר' ישמעאל תנא דבר שממלא תבואה בקשיה במתניתא תנא דבר שיורד על המלילות ועל הקשין","ת\"ר יורה במרחשון ומלקוש בניסן אתה אומר יורה במרחשון או אינו אלא בחדש כסליו ת\"ל (דברים יא, יד) בעתו יורה ומלקוש מה מלקוש בעתו אף יורה בעתו (כיון שיצא ניסן וירדו גשמים אינו סימן ברכה)","תניא אידך יורה במרחשון ומלקוש בניסן דברי ר\"מ וחכמים אומרים יורה בכסליו","מאן חכמים אמר רב חסדא ר' יוסי היא דתניא איזו היא רביעה ראשונה הבכירה בשלשה במרחשון בינונית בשבעה בו אפילה בשבעה עשר בו דברי ר\"מ ר' יהודה אומר בשבעה ובי\"ז ובעשרים ושלשה","ר' יוסי אומר בי\"ז ובעשרים ושלשה ובראש חדש כסליו וכן היה ר' יוסי אומר אין היחידים מתענין עד שיגיע ראש חדש כסליו","אמר רב חסדא הלכה כר' יוסי אמימר מתני להא דרב חסדא בהא לישנא בשלשה במרחשון שואלין את הגשמים רבן גמליאל אומר בשבעה בו אמר רב חסדא הלכה כרבן גמליאל","כמאן אזלא הא דתניא ר\"ש בן גמליאל אומר גשמים שירדו שבעה ימים זה אחר זה אתה מונה בהן רביעה ראשונה ושניה ושלישית כמאן כר' יוסי אמר רב חסדא הלכה כר' יוסי","בשלמא רביעה ראשונה לשאול שלישית להתענות שניה למאי אמר ר' זירא לנדרים דתנן"],[[0,"יהיו כמותך","בתורה ולעושר וכבוד:"],[1,"יורה","ונתתי מטר ארצכם בעתו יורה ומלקוש (דברים י״א:י״ד):"],[1,"יורה","רביעה ראשונה היורדת במרחשון כדלקמן למה נקרא יורה שמורה להן להטיח גגותיהן בטיח של טיט שלא יטפו גשמים בבית:"],[1,"ולהכניס פירותיהן","שהניחו בשדות לייבשן עד עכשיו:"],[1,"כל צרכיהן","שאר דברים הצריכים לימות הגשמים:"],[1,"תלמיה רוה","כשאתה מרוה תלמי חרישה של ארץ ישראל:"],[1,"נחת הוא לגדודיה","בני אדם היינו פשט המקרא ולקמיה דריש שאפי' גייסות פוסקות בו:"],[1,"שיורד בנחת","והכי משמע יורה כאדם שמורה לתלמידיו בנחת דכתיב (קהלת ט׳:י״ז) דברי חכמים בנחת נשמעים אי נמי לשון חץ יורה ההולך ביושר ואינו נוטה לכאן ולכאן לשון אחר שמתכוין לארץ ואינו יורד בזעף בספרי:"],[2,"ה\"ג או אינו אלא ששוטף את הזרעים","כלומר דעד השתא אמרינן יורה לברכה או אינו אלא יורה לשון קללה כמו ירה יירה (שמות י״ט:ה׳) ששובר הכל או לשון חץ היורה והכי משמע קרא והיה אם שמוע תשמעו אל מצותי וגו' ואם לאו ונתתי מטר ארצכם יורה לרעה מלתא בעלמא הוא ואורחא דברייתא למתני כי האי גוונא:"],[2,"משיר פירותיהן","שעודן באילן כגון אתרוגים או רמונים או סופי תאנים ולא גרסינן שוטף את הגרנות דגרנות במרחשון ליכא:"],[2,"מה מלקוש לברכה","שא\"א לדורשו לשבר גרנות ולהשיר פירות שאינם מצויים באותו הפרק ואי אתה יכול לדורשו אלא לטובה שיורד על המלילות ועל הקשין וממלא את התבואה בקשיה:"],[2,"","הדר אמר דלמא מלקוש קללה הוא והכי משמע שמל וקשה כלומר מל את הבתים והאילנות שמפילן ומשברן וקשה לתבואה:"],[2,"שמפיל את הבתים","ומשמעו כדלקמן שמל קשיותן של ישראל אי נמי שמל דבר הקשה חותך ומשבר את הבתים כלומר אין בו תקלת גרנות והשרת פירות לפי שא\"א לו:"],[2,"שמעלה סקאים","וברכה דקרא למילוי מים בורות שיחין ומערות גימגום:"],[2,"סקאי","מין ארבה כדמתרגם הצלצל (דברים כח) סקאה ומלקוש לשון ארבה כמו והנה לקש אחר גזי המלך (עמוס ז׳:א׳):"],[3,"את המורה לצדקה","אלמא יורה לטובה:"],[4,"ה\"ג או אינו אלא יורה בתשרי ומלקוש באייר","שיש עדין מלילות וקשין:"],[4,"ת\"ל בעתו","יורה במרחשון ומלקוש בניסן שכך היא העת והזמן ויפה הוא כדלקמן דזמן רביעה ראשונה במרחשון הוא אית ספרים דכתוב בהו או אינו אלא בכסליו דזמן יורה בכסליו הוא וכרבנן דפליגי עליה דר\"מ לקמן ת\"ל בעתו יורה ומלקוש מה מלקוש בעתו אף יורה בעתו דמלקוש זהו שיורד על המלילות ועל הקשין וזהו ניסן שיש בו קשין ומלילו:"],[5,"דבר שמל קשיותן של ישראל","שכשאינו יורד חוזרין ישראל בתשובה ומתענין ועושין צדקות:"],[5,"שממלא תבואה בקשיה","ומשלימה:"],[5,"מלילות","ראשי שיבולות שאדם מולל בידו כדכתיב (דברים כ״ג:כ״ו) וקטפת מלילות בידך:"],[5,"וקשין","קנה:"],[8,"הי רביעה","איזה זמן רביעה:"],[8,"בכירה","ראשונה ולקמן מפרש למאי הלכתא נינהו יורה יש בו ג' זמני גשמים:"],[8,"אפילה","אחרונה כמו כי אפילות הנה (שמות ט׳:ל״ב):"],[8,"ר' יהודה אומר","בכירה בז' במרחשון ובינונית בי\"ז ואפילה בכ\"ג וכולהו הני תלתא יורה קרי להו:"],[9,"אין היחידים מתענין כו'","דאמרינן בסמוך שלישית להתענות והואיל וזמן שלישית בראש חדש הוא אין ליחידים להתענות:"],[9,"יחידים","חסידים והכי אמרינן במתני' לקמן (תענית דף י.) הגיע י\"ז במרחשון ולא ירדו גשמים התחילו היחידים להתענות שמכאן ואילך זמן רביעה אפילה לר\"מ דסתם מתני' ר\"מ וה\"נ אמר ר' יוסי דאין מתענין עד ר\"ח כסליו דהיינו רביעה אפילה והיינו כחכמים דאמרי יורה בכסליו:"],[10,"אמר רב חסדא הלכה כר' יוסי","ואמימר תני להא דאמר רב חסדא הלכה כרבן גמליאל דאינו שואל עד ז' במרחשון:"],[11,"ז' ימים בזה אחר זה","שירדו גשמים עכשיו ופסקו עד יום שביעי וירדו ז' ימים זה אחר זה אתה מונה בהן ראשונה ושניה ושלישית:"],[11,"כר' יוסי","דאליבא דר' יוסי הכי הוו בין רביעה ראשונה ושניה או שניה ושלישית דראשונה בי\"ז ושניה בכ\"ג דהיינו ז' ימים עם שנים ימי רביעה ומכ\"ג עד ל' ז' ימים בלא יום רביעה אחרונה דלכולהו תנאי לא הוי הכי דלר\"מ דאמר ראשונה בג' ושניה בז' ליכא בין זו לזו אלא ארבעה ימים בין שניה לשלישית יש י' ימים ולר' יהודה בין ראשונה לשניה י' ימים אבל בין שניה לשלישית יש יותר:"],[11,"","נראה לרבי דהכי גרסינן אמר רב חסדא הלכה כר' יהודה דאמר בכירה בז' במרחשון ואז מתחילין לשאול כדלקמן (תענית דף י.):"],[12,"ראשונה לשאול","מכאן ואילך ותן טל ומטר:"],[12,"שלישית להתענות","שאם לא ירדו גשמים עד זמן רביעה שלישית אפי' פעם אחת מתענין היחידים שני וחמישי ושני:"]],[[2,"","מלקוש לברכה או אינו אלא שמפיל הבתים ומשבר האילנות וכו'. צ\"ע אמאי לא קאמר ומשבר הגרנות ומשיר את הפירות כדלעיל:"],[11,"","גשמים שירדו ז' ימים זה אחר זה ולא פסקו אתה מונה בהן רביעה ראשונה ושניה. כיון דלא פסקו ז' ימים דאין בין י\"ז לכ\"ג אלא ז' ימים י\"ז י\"ח י\"ט כ' כ\"א כ\"ב כ\"ג אבל לא גרסינן ושלישית שהרי אם יתחיל בכ\"ג וירדו ז' ימים רצופים אכתי לא תמצא רביעה שלישית דאיכא ח' ימים מכ\"ג עד ר\"ח כסליו ואנשי נרבונ\"א גורסין גשמים שירדו ז' ימים זה אחר זה אתה מונה בהם רביעה שניה ושלישית כיצד הגשמים התחילו באמצע היום וירדו ז' ימים רצופים א\"כ ירדו עד חצי יום של ר\"ח מעת לעת:"]]],[["הנודר עד הגשמים משירדו גשמים עד שתרד רביעה שניה","רב זביד אמר לזיתים דתנן מאימתי כל אדם מותרין בלקט בשכחה ובפאה משילכו הנמושות בפרט ובעוללות משילכו עניים בכרם ויבואו בזיתים משתרד רביעה שניה","מאי נמושות אמר ר' יוחנן סבי דאזלי אתיגרא ר\"ל אמר לקוטי בתר לקוטי","רב פפא אמר כדי להלך בשבילי הרשות דאמר מר מהלכין כל אדם בשבילי הרשות עד שתרד רביעה שניה","רב נחמן בר יצחק אמר לבער פירות שביעית דתנן עד מתי נהנין ושורפין בתבן ובקש של שביעית עד שתרד רביעה שניה","מאי טעמא דכתיב (ויקרא כה, ז) ולבהמתך ולחיה אשר בארצך כל זמן שחיה אוכלת בשדה האכל לבהמתך בבית כלה לחיה מן השדה כלה לבהמתך מן הבית","אמר רבי אבהו מאי לשון רביעה דבר שרובע את הקרקע כדרב יהודה דאמר רב יהודה מיטרא בעלה דארעא הוא שנאמר (ישעיהו נה, י) כי כאשר ירד הגשם והשלג מן השמים ושמה לא ישוב כי אם הרוה את הארץ והולידה והצמיחה","ואמר רבי אבהו רביעה ראשונה כדי שתרד בקרקע טפח שניה כדי לגוף בה פי חבית אמר רב חסדא גשמים שירדו כדי לגוף בהן פי חבית אין בהן משום ועצר","ואמר רב חסדא גשמים שירדו קודם ועצר אין בהן משום ועצר","אמר אביי לא אמרן אלא קודם ועצר דאורתא אבל קודם ועצר דצפרא יש בהן משום ועצר דאמר רב יהודה בר יצחק הני ענני דצפרא לית בהו מששא דכתיב (הושע ו, ד) מה אעשה לך אפרים מה אעשה לך יהודה וחסדכם כענן בקר וגו'","א\"ל רב פפא לאביי והא אמרי אינשי במפתח בבי מיטרא בר חמרא מוך שקך וגני לא קשיא הא דקטיר בעיבא הא דקטיר בענני","אמר רב יהודה טבא לשתא דטבת ארמלתא איכא דאמרי דלא ביירי תרביצי ואיכא דאמרי דלא שקיל שודפנא איני והאמר רב חסדא טבא לשתא דטבת מנוולתא לא קשיא הא דאתא מיטרא מעיקרא הא דלא אתא מיטרא מעיקרא","ואמר רב חסדא גשמים שירדו על מקצת מדינה ועל מקצת מדינה לא ירדו אין בהן משום ועצר איני והכתיב (עמוס ד, ז) וגם אנכי מנעתי מכם את הגשם בעוד שלשה חדשים לקציר והמטרתי על עיר אחת ועל עיר אחת לא אמטיר חלקה אחת תמטר וגו' ואמר רב יהודה אמר רב שתיהן לקללה","לא קשיא הא דאתא טובא הא דאתא כדמבעי ליה אמר רב אשי דיקא נמי דכתיב תמטר תהא מקום מטר ש\"מ","א\"ר אבהו מאימתי מברכין על הגשמים משיצא חתן לקראת כלה","מאי מברך אמר רב יהודה אמר רב מודים אנחנו לך ה' אלהינו על כל טפה וטפה שהורדת לנו ור' יוחנן מסיים בה הכי אילו פינו מלא שירה כים ולשוננו רנה כהמון גליו כו' עד אל יעזבונו רחמיך ה' אלהינו ולא עזבונו ברוך רוב ההודאות","רוב ההודאות ולא כל ההודאות אמר רבא אימא אל ההודאות אמר רב פפא הלכך"],[[0,"הנודר עד הגשמים","דאמר קונם אם אהנה מדבר זה עד הגשמים:"],[0,"עד שתרד רביעה שניה","בנדרים הולכין אחר לשון בני אדם ואין קורין גשמים לראשונה עד שתרד שניה שמכאן ואילך מקולקלות הדרכים ומאוסות מפני הגשמים ל\"א עד הגשמים משמע תרי דהיינו רביעה שניה:"],[1,"כל אדם","אפילו העשירים:"],[1,"פרט","לא תפאר אחריך (דברים כד) לא תטול תפארתו ממנו:"],[1,"משילכו הנמושות","בשדה דמכאן ואילך נתייאשו שאר העניים לפי שיודעין אם נשאר לקט שכחה ופאה נמושות נטלום:"],[1,"נמושות","לשון ממשש:"],[1,"משילכו עניים בכרם ויבאו","כלומר שלקטו וחזרו ובאו פעם שניה והשתא מסחי דעתייהו עניים:"],[1,"משתרד רביעה שניה","דעד ההיא שעתא לקטו הכל:"],[2,"דאזלי אתיגרא","הולכין בנחת ומעייני טפי מחזיק בפלך (שמואל ב ג) מתרגמא אתיגרא:"],[2,"לקוטי בתר לקוטי","עני מוליך בנו אחריו שמכאן ואילך פוסקים שאר עניים מללקוט:"],[3,"ה\"ג רב פפא אמר לשבילי הרשות","כלומר שיש רשות מב\"ד לעוברי דרכים לקצר שבילן לילך בשדות:"],[3,"עד שתרד רביעה שניה","שמכאן ואילך גדלה התבואה וקשה לה דישת הרגל דאמר מר בפרק מרובה בתנאים שהתנה יהושע מהלכין בשבילי הרשות וכו':"],[4,"בתבן וקש של שביעית","ספיחים שגדלו בשביעית דיש בהן איסור שביעית או תבואה שגדלה בשביעית לאחר שנכנסה:"],[5,"כלה לחיה מן השדה","לשון זכר כמו (בראשית י״ח:כ״א) עשו כלה כלומר כלה האוכל:"],[5,"כלה לבהמתך","כמו כלה בחימה כלה ואינימו (תהילים נ״ט:י״ד) ומשירדה רביעה שניה מכאן ואילך אין תבן וקש בשדות שהגשמים עושין אותן זבל:"],[6,"והולידה","כאדם שמוליד:"],[7,"גשמים ברביעה ראשונה","אם באין כל כך שנימס הקרקע יפין הן ואין צריך להתענות:"],[7,"לגוף בה פי חבית","ששותת מן המים עד שנעשה תיחוח כל כך שיכול לעשות מגופת חבית בלא תוספת מים:"],[7,"אין בהם משום ועצר","אין זו קללה של ועצר את השמים:"],[8,"קודם ועצר","קודם זמן ק\"ש דכתיב ביה ועצר את השמים אע\"פ שלא יהיה רוב גשמים:"],[9,"אבל ירדו קודם ועצר דצפרא יש בהן משום ועצר","הואיל ולא ירדו ביום ואין יפין לעולם:"],[9,"לית בהו מששא","ואין שנתן מתברכת:"],[9,"וחסדכם כענן בקר","שאין בו ממש:"],[10,"מיטרא במיפתח בבי","אם יורדין בבקר כשפותחין הפתחים יקפל החמר שמוכר תבואה את שקו ליכנס לישן מפני שהשנה מתברכת ויהיה שובע בעולם ולא ישתכר במכירת תבואתו אלמא יפין הן:"],[10,"דקטיר בעיבא","אם נתקשרו שמים בעננים עבים ולא קלושים אין בהם משום ועצר:"],[10,"דקטיר בעננא","שהיא קלושה מעב אין בו ממש:"],[11,"טבא לשתא","אשריה כלומר טובה יש לשנה דטבת ארמלתא שאין גשמים יורדין בה להרביע את הארץ:"],[11,"איכא דאמרי דלא ביירי תרביצי","אותן מקומות שמרביצין בהן תורה אינן בורות מפני שהדרכים יפין הן והולכין התלמידים ממקום למקום ללמוד תורה ל\"א לא ביירי תרביצי גנות שאינן גדילין על רוב מים כגון כרשינין:"],[11,"לא שקיל שודפנא","אין השדפון נאחז ומתדבק בתבואה:"],[11,"מנוולתא","שהדרכים מנוולים בטיט מפני הגשמים:"],[11,"הא דאתא מיטרא מעיקרא","שירדו הגשמים בזמנן במרחשון וירדו אף בטבת רעים הן שכבר די לעולם בגשמים של מרחשון:"],[11,"דלא אתא מיטרא מעיקרא","טבא לשתא דטבת מנוולתא לשון אחר הא דאתא מיטרא מעיקרא טבא דמנוולתא:"],[12,"אין בהם משום ועצר","דאותן של קצת מדינה שירדו להן גשמים מוכרין לאחרים:"],[12,"ואמר רב יהודה אמר רב שתיהן לקללה","אותן שירדו ואותן שלא ירדו מפני שרוב גשמים קלקלו את תבואתם:"],[13,"הא דאיכא מיטרא טובא","יותר מדאי שתיהן לקללה:"],[13,"כדמבעי ליה","אין בהם משום ועצר שקצת מדינה תספק לקצת מדינה:"],[13,"תמטר תהא מקום מטר","כלומר יותר מדאי:"],[14,"מאימתי מברכין על הגשמים","בפרק הרואה (ברכות נד.) אמרינן על הגשמים אומר הטוב והמטיב והתם (דף נט.) פרכינן הך ברכה דתקון לה רבנן ומשנינן לה הא דחזא מיחזא והא דשמע משמע:"],[14,"חתן לקראת כלה","שירדו כל כך שכשהטפה נופלת יוצאה אחרת ובולטת כנגדה מפי מורי ל\"א שהשווקין מקלחין מים שוק מקלח וזה מקלח כנגדו:"],[16,"רוב ההודאות","כלומר רוב ההודאות אתה קורא להקב\"ה ולא כל ההודאות והכי משמע ברוך אתה ברוב ההודאות ולא בכל אלא כך חותם בא\"י אמ\"ה אל ההודאות דמשמע כל ההודאות:"]],[[2,"","דאזלי אתיגרא. פי' שהולכים במקלות ונשענים עליהם ואמר דתרגומא מחזיק בפלך דכתיב גבי יואב הוי באתיגרא:"],[3,"","בשבילי הרשות. פי' בדרך שעשוי דרך השדות והכרמים:"],[3,"","עד שתדר רביעה שניה. מכאן ואילך מזקי להו:"],[4,"","עד מתי נהנין ושורפין בתבן ובקש של שביעית. פירוש בשנה שמינית וכו' וס\"ל כמ\"ד ספיחי זרעים מותרים ולר' עקיבא דאמר ספיחי זרעים אסורים מקרא דהן לא נזרע ולא נאסוף כדמפרש במסכת פסחים פרק מקום שנהגו (פסחים דף נא:) צ\"ל דמוקי לה ולבהמתך ולחיה וגו' בספיחי אילנות ולאו דוקא תבואה קאמר אלא כגון תבואת הכרם דהיינו אילנות אבל ספיחי זרעים אסורים:"],[9,"","לא אמרן אלא קודם ועצר דאורתא. כלומר שירדו גשמים קודם ק\"ש של ערבית אבל קודם של שחרית יש בהם משום ועצר כדאמר רב שמואל בר רב יצחק:"],[11,"","איכא דאמרי לא ביירי תרביצי. שאין הגנות ריקים מזרעים:"]]],[["נימרינהו לתרוייהו אל ההודאות ורוב ההודאות","אמר ר' אבהו גדול יום הגשמים מתחיית המתים דאילו תחיית המתים לצדיקים ואילו גשמים בין לצדיקים בין לרשעים ופליגא דרב יוסף דאמר רב יוסף מתוך שהיא שקולה כתחיית המתים קבעוה בתחיית המתים","אמר רב יהודה גדול יום הגשמים כיום שניתנה בו תורה שנא' (דברים לב, ב) יערף כמטר לקחי ואין לקח אלא תורה שנא' (משלי ד, ב) כי לקח טוב נתתי לכם תורתי אל תעזובו רבא אמר יותר מיום שניתנה בו תורה שנאמר יערף כמטר לקחי מי נתלה במי הוי אומר קטן נתלה בגדול","רבא רמי כתיב יערף כמטר לקחי וכתיב תזל כטל אמרתי אם תלמיד חכם הגון הוא כטל ואם לאו עורפהו כמטר","תניא היה ר' בנאה אומר כל העוסק בתורה לשמה תורתו נעשית לו סם חיים שנאמר (משלי ג, יח) עץ חיים היא למחזיקים בה ואומר (משלי ג, ח) רפאות תהי לשרך ואומר (משלי ח, לה) כי מוצאי מצא חיים וכל העוסק בתורה שלא לשמה נעשית לו סם המות שנאמר יערף כמטר לקחי ואין עריפה אלא הריגה שנאמר (דברים כא, ד) וערפו שם את העגלה בנחל","א\"ל ר' ירמיה לר' זירא ליתי מר ליתני א\"ל חלש לבאי ולא יכילנא לימא מר מילתא דאגדתא א\"ל הכי אמר ר' יוחנן מאי דכתיב (דברים כ, יט) כי האדם עץ השדה וכי אדם עץ שדה הוא","אלא משום דכתיב (דברים כ, יט) כי ממנו תאכל ואותו לא תכרת וכתיב אותו תשחית וכרת הא כיצד אם ת\"ח הגון הוא ממנו תאכל ואותו לא תכרת ואם לאו אותו תשחית וכרת","אמר רבי חמא (אמר רבי) חנינא מאי דכתיב (משלי כז, יז) ברזל בברזל יחד לומר לך מה ברזל זה אחד מחדד את חבירו אף שני תלמידי חכמים מחדדין זה את זה בהלכה","אמר רבה בר בר חנה למה נמשלו דברי תורה כאש שנאמר (ירמיהו כג, כט) הלא כה דברי כאש נאם ה' לומר לך מה אש אינו דולק יחידי אף דברי תורה אין מתקיימין ביחידי","והיינו דאמר רבי יוסי בר חנינא מאי דכתיב (ירמיהו נ, לו) חרב אל הבדים ונואלו חרב על שונאיהן של תלמידי חכמים שעוסקין בד בבד בתורה ולא עוד אלא שמטפשין שנאמר ונואלו","ולא עוד אלא שחוטאין כתיב הכא ונואלו וכתיב התם (במדבר יב, יא) אשר נואלנו ואשר חטאנו ואיבעית אימא מהכא (ישעיהו יט, יג) נואלו שרי צוען [וגו'] והתעו את מצרים","אמר רב נחמן בר יצחק למה נמשלו דברי תורה כעץ שנאמר (משלי ג, יח) עץ חיים היא למחזיקים בה לומר לך מה עץ קטן מדליק את הגדול אף תלמידי חכמים קטנים מחדדים את הגדולים והיינו דאמר ר' חנינא הרבה למדתי מרבותי ומחבירי יותר מרבותי ומתלמידי יותר מכולן","רבי חנינא בר פפא רמי כתיב (ישעיהו כא, יד) לקראת צמא התיו מים וכתיב (ישעיהו נה, א) הוי כל צמא לכו למים אם תלמיד הגון הוא לקראת צמא התיו מים ואי לא הוי כל צמא לכו למים","רבי חנינא בר חמא רמי כתיב (משלי ה, טז) יפוצו מעינותיך חוצה וכתיב (משלי ה, יז) יהיו לך לבדך אם תלמיד הגון הוא יפוצו מעינותיך חוצה ואם לאו יהיו לך לבדך","(ואמר) רבי חנינא בר אידי למה נמשלו דברי תורה למים דכתיב הוי כל צמא לכו למים לומר לך מה מים מניחין מקום גבוה והולכין למקום נמוך אף דברי תורה אין מתקיימין אלא במי שדעתו שפלה","ואמר רבי אושעיא למה נמשלו דברי תורה לשלשה משקין הללו במים וביין ובחלב דכתיב הוי כל צמא לכו למים וכתיב (ישעיהו נה, א) לכו שברו ואכלו ולכו שברו בלא כסף ובלא מחיר יין וחלב לומר לך מה שלשה משקין הללו אין מתקיימין אלא בפחות שבכלים אף דברי תורה אין מתקיימין אלא במי שדעתו שפלה","כדאמרה ליה ברתיה דקיסר לר' יהושע בן חנניה אי חכמה מפוארה בכלי מכוער אמר לה אביך רמי חמרא במני דפחרא אמרה ליה אלא במאי נירמי אמר לה אתון דחשביתו רמו במאני דהבא וכספא","אזלה ואמרה ליה לאבוה רמייא לחמרא במני דהבא וכספא ותקיף אתו ואמרו ליה אמר לה לברתיה מאן אמר לך הכי אמרה ליה רבי יהושע בן חנניה קריוהו אמר ליה אמאי אמרת לה הכי אמר ליה כי היכי דאמרה לי אמרי לה והא איכא שפירי דגמירי"],[[0,"למימרינהו לתרוייהו","ברוך אתה ברוב ההודאות במרבית ההודאות האל של כל ההודאות משמע ומתחלה היה משמע רוב ממש ולא מרובות וכמו כן בישתבח אל מלך גדול בתשבחות אל ההודאות. מפי רבי:"],[1,"","רשעי עובדי כוכבים אינן חיין כי תולעתם לא תמות ואשם לא תכבה (ישעיהו ס״ו:כ״ד):"],[1,"ופליגא דרב יוסף","דאיהו אמר כתחיית המתים ולא יותר שבה חיים בני אדם שהתבואה גדילה בו:"],[2,"כמטר לקחי","השוה לקח למטר:"],[3,"יערף","כמו אף שמיו יערפו טל (דברים ל״ג:כ״ח) ושחקים ירעפו טל (משלי ג׳:כ׳) שהיא מרבה הפירות:"],[3,"כתיב תזל כטל","דמשמע נחת:"],[3,"ערפיהו כמטר","הרגהו:"],[4,"לשמה","משום כאשר צוני ה' אלהי ולא כדי להקרות רבי:"],[5,"לא יכילנא","למיגמר:"],[5,"וכי אדם עץ השדה","אלא מקיש אדם לעץ השדה מה עץ השדה אם עץ מאכל הוא ממנו תאכל ואותו לא תכרות כך תלמידי חכמים אם הגון הוא ממנו תאכל למוד הימנו ואם לאו אותו תשחית סור מעליו:"],[7,"ברזל בברזל יחד","ואיש יחד פני רעהו מה ברזל זה אחד מחדד את חבירו כגון סכין על גבי חבירתה:"],[8,"אינה דולקת יחידי","עץ אחד אינה דולקת אלא ב' או ג' ביחד:"],[8,"יחידי","בלא חבר שיחדדנו:"],[9,"שמוסיפין טפשות דכתיב נואלנו","אשר נואלנו מתרגם דאיטפשנא:"],[10,"שחוטאין","דכתיב נואלו גבי חטאנו:"],[10,"ואיבעית אימא מהכא נואלו שרי צוען וגו' והתעו את מצרים","ותועה היינו חוטא:"],[11,"תורה כעץ","דכתיב עץ חיים היא למחזיקים בה כשמדליק את האור מצית את העצים דקין תחלה:"],[11,"קטנים מחדדין","ששואלין כל שעה:"],[12,"התיו","משמע להוליך לו מים:"],[12,"וכתיב לכו למים","ילך הוא עצמו:"],[12,"אם תלמיד (חכם) הגון","שרוצה ללמוד ממך מצוה לרב לילך אצלו במקומו:"],[12,"ואם לאו","ילך הוא אצל הרב:"],[13,"יפוצו מעינותיך חוצה","אם הגון הוא אמור לו סתרי תורה:"],[13,"ואם לאו יהיו לך לבדך","ואין לזרים אתך:"],[15,"שלשה משקים הללו","מים יין וחלב זו התורה שאינו נותן בה כלום ויודעה ולומדה:"],[15,"בפחות שבכלים","במאני דפחרא:"],[16,"במאני דפחרא","בדרך שחוק אמר ומרמז מה את אומרת לי והלא אביך נותן יין בכלים מכוערין של חרס:"],[16,"ואלא במאי נירמיה","אם לא בשל חרס הא כולי עבדי הכי:"],[17,"ותקיף","החמיץ:"],[17,"כי היכי דאמרה לי","אי חכמה מפוארה בכלי מכוער הכי אמרי לה דיין משתמר בכלי מכוער אף התורה מתקיימת בי יותר משאילו הייתי נאה:"]],[[4,"","וכל העוסק בתורה שלא לשמה תורתו נעשית לו סם המות. וקשה והלא אמרינן (פסחים דף נ:) לעולם יעסוק אדם בתורה אע\"ג שאינה לשמה שמתוך שלא לשמה בא לשמה ויש לומר דתרי שלא לשמה הוי דמה שאמרינן לעולם יעסוק בתורה אפילו שלא לשמה היינו כלומר כדי שיקרא רבי או כדי שיכבדוהו ומה שאמרינן הכא כל העוסק בתורה שלא לשמה נעשה לו סם המות היינו מי שלומד לקנטר:"],[6,"","אם תלמיד חכם הגון ממנו תאכל. פירוש למוד לפניו ואותו לא תכרות כלומר לא תפרד ממנו לילך לפני רב אחר ואם לאו לא תלמוד לפניו והא דאמרינן דלומדים מת\"ח אע\"פ שאינו הגון כר\"מ שהיה לומד לפני אחר במסכת חגיגה (דף טו.) היינו דוקא תלמיד חכם (אחר) יכול ללמוד לפניו לפי שלא ילמוד ממעשיו אבל אם אינו תלמיד חכם אינו רשאי ללמוד לפניו:"],[15,"","אף דברי תורה וכו'. וכן נמי אמרינן בעירובין פ' כיצד מעברין (עירובין דף נה.) לא בשמים היא ולא מעבר לים היא כלומר לא תמצא התורה במי שמגביה עצמו כשמים שדעתו גבוה ולא בסוחרים ההולכים במדינת הים בעבר הים דאי ספרא לא סייפא ואי סייפא לא ספרא והכי נמי איתא התם לא בסחרנין ולא בתגרין ולא באיסטרולגין כלומר באותן שרואין בכוכבים אמרו ליה לשמואל והא מר איסטרולגוס הוא אמר להו תיתי לי דלא מעיינא בהו אלא בעידן דנפקא למיא פירוש להטיל מים ולא אני מבטל לעצמי:"]]],[["אי הוו סנו טפי הוו גמירי דבר אחר מה שלשה משקין הללו אין נפסלין אלא בהיסח הדעת אף דברי תורה אין משתכחין אלא בהיסח הדעת","אמר רבי חמא בר' חנינא גדול יום הגשמים כיום שנבראו שמים וארץ שנאמר (ישעיהו מה, ח) הרעיפו שמים ממעל ושחקים יזלו צדק תפתח ארץ ויפרו ישע וצדקה תצמיח יחד אני ה' בראתיו בראתים לא נאמר אלא בראתיו","אמר רב אושעיא גדול יום הגשמים שאפי' ישועה פרה ורבה בו שנאמר תפתח ארץ ויפרו ישע אמר רבי תנחום בר חנילאי אין הגשמים יורדים אלא א\"כ נמחלו עונותיהן של ישראל שנאמר (תהלים פה, ב) רצית ה' ארצך שבת שבות יעקב נשאת עון עמך כסית כל חטאתם סלה","א\"ל זעירי מדיהבת לרבינא אתון מהכא מתניתו לה אנן מהכא מתנינן לה (מלכים א ח, לד) ואתה תשמע השמים וסלחת לחטאת וגו'","אמר ר' תנחום בריה דרבי חייא איש כפר עכו אין הגשמים נעצרין אא\"כ נתחייבו שונאיהן של ישראל כליה שנאמר (איוב כד, יט) ציה גם חום יגזלו מימי שלג שאול חטאו א\"ל זעירי מדיהבת לרבינא אתון מהכא מתניתו לה אנן מהכא מתנינן לה (דברים יא, יז) ועצר את השמים ואבדתם מהרה","אמר רב חסדא אין הגשמים נעצרין אלא בשביל ביטול תרומות ומעשרות שנאמר ציה גם חום יגזלו מימי שלג מאי משמע תנא דבי רבי ישמעאל בשביל דברים שצויתי אתכם בימות החמה ולא עשיתם יגזלו מכם מימי שלג בימות הגשמים","אמר רבי שמעון בן פזי אין הגשמים נעצרין אלא בשביל מספרי לשון הרע שנאמר (משלי כה, כג) רוח צפון תחולל גשם ופנים נזעמים לשון סתר","אמר רב סלא אמר רב המנונא אין הגשמים נעצרין אלא בשביל עזי פנים שנאמר (ירמיהו ג, ג) וימנעו רביבים ומלקוש לא היה ומצח אשה זונה היה לך וגו' ואמר רב סלא אמר רב המנונא כל אדם שיש לו עזות פנים סוף נכשל בעבירה שנאמר ומצח אשה זונה היה לך רב נחמן אמר בידוע שנכשל בעבירה שנאמר היה לך ולא נאמר יהיה לך","אמר רבה בר רב הונא כל אדם שיש לו עזות פנים מותר לקרותו רשע שנאמר (משלי כא, כט) העז איש רשע בפניו רב נחמן בר יצחק אמר מותר לשנאותו שנאמר (קהלת ח, א) ועז פניו ישונא אל תקרי ישונא אלא ישנא","אמר רב קטינא אין הגשמים נעצרין אלא בשביל ביטול תורה שנאמר (קהלת י, יח) בעצלתים ימך המקרה בשביל עצלות שהיה בישראל שלא עסקו בתורה נעשה שונאו של הקב\"ה מך ואין מך אלא עני שנאמר (ויקרא כז, ח) ואם מך הוא מערכך ואין מקרה אלא הקב\"ה שנאמר (תהלים קד, ג) המקרה במים עליותיו","רב יוסף אמר מהכא (איוב לז, כא) ועתה לא ראו אור בהיר הוא בשחקים ורוח עברה ותטהרם ואין אור אלא תורה שנאמר (משלי ו, כג) כי נר מצוה ותורה אור בהיר הוא בשחקים תנא דבי ר' ישמעאל אפילו בשעה שרקיע נעשה בהורין בהורין להוריד טל ומטר רוח עברה ותטהרם","אמר ר' אמי אין הגשמים נעצרין אלא בעון גזל שנאמר (איוב לו, לב) על כפים כסה אור בעון כפים כסה אור ואין כפים אלא חמס שנאמר (יונה ג, ח) ומן החמס אשר בכפיהם ואין אור אלא מטר שנאמר (איוב לז, יא) יפיץ ענן אורו","מאי תקנתיה ירבה בתפלה שנאמר (איוב לו, לב) ויצו עליה במפגיע ואין פגיעה אלא תפלה שנאמר (ירמיהו ז, טז) ואתה אל תתפלל בעד העם הזה [וגו'] ואל תפגע בי","וא\"ר אמי מאי דכתיב (קהלת י, י) אם קהה הברזל והוא לא פנים קלקל אם ראית רקיע שקיהה כברזל מלהוריד טל ומטר בשביל מעשה הדור שהן מקולקלין שנא' והוא לא פנים קלקל","מה תקנתן יתגברו ברחמים שנא' (קהלת י, י) וחילים יגבר ויתרון הכשיר חכמה כל שכן אם הוכשרו מעשיהן מעיקרא","ריש לקיש אמר אם ראית תלמיד"],[[0,"אי הוו סנו","אותם נאים שהם חכמים:"],[0,"טפי הוו גמירי","שאי אפשר לנאה להשפיל דעתו ובא לידי שכחה:"],[0,"בהיסח הדעת","שאם לא ישמרם יפה יהו נשפכין או נופל לתוכן דבר מאוס ונפסלים מלשתות בדבר קל יותר משמן ודבש שמתוך שהן עבים צפה הפסולת למעלה ואפשר אדם נוטל העליון וזורקו לחוץ והתחתון בר ונקי מה שאין כן במשקה צלול שאינו עב קליי\"ר בלע\"ז:"],[0,"בהיסח הדעת","אם אינו מחזירם תמיד:"],[1,"שנאמר הרעיפו שמים ממעל ושחקים יזלו צדק תפתח ארץ ויפרו ישע וצדקה תצמיח יחד אני ה' בראתיו בראתים לא נאמר","דמשמע אשחקים יזלו קאי אלא אני ה' בראתיו לטל ומטר שמע מינה שמשתבח ומתפאר הקב\"ה במטר השמים:"],[2,"ישועה פרה ורבה בו","מליצי זכות נכנסין לפניו ביום הגשמים שנזכר לישועה מתוך שעת רצון הוא לישנא דקרא ויפרו ישע ואימתי בזמן שהשחקים יזלו צדק:"],[2,"רצית ה' ארצך","במים:"],[2,"נשאת עון עמך","מיד:"],[3,"ה\"ג א\"ל מר זעירי מדיהבת לרבינא כו'","זעירי סתם היה מן הראשונים ורבינא סוף הוראה לא ראו זה את זה:"],[3,"ואתה תשמע השמים וגו'","ואומר ונתת מטר על ארצם בתפלה דשלמה:"],[4,"ציה גם חום יגזלו מימי שלג","כשציה גם חום גוזלין מימות השלג שאינן יורדין מטר כמשפטם בידוע ששאול חטאו:"],[4,"ולא יהיה מטר","וסמיך ליה ואבדתם:"],[5,"ציה","דריש לשון צווי דברים שצויתי אתכם בימות החמה תרומות ומעשרות גזלו מימי שלג את המטר:"],[6,"רוח צפון תחולל גשם ופנים נזעמים לשון שקר","תחולל תבטל כמו לא יחל דברו (במדבר ל׳:ג׳) כדאמרי' ביבמות (דף עב.) דרוח צפון ברור הוא ומביא אורה לעולם מה שגשמים נעצרין ופנים נזעמין שמראה הקב\"ה שאינו מביא מטר לעולם מפני לשון שקר רכילות ופשט המקרא כשם שרוח צפון תחולל גשם כך פנים נזעמים מפני לשון שקר:"],[7,"וימנעו רביבים","משום דמאנת הכלם שהיה בך עזות:"],[7,"היה","משמע כבר נכשל:"],[8,"העז איש","שיש בו עזות פנים אמור לו רשע בפניו ואין בו משום מלקות כדאמרי' במסכת קדושין (דף כח.) ומשום דבר זה בלבד מותר לקרותו רשע:"],[8,"מותר לשנאותו","אע\"ג דכתיב ואהבת לרעך כמוך:"],[8,"ועז פניו ישונא","ועז כתיב חסר ו' מי שהוא עז פנים ישנא בשו\"א:"],[9,"ימך","כמי שאין בו כח להוריד טל ומטר:"],[10,"ועתה לא ראו אור","מפני שלא ראו אור של תורה:"],[10,"אפילו כשהשמים בהורין","כמו בהרת מנומר בעבים ורוצה להוריד גשמים רוח עברה ותטהרם מפזרת העבים:"],[11,"","המלאך אף ברי שמו יפיץ ענן אורו גשם שלו:"],[12,"ויצו","הקדוש ברוך הוא:"],[12,"עליה","על הגשם שתרד:"],[12,"במפגיע","כשיתפלל עליה כמו ואל תפגע בי:"],[13,"קהה הברזל","כמו הקהה את שיניו ושיני בנים תקהינה (ירמיהו ל״א:כ״ט):"],[13,"והוא לא פנים קלקל","שקלקלו הדור:"],[14,"וכ\"ש אם הוכשרו מעשיהן","קודם לכן והכי משמע ויתרון הכשיר ויתרון שהכשיר לחכמה אם הכשירו מעשיהן מתחילה שיבואו הגשמים יותר מבחיילים יגבר שהן מגבירין חיילים ועומדין בתפלה בזמן שקלקלו:"]],[[0,"","אי הוו סנו הוו חכימי. פ' אם היו שונאים היופי הוו תלמידי חכמים ביותר:"],[1,"","בראתים לא נאמר אלא בראתיו. פי' דמשמע דמהדר אגשם ואם כן משום דגדול יום הגשמים כיום שנברא בו שמים וארץ משתבח ביה הקב\"ה אי הוה כתיב בראתים הוה משמע דאהדר אשמים וארץ:"],[6,"","פנים נזעמים לשון סתר. פירוש בשביל לשון שקר שאומר לשון הרע הרוח צפון תבטל הגשם והיינו פנים נזעמים:"],[8,"","מותר לקרותו רשע. אף על גב דאמרי' בקדושין (דף כח.) הקורא לחבירו רשע יורד עמו לחייו לזה מותר דודאי נכשל בעבירה ועומד במורדו דהכרת פניו ענתה בו:"],[10,"","בהורין לשון בהרות טרוק\"ש בלע\"ז:"]]],[["שלמודו קשה עליו כברזל בשביל משנתו שאינה סדורה עליו שנאמר (קהלת י, י) והוא לא פנים קלקל","מאי תקנתיה ירבה בישיבה שנאמר (קהלת י, י) וחילים יגבר ויתרון הכשיר חכמה כ\"ש אם משנתו סדורה לו מעיקרא","כי הא דריש לקיש הוה מסדר מתני' ארבעין זמנין כנגד מ' יום שניתנה תורה ועייל לקמיה דר' יוחנן רב אדא בר אהבה מסדר מתני' עשרין וארבע זמנין כנגד תורה נביאים וכתובים ועייל לקמיה דרבא","רבא אמר אם ראית תלמיד שלמודו קשה עליו כברזל בשביל רבו שאינו מסביר לו פנים שנאמר והוא לא פנים קלקל","מאי תקנתיה ירבה עליו רעים שנאמר וחילים יגבר ויתרון הכשיר חכמה כ\"ש אם הוכשרו מעשיו בפני רבו מעיקרא","ואמר ר' אמי מאי דכתיב (קהלת י, יא) אם ישוך הנחש בלא לחש ואין יתרון לבעל הלשון אם ראית דור שהשמים משתכין כנחשת מלהוריד טל ומטר בשביל לוחשי לחישות שאין בדור","מאי תקנתן ילכו אצל מי שיודע ללחוש דכתיב (איוב לו, לג) יגיד עליו רעו ואין יתרון לבעל הלשון ומי שאפשר לו ללחוש ואינו לוחש מה הנאה יש לו","ואם לחש ולא נענה מאי תקנתיה ילך אצל חסיד שבדור וירבה עליו בתפלה שנאמר (איוב לו, לב) ויצו עליה במפגיע ואין פגיעה אלא תפלה שנאמר (ירמיהו ז, טז) ואתה אל תתפלל בעד העם הזה ואל תשא בעדם רנה ותפלה ואל תפגע בי","ואם לחש ועלתה בידו ומגיס דעתו עליו מביא אף לעולם שנאמר (איוב לו, לג) מקנה אף על עולה","רבא אמר שני ת\"ח שיושבין בעיר אחת ואין נוחין זה לזה בהלכה מתקנאין באף ומעלין אותו שנאמר מקנה אף על עולה","אמר ר\"ל מאי דכתיב אם ישוך הנחש בלא לחש ואין יתרון לבעל הלשון לעתיד לבא מתקבצות ובאות כל החיות אצל הנחש ואומרים לו ארי דורס ואוכל זאב טורף ואוכל אתה מה הנאה יש לך אמר להם ואין יתרון לבעל הלשון","אמר רבי אמי אין תפלתו של אדם נשמעת אלא אם כן משים נפשו בכפו שנאמר (איכה ג, מא) נשא לבבנו אל כפים [איני והא] אוקים שמואל אמורא עליה ודרש (תהלים עח, לו) ויפתוהו בפיהם ובלשונם יכזבו לו ולבם לא נכון עמו ולא נאמנו בבריתו ואף על פי כן (תהלים עח, לח) והוא רחום יכפר עון וגו'","לא קשיא כאן ביחיד כאן בציבור","אמר ר' אמי אין גשמים יורדין אלא בשביל בעלי אמנה שנאמר (תהלים פה, יב) אמת מארץ תצמח וצדק משמים נשקף","וא\"ר אמי בא וראה כמה גדולים בעלי אמנה מניין מחולדה ובור ומה המאמין בחולדה ובור כך המאמין בהקב\"ה עאכ\"ו","אמר רבי יוחנן כל המצדיק את עצמו מלמטה מצדיקין עליו הדין מלמעלה שנאמר אמת מארץ תצמח וצדק משמים נשקף רבי חייא בר אבין אמר רב הונא מהכא (תהלים צ, יא) וכיראתך עברתך","ריש לקיש אמר מהכא (ישעיהו סד, ד) פגעת את שש ועושה צדק בדרכיך יזכרוך הן אתה קצפת ונחטא בהם עולם ונושע אמר ריב\"ל כל השמח ביסורין שבאין עליו מביא ישועה לעולם שנאמר בהם עולם ונושע","אמר ריש לקיש מאי דכתיב (דברים יא, יז) ועצר את השמים בשעה שהשמים נעצרין מלהוריד (טל ומטר) דומה לאשה שמחבלת ואינה יולדת והיינו דאמר ריש לקיש משום בר קפרא נאמרה עצירה בגשמים ונאמרה עצירה באשה"],[[0,"שלמודו קשה עליו כברזל","שקשה לו מרוב קושיות בשביל משנתו שאינה סדורה לו ואינו זוכר מה כתיב בה ולפיכך אינו יודע לפרק אי נמי שגורסה בטעות פוטר על החיוב ומחייב על הפטור ומקשי עלה מדוכתא אחריתי והכי משמע קרא והוא לא שאינו יודע שמועתו מפני שפנים קלקל שקלקל במשנה שהיא קודם לגמרא:"],[1,"ירבה בישיבה","שיסדירו בני הישיבה משנתם שנאמר וחיילים בין תלמידים שהן חיילות חיילות:"],[1,"ויתרון הכשיר","כשסידר משנתו מתחילה:"],[2,"כנגד מ' יום שניתנה התורה","שתתקיים בידו והדר עייל קמיה דר' יוחנן למיגמר גמרא:"],[2,"כנגד תנ\"ך","שהן כ\"ד ספרים:"],[3,"שפנים קלקל","שהראה לו פנים רעות:"],[4,"ירבה עליו רעים","לפייס הימנו שיסבור לו פנים:"],[5,"משתכין עליו כנחושת","מאדימין פנים כעין רודיליי\"א כדאמרי' בבבא מציעא (דף כו.) דשתיך טפי שהעלה חלודה שנעצרין (מלהוליד) טל ומטר:"],[5,"לוחשי לחישות","בשביל שאין מתפללים תפלה בלחש:"],[6,"יגיד עליו רעו","יתפלל עליו חבירו וגבי גשמים כתיב באיוב:"],[6,"ואין יתרון לבעל הלשון","כלומר מה הנאה יש לבעל הלשון שיודע ללחוש ואינו לוחש:"],[8,"מקנה אף על עולה","מקנה אף מי שמגיס דעתו ועולה:"],[9,"ואין נוחין זה לזה כו'","והכי משמע בשביל שצריך להגיד זה לזה ולהיות נוחין בהלכה ואינן עושין מקנה מתקנאים מתגרים באף ומעלים אותו ומביאים אותו עליהן. ויש גורסין ונוחין זה לזה בהלכה מתקנאים באף וכו' משיגיד עליו רעו שנוחין זה לזה מתקנאים באף ומעלים אותו מעליהם:"],[10,"ארי דורס ואוכל","מיד ואינו מתירא:"],[10,"טורף ואוכל","שמוליך לחוריו ואוכל שם שמפחד מן הבריות ולכולן יש להם הנאה:"],[10,"ולך מה הנאה יש לך","שאתה נושך בני אדם והורגן והוא אומר מה יתרון לבעל הלשון שמספר לשון הרע אע\"פ שאין לו הנאה ולפיכך מביאו הקב\"ה בדין אצל נחש כדי שיתבייש מפני שהשיא אדם הראשון ומתביישין עמו מספרי לשון הרע:"],[11,"ולבם לא נכון עמו","עם הקב\"ה:"],[11,"ואעפ\"כ","כתוב בסמוך והוא רחום יכפר עון ושומע תפלתם והיכי אמרת שאין תפלתם נשמעת אא\"כ משים נפשו בכפו כלומר שנפשו מכוונת בכפו:"],[12,"בצבור","תפלתם נשמעת ואע\"פ שאין לב כולם שלם כדכתיב ויפתוהו בפיהם בדברים ל' רבים:"],[12,"ביחיד","אינו אלא א\"כ לבו מכוון:"],[13,"בזמן שאמת מארץ תצמח","שיש אמונה במשא ומתן אז צדק משמים נשקף דהיינו גשמים שהן צדקה:"],[14,"מחולדה ובור","שהמיתו שני בני אדם מצוי הוא באגדה מעשה בבחור אחד שנתן אמונתו לריבה אחת שישאנה אמרה מי מעיד והיה שם בור אחד וחולדה אמר הבחור בור וחולדה עדים בדבר לימים עבר על אמונתו ונשא אחרת והוליד שני בנים אחד נפל לבור ומת וא' נשכתו חולדה ומת אמרה לו אשתו מה מעשה הוא זה שבנינו מתים במיתה משונה ואמר לה כך וכך היה המעשה:"],[14,"המאמין בהקדוש ברוך הוא","שמשימו עד בינו לבין חבירו על אחת כמה וכמה:"],[15,"המצדיק עצמו","שמכשיר ומקשט מעשיו:"],[15,"מצדיקין עליו","מדקדקין עמו אפילו כחוט השערה יותר משאילו מקלקל מעשיו כדי למרק עונותיו:"],[15,"שנאמר אמת מארץ תצמח","אז צדק משמים נשקף צדקה אין כתיב כאן אלא צדק דמשמע דין:"],[15,"וכיראתך עברתך","על מי שהוא ירא אותך אתה מחזיק עברתך כדי למרק עונותיו ופשט המקרא מי יודע עוז אפך מי יודע עוז וכח למצוא אותו לנוס מפניך ביום אפך וכיראתך עברתך כשם שאתה יראוי ומפוחד כך יש להתיירא ולהתפחד מעברתך:"],[16,"פגעת את שש ועושה צדק","במי ששמח ועושה צדק שהן העושים כך בדרכיך יזכירוך אתה פוגע בו אם חוטא כלום כמו ויפגע בו וימת קרא הכי הוא פגעת את שש ועושה צדק והן העושין כך בדרכיך יזכירוך באותם דרכים שאתה מייסרן ביסורין יזכירוך לטובה ואומרים הן אתה קצפת בשביל שחטאנו בהם עולם ונושע בשבילם נושע לעולם הבא:"],[17,"שחובלת","כמו חבלי יולדה אף השמים עושין כן וקשה לעולם ועל חטא הוא:"]],[[5,"","אם ראית דור שהשמים משתכין עליו כנחושת מלהוריד גשם עליו וכו'. מכאן מוכיח ר\"ת דהא דאמרי' בבבא בתרא (דף יט. ושם) אין טומנין בסלעים מ\"ט משום דמשתכי ליה לקדירה ר\"ל משתכי מקלקלים המאכל שבקדירה ובלע\"ז אורמשי\"ר והא דאמר לקדירה לאו דוקא לקדירה אלא למאכל שבקדירה דהכי נמי קאמר (שבת דף יח:) האי קדרה חייתא שרי ואין לפרש כפרש\"י שפי' התם משתכי משברים הקדירה דא\"כ מאי קאמר הכא שהשמים משתכין ר\"ל שהשמים משתברין אלא ודאי משתכים ר\"ל מעלין חלודה כמו דבר שבטל ממלאכתו ימים רבים ומחליד ובלע\"ז ראוליי\"ר:"],[8,"","ואי לוחש ועלתה בידו ומגיס דעתו מביא אף לעולם שנאמר יגיד עליו ריעו וגו'. כלומר אם יגיד עליו ריעו שעל ידו באו הגשמים והוא מגיס דעתו מקנה אף עולה כלומר הוא קונה אף ועולה כלומר אם עולה שמגיס דעתו עליו הוא מקנה האף:"],[14,"","בחולדה ובור כך בהקב\"ה על אחת כמה וכמה. פי' מאמין בחולדה ובור מעשה היה בנערה אחת היתה רוצה לילך לבית אביה והיה בור בדרך ונפלה ובא בחור אחד ואמר אם אני אעליך תנשאי לי אמרה לו הן ונשבעו ביניהן שהוא לא ישא אשה אחרת והיא לא תנשא לאיש אחר ואמרו מי מעיד בינינו והיתה חולדה אחת הולכת לפני הבור ואמרו אלו שנים בור וחולדה יהיו עדים בינינו והלכו לדרכם והיא עמדה בשבועתה והוא נשה אשה אחרת וילדה בן באת חולדה ונשכתו ומת וילדה לו בן שני ונפל לבור ומת אמרה לו אשתו מה זה המעשה שהגיע לנו שלא כשאר בני אדם נזכר השבועה וסיפר לאשתו כל המעשה אמרה לו א\"כ חזור וקחנה וכתב לה גט והלך ונשא את הבתולה והיינו דאמרי המאמין בבור וחולדה שהעמידו עדותן:"]]],[["נאמרה עצירה באשה שנאמר (בראשית כ, יח) כי עצר עצר ה' בעד כל רחם ונאמרה עצירה בגשמים דכתיב (דברים יא, יז) ועצר את השמים","נאמר לידה באשה ונאמר לידה בגשמים נאמר לידה באשה דכתיב (בראשית ל, כג) ותהר ותלד בן ונאמר לידה בגשמים דכתיב (ישעיהו נה, י) והולידה והצמיחה","נאמר פקידה באשה ונאמר פקידה בגשמים נאמר פקידה באשה דכתיב (בראשית כא, א) וה' פקד את שרה ונאמר פקידה בגשמים דכתיב (תהלים סה, י) פקדת הארץ ותשקקה רבת תעשרנה פלג אלהים מלא מים","מאי פלג אלהים מלא מים תנא כמין קובה יש ברקיע שממנה גשמים יוצאין","אמר רבי שמואל בר נחמני מאי דכתיב (איוב לז, יג) אם לשבט אם לארצו אם לחסד ימציאהו אם לשבט בהרים ובגבעות אם לחסד ימציאהו לארצו בשדות ובכרמים","אם לשבט לאילנות אם לארצו לזרעים אם לחסד ימציאהו בורות שיחין ומערות","בימי רבי שמואל בר נחמני הוה כפנא ומותנא אמרי היכי נעביד ניבעי רחמי אתרתי לא אפשר אלא ליבעי רחמי אמותנא וכפנא ניסבול אמר להו ר' שמואל בר נחמני ניבעי רחמי אכפנא דכי יהיב רחמנא שובעא לחיי הוא דיהיב דכתיב (תהלים קמה, טז) פותח את ידך ומשביע לכל חי רצון","ומנלן דלא מצלינן אתרתי דכתיב (עזרא ח, כג) ונצומה ונבקשה מאלהינו על זאת מכלל דאיכא אחריתי במערבא אמרי משמיה דר' חגי מהכא (דניאל ב, יח) ורחמין למבעא מן קדם אלה שמיא על רזא דנא מכלל דאיכא אחריתי","בימי ר' זירא גזור גזרה וגזור דלא למיתב בתעניתא אמר להו ר' זירא נקבליה עילוון ולכי בטיל הגזירה ליתביה","אמרי ליה מנא לך הא אמר להו דכתיב (דניאל י, יב) ויאמר אלי אל תירא דניאל כי מן היום הראשון אשר נתת את לבך להבין ולהתענות לפני אלהיך נשמעו דבריך","אמר רבי יצחק אפילו שנים כשני אליהו וירדו גשמים בערבי שבתות אינן אלא סימן קללה היינו דאמר רבה בר שילא קשה יומא דמיטרא כיומא דדינא אמר אמימר אי לא דצריך לברייתא בעינן רחמי ומבטלינן ליה","ואמר רבי יצחק שמש בשבת צדקה לעניים שנאמר (מלאכי ג, כ) וזרחה לכם יראי שמי שמש צדקה ומרפא ואמר רבי יצחק גדול יום הגשמים שאפילו פרוטה שבכיס מתברכת בו שנאמר (דברים כח, יב) לתת מטר ארצך בעתו ולברך את כל מעשה ידיך","ואמר רבי יצחק אין הברכה מצויה אלא בדבר הסמוי מן העין שנאמר (דברים כח, ח) יצו ה' אתך את הברכה באסמיך תנא דבי ר' ישמעאל אין הברכה מצויה אלא בדבר שאין העין שולטת בו שנאמר יצו ה' אתך את הברכה באסמיך","ת\"ר הנכנס למוד את גרנו אומר יר\"מ ה' אלהינו שתשלח ברכה במעשה ידינו התחיל למוד אומר ברוך השולח ברכה בכרי הזה מדד ואח\"כ בירך הרי זו תפלת שוא לפי שאין הברכה מצויה לא בדבר השקול ולא בדבר המדוד ולא בדבר המנוי אלא בדבר הסמוי מן העין:","קיבוץ גייסות צדקה (מעשה) פרנס סימן: אמר רבי יוחנן גדול יום הגשמים כיום קבוץ גליות שנאמר (תהלים קכו, ד) שובה ה' את שביתנו כאפיקים בנגב ואין אפיקים אלא מטר שנאמר (שמואל ב כב, טז) ויראו אפיקי ים","ואמר רבי יוחנן גדול יום הגשמים שאפילו גייסות פוסקות בו שנאמר (תהלים סה, יא) תלמיה רוה נחת גדודיה ואמר רבי יוחנן אין הגשמים נעצרין אלא בשביל פוסקי צדקה ברבים ואין נותנין שנאמר (משלי כה, יד) נשיאים ורוח וגשם אין איש מתהלל במתת שקר","וא\"ר יוחנן מאי דכתיב"],[[0,"נאמרה עצירה באשה כו'","כלומר על כולן מבקשים רחמים:"],[2,"פלג","בריכה:"],[3,"כמין קובה","אהל מלא מים:"],[4,"אם לשבט","אם גזר הקב\"ה רוב גשמים לרעה אז יורדים בכח כשבט שמכה בכח וחזרו בתשובה הקב\"ה מורידן על הרים וגבעות מקום שאין שם איש:"],[4,"אבל אם לחסד","שיורדין בנחת ימציאהו לארצו לארץ ישראל:"],[6,"אתרתי","לא בעינן רחמי אהדדי כדלקמן:"],[6,"נבעי רחמי אכפנא","דליתיב שובעא ומותנא ליבטל ממילא:"],[6,"דכי יהיב רחמנא שובעא לחיי הוא דיהיב","לחיים ולא למתים דאינו מביא שובעא כדי להמית בני אדם אלא כדי שיחיו:"],[6,"משביע לכל חי רצון","שובע נותן לבני אדם חיים:"],[7,"על זאת","על חדא משמע בעזרא כתיב:"],[7,"על רזא דנא","בדניאל כתיב:"],[8,"דלא ליתבו בתעניתא","דלא בעו דליתי ברכה לעולם בשבילן:"],[8,"ניקבל עילוון","יומי תעניתא דמשום קבלה מהני לן כתעניתא וכי בטיל גזרה עבדין להו:"],[9,"ומנלן דעבדינן הכי","כלומר דמהני אי עבדינן הכי:"],[9,"אשר נתת לבך להתענות לפני אלהיך נשמעו דבריך","אלמא משקיבל עליו נשמעו דבריו:"],[10,"כשני אליהו","בימי אחאב שהיה העולם צריך לגשמים דכתיב (מלכים א י״ז:א׳) אם יהיה השנים האלה טל ומטר כי אם לפי דברי:"],[10,"סימן קללה","שבני אדם צריכים לחזר בשוק לקנות סעודת שבת:"],[10,"","והיינו דאמר ר' שילא:"],[10,"קשי יומי דמיטרא","שאין בני אדם יכולין לעשות צרכיהן:"],[10,"כיומא דדינא","שני וחמישי שמתקבצין בני אדם לדון עם חבריהן כתקנת עזרא שיש הומות וקולות ואוושות ביום הגשמים כיום הדין ובערב שבת כל שכן דקשי מיטרא:"],[10,"ומבטלינהו","לירידת גשמים שטורחין בני אדם ואינן יכולין לצאת ולבא:"],[11,"צדקה לעניים","שמתעדנין בה ונוח להן יום ברור ומתחממין בה ביום הצינה:"],[11,"יראי שמי","שומרי שבת:"],[11,"פרוטה שבכיס","אפי' מעשה ידים שאינן צריכים לגשמים מתברכין:"],[13,"ברוך השולח ברכה","(שיפוע) ומזכיר בה מלכות ואזכרה ככל הברכות כולן:"],[13,"הרי זו תפילת שוא","ושוב אין ברכה נכנסת בה:"],[13,"בדבר הסמוי מן העין","שאינו יודע הסכום:"],[14,"כאפיקים","כאפיקי נחלים:"],[14,"בנגב","יבשה והנה חרבו מתרגמינן נגיבו:"],[14,"אפיקי ים","מוצאי ים אלמא אפיק לשון מים ואפיקים בנגב נמי לשון גשמים:"],[15,"גייסות","חיילות כשאתה מרווה תלמי הארץ בגשם מיד גדודים נוחין כדלקמן:"],[15,"פוסקי צדקה ברבים","לשם ולפנים ואורחא דמילתא נקט שאין אדם עשוי לפסוק צדקה בינו לבין עצמו ואינו נותן:"],[15,"נשיאים ורוח","באין לעולם כאילו גשמים יורדין ואינן יורדין בשביל האיש המתהלל במתת שקר דכשם שהוא עושה לפנים ומחניף את העניים אף שמים מחניפין את הארץ שמראין נשיאים ורוח וגשם אין אי נמי אין קאי אשלשתם דמכל אלו נעצרין:"]],[[7,"","ונצומה ונבקשה מאלהינו. ויעתר לנו פירוש מדקאמר על [זאת] משמע דאיכא מילתא אחריתא וכן פירש בסמוך על דנא:"],[12,"","אלא בדבר הסמוי מן העין שנאמר יצו ה' וגו'. תימה דאמרינן פרק כל הבשר (חולין דף קה:) גבי הני שקולאי דדרו חביתא דחמרא בעו לאתפוחי אותבוהו תותי מרזיבא פקע חביתא ומפרש שם בשביל השד שהיה שם עד דאכפייה מר בר רב אשי לשד לשלם אמר ליה שידא למר בר רב אשי ליקבע לי מר זימנא דאיזיל ואשלם קבע ליה זימנא כי מטא זימניה איעכב ואמר ליה אמאי לא אתית בזמנך אמר ליה כל מידי דצייר וחתים וכייל ומני לית לן רשות למישקל מיניה אלמא בדבר המדוד והמנוי לית ליה רשות למשקל מיניה ובדבר הסמוי אית ליה רשות אלמא אין ברכה בדבר הסמוי וי\"ל דלא קשה מידי דהא דקאמר התם היינו טעמא דלית להו אלא בדבר הפקר ולא דבר דכייל ומנוי או צייר וחתים היינו בשביל דאין ברכה מצויה בהני ולית בהו דבר הפקר והאי דבעלים נינהו אלא בדבר הסמוי והיינו מטעם דהברכה מצויה בדבר הסמוי ומה שמתרבה בשביל הברכה אית להו רשות למישקל בסמוי דהיינו כמו הפקר שאין לשום אדם זכות בו אי נמי הכא מיירי בדבר המנוי והמדוד בלא צייר וחתים ובהא אית להו רשותא והתם מיירי במדוד ומנוי וכייל וצייר וחתים ובהא לית להו רשותא:"],[14,"","גדול יום גשמים כיום קיבוץ גליות שנאמר שובה ה' את שביתנו כאפיקים בנגב וגו'. ואם תאמר אמאי לא קאמר גדול יום הגשמים יותר מקיבוץ גליות דהא כאפיקים בנגב כתיב ומי נתלה במי קטן נתלה בגדול שאפיקים גדולים מיום קיבוץ גליות דהכי נמי אמר (לעיל תענית דף ז.) יערוף כמטר לקחי מי נתלה במי קטן נתלה בגדול וי\"ל דה\"פ אנו מתפללים הכי שובה ה' את שביתנו כאפיקים היורדין בנגב שגדול יום קיבוץ כאפיקים בנגב א\"כ עשה עמנו לטובה אות בקבוץ גליות בהיות כי זה כמו זה ואפיקים בנגב תחדש בכל יום כיום קיבוץ גליות אבל יותר לא:"]]],[["(דברים יד, כב) עשר תעשר עשר בשביל שתתעשר","אשכחיה ר' יוחנן לינוקא דריש לקיש אמר ליה אימא לי פסוקיך א\"ל עשר תעשר א\"ל ומאי עשר תעשר א\"ל עשר בשביל שתתעשר אמר ליה מנא לך א\"ל זיל נסי","אמר ליה ומי שרי לנסוייה להקב\"ה והכתיב (דברים ו, טז) לא תנסו את ה' א\"ל הכי אמר רבי הושעיא חוץ מזו שנאמר (מלאכי ג, י) הביאו את כל המעשר אל בית האוצר ויהי טרף בביתי ובחנוני נא בזאת אמר ה' צבאות אם לא אפתח לכם את ארובות השמים והריקותי לכם ברכה עד בלי די","מאי עד בלי די אמר רמי בר חמא אמר רב עד שיבלו שפתותיכם מלומר די א\"ל אי הות מטי התם להאי פסוקא לא הוית צריכנא לך ולהושעיא רבך","ותו אשכחיה ר' יוחנן לינוקיה דריש לקיש דיתיב ואמר (משלי יט, ג) אולת אדם תסלף דרכו ועל ה' יזעף לבו","יתיב רבי יוחנן וקא מתמה אמר מי איכא מידי דכתיבי בכתובי דלא רמיזי באורייתא א\"ל אטו הא מי לא רמיזי והכתיב (בראשית מב, כח) ויצא לבם ויחרדו איש אל אחיו לאמר מה זאת עשה אלהים לנו","דל עיניה וחזא ביה אתיא אימיה אפיקתיה אמרה ליה תא מקמיה דלא ליעבד לך כדעבד לאבוך","(א\"ר יוחנן מטר בשביל יחיד פרנסה בשביל רבים מטר בשביל יחיד דכתיב (דברים כח, יב) יפתח ה' לך את אוצרו הטוב לתת מטר ארצך פרנסה בשביל רבים דכתיב (שמות טז, ד) הנני ממטיר לכם לחם","מיתיבי ר' יוסי בר' יהודה אומר שלשה פרנסים טובים עמדו לישראל אלו הן משה ואהרן ומרים וג' מתנות טובות ניתנו על ידם ואלו הן באר וענן ומן באר בזכות מרים עמוד ענן בזכות אהרן מן בזכות משה מתה מרים נסתלק הבאר שנאמר (במדבר כ, א) ותמת שם מרים וכתיב בתריה ולא היה מים לעדה וחזרה בזכות שניהן","מת אהרן נסתלקו ענני כבוד שנאמר (במדבר כא, א) וישמע הכנעני מלך ערד מה שמועה שמע שמע שמת אהרן ונסתלקו ענני כבוד וכסבור ניתנה לו רשות להלחם בישראל והיינו דכתיב (במדבר כ, כט) ויראו כל העדה כי גוע אהרן","אמר ר' אבהו אל תקרי ויראו אלא וייראו כדדריש ר\"ל דאר\"ל כי משמש בארבע לשונות אי דלמא אלא דהא","חזרו שניהם בזכות משה מת משה נסתלקו כולן שנאמר (זכריה יא, ח) ואכחיד את שלשת הרועים בירח אחד וכי בירח אחד מתו והלא מרים מתה בניסן ואהרן באב ומשה באדר אלא מלמד שנתבטלו ג' מתנות טובות שנתנו על ידן ונסתלקו כולן בירח אחד","אלמא אשכחן פרנסה בשביל יחיד שאני משה כיון דלרבים הוא בעי כרבים דמי","רב הונא בר מנוח ורב שמואל בר אידי ורב חייא מווסתניא הוו שכיחי קמיה דרבא כי נח נפשיה דרבא אתו לקמיה דרב פפא כל אימת דהוה אמר להו שמעתא ולא הוה מסתברא להו הוו מרמזי אהדדי חלש דעתיה"],[[1,"לינוקא דריש לקיש","בן אחותו של ר' יוחנן ולאחר מיתתו של ריש לקיש כדמוכח לקמן:"],[1,"אמר","ינוקא לר' יוחנן מאי עשר תעשר:"],[2,"א\"ל ינוקא","והכתיב לא תנסו:"],[3,"שיבלו","כלומר שייגעו דולוראנ\"ט בלע\"ז:"],[3,"אי הוה מטינא להתם","להאי קרא דהביאו את כל המעשר הוה ידעית ליה ממילא:"],[3,"לר' הושעיא רבך","דאמרית לי משמיה:"],[4,"אולת אדם תסלף דרכו ועל ה' יזעף לבו","כשאדם חוטא מסלף דרכו שבאין עליו פגעים ועל השם יזעף לבו שכועס ואומר מפני מה אירע לי פגע זה:"],[5,"ולא רמזה","משה באורייתא שהחומש הוא יסוד נביאים וכתובים ובכולן יש סמך למצוא מן התורה:"],[6,"דלי עיניה","רבי יוחנן שהיו עפעפיו מכסין את עיניו ומגביהין במזלגי דכספא בבבא קמא בפ' אחרון (דף קיז.) שהיה רוצה לראותו מפני שהוא חריף:"],[6,"דלא ליעביד לך כדעבד לאבוך","שלא יתן עיניו בך כמו שנתן באביך והמיתו בבבא מציעא (דף פד.):"],[7,"מטר בשביל יחיד","שאם א\"צ מטר אלא לאדם אחד כגון שזרע אחר זמן זריעת בני אדם או שדר בעיר שכולה נכרים וצריך למטר בא בזכותו ופרנסה שפע טובה ומחיה לכל העולם אינו בא לעולם בזכות אחד אלא בשביל רבים שאם רבים צריכין שובע שתשלח ברכה בתבואה הקב\"ה עושה אם זכו אבל יחיד הצריך שיתברכו תבואותיו אין הקב\"ה משנה בעבורו דין השנה אלא כפי ברכותיה ואע\"פ שמוריד בשביל יחיד מטר זה להשביח תבואותיו שלא יהו גרועות משל אחרים אבל לעשות שדהו כשדה שובע לא:"],[7,"מטר ארצך","של אחד משמע:"],[7,"ממטיר לכם","לשון רבים:"],[8,"בארה של מרים","סלע וזבין ממנו מים והיה מתגלגל והולך עם ישראל והוא הסלע שבו הכה משה שלא היה רוצה להזיל מימיו בשבילו לפי שמתה מרים:"],[8,"חזרה בזכות שניהן","שכן כתיב ודברתם שניכם אל הסלע ונתן מימיו:"],[9,"ונסתלקו ענני כבוד","ענני רקיע וענני עשן ושאר עננים אינן של כבוד:"],[10,"כי משמש ארבע לשונות אי דלמא אלא דהא","כל מקום שצריך לדרוש כי בין לענין דרשה בין למשמעות המקרא תוכל לשנותו באחד מהני ארבע לשונות דלשון כי משמע בכולם וכן וכד וברם וארי בכלל הני ד' הן והאי דכי גוע אהרן משתמש בלשון דהא ושמעינן מינה טעמא דקרא דמה טעם נתראו דהא מית שהרי מת אהרן וריש לקיש לא אתי למימר דלא מתרגמין שום כי בעולם אלא מהני לשונות אלא אפי' מתרגם דלמא ארי דרשינן משמעותיה כמשמעות דהא ומאן דמתרגם וחזיאו כל כנישתא דהא מית טועה הוא דאם כן ואתחזיאו מיבעי ליה ויראו כל העדה במשקל ויראו ראשי הבדים וירפו המים ויעלו מעל משכן קרח:"],[11,"חזרו שניהם בזכות משה","מדכתיב ואכחיד את שלשת הרועים פשיטא לן דבדידהו משתעי שלא מצינו פרנסים לישראל שלשה כאחד אלא הם:"],[11,"מתה בניסן","שנאמר (במדבר כ) ויבואו בני ישראל כל העדה מדבר צין בחדש הראשון וישב העם בקדש ותמת שם מרים ותקבר שם (בפרה) אדומה:"],[11,"אהרן מת","באחד לחדש:"],[13,"מווסתניא","מאותו מקום:"],[13,"אחוו להדדי","מראין ומביטין זה לזה דלא סלקא להו שמעתא כרבא:"]],[[0,"","עשר תעשר. הכי איתא בסיפרי עשר תעשר את כל תבואת זרעך היוצא השדה שנה שנה אין לי אלא תבואת זרעך שחייב במעשר רבית ופרקמטיא וכל שאר רווחים מנין ת\"ל את כל דהוה מצי למימר את תבואתך מאי כל לרבות רבית ופרקמטיא וכל דבר שמרויח בו והכי נמי איכא בהגדה היוצא השדה שנה [שנה] כלומר אם לא תעשר שדך כהוגן לא יהיה לך אלא היוצא מן השדה כלומר לא יעשה שדך אלא כפי מעשרות שהיו קודם לכן דהיינו היוצא מן השדה כלומר מה שהיית רגיל להוציא למעשר מן השדה ומעשה באדם אחד שהיה עשיר והיה לו שדה שעשתה אלף כור והיה אותו עשיר נוטל ק' כורין למעשר ומפריש כל שנה ושנה וכן עשה כל ימיו כשחלה למות קרא לבנו ואמר לו בני דע ששדה זו שאני מוריש לך עושה בכל שנה ושנה אלף כורין הזהר שתפריש ק' כורין כאשר עשיתי ומת אותו האיש ועמד הבן במקומו ועשה השדה אלף כורין כאשר היה עושה בחיי האב והפריש ממנה ק' כורין בשנה שניה נסתכל וראה הבן שמעשר היה דבר גדול ואמר שלא יפריש לשנה אחרת נתמעט השדה ולא עשה כי אם מאה כורין נצטער עליו ושמעו קרוביו שכך מיעט ולא הפריש מעשר באו כולם אצלו מלובשים לבנים ושמחים אמר להם כמדומה לי שאתם שמחים בקלקלתי אמרו לו נצטער עליך כי גרמת לך כל הרעה הזאת ומפני מה לא הפרשת מעשר כראוי היטב בא וראה כי מתחלה כשבא השדה לידך היית בעל הבית והקב\"ה כהן שהיה המעשר חלקו ליתן לעניים ועכשיו שלא הפרשת חלקו לו היה הקב\"ה בעל הבית ואתה כהן שאין שדך עושה מה שהיה עושה מתחלה אלף כורין והפריש לך מאה כורין והיינו דכתיב (במדבר ה) ואיש את קדשיו לו יהיו כלומר כשאינו מפריש כהוגן לא יהיה לו אלא הקדשים כלומר המעשר ועל זה אמרו חכמים המעכב מעשרותיו לסוף בא שלא יהיה לו אלא אחד מעשר כדכתיב (ישעיהו ה) וזרע חומר יעשה איפה דהיינו המעשר דאיפה ג' סאין ובחומר יש (לו) ל' סאין וכן כתיב כי עשרת צמדי כרם יעשו בת אחת וה\"ר נתן האופניא\"ל פי' היוצא מן השדה כלומר ואם לאו שאין אתה מפריש העישור יהיה לאותו היוצא לשדה דהיינו עשו הרשע כלומר שיקחוהו העובדי כוכבים:"]]],[["אקרויה בחלמיה (זכריה יא, ח) ואכחיד את שלשת הרועים למחר כי הוו מיפטרי מיניה אמר להו ליזלו רבנן בשלמא:","רב שימי בר אשי הוה שכיח קמיה דרב פפא הוה מקשי ליה טובא יומא חד חזייה דנפל על אפיה שמעיה דאמר רחמנא ליצלן מכיסופא דשימי קביל עליה שתיקותא ותו לא אקשי ליה","ואף ר\"ל סבר מטר בשביל יחיד דאמר ר\"ל מנין למטר בשביל יחיד דכתיב (זכריה י, א) שאלו מה' מטר בעת מלקוש ה' עושה חזיזים ומטר גשם יתן להם לאיש עשב בשדה","יכול לכל תלמוד לומר לאיש ותניא אי לאיש יכול לכל שדותיו ת\"ל שדה אי שדה יכול לכל השדה ת\"ל עשב","כי הא דרב דניאל בר קטינא הוה ליה ההיא גינתא כל יומא הוה אזיל וסייר לה אמר הא מישרא בעיא מיא והא מישרא לא בעיא מיא ואתא מיטרא וקמשקי כל היכא דמיבעי ליה מיא","מאי ה' עושה חזיזים א\"ר יוסי (בר) חנינא מלמד שכל צדיק וצדיק הקב\"ה עושה לו חזיז בפני עצמו מאי חזיזים אמר רב יהודה פורחות אמר רבי יוחנן סימן למטר פורחות מאי פורחות אמר רב פפא עיבא קלישא תותי עיבא סמיכתא","אמר רב יהודה נהילא מקמי מיטרא אתי מיטרא בתר מיטרא פסיק מיטרא מקמי מיטרא אתי מיטרא וסימניך מהולתא דבתר מיטרא פסיק מיטרא וסימניך חריא דעיזי:","עולא איקלע לבבל חזא פורחות אמר להו פנו מאני דהשתא אתי מיטרא לסוף לא אתי מיטרא אמר כי היכי דמשקרי בבלאי הכי משקרי מיטרייהו","עולא איקלע לבבל חזי מלא צנא דתמרי בזוזא אמר מלא צנא דדובשא בזוזא ובבלאי לא עסקי באורייתא בליליא צערוהו אמר מלא צנא דסכינא בזוזא ובבלאי עסקי באורייתא","תניא ר' אליעזר אומר כל העולם כולו ממימי אוקיינוס הוא שותה שנאמר (בראשית ב, ו) ואד יעלה מן הארץ והשקה את כל פני האדמה אמר לו רבי יהושע והלא מימי אוקיינוס מלוחין הן אמר לו ממתקין בעבים","ר' יהושע אומר כל העולם כולו ממים העליונים הוא שותה שנאמר (דברים יא, יא) למטר השמים תשתה מים אלא מה אני מקיים ואד יעלה מן הארץ מלמד שהעננים מתגברים ועולים לרקיע ופותחין פיהן כנוד ומקבלין מי מטר שנאמר (איוב לו, כז) יזקו מטר לאדו","ומנוקבות הן ככברה ובאות ומחשרות מים על גבי קרקע שנאמר (שמואל ב כב, יב) חשרת מים עבי שחקים ואין בין טיפה לטיפה אלא כמלא נימא ללמדך שגדול יום הגשמים כיום שנבראו בו שמים וארץ","שנאמר (איוב ט, י) עושה גדולות עד אין חקר וכתיב (איוב ה, י) הנותן מטר על פני ארץ וכתיב להלן (ישעיהו מ, כח) הלא ידעת אם לא שמעת אלהי עולם ה' אין חקר לתבונתו (וכתיב (תהלים סה, ז) מכין הרים בכחו וגו')","כמאן אזלא הא דכתיב (תהלים קד, יג) משקה הרים מעליותיו וא\"ר יוחנן מעליותיו של הקב\"ה כמאן כרבי יהושע","ור' אליעזר כיון דסלקי להתם משקה מעליותיו קרי להו דאי לא תימא הכי (דברים כח, כד) אבק ועפר מן השמים היכי משכחת לה אלא כיון דמדלי להתם מן השמים קרי ליה הכא נמי כיון דסלקי להתם מעליותיו קרי ליה","כמאן אזלא [הא] דא\"ר חנינא (תהלים לג, ז) כונס כנד מי הים נותן באוצרות תהומות מי גרם לאוצרות שיתמלאו בר תהומות כרבי אליעזר ור' יהושע ההוא"],[[0,"אקרויה","היו מקרין אותו מקרא זה בחלום ואכחיד את שלשת הרועים בירח אחד שרוצין לעונשן בשמים משום דמכספי ליה:"],[1,"קבל עליו","רב שימי שתיקותא מלהקשות עוד:"],[3,"יכול לכל","כלומר יכול אין נותן מטר אא\"כ הכל צריכין לו:"],[3,"ת\"ל לאיש","אפילו בשביל אחד:"],[3,"אי לאיש יכול לכל שדותיו","כלומר אינו יורד עד שהוא צריך לכל שדותיו:"],[3,"ת\"ל שדה","אפי' אינו צריך אלא בשדה אחד:"],[3,"אי בשדה יכול עד שיצטרך לכל השדה ת\"ל עשב","אפילו אינו צריך אלא לעשב אחד (עשב) בשביל ירק אחד יורד עליו מטר:"],[4,"וסייר","מעיין:"],[4,"מישרא","ערוגה:"],[5,"עושה לו חזיז","לכל צדיק הבא בעולם הזה להריק לו גשמים על שדותיו ברישא בעי מאי חזיזים לשון רבים והדר בעי ומאי נינהו חזיזים מאי נינהו דקרי חזיזי:"],[5,"ה\"ג עיבא קלישתא דתותי עיבא סמיכתא","דתותי עיבא כלפי הארץ:"],[6,"נהילא","כמו קיטמא נהילא (חולין נא:) שהיא דקה גשמים דקים כקמחא נהילא שהיא דקה הבאין תחילה למטר ואח\"כ בא מטר:"],[6,"אתי מיטרא","גשמים יורדין לרוב ואין פוסקין מהר אבל בא מטר תחילה ומתחילין דקין לבא פוסקין מיד:"],[6,"מהולתא","שמתחילה יוצא קמח דק ולבסוף סובין גסין:"],[6,"חריא דעיזי","ריעי של עזים בתחילה יוצאה גסה ולבסוף דקה ופוסק:"],[8,"דתמרי","דבש עושין מהן:"],[8,"ובבלאי לא עסקי","כלומר יכולין הן לעסוק תמיד שיש להן מזונות בזול ובלא טורח:"],[8,"מצערים","בשלשול דאמרו (גיטין דף ע.) תמרי משחנן ומשלשלן:"],[8,"מלא צנא דסכיני בזוזא","שמתוך שלוקחין אותו בזול אוכלין מהן הרבה ומצערים אותן:"],[9,"ממימי אוקיינוס","כלומר ממים של מטה ולא ממים של מעלה שנאמר ואד יעלה מן הארץ ששתה בארץ ועלה:"],[9,"מלוחין הן","ואין תבואה גדילה מהן:"],[10,"יזקו מטר לאדו","רקיעין מוציאין מים לעבים:"],[10,"יזקו","כמו יצוקו צק לעם ויאכלו (מלכים ב ד׳:מ״א):"],[11,"חשרת מים עבי שחקים","העבים מחשרין כלומר משירין המים לארץ:"],[11,"ללמדך","אקרא דלקמן קאי ואומר מכין הרים לא גרסינן הכא:"],[12,"ואומר מכין הרים","לא גרסינן הכא:"],[13,"ואמר רבי יוחנן מעליותיו של מעלה","כלומר ממים העליונים ורבי יוחנן מים העליונים אתא לאשמועינן דאי לאו רבי יוחנן הוי אמינא דהכי קאמר מעליות שהקדוש ברוך הוא עומד בהם הוא משקה אותן למטה ולעולם המים מאוקיינוס:"],[13,"כרבי יהושע","דאמר ממים העליונים:"],[14,"ור' אליעזר","אמר לעולם מעליותיו של הקב\"ה כרבי יוחנן וכו':"],[15,"תהומות","מים של מטה כדכתיב תהומות יכסיומו (שמות טו):"]],[[3,"","תלמוד לומר עשב. פי' שאם לא יהיו צריכים אלא לעשב אחד ירד על אותו עשב ועל שאר כל השדה לא ירדו:"],[6,"","נהילא מקמי מיטרא. פי' גשם דק וסימנך מהולתא פירוש שמתחילה יוצא הפסולת ואח\"כ הסולת פירוש שלא היו עושין כמו דעבדינן האידנא היו כותשין החטין במכתשת עד שנקלף כל הסובין מעל החטים וכי הוו מרקדין על גבי נפה היה הפסולת הסובין שעליו יוצא לכתחילה ואחר כך היה יוצא הסולת:"],[6,"אתי מיטרא","גשמים יורדין לרוב ואין פוסקין מהר אבל בא מטר תחילה ומתחילין דקין לבא פוסקין מיד:"],[6,"","חריא דעיזי. פי' ריעי של עזים שבתחילה ריעי גדול וכשהיא פוסקת מתרזת זבל דק:"],[13,"","ואמר רבי יוחנן מעליותיו של הקב\"ה כמאן כר' יהושע. פי' כרבי יהושע דאמר כל העולם כולו ממים העליונים הם שותים דאי כרבי אליעזר הא אמר מימי אוקיינוס הוא שותה:"]]],[["בברייתו של עולם","ת\"ר א\"י נבראת תחילה וכל העולם כולו נברא לבסוף שנאמר (משלי ח, כו) עד לא עשה ארץ וחוצות א\"י משקה אותה הקב\"ה בעצמו וכל העולם כולו ע\"י שליח שנאמר (איוב ה, י) הנותן מטר על פני ארץ ושולח מים על פני חוצות","א\"י שותה מי גשמים וכל העולם כולו מתמצית שנאמר הנותן מטר על פני ארץ וגו' א\"י שותה תחילה וכל העולם כולו לבסוף שנאמר הנותן מטר על פני ארץ וגו' משל לאדם שמגבל את הגבינה נוטל את האוכל ומניח את הפסולת","אמר מר ממתקין הן בעבים מנליה דא\"ר יצחק בר יוסף א\"ר יוחנן כתיב (תהלים יח, יב) חשכת מים עבי שחקים וכתיב (שמואל ב כב, יב) חשרת מים עבי שחקים","שקול כף ושדי אריש וקרי ביה חכשרת","ור' יהושע בהני קראי מאי דריש בהו סבר לה כי הא דכי אתא רב דימי אמר אמרי במערבא נהור ענני זעירין מוהי חשוך ענני סגיין מוהי","כמאן אזלא הא דתניא מים העליונים במאמר הם תלוים ופירותיהן מי גשמים שנאמר (תהלים קד, יג) מפרי מעשיך תשבע הארץ כמאן כר' יהושע ור' אליעזר ההוא במעשה ידיו של הקב\"ה הוא דכתיב","אריב\"ל כל העולם כולו מתמצית גן עדן הוא שותה שנאמר (בראשית ב, י) ונהר יוצא מעדן וגו' תנא מתמצית בית כור שותה תרקב:","ת\"ר ארץ מצרים הויא ד' מאות פרסה על ד' מאות פרסה והוא אחד מששים בכוש וכוש אחד מששים בעולם ועולם א' מששים בגן וגן אחד מששים לעדן ועדן אחד מס' לגיהנם נמצא כל העולם כולו ככיסוי קדרה לגיהנם וי\"א גיהנם אין לה שיעור וי\"א עדן אין לה שיעור","א\"ר אושעיא מאי דכתיב (ירמיהו נא, יג) שוכנת על מים רבים רבת אוצרות מי גרם לבבל שיהו אוצרותיה מליאות בר הוי אומר מפני ששוכנת על מים רבים אמר רב עתירה בבל דחצדא בלא מיטרא אמר אביי נקיטינן טובעני ולא יובשני:","\u0001מתני׳\u0002 בג' במרחשון שואלין את הגשמים רבן גמליאל אומר בשבעה בו ט\"ו יום אחר החג כדי שיגיע אחרון שבישראל לנהר פרת:","\u0001גמ׳\u0002 א\"ר אלעזר הלכה כרבן גמליאל תניא חנניה אומר ובגולה עד ששים בתקופה אמר רב הונא בר חייא אמר שמואל הלכה כחנניה","איני והא בעו מיניה משמואל מאימת מדכרינן ותן טל ומטר אמר להו מכי מעיילי ציבי לבי טבות רישבא דילמא אידי ואידי חד שיעורא הוא","איבעיא להו יום ששים כלפני ששים או כלאחר ששים ת\"ש רב אמר יום ששים כלאחר ששים ושמואל אמר יום ששים כלפני ששים","א\"ר נחמן בר יצחק וסימנך עילאי בעו מיא תתאי לא בעו מיא אמר רב פפא הלכתא יום ששים כלאחר ששים:","\u0001מתני׳\u0002 הגיע י\"ז במרחשון ולא ירדו גשמים התחילו היחידים מתענין ג' תעניות אוכלין ושותין משחשיכה ומותרין במלאכה וברחיצה ובסיכה ובנעילת הסנדל ובתשמיש המטה הגיע ר\"ח כסליו ולא ירדו גשמים ב\"ד גוזרין שלש תעניות על הצבור אוכלין ושותין משחשיכה ומותרין במלאכה וברחיצה ובסיכה ובנעילת הסנדל ובתשמיש המטה:","\u0001גמ׳\u0002 מאן יחידים אמר רב הונא רבנן ואמר רב הונא יחידים מתענין שלשה תעניות שני וחמישי ושני","מאי קמשמע לן תנינא אין גוזרין תענית על הצבור בתחילה בחמישי שלא להפקיע את השערים אלא שלש תעניות הראשונות שני וחמישי ושני","מהו דתימא הני מילי צבור אבל יחיד לא קמשמע לן תניא נמי הכי כשהתחילו היחידים להתענות מתענין שני וחמישי ושני ומפסיקין בראשי חדשים"],[[0,"בברייתו של עולם","כתיב שהיה כל העולם שטוף במים והקב\"ה כונסן במקום אחד כמכניס מים בנאד שנתנם באוצרות דכתיב נותן באוצרות תהומות שם חול גבולו ואוצר לים:"],[1,"על פני ארץ","א\"י:"],[2,"משיורי תמצית","מה שנשאר בעבים אחר שתיית':"],[2,"בתחילה שותה","שם יורדין הגשמים תחילה כך שמעתי:"],[3,"חשרת מים וחשכת מים","שני מקראות הן חד בתהלים וחד בשמואל בוידבר דוד:"],[4,"ה\"ג שקול כף ושדי אריש","כלומר קח כף שבמלת חשכת וצרפו עם מלת חשרת וקרי ביה חכשרת שממתקין ומכשירין בעבים:"],[5,"חשוך ענני סגיאין מימוהי","והיינו דכתיב חשכת מים:"],[5,"נהור ענני","כשהענן קליש זעירן מימוהי ומכלל חשוך סגיאין אתה למד אבל נהור זעירין וחשרת לשון השרה כמו אין שורין דיו (שבת דף יז:) כו' כדדריש ליה רבי יהושע לעיל אבל חשכת מיבעי ליה להכי ולהכי:"],[6,"במאמר הן תלוין","אינן נחות על שום דבר אלא מכונסות ועומדות כמין בריכה ותלויות במאמרו של הקב\"ה:"],[6,"ופירותיהן מי גשמים","משום לישנא דקרא נקט הכי משום דכתיב מפרי מעשיך תשבע הארץ ופירותיהם כלומר מזיעת המים שאין נחסרין כלום כדכתיב (תהילים ס״ה:י׳) פלג אלהים מלא מים כל שעה והקרן קיימת ופירותיהן מי גשמים וכן מפורש בבראשית רבה:"],[7,"ונהר יוצא מעדן","סימן לדבר שגן עדן שותה מן הגשמים תחילה דכתיב ונהר יוצא מעדן להשקות את הגן וגו':"],[7,"תנא מתמצית בית כור","כלי שמשקין במימיו בית כור יכולין להשקות בתמציתו שיעור זריעת תרקב שהוא אחד מששים בבית כור והכי נמי עולם אחד מששים בגן עדן ודי לו בתמצית העננים המשקין את הגן גן לפני כל העולם כולו כעדן לגן:"],[8,"נמצא כל העולם ככיסוי קדרה","הקטן כנגד הקדרה:"],[9,"שוכנת על מים רבים","רבת אוצרות בא קצך אמת בצעך:"],[9,"שרבו אוצרותיה","שקנו עושר:"],[9,"מים רבים","שמשקין שדותיהן דבבל עמוקים מכל הארצות וגשמים מטפטפין ויורדין שם:"],[9,"עתירה בבל","עשירה היא בבל שקוצרין בה תבואה בלא מטר שאינן צריכים לגשמים:"],[9,"נקטינן","דהכי חצדא בבל בלא מיטרא:"],[9,"דטובעני","היא מקום מצולה ורקק:"],[9,"ולא יובשני","שאינה יבשה:"],[10,"מתני' בשלשה במרחשון שואלין את הגשמים וכו' רבן גמליאל אומר בשבעה בו בט\"ו יום אחר החג","כלומר בשבעה במרחשון הוא ט\"ו אחר החג:"],[10,"כדי שיגיע האחרון","כלומר קודם ביאת מים לנהר פרת שהוא רחוק יותר:"],[11,"גמ' ובגולה ששים","ובגולה אין שואלין עד ששים בתקופה לפי שהוא מקום נמוך ואין צריכים מטר כל כך:"],[12,"מכי מעיילי ציבי לבי טבות רישבא","משעה שמכניסין עצים לאוצר לצורך ימות הגשמים שכן היו נוהגין לפי שהיו יודעין שזמן גשמים הוא משם ואילך ולא היו יכולין לחטוב עצים ביער:"],[12,"רישבא","צייד עופות כמו אין פורשין רשבים ליונים (ב\"ק דף עט:) טבות שם אדם:"],[13,"כלפני ס'","ולא מדכרינן:"],[13,"כלאחר ס'","ומדכרינן:"],[14,"עילאי בעו מים","העומדים בהרים צריכין יותר מים מפני שהגשמים מתגלגלים ויורדין למטה:"],[14,"תתאי לא בעו מים","שמתכנסין כל מימי ההרים לבקעה ה\"נ רב שהיה מארץ ישראל כדאמרינן בעלמא (גיטין דף ו.) מכי אתא רב לבבל וארץ ישראל גבוהה מכל הארצות משום הכי אמר כלאחר ששים ובבבל בגולה מתוך שאינן צריכין לגשמים אין שואלין עד ס' לתקופת תשרי וכן אנו נוהגים שכל מנהגינו אחר בני בבל:"],[15,"מתני' הגיע שבעה עשר וכו'","אוכלין ושותין משחשיכה שאין אוכלין מבעוד יום כיום הכפורים ותשעה באב:"],[17,"גמ' מאי קמ\"ל","האי דקאמר שני וחמישי ושני:"],[17,"תנינא","בפירקין דלקמן (תענית דף טו:) אין גוזרין תענית כו' שלא להפקיע את השערים שאם היו מתחילין להתענות בחמישי היו קונין למוצאי התענית שתי סעודות גדולות אחד לתענית ואחד לשבת וכסבור המוכר שרעב בא לעולם ואתי לאפקועי שערים:"],[17,"אפקועי","מבטל שיעור מדה הראשונה וממעטה:"],[18,"אבל יחידים לא","שלש תעניות שהיחידין עושין קודם לצבור אינן זקוקין להתחיל בשני דליכא אפקיעת שערים משום יחידים לחודייהו והללו ג' תעניות דיחידים אינן בכלל י\"ג תעניות דצבור תדע דקא חשיב במתני' שלש ושלש ושבע:"],[18,"ומפסיקין בראשי חדשים","שאם חל ר\"ח בשני ובחמישי לאחר שהתחילו להתענות פוסקין תעניתם:"]],[[4,"","קרי ביה חכשרת. פי' הטל הכ\"ף מן חשכת ושדי עם חשרת ויהיה חכשרת כלומר שהמים בעננים מתכשרים שהעננים שותים לבסוף הם ממתקים בעבים:"],[9,"","טובעני ולא יובשני. פי' מוטב להיות בארץ שהיא לחה מכשהיא יבשה:"],[14,"","הלכתא יום ס' כלאחר ס'. וכן עמא דבר ויום תקופה מתחיל:"],[17,"","אין גוזרין תענית על הצבור בתחילה בחמישי שלא להפקיע השערים. פי' שע\"י שעשו הצבור תענית יקנו מזון של חמישי ושל שבת וכסבורים העם יוקר היא ויפקיעו השערים:"]]],[["ובימים טובים הכתובין במגילת תענית","תנו רבנן אל יאמר אדם תלמיד אני איני ראוי להיות יחיד אלא כל תלמידי חכמים יחידים אי זהו יחיד ואיזהו תלמיד יחיד כל שראוי למנותו פרנס על הצבור תלמיד כל ששואלין אותו דבר הלכה בלמודו ואומר ואפילו במסכת דכלה","תנו רבנן לא כל הרוצה לעשות עצמו יחיד עושה תלמיד עושה דברי ר' מאיר רבי יוסי אומר עושה וזכור לטוב לפי שאין שבח הוא לו אלא צער הוא לו","תניא אידך לא כל הרוצה לעשות עצמו יחיד עושה תלמיד עושה דברי רבי שמעון בן אלעזר רבן שמעון בן גמליאל אומר במה דברים אמורים בדבר של שבח אבל בדבר של צער עושה וזכור לטוב שאין שבח הוא לו אלא צער הוא לו","ת\"ר מי שהיה מתענה על הצרה ועברה על החולה ונתרפא הרי זה מתענה ומשלים ההולך ממקום שאין מתענין למקום שמתענין הרי זה מתענה עמהן ממקום שמתענין למקום שאין מתענין הרי זה מתענה ומשלים","שכח ואכל ושתה אל יתראה בפני הצבור ואל ינהיג עידונין בעצמו שנאמר (בראשית מב, א) ויאמר יעקב לבניו למה תתראו אמר להם יעקב לבניו אל תראו עצמכם כשאתם שבעין לא בפני עשו ולא בפני ישמעאל כדי שלא יתקנאו בכם","(בראשית מה, כד) אל תרגזו בדרך אמר רבי אלעזר אמר להם יוסף לאחיו אל תתעסקו בדבר הלכה שמא תרגזו עליכם הדרך","איני והאמר ר' אלעאי בר ברכיה שני תלמידי חכמים שמהלכים בדרך ואין ביניהן דברי תורה ראויין לישרף שנאמר (מלכים ב ב, יא) ויהי המה הולכים (הולך) ודבר והנה רכב אש וסוסי אש ויפרידו בין שניהם טעמא דאיכא דיבור הא ליכא דיבור ראויין לישרף","לא קשיא הא למיגרס הא לעיוני","במתניתא תנא אל תפסיעו פסיעה גסה והכניסו חמה לעיר אל תפסיעו פסיעה גסה דאמר מר פסיעה גסה נוטלת אחד מחמש מאות ממאור עיניו של אדם","והכניסו חמה לעיר כדרב יהודה אמר רב דאמר רב יהודה אמר רב לעולם יצא אדם בכי טוב ויכנס בכי טוב שנאמר (בראשית מד, ג) הבקר אור והאנשים שלחו","אמר רב יהודה אמר רבי חייא המהלך בדרך אל יאכל יותר משני רעבון מאי טעמא הכא תרגימו משום מעיינא במערבא אמרי משום מזוני מאי בינייהו איכא בינייהו"],[[0,"","וכן בימים טובים הכתובים במגילת תענית:"],[1,"תלמיד אני","ואיני חשוב כל כך כיחידים כלומר איני ראוי להתחיל תענית עם היחידים:"],[2,"לא כל הרוצה לעשות עצמו יחיד","לענין תענית:"],[2,"עושה","דנראה מגסי הרוח ותנן (אבות פרק ג משנה י) כל שרוח הבריות נוחה הימנו כו':"],[2,"הכי גרסינן התלמידים עושין עצמן","כדאמרינן לעיל שכל התלמידים ראויין לכך ואין בהם משום גסות הרוח:"],[2,"רבי יוסי אומר כל אדם","ואפילו שאינו תלמיד עושה עצמו יחיד להתענות וזכור לטוב דצער הוא לו ולא גסות לישנא אחרינא גרסינן לא כל הרוצה לעשות עצמו יחיד עושה תלמיד עושה כלומר ולא כל הרוצה נמי לעשות עצמו תלמיד להתנהג עצמו במדת תלמיד בחלוקו ובמטתו ולהתנאות בסודר של תלמידי חכמים ושאר דברים עושה דכל הרוצה ליטול לו את השם לא יטול ורבי יוסי ארישא ומסתבר כי האי לישנא מדקא מהדר רבן שמעון בן גמליאל דבר של שבח אינו עושה מכלל דאיירי בשבח:"],[4,"על החולה ונתרפא","הוא הדין אם מת החולה בעי לקיומי נדרו:"],[4,"על הצרה ועברה","מתענה ומשלים ואם לאו נראה כמתנה עם קונו אם תעבור (אתענה) ואם לאו (לא) אתענה:"],[4,"למקום שאין מתענין הרי זה מתענה ומשלים","כל התעניות שקבלו עליהן בני עירו דנותנין עליו חומרי המקום שיצא משם:"],[5,"אכל ושתה","דיעבד:"],[5,"אל יתראה בפניהן","שנראה כחתן בין אבלים ויתקנאו בו:"],[5,"ואל ינהיג עדונים בעצמו","שלא יאמר הואיל ואכלתי כל שהוא אוכל הרבה:"],[5,"אל תראו עצמכם","שיש לכם חטים הרבה ולא הלכו אלא בשביל דבר זה שלא להתראות בפני בני עשו שהיו צעורים ורעבים:"],[6,"תרגזו עליכם הדרך","תתעו:"],[7,"לישרף באש","דכתיב והנה סוסי אש וכתיב בההוא עניינא הלוך ודבר ואהכי כתביה לאשמועינן דאי לאו שהיו הולכין בעומקה של הלכה לא [היו ניצולין]:"],[8,"הא למגרס","מבעי ליה באורחא אבל במלתא דמבעי ליה לעיוני לא:"],[9,"במתניתא תנא","מאי אל תרגזו בדרך אל תזיקו עצמכם בפסיעה גסה:"],[9,"והכניסו חמה לעיר","כשאתם לנין ושוכבין בדרך בעיירות הכניסו לעיר בעוד שהחמה זורחת:"],[10,"יצא אדם בכי טוב","שימתין עד שיאור כמו וירא אלהים את האור כי טוב (בראשית א):"],[10,"ויכנס בכי טוב","בערב בעוד שהחמה זורחת שאין ליסטין מצויין אי נמי שלא יפול בבורות ובקעים שבעיר שלא יעלילו עליו עלילות מרגל אתה או גנב:"],[10,"הבוקר אור והאנשים שולחו המה וחמוריהם","מיכן שיצאו בכי טוב והוא הדין ליכנס בכי טוב יש ספרים דלא כתיב בהו האי קרא אלא מילתא דרב יהודה סברא הוא ולא בעי' קרא:"],[11,"לא יאכל יותר ממה שאוכל בשני רעבון","דאמר לקמן (תענית דף יא.) שצריך להרעיב עצמו בשני רעבון:"],[11,"(הכא","זה בבלי הוא וכי משתעי בבבל קאמר הכא וכל הא לן והא להו בבבל קאמר):"],[11,"משום מעיינא","שלא יתחלחלו מעיו של אדם ברוב אכילתו מפני טורח הדרך יש אומרים יהיו מעיו של אדם שופכין זה לזה כעין מעיין:"],[11,"משום מזוני","שמא אין לו לאח\"כ:"]],[[1,"","איזהו יחיד כו' שראוי למנותו פרנס על הצבור להיות פרנס ואיזהו תלמיד. כל ששואלין דבר הלכה בכל מקום וכו'. וקשה דהכא משמע דקרי תלמיד אותו שיודע להשיב כששואלין לו דבר הלכה בכל מקום ואומרה והתם אמרינן במס' שבת פרק ואלו קשרים (שבת דף קיד.) איזהו תלמיד הראוי למנותו פרנס על הצבור כשיודע להשיב כל ששואלין דבר הלכה ואפילו במסכת כלה אלמא הראוי למנותו פרנס על הצבור הוי כשיודע להשיב והכא משמע דאותו הראוי למנותו פרנס הוי מילתא אחריתי ועוד דהכא משמע דיחיד עדיף מדקאמר בסמוך לא כל הרוצה לעשות עצמו יחיד עושה אבל הרוצה לעשות עצמו תלמיד עושה ויש לומר דיש חילוק בתלמיד דדוקא כשהרב בא אל מקום אחד וכל התלמידים אצלו זה שואל אל הרב ממה שהוא לומד וזה שואל ממקום אחר ואותו הרב יודע להשיב לכל התלמידים לכל אחד ואחד כפי שאילתו ואפילו במס' כלה זהו יחיד דעדיף מתלמיד דהכא ונקרא תלמיד התם בפרק אלו קשרים אותו ודאי ראוי למנותו פרנס על הצבור אבל אם אינו יודע להשיב אלא במסכת שלו נקרא גם כן תלמיד ומזה מיירי הכא:"],[4,"","ההולך ממקום שמתענין למקום שאין מתענין הרי מתענה ומשלים. ל\"ש דעתו לחזור ל\"ש אין דעתו לחזור הואיל וקבל עליו התענית:"],[5,"","למה תתראו. כמו שמפרש אל תראו עצמכם בפני בני עשו וכו' ויש במדרש למה תתראו פירוש למה תהיו כחושין:"],[6,"","אל תרגזו בדרך. ויש מדרש אל תפסיקו מדבר הלכה:"],[7,"","ואין ביניהם דברי תורה ראוים לישרף דכתיב ויהי המה הולכים הלוך ודבר וגו' טעמא דאיכא דבור וכו'. ויש מדרש שהם היו מדברים דברים בטלים ומש\"ה ראוין לישרף:"],[9,"","פסיעה גסה נוטלת אחת מחמש מאות ממאור עיניו של אדם ואין להקשות אם כן בחמש מאות פסיעות גסות יהיה ניטל כל מאור עיניו של אדם והא קא חזינן דלאו הכי הוה ונראה לפרש דהפסיעה ראשונה נוטל אחת מחמש מאות והפסיעה שניה נוטל פחות מן הראשונה ששניה אינה נוטלת אלא אחד מחמש מאות הנשארים כמו בעישורייתא דבי רבי (כתובות דף סח.) ר\"ל העישור ממה שנשאר אבל עדיין קשה דמ\"ש פסיעה ראשונה דנוטלת יותר מן השניה אלא יש לומר דלא נוטלת אלא פסיעה ראשונה דוקא ומכאן ואילך כיון דדש דש אי נמי פסיעה ראשונה נוטלת טפי משום דכל התחלות קשות:"],[10,"","לעולם יצא אדם בכי טוב. פי' בפרק קמא דפסחים (דף ב.) [וע\"ע תוס' ב\"ק ס:]:"],[11,"","משום מעיינא. פירוש משום שהבני מעיין הוי קשה להו:"]]],[["דיתיב בארבא אי נמי דקאזיל מאוונא לאוונא","רב פפא כל פרסה ופרסה אכיל חדא ריפתא קסבר משום מעיינא","אמר רב יהודה אמר רב כל המרעיב עצמו בשני רעבון ניצל ממיתה משונה שנאמר (איוב ה, כ) ברעב פדך ממות מרעב מיבעי ליה אלא הכי קאמר בשכר שמרעיב עצמו בשני רעבון ניצול ממיתה משונה","אמר ריש לקיש אסור לאדם לשמש מטתו בשני רעבון שנאמר (בראשית מא, נ) וליוסף ילד שני בנים בטרם תבוא שנת הרעב תנא חסוכי בנים משמשין מטותיהן בשני רעבון","תנו רבנן בזמן שישראל שרויין בצער ופירש אחד מהן באין שני מלאכי השרת שמלוין לו לאדם ומניחין לו ידיהן על ראשו ואומרים פלוני זה שפירש מן הצבור אל יראה בנחמת צבור","תניא אידך בזמן שהצבור שרוי בצער אל יאמר אדם אלך לביתי ואוכל ואשתה ושלום עליך נפשי ואם עושה כן עליו הכתוב אומר (ישעיהו כב, יג) והנה ששון ושמחה הרוג בקר ושחוט צאן אכול בשר ושתות יין אכול ושתו כי מחר נמות מה כתיב בתריה (ישעיהו כב, יד) ונגלה באזני ה' צבאות אם יכופר העון הזה לכם עד תמותון","עד כאן מדת בינונים אבל במדת רשעים מה כתיב (ישעיהו נו, יב) אתיו אקחה יין ונסבאה שכר והיה כזה יום מחר מה כתיב בתריה הצדיק אבד ואין איש שם על לב כי מפני הרעה נאסף הצדיק","אלא יצער אדם עם הצבור שכן מצינו במשה רבינו שציער עצמו עם הצבור שנאמר (שמות יז, יב) וידי משה כבדים ויקחו אבן וישימו תחתיו וישב עליה וכי לא היה לו למשה כר אחת או כסת אחת לישב עליה אלא כך אמר משה הואיל וישראל שרויין בצער אף אני אהיה עמהם בצער וכל המצער עצמו עם הצבור זוכה ורואה בנחמת צבור","ושמא יאמר אדם מי מעיד בי אבני ביתו של אדם וקורות ביתו של אדם מעידים בו שנאמר (חבקוק ב, יא) כי אבן מקיר תזעק וכפיס מעץ יעננה דבי רבי שילא אמרי שני מלאכי השרת המלוין לו לאדם הן מעידין עליו שנאמר (תהלים צא, יא) כי מלאכיו יצוה לך","רבי חידקא אומר נשמתו של אדם היא מעידה עליו שנאמר (מיכה ז, ה) משוכבת חיקך שמור פתחי פיך ויש אומרים אבריו של אדם מעידים בו שנאמר (ישעיהו מג, י) אתם עדי נאם ה'","(דברים לב, ד) אל אמונה ואין עול אל אמונה כשם שנפרעין מן הרשעים לעולם הבא אפילו על עבירה קלה שעושין כך נפרעין מן הצדיקים בעולם הזה על עבירה קלה שעושין","ואין עול כשם שמשלמין שכר לצדיקים לעולם הבא אפילו על מצוה קלה שעושין כך משלמין שכר לרשעים בעולם הזה אפילו על מצוה קלה שעושין","צדיק וישר הוא (אמרו בשעת) פטירתו של אדם לבית עולמו כל מעשיו (נפטרין) לפניו ואומרים לו כך וכך עשית במקום פלוני ביום פלוני והוא אומר (הין) ואומרים לו חתום וחותם שנאמר (איוב לז, ז) ביד כל אדם יחתום ולא עוד אלא שמצדיק עליו את הדין ואומר להם יפה דנתוני לקיים מה שנאמר (תהלים נא, ו) למען תצדק בדברך","אמר שמואל כל היושב בתענית נקרא חוטא סבר כי האי תנא דתניא ר' אלעזר הקפר ברבי אומר מה תלמוד לומר (במדבר ו, יא) וכפר עליו מאשר חטא על הנפש וכי באיזה נפש חטא זה אלא שציער עצמו מן היין","והלא דברים קל וחומר ומה זה שלא ציער עצמו אלא מן היין נקרא חוטא המצער עצמו מכל דבר ודבר על אחת כמה וכמה","ר' אלעזר אומר נקרא קדוש שנאמר (במדבר ו, ה) קדוש יהיה גדל פרע שער ראשו ומה זה שלא ציער עצמו אלא מדבר אחד נקרא קדוש המצער עצמו מכל דבר על אחת כמה וכמה","ולשמואל הא איקרי קדוש ההוא אגידול פרע קאי ולר' אלעזר הא נקרא חוטא ההוא דסאיב נפשיה","ומי אמר רבי אלעזר הכי והאמר ר' אלעזר לעולם ימוד אדם עצמו"],[[0,"דיתיב בארבא","שהולך בספינה משום מזוני איכא משום מעיינא ליכא:"],[0,"מאוונא לאוונא","מקום מלון התגרים מכפר לכפר דמשתכחי מזוני וליכא למיחש למזוני ולמעיינא איכא למיחש:"],[1,"כל פרסה ופרסה אכל ריפתא","קסבר רב פפא הא דאמור רבנן לא ליכול טפי משום מעיינא ואיהו לא מיסתפי ממעיינא דבעל בטן הוה ענין אחר כריסו רחבה כדאיתא בבבא מציעא (דף פד.) דקא חשיב אבריה דרב פפא וכאיש גבורתו ולפיכך יכול לאכול הרבה ואינו מזיק לו:"],[2,"מיתה משונה","מת בחרב וברעב וכל מיתה שאינה בידי מלאך המות כדרך כל אדם על מטתו:"],[2,"בשכר שמצער עצמו","כשישראל בצער:"],[3,"אסור לשמש מטתו בשני רעבון","דצריך אדם לנהוג צער בעצמו:"],[3,"חסוכי בנים","חסירי בנים דגרסינן במנחות (דף כט.) לגבי מנורה ומי חסיכי כולי האי שלא קיימו פריה ורביה:"],[4,"שני מלאכי שרת מלוין לו לאדם","אחד מימינו ואחד משמאלו דכתי' (תהילים צ״א:י״א) כי מלאכיו יצוה לך:"],[5,"","הנה ששון ושמחה הרוג בקר ושחוט צאן אכול בשר ושתות יין כי מחר נמות ונגלה באזני ה' צבאות אם יכופר העון הזה לכם עד תמותון:"],[6,"זו מידת בינונים","שיראין מן המיתה כדכתיב בהו כי מחר נמות:"],[6,"אתיו אקחה יין ונסבאה שכר והיה כזה יום מחר","גדול יותר מאד:"],[6,"הצדיק אבד ואין איש שם על לב","מפני מה הוא מת מפני הרעה נאסף הצדיק מפני שלא יצטער הוא ברעה ואחר שהיא גזרה מלפניו כי מפני הרעה נאסף הצדיק ל\"א מפני רעות של אלו הוא נאסף שאין הקב\"ה רוצה שיבקש עליהם רחמים:"],[8,"כפיס","חצי לבינה ורגילין לתתה בין שתי נדבכי העצים:"],[9,"","הכי גרסינן אבריו של אדם הן מעידין בו שנאמר ואתם עדי לשון רבים נאם ה':"],[10,"מאי דכתיב אל אמונה ואין עול כשם שמשלם כו'","כך משלם לרשעים בעולם הזה כדי לטורדן מן העולם הבא וכדכתיב (דברים ז׳:י׳) ומשלם לשונאיו אל פניו להאבידו:"],[11,"ואין עול","שאין עושה דין בלא דין אמת וצדק:"],[12,"צדיק וישר","מצדיק הדין על הצדיקים לפרוע מהם ועושה טובה וישרות עם הרשעים לפרוע כל זכותם בעולם הזה כדי לטורדן:"],[12,"ביד כל אדם יחתום","כותב מעשה כל אדם ומחתים יד על כל מעשיו:"],[12,"למען תצדק בדברך","שהוא מצדיק עליו בדבריך שאתה מראה לו:"],[13,"וכי באיזה נפש חטא זה","מי הרג שנקרא חוטא שאין מצוה לצער עצמו כדאמרינן צדיקי (מי) אכלי האי עלמא (והאיך) מי סני להו במס' הוריות (פ\"ג דף י:):"],[15,"נקרא קדוש","רישיה דקרא קא דריש בשביל שמתוך כך מתמרקין עונותיו שמתענה:"],[16,"לשמואל קדוש יהיה אגדל פרע קאי","ששערו אסור בהנאה אבל הוא עצמו לא נקרא קדוש ולר' אלעזר חוטא דסאיב כתרגומו מאשר חטא על הנפש פשט המקרא על שנטמא במת:"]],[[3,"","אסור לאדם לשמש מטתו בשני רעבון. ואם תאמר הרי יוכבד נולדה בין החומות ואותו העת עת רעב היה וע\"כ שימשו מטותיהן בשני רעבון ויש לומר דלכ\"ע לא הוי אסור אלא למי שרוצה לנהוג עצמו בחסידות ויוסף לא שימש אבל שאר בני אדם שימשו:"],[13,"","אמר שמואל כל היושב בתענית נקרא חוטא. וקשיא דאמרינן בפ' החובל (ב\"ק דף צא: ושם) החובל בעצמו רשאי אבל אחרים שחבלו בו חייבים ומפרש התם הא דקאמר החובל בעצמו רשאי אמר שמואל ביושב בתענית אלמא משמע דשמואל קאמר דיושב בתענית לא נקרא חוטא ויש לומר דודאי הוי חוטא כדאמרינן הכא מקל וחומר מנזיר ומה נזיר שלא ציער עצמו אלא מיין וכו' אבל מכל מקום המצוה שהוא עושה התענית גדול יותר מן העבירה ממה שהוא מצער נפשו דמצוה לנדור כדאמרינן (סוטה דף ב.) הרואה סוטה בקלקולה יזיר עצמו מן היין ומכל מקום יש קצת חטא מידי דהוה אמתענה תענית חלום בשבת דקורעין גזר דינו ונפרעין ממנו תענית של שבת ומאי תקנתיה ליתב תעניתא לתעניתיה:"]]],[["כאילו קדוש שרוי בתוך מעיו שנאמר (הושע יא, ט) בקרבך קדוש ולא אבוא בעיר לא קשיא הא דמצי לצעורי נפשיה הא דלא מצי לצעורי נפשיה","ר\"ל אמר נקרא חסיד שנאמר (משלי יא, יז) גומל נפשו איש (חסיד) [צ\"ל חסד] ועוכר שארו וגו' אמר רב ששת האי בר בי רב דיתיב בתעניתא ליכול כלבא לשירותיה","אמר רבי ירמיה בר אבא אין תענית צבור בבבל אלא תשעה באב בלבד (אמר) ר' ירמיה בר אבא אמר ריש לקיש אין תלמיד חכם רשאי לישב בתענית מפני שממעט במלאכת שמים:","אוכלין ושותין משחשיכה כו': אמר רבי זעירא אמר רב הונא יחיד שקיבל עליו תענית אפילו אכל ושתה כל הלילה למחר הוא מתפלל תפלת תענית לן בתעניתו אינו מתפלל של תענית","אמר רב יוסף מאי קסבר רב הונא סבירא ליה אין מתענין לשעות או דלמא מתענין לשעות והמתענה לשעות אינו מתפלל תפלת תענית","אמר ליה אביי לעולם קסבר רב הונא מתענין לשעות והמתענה לשעות מתפלל תפלת תענית ושאני הכא דאיכא שעות דליליא דלא קביל עליה מעיקרא","מר עוקבא איקלע לגינזק בעו מיניה מתענין לשעות או אין מתענין לשעות לא הוה בידיה קנקנין של נכרים אסורין או מותרין לא הוה בידיה במה שימש משה כל שבעת ימי המלואים לא הוה בידיה","אזל ושאיל בי מדרשא אמרו ליה הלכתא מתענין לשעות ומתפללין תפלת תענית והלכתא קנקנין של נכרים לאחר שנים עשר חדש מותרין במה שימש משה כל ז' ימי המלואים בחלוק לבן רב כהנא מתני בחלוק לבן שאין לו אימרא","אמר רב חסדא"],[[0,"כאילו קדוש שרוי בתוך מעיו","כאילו כל מעיו קדוש ואסור להכחישן דהכי משמע בקרבך קדוש כלומר דאסור להתענות:"],[0,"בקרבך קדוש","רישיה דקרא קדריש בשביל שקדוש שרוי בצער לא אבוא בעיר של מעלה עד שאבנה ירושלים של מטה ורמיזא בעלמא הוא:"],[0,"הא דמצי מצער נפשיה","שיכול לסבול התענית משבחו הקב\"ה אבל מי שאינו יכול להתענות נקרא חוטא:"],[1,"נקרא חסיד","המתענה דכתיב גומל נפשו איש חסיד מפריש עצמו ממאכל ומשתה כמו ביום הגמל את יצחק (בראשית כ״א:ח׳) שברי\"ר בלע\"ז מפי מורי אי נמי גומל לשון תגמול שמשלים נפשו לקונו:"],[1,"ועוכר שארו","המתענה ומכחיש בשרו נקרא אכזר:"],[1,"שירותיה","סעודתו כלבא ליכול סעודתו ולכך המתענה אינו מועיל לו אלא כמי שמתענה מפני שאין לו מה יאכל:"],[2,"אין תענית צבור בבבל","לענין איסורי חומרי תענית אמר ר' ירמיה למילתיה שהיו נוהגין בו כעין אבילות שהיו אוכלין מבעוד יום ואסורין בנעילת הסנדל אלא תשעה באב בלבד:"],[2,"שממעט במלאכת שמים","חלש הוא ואינו יכול ללמוד:"],[3,"יחיד שקיבל עליו תענית","מאתמול הרי אני יושב בתענית למחר אפילו אכל ושתה כל הלילה עד עמוד השחר למחר מתפלל תפלת תענית עננו:"],[3,"לן בתעניתו","באותו תענית שקיבל עליו שלא אכל במוצאי תעניתו ולן כל אותו הלילה לשם תענית עד הבקר:"],[3,"למחר אין מתפלל תפלת תענית","אינו יכול להתפלל עננו קודם שיאכל כדי לצאת ידי חובת תענית של לילה אע\"פ שהוא יום אחד כדכתיב (בראשית א׳:ה׳) ויהי ערב ויהי בוקר יום אחד ולקמן מפרש ואזיל מאי קסבר רב הונא מאי טעמא אין מתפלל למחר עננו:"],[4,"","והכי גרסינן מאי קסבר רב הונא מיסבר קסבר אין מתענין לשעות או דלמא קסבר מתענין לשעות והמתענה לשעות אינו מתפלל תפלת תענית אמר אביי לעולם קסבר מתענין לשעות ( *ומתפלל ) תפלת תענית כו' – פירוש מאי קסבר ר' הונא אין מתענין לשעות כלומר האי דקאמר למחר אין מתפלל תפלת תענית לכך אינו מתפלל דקבלת תענית זה אינו קבלה ואינו תענית כלל ואם רוצה לאכול ולסעוד בתוך התענית הרשות בידו דאין מקבלין תענית לשעות כגון זה שלא קיבל תענית של לילה זה מאתמול כדקתני לן בתעניתו דמשמע מאליו כשהחשיך ובא לסעוד עמד ולא אכל כלומר שהיה בדעתו לאכול עד שעבר מקצת הלילה שעה אחת או שתי שעות ואחר כך נמלך ולן בתעניתו או דלמא האי דקאמר רב הונא למחר אין מתפלל תפלת תענית לאו משום דאין מתענין לשעות דשם תענית עליו ואם רוצה לחזור בו ולטעום אחר שהתחיל בתענית אינו יכול אלא להכי אינו מתפלל תפלת תענית דסבר אין תענית של שעות חשוב וחמור כל כך שיהא צריך להתפלל עליו עננו:"],[5,"לעולם קסבר","בעלמא דמתענין לשעות והמתענה לשעות מתפלל תפלת תענית והכא מאי טעמא אין מתפלל תפלת תענית דשאני הכא היכא דהתענה אתמול ובלילה לן בתעניתו דלא קיבלה עילויה שלא קיבל עליו תענית זה בפני עצמו מאתמול כדרך שאר מתענין לשעות ואינו חשוב להתפלל עליו עננו:"],[6,"מר עוקבא איקלע לגינזק","גרסינן דאילו ר' עקיבא לא היה מסתפק לו הנך בעיי ועוד דבלשון ברייתא הוה משתעי ביה מעשה ברבי עקיבא כו' ולא בגמרא:"],[6,"במה שימש משה","דאילו באהרן כתיב בגדי כהונה דכתיב (שמות כט) והלבשתם שבשעה שהיה משה עובד אהרן היה לבוש בגדי כהונה ועבודה דמשה גזירת הכתוב הוא ובגדי כהונה לא מצינו בו ומסתמא אין הדבר כשר שהיה עובד בבגדיו של חול שיוצא בהן לשוק:"],[7,"קנקנים של חרס","שמכניסין בהן יין לקיום אסור להשתמש בהן:"],[7,"לאחר שנים עשר חדש","הולך טעם יין נסך ומותרים בלא עירוי מים אבל תוך י\"ב חדש צריך עירוי שלשה ימים מעת לעת:"],[7,"בחלוק לבן","של פשתן עשוי לשם כך:"],[7,"רב כהנא מתני","כי האי לישנא:"],[7,"בחלוק לבן שאין בו אימרא","שפה מתרגמינן אימרא (שם כח) כלומר תחוב היה מחוט אחד כל החלוק ולא כבגדים שלנו שבתי הידים מדובקין בבגד הגוף בתפירה כדי שלא יחשדוהו שמא באותה שפה הוציא מעות הקודש משום שנאמר (במדבר ל״ב:כ״ב) והייתם נקיים מה' ומישראל:"]],[[0,"","כאילו קדוש. הקב\"ה פירוש והא אמר לעיל שנקרא קדוש כלומר שהיושב בתענית נקרא קדוש ומשני לא קשיא:"],[1,"","גומל נפשו. פירוש שגומל חסד לנפשו שאינו מתענה נקרא חסיד:"],[2,"","אין תענית צבור בבבל אלא תשעה באב בלבד. פירוש שהיה להם הרבה גשמים:"],[3,"","יחיד שקיבל עליו תענית אע\"פ שאכל ושתה כל הלילה מתפלל תפלת תענית . תימה אמאי נקט יחיד דצבור נמי דאמרינן במתני' (לעיל תענית דף י.) דעושין שלשה תעניות ואוכלים משחשיכה וצ\"ע:"],[3,"","לן בתעניתו. פירוש שהתענה היום ובלילה לא אכל ולן בתעניתו אע\"ג שהלינה היה מכח תענית שקיבל עליו אינו מתפלל תפלת תענית ובה\"ג יש אוכל ומתפלל תפלת תענית ומפרש כמו הכא דבשחרית אומר תפלת תענית אע\"פ שאכל כל הלילה ויש מתענה שאינו מתפלל כמו בערבית אע\"פ שלא אכל ומפרש בהלכות גדולות דאין אומרין עננו בתפלת שחרית שמא נמצא שקרן בתפלתו דשמא לא יסיים התענית ולי נראה דלא נקרא שקרן כיון שהיה בדעתו להתענות אפילו אקרי אונס אחר כך ולא מצי לצער נפשיה לא גרע ממתענין לשעות וכן משמע מהא דתנן (לקמן תענית דף יט.) ירדו להם גשמים קודם חצות אינן משלימין ומסתמא משמע שאמרו תפלת תענית מכל מקום אין זה ראיה גמורה דשמא לא אמרוה ומהא דלקמן (תענית דף יב:) גבי רב הונא בריה דרב יהושע בריה דרב אידי דיתיב בתעניתא מדאמרו ליה ליזוף מר וליפרע ואמר להו תענית חלום הוא אמאי לא אמר מפני שאמר תפלת תענית אין זה ראיה לדברי ה\"ג דלא היה דעתו להתענות מבעוד יום ולא קבל עליו וכתב הר\"מ מי שלא קבל עליו מבעוד יום דאין אומר עננו אי לאו דתענית חלום הוא ונוהגים ששליח צבור אומרו בשחרית כדי להודיע לעולם ולהזכיר התענית אבל יחיד אינו אומר עד המנחה [ובטור אורח חיים (סי' תקסה) אומר שליח צבור אומר בכל פעם שאי אפשר שלא יתענו קצת מקהל עכ\"ל]:"]]],[["הא דאמרת מתענין לשעות והוא שלא טעם כלום עד הערב א\"ל אביי הא תענית מעלייתא היא לא צריכא דאימלך אימלוכי","ואמר רב חסדא כל תענית שלא שקעה עליו חמה לאו שמיה תענית מיתיבי אנשי משמר מתענין ולא משלימין התם לצעורי נפשיה בעלמא הוא","תא שמע דא\"ר אליעזר (בן) צדוק אני מבני בניו של סנאב בן בנימין ופעם אחת חל ט' באב להיות בשבת ודחינוהו לאחר השבת והתענינו בו ולא השלמנוהו מפני שיו\"ט שלנו הוא התם נמי לצעורי נפשיה בעלמא הוא","תא שמע דאמר רבי יוחנן אהא בתענית עד שאבוא לביתי התם לשמוטיה נפשיה מבי נשיאה הוא דעבד","אמר שמואל כל תענית שלא קיבל עליו מבעוד יום לאו שמיה תענית ואי יתיב מאי אמר רבה בר שילא דמי למפוחא דמליא זיקא","אימת מקביל ליה רב אמר במנחה ושמואל אמר בתפלת המנחה אמר רב יוסף כוותיה דשמואל מסתברא דכתיב במגילת תענית להן כל איניש דייתי עלוהי מקדמת דנא ייסר","מאי לאו ייסר עצמו בצלו לא יאסר עצמו","פליגי בהא רבי חייא ורבי שמעון ברבי חד אמר ייסר וחד אמר יאסר מ\"ד ייסר כדאמרינן למאן דאמר יאסר מאי היא","דתניא במגילת תענית כל איניש דייתי עלוהי מקדמת דנא יאסר כיצד יחיד שקיבל עליו שני וחמישי (ושני) של כל השנה כולה ואירעו בם ימים טובים הכתובין במגילת תענית אם נדרו קודם לגזרתנו יבטיל נדרו את גזרתנו ואם גזרתנו קודמת לנדרו תבטל גזרתנו את נדרו","תנו רבנן עד מתי אוכל ושותה עד שיעלה עמוד השחר דברי רבי רבי אליעזר בר שמעון אומר עד קרות הגבר אמר אביי לא שנו אלא שלא גמר סעודתו אבל גמר סעודתו אינו אוכל","איתיביה רבא גמר ועמד הרי זה אוכל התם כשלא סילק איכא דאמרי אמר רבא לא שנו אלא כשלא ישן אבל ישן אינו אוכל איתיביה אביי ישן ועמד הרי זה אוכל התם במתנמנם","היכי דמי מתנמנם אמר רב אשי"],[[0,"הא דאמרת מתענין לשעות והוא שלא טעם כלום כל אותו היום","כלומר לא אמרו במתענה שאכל בו ביום כגון שהתחיל להתענות עד חצי היום ואח\"כ אכל דאין זה עינוי ואם אכל קודם חצות אין בכך כלום דאינו תענית של כלום אלא כשהשלים כל היום אע\"פ שלא קיבלו עליו מאתמול ופריך אי דקבל עליו להתענות עד חצי יום והדר מתענה כל היום האי תעניתא מעלי' הוא ופשיטא דתענית גמור הוא ואפילו תפלת תענית נמי מתפלל עליו ולא איצטריך לאוקומי הלכה בהכי דזהו תענית גמור והאי מקשה סבר דהאי הלכה מתענין לשעות כמשמעו דיכול להתענות עד חצי היום מתענה קרינא ביה:"],[0,"לא צריכנא דממליך אימלוכי","כלומר לא היה בדעתו כלל להתענות אלא אתא ליה טרדא ולא אכל עד חצי היום וכי מטא חצי יום ממליך אמר הואיל והתעניתי עד חצי היום אתענה כל היום:"],[1,"שלא שקעה עליו חמה","שלא התענה עד אותה שעה:"],[1,"אנשי משמר","כהנים ולוים העובדין מתענין כדלקמן בפרק סדר תעניות:"],[1,"ולא משלימין","לפי שהן עסוקין בעבודה ואין יכולים להשלים אלמא אע\"ג דאינו משלים מתענה קרי ליה:"],[1,"לצעורי נפשייהו","עם הצבור אבל אינו תענית לא להתפלל תפלת עננו ולא לקובעו עליו חובה כלל וכל שעה שהוא רוצה לאכול אוכל:"],[2,"מבני (סנאב) בן בנימין","משבט בנימין:"],[2,"שיום טוב שלנו היה","כדלקמן בשלשה פרקים (תענית דף כו.) זמן עצי כהנים והעם כו' עד בחמשה באב בני פרעוש בן יהודה בעשרה בו בני (סנאב) בן בנימין שעל ידי מעשה קבעו להן חכמים להתנדב עצים ולהביא למערכה וכשמגיע זמנו מביאין אותן ומדליקין אותן על גבי המזבח אע\"פ שהיו שם שאר עצים הרבה משא\"כ בשאר מתנדבי עצים דאין מבערין אותן בזמן שיש עצים אחרים במסכת מנחות (דף קו:) אמרינן המתנדב עצים לא יפחות משני גזירין ועצים טעונין קמיצה טעונים הגשה כו':"],[3,"דאמר רבי יוחנן","פעמים שהיה אומר אהא בתענית עד שאבוא לביתי ואי מטי לביתיה בשתים או בג' שעות ביום הוה אכיל וקרי ליה מתענה:"],[3,"לשמוטיה נפשיה מבי נשיאה","דלא ליטרחוהו למיכל בהדייהו שהיה מבקש הימנו שיאכל עמו היה אומר כן שלא יטריחנו לאכול עמו ומיהו לא הוי תענית שאם היה רוצה היה אוכל מיד ואין בנדרו כלום:"],[4,"ואי יתיב מאי","מי סליק לתענית אי לא:"],[4,"למפוחא","הוא המפוח שנופחין בו הנפחין את האור המתמלא ברוח אף זה נתמלא רוח שלא אכל בחנם:"],[5,"במנחה","בזמן המנחה ואפילו בשוק אומר הריני מחר בתענית:"],[5,"בתפלת המנחה","בסופה תוספת ריצוי ותחנונים עד שאומר הריני מחר בתענית ודוקא נקט מנחה משום דסמוך לתחלת יום תעניתו לאפוקי תפלת יוצר ודיקא נמי מדפסיק שמואל ופליג אדרב דאמר בזמן המנחה שיעורא יתירא:"],[5,"כדכתיב במגילת תענית","לסוף ימים טובים הכתובים במגילת תענית כתיב בה מקדמת דנא ייסר לעיל מינה תני אילין יומיא די לא להתענאה בהון להן כל איניש דייתי עלוה תענית מן קדמת דנא לפני אלו ימים טובים כגון שקיבל עליו עשרה תעניות או עשרים ונכנסו אלו הימים בהם:"],[6,"ייסר בצלו","בתפלה ואי לא קבליה עליה בתפלת המנחה לא דחי להנך ימים טובים אלמא דעיקר תענית בעי לקבולי בתפלת המנחה עילויה ואי לא קבליה עילויה בתפלת המנחה לא עשה כלום:"],[6,"ייסר","לשון ואסרה אסר (במדבר ל):"],[6,"בצלו","צלותא איכא דאמרי לשון נדר שקבל עליו להתענות כמו הרימותי ידי אל ה' (בראשית י״ד:כ״ב) דמתרגמינן ארימית ידי בצלו ואין רבי מודה האי דקתני דכתיב משום דמגילת תענית היתה נכתבת לבד לזכרון נסים:"],[7,"וחד אמר יאסר","דלא הוי תני ייסר בצלו דמשמע דוקא כדאמרינן אי מקבל בתפלת המנחה אין ואי לא לא אלא יאסר דמשמע יהא אסור לאכול אי אתי עליה תעניות מן קדמת דנא בין בתפלה בין שלא בתפלה:"],[7,"מאי היא","מאי קסבר ומשני כדתניא יחיד שקבל עליו תענית שני וחמישי של כל השנה כולה כלומר כדמפרש בהדיא אם נדרו קודם לגזרתנו כו' ולא שנא בין בתפלה בין שלא בתפלה:"],[8,"קודם גזרתנו","קודם שגזרו חכמים ימים טובים הללו אבל משגזרו אע\"פ שהתחיל תעניותיו קודם הזמנים הללו לא דחו:"],[9,"עד מתי אוכל ושותה","בלילה כשמתענה למחר בכל תעניות שהוא אוכל משתחשך ואפילו בתענית יחיד קא מיירי:"],[9,"עד קרות הגבר","אפילו פעם ראשונה קאמר מדקאמר גבי יוצא יחידי בלילה בסדר יומא (דף כא.) עד שישלש:"],[9,"שלא גמר סעודתו","אבל גמר דברי הכל אינו אוכל:"],[10,"אכל ועמד","אע\"פ שבירך ועמד משולחנו חוזר ואוכל ואין בכך כלום:"],[10,"שלא סילק","את הטבלא דלאו עקירה היא ולא אסח דעתיה מאכילה וכסעודה אריכתא דמיא:"],[10,"איכא דאמרי אמר רבא כו'","והלכה כאיכא דאמרי אוכל ושותה עד שיישן קבע ועד שיעלה עמוד השחר כרבי:"],[10,"אבל ישן","הפסקה היא ושוב אינו אוכל:"],[10,"התם","לאו ישן ממש אלא מתנמנם שומיליי\"ר בלע\"ז:"]],[[1,"","כל תענית שלא שקעה עליו חמה לא שמיה תענית. פי' במסכת ע\"ז פרק אין מעמידין (עבודה זרה דף לד.) וכן בחלוק שאין לו אימרא פירש התם וכל הפסק דמתענין לשעות דכל תענית צריך לקבלו מבערב בתפלת המנחה בשומע תפלה ואם הוא שבת באלהי נצור וצריך שיאמר למחר אהיה בתענית יחיד כי היכי דליכא למטעי בתענית צבור:"],[2,"","התם לצעורי נפשיה בעלמא. ואע\"ג דאמרינן (ר\"ה דף יח:) משחרב בית המקדש בטלה מגילת תענית והאי עובדא דרבי אליעזר בר צדוק היה לאחר חורבן דאי קודם החורבן אמרינן (שם) כיון שיש שלום אין שם גזירות המלכות האי תנא סבר דלא בטלה:"],[6,"","יאסר. פי' יאסר באל\"ף הוי לשון אסור שאסר עצמו וייסר הוי לשון הסרה כלומר יסור מן הנדר יהיה מותר לאכול למחר שיהיה יום טוב ואין להתענות:"],[8,"","ואם גזרתנו קודם לנדרו ידחה נדרו מפני גזרתנו. אומר רש\"י ידחה נדרו מכל וכל ולא ישלים אותו תענית והר\"י מסופק בדבר ויש להחמיר דדוקא אותו יום לא יתענה אבל ישלים אותו ליום מחר וכן יש ליזהר שלא להתענות בראש חדש ובחנוכה ובפורים דמאלו ודאי לא בטלה מגילת תענית:"]]],[["נים ולא נים תיר ולא תיר דקרו ליה ועני ולא ידע אהדורי סברא וכי מדכרי ליה מדכר","אמר רב כהנא אמר רב יחיד שקיבל עליו תענית אסור בנעילת הסנדל חיישינן שמא תענית צבור קיבל עליו היכי ליעבד אמר רבה בר רב שילא לימא הכי למחר אהא לפניך בתענית יחיד","אמרו ליה רבנן לרב ששת הא קא חזינן רבנן דמסיימי מסנייהו ואתו לבי תעניתא איקפד ואמר להו דלמא מיכל נמי אכול","אביי ורבא מעיילי כי מסיימי אפנתא מרימר ומר זוטרא מחלפי דימינא לשמאלא ודשמאלא לימינא רבנן דבי רב אשי נפקי כי אורחייהו סברי כי הא דאמר שמואל אין תענית צבור בבבל אלא תשעה באב בלבד","אמר רב יהודה אמר רב לוה אדם תעניתו ופורע כי אמריתה קמיה דשמואל אמר לי וכי נדר קבל עליה דלא סגי דלא משלם לצעורי נפשיה קביל עליה אי מצי מצער נפשיה אי לא מצי לא מצער נפשיה","איכא דאמרי אמר רב יהודה אמר רב לוה אדם תעניתו ופורע כי אמריתה קמיה דשמואל אמר לי פשיטא לא יהא אלא נדר נדר מי לא מצי בעי לשלומי ומיזל למחר וליומא אחרינא","רב יהושע בריה דרב אידי איקלע לבי רב אסי עבדו ליה עגלא תילתא אמרו ליה ליטעום מר מידי א\"ל בתעניתא יתיבנא אמרו ליה ולוזיף מר וליפרע לא סבר מר להא דאמר רב יהודה אמר רב לוה אדם תעניתו ופורע אמר להו תענית חלום הוא","ואמר רבה בר מחסיא אמר רב חמא בר גוריא אמר רב יפה תענית לחלום כאש לנעורת (אמר) רב חסדא ובו ביום ואמר רב יוסף ואפילו בשבת מאי תקנתיה ליתיב תעניתא לתעניתא:","\u0001מתני׳\u0002 עברו אלו ולא נענו בית דין גוזרין ג' תעניות אחרות על הצבור אוכלין ושותין מבעוד יום ואסורין במלאכה וברחיצה ובסיכה ובנעילת הסנדל ובתשמיש המטה ונועלין את המרחצאות","עברו אלו ולא נענו ב\"ד גוזרין עליהן עוד שבע שהן י\"ג תעניות על הצבור הרי אלו יתרות על הראשונות שבאלו מתריעין ונועלין את החנויות בשני מטין עם חשיכה ובחמישי מותרין מפני כבוד השבת","עברו אלו ולא נענו ממעטין במשא ומתן בבנין ובנטיעה באירוסין ובנישואין ובשאילת שלום בין אדם לחבירו כבני אדם הנזופין למקום היחידים חוזרין ומתענין עד שיצא ניסן יצא ניסן וירדו גשמים סימן קללה שנא' (שמואל א יב, יז) הלא קציר חטים היום וגו':","\u0001גמ׳\u0002 בשלמא כולהו אית בהו תענוג רחיצה וסיכה ותשמיש המטה אבל מלאכה צער הוא אמר רב חסדא אמר רב ירמיה בר אבא אמר קרא (יואל א, יד) קדשו צום קראו עצרה אספו זקנים כעצרת מה עצרת אסור בעשיית מלאכה אף תענית אסור בעשיית מלאכה","אי מה עצרת מאורתא אף תענית נמי מאורתא אמר רבי זירא לדידי מיפרשא לי מיניה דר' ירמיה בר אבא אמר קרא אספו זקנים דומיא דאסיפת זקנים מה אסיפת זקנים ביום אף צום נמי ביום ואימא מטיהרא אמר רב שישא בריה דרב אידי מסייע ליה לרב הונא דאמר מצפרא כינופיא","היכי עבדי אמר אביי מצפרא עד פלגא דיומא מעיינינן במילי דמתא מכאן ואילך ריבעא דיומא קרינן בספרא ואפטרתא מכאן ואילך בעינן רחמי שנא' (נחמיה ט, ג) ויקומו על עמדם ויקראו בספר תורת ה' אלהיהם רביעית היום ורביעית מתודים ומשתחוים לה' אלהיהם"],[[0,"תיר","ער כדמתרגמינן (בראשית מא) ויקץ ואיתער:"],[0,"אהדורי סברא","אם צריך ממנו דבר שצריך הרהור אינו יודע לומר בעוד שמתנמנם:"],[0,"וכי מדכרו ליה מדכר","כזה שמעת מדכר:"],[1,"יחיד שקבל עליו תענית","סתם ואינו יודע איזה תענית קבל עליו אם של יחיד אם של צבור:"],[1,"ואסור בנעילת כו'","שמא תענית צבור כשלש ראשונות או כז' אחרונות קיבל עליו:"],[2,"קאתו רבנן לתעניתא כו'","בתענית צבור וסברי לה כשמואל דאמר אין תענית צבור בבבל בפרק מקום שנהגו (פסחים דף נד:) דאסור בנעילת הסנדל ובכל הני:"],[2,"איקפד רב ששת דלמא מיכל נמי אכלי","ופורשים מדרכי צבור ולית ליה דשמואל ואנן האידנא נהגינן כשמואל:"],[3,"אפנתא","אישקריפי\"ט:"],[3,"מחלפי","ביומא דתעניתא:"],[5,"לצעורי בעלמא","אי מצי מצער נפשיה ואי לא לא יהא אלא (ליומא) אחרינא:"],[7,"ואפילו בשבת","יכול להתענות כדי שיתבטל צער גופו:"],[9,"בשני מטין עם חשיכה","ולא נועלין ולא פותחין הואיל ולאו לכבוד שבת הוה ובחמישי מותרין לפתוח לגמרי:"],[11,"קדשו צום קראו עצרה אספו זקנים","כל יושבי הארץ בית ה' אלהיכם וזעקו אל ה':"],[11,"מה עצרת","שבועות ושמיני עצרת:"],[12,"אי מה עצרת","איסור מלאכתו מאורתא:"],[12,"דומיא דאסיפת זקנים ביום","דבלילה כל אחד בביתו ואינן נאספין:"],[12,"מסייע ליה לרב הונא","הא דפשיטא לך דאסיפת זקנים ביום:"],[12,"דאמר מצפרא כינופיא","ביום תענית צבור מתקבצין ובאין לבית הכנסת מן הבקר:"],[13,"היכי עבדי","מאי עבדי בכינופיא דמצפרא ובכוליה יומא דתעניתא:"],[13,"מעיינין במילי דמתא","דרישה וחקירה לבדוק במעשיהם בעסקי בני העיר אם גזל וחמס ביניהן ומפייסין אותן:"],[13,"ריבעא דיומא","מחצות ואילך עושין ב' חלקים:"],[13,"בפלגא","דהיינו ריבעא דיומא קרו ויחל משה ומפטירין דרשו את ה' בהמצאו:"]],[[0,"","נים ולא נים תיר ולא תיר. אומר רבי נים ולא נים בתוך השינה כשניעור משנתו תיר ולא תיר בתחילת השינה אך לא נראה בערבי פסחים (דף קכ:) דקאמר נתנמנמו יאכלו נרדמו לא יאכלו ואמר רב אשי ה\"ד נתנמנמו נים ולא נים וכו' והתם מיירי בתחילת השינה בין נים ולא נים בין תיר ולא תיר לכנ\"ל כפירוש רש\"י דאי הוה אמר נים ולא נים הוה אמינא דתיר הוי טפי מנים ואי הוה אמר תיר ולא תיר ה\"א דנים הוי טפי מתיר הלכך איצטריך תרווייהו וכולהו בתחילת השינה כדמפרש התם ובירושלמי מפורש גבי הך ברייתא עד כמה אוכל ושותה עד קרות הגבר וה\"ה עד שיעלה עמוד השחר ובד\"א שהתנה אבל לא התנה וישן אינו יכול לאכול:"],[3,"","אביי ורבא סיימי אפנתא. פירוש במנעל שאין שוליים שול\"א בלע\"ז:"],[4,"","דאי מצי מצער נפשיה עביד אי לא מצי מצער נפשיה לא עביד. ומשום הכי קאמר שמואל דלוה תעניתו ופורע דוקא היכי דלא מצי מצער נפשיה אבל היכי דמצי מצער נפשיה לא מצי ללוות תעניתו והכי מסקנא אם אמר הריני בתענית למחר צריך לצעוריה נפשיה ואינו יכול ללוות ופורע בחנם ואפילו אכל בשוגג ישלים אותו והר\"י מסופק בדבר אם יכול ללוותו ולפרוע היכי דקביל עליה כבר להתענות והתענה עד חצי היום או רביע יום ואפילו לא מצי לצעורי נפשיה אבל לא התענה ודאי דיכול ללוות אחר בשבילו או אם טעה ואכל בשוגג יאכל וישלים יום אחר ואם התענה בשבת כגון תענית חלום דצריך לפרוע כדאמר ובלבד דיתיב תעניתא לתעניתא אם אירע שיהיה ר\"ח אותו יום אז ידחה לתעניתו עד יום אחר בשבוע וכן נראה למ\"ר שי':"],[12,"","מה אסיפת זקנים ביום אף צום ביום. אבל בלילה לא תימה אמאי אוכלים ושותים מבעוד יום כל הלילה נמי היו יכולין לאכול ולשתות מה אסיפת זקנים ביום אף צום ביום אבל בלילה לא ויש לומר דלא יליף צום מאסיפה אלא לענין עשיית מלאכה דדוקא מלאכה גמרינן מאסיפה דהא לא כתיב בקרא אלא אספו זקנים וקדשו צום אבל אכילה לא כתיב בקרא:"]]],[["איפוך אנא לא סלקא דעתך דכתיב (עזרא ט, ד) ואלי יאספו כל חרד בדברי אלהי ישראל על מעל הגולה וגו' וכתיב (עזרא ט, ה) ובמנחת הערב קמתי מתעניתי ואפרשה כפי אל ה'","אמר רפרם בר פפא אמר רב חסדא כל שהוא משום אבל כגון תשעה באב ואבל אסור בין בחמין בין בצונן כל שהוא משום תענוג כגון תענית צבור בחמין אסור בצונן מותר","אמר רב אידי בר אבין אף אנן נמי תנינא ונועלין את המרחצאות א\"ל אביי ואי בצונן אסור סוכרין את הנהרות מבעי ליה למיתני","אמר רב שישא בריה דרב אידי אבא הכי קשיא ליה מכדי תנן אסור ברחיצה נועלין את המרחצאות למה לי אלא לאו ש\"מ בחמין אסור בצונן מותר","לימא מסייע ליה כל חייבי טבילות טובלין כדרכן בין בט' באב בין ביוה\"כ במאי אילימא בחמין טבילה בחמין מי איכא שאובין נינהו","אלא לאו בצונן וחייבי טבילות אין איניש אחרינא לא אמר רב חנא בר קטינא לא נצרכה אלא לחמי טבריא","אי הכי אימא סיפא א\"ר חנינא סגן הכהנים כדי הוא בית אלהינו לאבד עליו טבילה פעם אחת בשנה ואי אמרת בצונן מותר ירחץ בצונן אמר רב פפא באתרא דלא שכיח צונן","תא שמע כשאמרו אסור במלאכה לא אמרו אלא ביום אבל בלילה מותר וכשאמרו אסור בנעילת הסנדל לא אמרו אלא בעיר אבל בדרך מותר הא כיצד יוצא לדרך נועל נכנס לעיר חולץ וכשאמרו אסור ברחיצה לא אמרו אלא כל גופו אבל פניו ידיו ורגליו מותר וכן אתה מוצא במנודה ובאבל","מאי לאו אכולהו ובמאי עסקינן אילימא בחמין פניו ידיו ורגליו מי שרו והאמר רב ששת אבל אסור להושיט אצבעו בחמין אלא לאו בצונן","לא לעולם בחמין ודקא קשיא לך וכן אתה מוצא במנודה ובאבל אשארא קאי","תא שמע דאמר ר' אבא הכהן משום ר' יוסי הכהן מעשה ומתו בניו של ר' יוסי בן רבי חנינא ורחץ בצונן כל שבעה התם כשתכפוהו אבליו הוה דתניא תכפוהו אבליו זה אחר זה הכביד שערו מיקל בתער ומכבס כסותו במים","אמר רב חסדא בתער אבל לא במספרים במים ולא בנתר ולא בחול","אמר רבא אבל מותר לרחוץ בצונן כל שבעה מידי דהוה אבשרא וחמרא מיתיבי"],[[0,"איפוך אנא","דפלגא דיומא קמא הוו קרו ומפטרי ובעו רחמי ובאידך פלגא מעייני:"],[0,"על מעל הגולה","ואני יושב משומם עד מנחת הערב ובמנחת הערב קמתי מתעניתי ובקרעי בגדי ומעילי ואכרעה על ברכי ואפרשה כפי אל ה' אלהי:"],[0,"ובמנחת הערב קמתי","אלמא באידך פלגא בעו רחמי עד פניא מכלל דפלגא קמא מעייני במילי דמתא:"],[0,"בנחמיה בן חכליה כתיב בעזרא ואלי יאספו","לי היו מתאספין ובאין טובים שבהן להגיד לפני על מעל וחטא הגולה להפרישם:"],[0,"משומם","אישתורדי\"ן בלע\"ז על מעלם שמתוודין עד מנחת הערב מחצות ואילך שהצל נוטה כדאמרינן במסכת יומא (דף כח:) צלותיה דאברהם מכי משחרי כותלי:"],[0,"קמתי מתעניתי","לא שמתענה עד המנחה ואח\"כ אוכל אלא כלומר מצער נפשיה ובקרעי ואם שאני קורע בגדי ומעילי הייתי מתפלל כדי שאתרצה:"],[1,"כל שהוא משום אבל","כל תענית שאסרו חכמים רחיצה משום אבל כגון ט' באב שהוא משום אבילות חורבן וכל שכן אבל ממש שמתו לפניו דאית ליה צערא טובא אסור בין בחמין וכו':"],[1,"משום תענוג","שמצטערין ואוסרין עצמן בתענוג:"],[2,"ה\"ג אמר רב אידי בר אבין אף אנן נמי תנינא ונועלין את המרחצאות וא\"ל אביי ואי בצונן אסור סוכרין את הנהרות מיבעי ליה למיתני","בתמיה אף אנן נמי תנינא במתנית' דקתני גבי תענית צבור ונועלין את המרחצאות דהיינו חמין אבל צונן מותר א\"ל אביי כלומר ואי הוה סבירא ליה לתנא דידן דבצונן אסור היכי הוה בעי למיתני סוכרין את הנהרות היכי מצי למיסכרינהו:"],[3,"אבא","רב אידי הכי קא קשיא ליה במתניתין דקאמר שמע מינה דלא אסר אלא חמין מכדי קתני מתני' אסורין ברחיצה וסתם רחיצה בין חמין בין צונן למה לי תו למיהדר ומיתנא ונועלין אלא למימרא דוקא חמין וכו':"],[4,"לימא מסייע ליה","לרב חסדא דאמר כל שהוא משום אבל אסור אפילו בצונן:"],[4,"כל חייבי טבילות","נדה ויולדת טובלים כדרכן:"],[4,"טבילה בחמין מי איכא","חמי האור הא שאובין נינהו:"],[5,"אלא לאו בצונן","וחייבי טבילות אין משום דטבילה בזמנה מצוה שממהר לטהר עצמו:"],[5,"","ה\"ג כולי עלמא לא בחמין ולא בצונן:"],[5,"לא נצרכה אלא לחמי טבריא","והלכך חייבי טבילות אין כולי עלמא לא אבל בצונן שרו:"],[6,"כדי","ראוי הוא בית אלהינו כו':"],[6,"ואם איתא","כדמוקמת לה דבצונן שרי מאי קא מהדר ליה רבי חנינא לתנא קמא מאיבוד טבילה נהי דלא טבלי בחמין משום כבוד בית אלהינו הא מצו טבלי בצונן אלא לאו בצונן נמי אסירי והיינו דאמר לאבד:"],[6,"אמר רב פפא","לעולם בחמי טבריא והיינו דקאמרי' חייבי טבילות אין כולי עלמא לא ובצונן כ\"ע שרי ומאי לאבד דקאמר ר' חנינא כגון באתרא דלא שכיח צונן:"],[7,"כשאמרו אסור [במלאכה]","גבי תענית צבור לא אמרו אלא ביום אבל בלילה מותר מהכא משמע דבלילי תשעה באב מותר במלאכה ואין ביטול אלא ביום אבל אין מפרסמין הדבר:"],[7,"יצא לדרך","חוץ לעיר:"],[7,"","וכן אתה מוצא במנודה ואבל:"],[8,"הכי גרסינן במאי אילימא בחמין מי שרי והאמר רב ששת אבל אסור להושיט אצבעו בחמין אלא לאו בצונן מאי לאו אכולהו כו'","הא דקתני וכן אתה מוצא במנודה ואבל אכל הני קאי ואפילו ארחיצה ושמע מינה דבתענית צבור אסור לרחוץ כל גופו ואפילו בצונן ותיובתא לרפרם בר פפא:"],[9,"לא אשארא קאי","אנעילה וסיכה לעולם הך רחיצה בחמין היא אבל בצונן שרי לרחוץ כל גופו והשתא דאמרת במנודה ואבל לאו ארחיצה קיימי ליכא לאקשויי כדפרכת לעיל אילימא בחמין מי שרי:"],[10,"ורחץ בצונן בתוך שבעה","גרסינן אלמא בצונן שרי:"],[10,"שתכפוהו אבליו","בזה אחר זה כדקתני שמתו בניו שניהם ולפיכך התירו לו כדאשכחן גבי שיער:"],[10,"מיקל בתער","דשקיל פורתא מינייהו:"],[11,"ובתער","דרך שינוי:"],[11,"נתר","קרקע הוא או אבן כעין שקורין קרי\"א בלע\"ז:"],[11,"בנתר וחול","דרך לכבס שיתלבן:"],[12,"מידי דהוה אבשרא וחמרא","דתענוג הן כצונן:"]],[[0,"","איפוך אנא. פי' דנימא פלגא קמייתא דיומא מצלו ובעו רחמי ואידך פלגא מעייני במיל דמתא ומשני לא ס\"ד:"],[1,"","אמר רב חסדא כל שהוא משום אבל כגון תשעה באב אסור אפילו בצונן ואבל אסור בין בחמין בין בצונן וכו'. ירושלמי יוסף בריה דרבי יהושע בן לוי בתשעה באב וביוה\"כ מרחיץ ידיו ומקנח במפה ומעבירה על גבי עיניו רבי יונה תרי סמרטוטי ויהיב תותי כרעיה פי' היה מניח סמרטוט תחת הכר כדי ללחלחו ומעבירו על גבי עיניו:"],[1,"","וכל שהוא משום תענוג וכו'. ועכשיו שאין תענית צבור בבבל אלא תשעה באב מותרין אפילו בחמין אפילו י\"ז בתמוז וצום גדליה כך פסק ראבי\"ה ור' יואל אביו אסר לרחוץ בחמין:"],[2,"","ונועלין המרחצאות. פי' שהן חמין:"],[2,"","אטו סוכרין נהרות כו'. כלומר אי הוה אסור בצונן מי איכא למיתני סוכרים נהרות פשיטא דלא מצי למסכר כלומר כמו כן לא תידוק מהא דקתני ונועלין המרחצאות:"],[4,"","טבילה בחמין מי איכא. הא שאובים נינהו מדלא קאמר משכחת לה טבילה (בחמין) דכשירה בחמין כגון שהוחמו והומשכו לבריכה אלא שאמר בחמי טבריא יש להוכיח דכולו שאוב אפילו ע\"י המשכה לא מהניא טבילה והא דאמר דהמשכה כולה כשירה ר\"ל לענין שאינה פוסלת את המקוה כשאר מים שאובים אבל טבילה ודאי אינו עולה בהם:"],[8,"","וכן אתה מוצא במנודה ואבל מאי לאו אכולהו. פי' אהא דקאמרינן ובצונן מותר דאבל נמי מותר בצונן וקשיא לרב חסדא דאמר אבל אסור בין בחמין בין בצונן ומשני אשארא כלומר אשאר דינין אנעילה וסיכה אבל לא קאי אהא דבצונן:"],[10,"","הכביד שערו מיקל בתער. פי' דרך חתיכה אבל לא כדרכו דרך גילוח מדקאמר מיקל ולא קאמר מגלח:"]]],[["אין הבוגרת רשאה לנוול את עצמה בימי אבל אביה הא נערה רשאה","מאי לאו ברחיצה ובמאי אילימא בחמין אין הבוגרת רשאה והאמר רב חסדא אבל אסור להושיט אצבעו בחמין אלא לאו בצונן לא אכיחול ופירכוס","לימא מסייע ליה דא\"ר אבא הכהן משום רבי יוסי הכהן מעשה ומתו בניו של ר' יוסי בר חנינא ורחץ בצונן כל שבעה","אמרי התם בשתכפוהו אבליו זה אחר זה דתניא תכפוהו אבליו זה אחר זה הכביד שערו מיקל בתער ומכבס כסותו במים אמר רב חסדא בתער אבל לא במספרים במים ולא בנתר ולא בחול ולא באהל","איכא דאמרי אמר רבא אבל אסור בצונן כל שבעה מאי שנא מבשר ויין התם לפכוחי פחדיה הוא דעביד","לימא מסייע ליה אין הבוגרת רשאה לנוול עצמה הא נערה רשאה במאי אילימא בחמין אין הבוגרת רשאה והאמר רב חסדא אבל אסור להושיט אצבעו בחמין אלא לאו בצונן לא אכיחול ופירכוס","אמר רב חסדא זאת אומרת אבל אסור בתכבוסת כל שבעה והלכתא אבל אסור לרחוץ כל גופו בין בחמין בין בצונן כל שבעה אבל פניו ידיו ורגליו בחמין אסור בצונן מותר אבל לסוך אפילו כל שהוא אסור ואם לעבר את הזוהמא מותר","צלותא דתעניתא היכי מדכרינן אדבריה רב יהודה לרב יצחק בריה ודרש יחיד שקיבל עליו תענית מתפלל של תענית והיכן אומרה בין גואל לרופא","מתקיף לה רב יצחק וכי יחיד קובע ברכה לעצמו אלא אמר רב יצחק בשומע תפלה וכן אמר רב ששת בשומע תפלה","מיתיבי אין בין יחיד לצבור אלא שזה מתפלל שמונה עשרה וזה מתפלל תשע עשרה מאי יחיד ומאי צבור אילימא יחיד ממש וצבור ש\"צ הני תשע עשרה עשרין וארבע הוו","אלא לאו ה\"ק אין בין יחיד דקבל עליו תענית יחיד ליחיד שקבל עליו תענית צבור אלא שזה מתפלל שמונה עשרה וזה מתפלל תשע עשרה ש\"מ יחיד קובע ברכה לעצמו","לא לעולם אימא לך שליח צבור ודקא קשיא לך שליח צבור עשרין וארבע מצלי בג' תעניות ראשונות דליכא עשרים וארבע","ולא והא אין בין קתני אין בין ג' ראשונות לג' אמצעיות אלא שבאלו מותרין בעשיית מלאכה ובאלו אסורין בעשיית מלאכה הא לכ\"ד זה וזה שוין","תנא ושייר מאי שייר דהאי שייר ותו והא אין בין קתני אלא תנא באיסורי קא מיירי בתפלות לא מיירי ואי בעית אימא באמצעייתא נמי לא מצלי כ\"ד","ולא והתניא אין בין ג' שניות לשבע אחרונות אלא שבאלו מתריעין ונועלין את החנויות הא לכל דבריהן זה וזה שוין וכי תימא הכא נמי תנא ושייר והא אין בין קתני","ותסברא אין בין דוקא"],[[0,"אין הבוגרת","שהביאה שתי שערות רשאה לנוול את עצמה אלא מתקשטת כדי שיקפצו עליה הא נערה שאינה ראויה להינשא עדיין עד שתבגר רשאה דבת חיוב אבילות היא וקטנה אינה חייבת ולא כלום:"],[0,"בימי אבל אביה","אפילו אירע אבילות לאביה שמת בנו אי נמי שמת אביה ממש אע\"פ שהיא בת חיוב אבילות אינה רשאה לנוול:"],[1,"אלא לאו בצונן","ואפ\"ה נערה אינה רוחצת בצונן אלמא דאבל אף בצונן אסור:"],[1,"אכיחול ואפירכוס","ולא קא מיירי ברחיצה כלל פירכוס בשיער כבוס בבגדים רחיצה בגוף:"],[6,"זאת אומרת","מדמוקמינן לה בכיחול ופירכוס הוא הדין לתכבוסת:"],[7,"תפלת תענית","עננו:"],[7,"בין גואל לרופא","ברכה בפני עצמה:"],[8,"וכי יחיד","חשוב כל כך שיהו מתקנין לו ברכה בפ\"ע להוסיף בתפלתו:"],[8,"בשומע תפלה","שכוללה בתוך הברכה וחותם בשומע תפלה דאותה ברכה וחתימתה משמע בין אתענית בין אכל מילי:"],[9,"אין בין יחיד לצבור","גבי תענית:"],[9,"שזה","יחיד מתפלל ביום תעניתו שמונה עשרה וכולל תפלת תענית בשומע תפלה:"],[9,"תשע עשרה","דקבע ליה בין גואל לרופא סתם תפלה קרי שמונה עשרה דברכת ולמלשינים ביבנה תקנוה כדאמרינן בברכות (דף כח:):"],[9,"כ\"ד הויין","בפירקין דלקמן (תענית דף טו.) דכ\"ד ברכות הוו ביומא דתעניתא והכא קתני י\"ט ותו לא:"],[10,"וצבור","יחיד שקיבל עליו תענית צבור אלמא יחיד קובע ברכה לעצמו כשקיבל תענית צבור:"],[11,"בקמייתא","בג' תעניות ראשונות דליכא כ\"ד כדאמרינן בפרק סדר תעניות כיצד בגמ' (שם):"],[12,"דאלו מותרין בעשיית מלאכה וכו'","ראשונות דלא חמירי כולי האי הא לכ\"ד ברכות זה וזה שוין וקס\"ד דאיתנהו לכ\"ד באמצעיות מדקמתריץ קמייתא דליכא כ\"ד מכלל דבאמצעיתא איתנהו ולא היא דליתנהו אלא באחרונות כדקתני התם ומשום דהא מילתא קמייתא מש\"ה פריך ליה מכ\"ד דליתנהו באמצעיות:"],[13,"תנא ושייר","תנא מילי דאיתנהו בין אמצעיות לראשונות ושייר אין בין לאו דוקא הוא כדמוכח לקמן גבי אידך:"],[13,"","ה\"ג מאי שייר דהאי שייר אלא באיסורי קא מיירי בתפלות לא קא מיירי ומאן דגריס שייר תיבה מוציאין את התיבה כו' שיבוש הוא דאינה אלא באחרונות כדבסמוך ומיפשט פשיטא ליה דאינה אלא באחרונות:"],[13,"מאי שייר דהאי שייר","דלא אורחא דתנא למתני כל מילי ולשיורי חדא אלא לעולם כ\"ד בקמייתא ליתנהו ולהכי לא חשיב להו באין בין דבתפלה לא קמיירי:"],[13,"באמצעיות נמי ליכא כ\"ד","אלא באחרונות כדאמרינן התם:"],[14,"שבאלו","האחרונות מתריעים ונועלין כדתנן נמי במתני' הא לכ\"ד זה וזה שוין דבתרוייהו איתנהו:"]],[[0,"","אין הבוגרת רשאה לטול עצמה. אומר ר\"י דהא רשאה לאו דוקא אלא ה\"ק אין הבוגרת חייבת הא נערה חייבת:"],[1,"","אלא בצונן. וקאמר נערה רשאה כלומר דאסורה ואת אמרת דבצונן מותר וקשה לרבא דאמר דבצונן מותר ומשני כי קתני אכיחול ואפירכוס:"],[8,"","אלא אמר רב יצחק בשומע תפלה. והכי פסק בשמעתא דתפלת תענית בשומע תפלה ואין יחיד קובע ברכה לעצמו לכך צריך כשאומר עננו בש\"ת (דצריך) לאומרו קודם שאומר הברכה כשמגיע לעננו קודם שיתחיל לומר כי אתה ש\"ת עמך ישראל ברחמים יאמר עננו ולא יחתום אלא יאמר כי אתה ה' עונה בעת צרה ומושיע ואח\"כ כי אתה ש\"ת עמך ישראל ברחמים בא\"י שומע תפלה אבל שליח צבור אומר גואל ישראל וקובע ברכה וחותם:"],[13,"","תנא ושייר. פי' תנא עשיית מלאכה ושייר כ\"ד ברכות פי' כ\"ד ברכות שבתעניתא היו מוסיפין ו' ברכות כדמפרש לקמן ברפ\"ב (תענית דף טו.):"],[13,"","מאי שייר דהאי שייר כו'. פי' דמשום חדא מילתא לא הוי לתנא לשייר וא\"ת הכא קאמר דלא תנא ושייר דהא אין בין קאמר דמשמע דאין בין זה לזה אלא אלו בלבד וקשה דהא במגילה (דף ח.) קתני אין בין נדרים לנדבות אלא שהנדרים חייב באחריותן ונדבות אינו חייב באחריותן ואנו יודעין דיש חילוק אחר דנדרים אינן באים אלא מן החולין דכל דבר שבחובה אינו בא אלא מן החולין ונדבות באות מן המעשר כדאמר (דברים כ״ז:ז׳) וזבחת שלמים ואכלת דכתיב גבי מעשר וי\"ל דהתם נמי דזה וזה שוה והני מילי גבי שלמים יש חילוק והא דקתני אין בין מיירי בעולות דאין בין עולות דנדרים לעולות דנדבה אלא שהנדרים חייב באחריותן מה שאין כן בנדבה דהא אין בין עולות דנדרים לעולות דנדבות אלא חילוק זה דהא כל עולות אינן באין אלא מן החולין:"],[15,"","ותסברא והא שייר תיבה. פי' מפרש לקמן (תענית דף טו:) שמוציאין התיבה ברחוב העיר (באמצעיות) באחרונות ותסברא דהא שייר תיבה פי' וליכא למימר דבאיסורא קמיירי דהא דמתריעין ונועלין מאי איסור איכא:"]]],[["והא שייר תיבה אי משום תיבה לאו שיורא הוא מילי דצינעא קתני מילי דבפרהסיא לא קתני","אמר רב אשי מתני' נמי דיקא דקתני מה אלו יתירות על הראשונות אלא שבאלו מתריעין ונועלין את החנויות אבל בכל דבריהן זה וזה שוין וכ\"ת הכא נמי תנא ושייר והא מה אלו קתני","ותסברא מה אלו דווקא הוא והא שייר לה תיבה אי משום תיבה לאו שיורא הוא משום דקא חשיב לה באידך פרקא השתא דאתית להכי עשרים וארבעה נמי לאו שיורא הוא דקתני לה באידך פירקא","מאי הוי עלה אמר רב שמואל בר ססרטאי וכן אמר רב חייא בר אשי אמר רב בין גואל לרופא ורב אשי אמר משמיה דרבי ינאי בריה דרבי ישמעאל בשומע תפלה והלכתא בשומע תפלה:","תני חדא עוברות ומיניקות מתענות בראשונות ואין מתענות באחרונות ותניא אידך מתענות באחרונות ואין מתענות בראשונות ותניא אידך אין מתענות לא בראשונות ולא באחרונות","אמר רב אשי נקוט אמצעייתא בידך דמיתרצון כולהו:","מה אלו יתירות על הראשונות אלא שבאלו מתריעין ונועלין את החנויות: במאי מתריעין רב יהודה אמר בשופרות ורב יהודה בריה דרב שמואל בר שילת משמיה דרב אמר בעננו","קס\"ד מאן דאמר בעננו לא אמר בשופרות ומאן דאמר בשופרות לא אמר בעננו והתניא אין פוחתין משבע תעניות על הצבור שבהן י\"ח התרעות וסימן לדבר יריחו ויריחו שופרות הוה ותיובתא למאן דאמר בעננו","אלא בשופרות דכולי עלמא לא פליגי דקרי לה התרעה כי פליגי בעננו מר סבר קרי לה התרעה ומר סבר לא קרי לה התרעה","למ\"ד בעננו כל שכן בשופרות ולמ\"ד בשופרות אבל בעננו לא","והתניא ושאר כל מיני פורעניות המתרגשות כגון חיכוך חגב זבוב וצירעה ויתושין ושילוח נחשים ועקרבים לא היו מתריעין אלא צועקין מדצעקה בפה התרעה בשופרות","תנאי היא דתניא על אלו מתריעין בשבת על עיר שהקיפוה גייס או נהר ועל ספינה המטורפת בים ר' יוסי אמר לעזרה אבל לא לצעקה","במאי אילימא בשופרות שופרות בשבת מי שרי אלא לאו בעננו וקרי לה התרעה ש\"מ:","בשני דר' יהודה נשיאה הוה צערא"],[[0,"והא שייר תיבה","דבאחרונות איתא והכא ליתא כדקתני לקמן (תענית דף טו.) סדר תעניות כיצד מוציאין את התיבה כו' ומותבינן בגמרא בהדיא מתיבה דליתא אלא באחרונות ומשני כי קתני נמי מתניתין בקמייתא:"],[0,"מילי דצינעא","מתריעין בבית הכנסת וכ\"ד נמי בבית הכנסת:"],[0,"בפרהסיא","תיבה ברחובה של עיר:"],[1,"דיקא נמי","דלכ\"ד זה וזה שוין דקתני מתניתין מה אלו יתירות על הראשונות כו' ואלו כ\"ד לא קא חשיב גבי אחרונות:"],[1,"והא מה אלו קתני","דמשמע דווקא:"],[2,"דהא קתני לה באידך פירקין","דמי ששנה מתניתין דהכא תנא נמי דהתם והאי דלא תנא בהאי סמיך אהתם דקתני באחרונות מוציאין התיבה מה שאין כן באמצעיות:"],[2,"השתא דאתית להכי","דמשום דקתני לה באידך פירקין דאמרת דלא הוי שיור כ\"ד נמי דאמרת דשוין נינהו איכא למימר דלא הוי שוין דהא אפי' שיורא נמי לא הוי דבהדיא קתני לה באידך פירקין דבאחרונות איתנהו באמצעיות לא ואיכא לתרוצי כתירוצא קמא בקמייתא דליכא כ\"ד:"],[3,"מאי הוי עלה","היכן אומרה יחיד:"],[5,"נקוט מציעיתא בידך","כלומר תריץ דבשלש אמצעיות היו מתענין ומתרצת לכולהו הנך מתנייתא הא דקתני בראשונות ולא באחרונות הנך ראשונות לאו ראשונות ממש נינהו אלא אמצעיות דאינהו הוו ראשונות לאחרונות אבל בשבע אחרונות לא מיתענו דכיון דשבע נינהו לא מצו עוברות ומיניקות למיקם בהו והא דקתני באחרונות ולא בראשונות הנך אחרונות אמצעיות נינהו והראשונות ראשונות ממש ואין מתענין בהן דלא תקיף רוגזא כולי האי וצחות לשון הוא לתנא למיקרי לאמצעיות ראשונות לאחרונ' ואחרונו' לראשונות:"],[6,"בשופרות","היו עושין ההתרעות ולשון התרעה כמו תרועה וסתם תרועה פשוטה לפניה ולאחריה במסכת ראש השנה (דף לד.) ואהכי מתריעין בשופרות כדכתיב (במדבר י׳:י׳) ותקעתם בחצוצרות וגו' תוקעין בשופרות כדי שיכניעו לבם לקול השופר ויהיו נרתעים מחטאתם ואשש ברכות שהיו מוסיפין ביום התענית היו תוקעין על כל ברכה יבבא אחת שהן י\"ח התרעות:"],[6,"רב יהודה אמר","מתריעין עננו בקול רם היו צועקים עננו אבינו עננו עננו אלהי אברהם עננו עננו אלהי יצחק עננו עננו אלהי יעקב עננו הכל כפי שאומרים בסוף הסליחות אבל עננו דתפלת תענית אומר אפי' בראשונות ואפי' יחיד אוקימנא דאומרה בשומע תפלה ותפלה קרי ליה התרעה דאי בשופרות מריעין מיבעי ליה ומאן דמפרש עננו של תפלת תענית משתבש דהא קתני בסמוך שהן י\"ח התרעות וקא פריך מן וסימן לדבר יריחו ואם איתא ליפריך בהדיא י\"ח תפלות של שמונה עשרה ברכות מי איכא בשבע תעניות:"],[7,"אין פוחתין מז' תעניות","באחרונות:"],[7,"שמונה עשרה התרעות","שהן מוסיפין ו' ברכות מי\"ח עד כ\"ד ולכל אחת שלש תרועות:"],[7,"וסימן לדבר","שלא תטעה אם התרעה הזו תרועה או תפלה:"],[7,"יריחו","דכתיב בה שופרות לישנא אחרינא סימן לדבר כלומר לכך מתריעין כדי שיענו כדרך שנענו ביריחו על ידי שופרות דכתיב (יהושע ו׳:כ׳) ויתקעו בשופרות וגו' וכתיב (שם) ותפול החומה תחתיה:"],[8,"אלא בשופרות כולי עלמא וכו'","דהא מתריעין דקתני הכא במתניתין דעבדינן בתעניות בשופרות:"],[8,"כי פליגי בעננו","כי פליגי במתריעין דאמרינן בעלמא על שאר פורענויות מ\"ס עננו נמי התרעה והאי דקתני בעלמא מתריעין בעננו ומאן דאמר בשופרות אבל בעננו לא:"],[10,"חגב","ארבה כתרגומו:"],[10,"צירעה","עוקצת את האדם:"],[10,"יתושין","נכנסין בעיניו ובחוטמו:"],[10,"חיכוך","כמו נתחכך בכותל:"],[10,"הא צעקה בפה היא","אלמא דצעקת פה לא קרי ליה התרעה:"],[11,"תנאי היא","האי תנא דשאר מיני פורעניות סבר צעקת פה לאו שמה התרעה ואידך סבר כו':"],[11,"גייס","וצרין עליה:"],[11,"נהר","המתפשט ויוצא לחוץ לשטוף את השדה ואת הבתים:"],[11,"המטורפת","כמו ביצים טרופות (חולין דף סד.) שהולכת ונדה ועתידה להיטבע במים:"],[11,"לעזרה","צועקין לבני אדם שיבואו לעזרם:"],[11,"ולא לצעקה","תפלה שאין אנו בטוחין כל כך שתועיל תפלתנו לצעוק עליהן בשבת אלמא צעקת פה קרי התרעה מפי מורי ל\"א לעזרה דקאמר תנא קמא מתריעין דמשמע בקול רם ואמר ליה רבי יוסי לעזרה שיהו מתפללין כל אחד בביתו לעזרה בעלמא:"]],[[2,"","לאו שיורא הוא דהא קתני לה באידך פירקא. והוא הדין דהוה מצי לתרוצי כדלעיל מילי דבפרהסיא לא קתני:"],[3,"","ורב יהודה בריה דרב שמואל בר שילת משמיה דרב אמר עננו. אומר הר\"י והאי עננו לא ר\"ל עננו שבתפלת תענית אלא ענינו שאומרים בסליחות וביום הכפורים עננו אבינו עננו אבל עננו דתפלה לא קאמר דהא בשלש ראשונות נמי אמר לה:"],[4,"","תני חדא מתענות בראשונות ולא באחרונות ותנא אידך מתענין באחרונות ולא בראשונות ותני אידך לא מתענין לא בראשונות ולא באחרונות נקוט מציעתא בידך. פירש הקונטרס השלש תעניות אמצעיות בידך דבאותן תעניות עוברות ומיניקות מתענות וה\"ק מתענות בראשונות פי' בראשונו' ר\"ל אמצעיות דהם ראשונות לאחרונו' שהיו חמורות אבל לא באחרונות דנפישי ולא מצו עבדי להו והא דקתני באחרונות ולא בראשונות האי אחרונו' היינו אמצעיות וקרי להו אחרונות שהם אחרונות מן הראשונות בתחלה גוזרין שלש תעניות וכן בשניה שלש אבל אין מתענות בראשונות שהם קלות והא דקתני לא בראשונות ולא באחרונות כלומר לא בשלש הראשונות הראשונות ממש ולא בשבע האחרונות האחרונות ממש אלא דווקא באמצעיות:"],[6,"","ורב יהודה בריה דרב שמואל בר שילת משמיה דרב אמר עננו. אומר הר\"י והאי עננו לא ר\"ל עננו שבתפלת תענית אלא ענינו שאומרים בסליחות וביום הכפורים עננו אבינו עננו אבל עננו דתפלה לא קאמר דהא בשלש ראשונות נמי אמר לה:"],[7,"","ובהן י\"ח תרועות וסימן לדבר יריחו. פירוש שביריחו עשו כן שהקיפוה ז' ימים והיו תוקעין בכל יום כמו כן תקנו בתעניות ובכל תענית מוסיפין שש ברכות ועל כל ברכה תוקעין מריעין ותוקעין א\"כ היינו י\"ח תרועות:"],[11,"","מתריעין לעזרה. פי' שיבואו לעזור העיר וכו' ומתריעין בפה פירוש והאי תרועה ר\"ל מתריעין בפה דאין להתיר תרועה בשופר בשבת:"]]],[["גזר תלת עשרה תעניות ולא איעני סבר למיגזר טפי אמר ליה ר' אמי הרי אמרו אין מטריחין את הצבור יותר מדאי","אמר ר' אבא בריה דרבי חייא בר אבא רבי אמי דעבד לגרמיה הוא דעבד אלא הכי אמר ר' חייא בר אבא אמר ר' יוחנן לא שנו אלא לגשמים אבל לשאר מיני פורעניות מתענין והולכין עד שיענו מן השמים תניא נמי הכי כשאמרו שלש וכשאמרו שבע לא אמרו אלא לגשמים אבל לשאר מיני פורעניות מתענין והולכין עד שיענו","לימא תיהוי תיובתיה דר' אמי אמר לך רבי אמי תנאי היא דתניא אין גוזרין יותר משלש עשרה תעניות על הצבור לפי שאין מטריחין את הצבור יותר מדאי דברי רבי רשב\"ג אומר לא מן השם הוא זה אלא מפני שיצא זמנה של רביעה","שלחו ליה בני נינוה לרבי כגון אנן דאפילו בתקופת תמוז בעינן מיטרא היכי נעביד כיחידים דמינן או כרבים דמינן כיחידים דמינן ובשומע תפלה או כרבים דמינן ובברכת השנים שלח להו כיחידים דמיתו ובשומע תפלה","מיתיבי אמר רבי יהודה אימתי בזמן שהשנים כתיקנן וישראל שרוין על אדמתן אבל בזמן הזה הכל לפי השנים הכל לפי המקומות הכל לפי הזמן אמר ליה מתניתא רמית עליה דרבי רבי תנא הוא ופליג","מאי הוי עלה רב נחמן אמר בברכת השנים רב ששת אמר בשומע תפלה והלכתא בשומע תפלה:","בשני מטין עם חשיכה ובחמישי כל היום מפני כבוד השבת: איבעיא להו היכי קתני בב' מטין עם חשיכה ובה' כל היום מפני כבוד השבת או דילמא בשני מטין ובחמישי פותחין כל היום כולו","תא שמע דתניא בשני מטין עד הערב ובחמישי פותחין כל היום כולו מפני כבוד השבת היו לו שני פתחים פותח אחד ונועל אחד היה לו אצטבא כנגד פתחו פותח כדרכו ואינו חושש:","עברו אלו ולא נענו ממעטין במשא ומתן ובבנין ובנטיעה: תנא בבנין בנין של שמחה נטיעה נטיעה של שמחה אי זהו בנין של שמחה זה הבונה בית חתנות לבנו אי זו היא נטיעה של שמחה זה הנוטע אבוורנקי של מלכים:","ובשאילת שלום: תנו רבנן חברים אין שאילת שלום ביניהן עמי הארץ ששואלין מחזירין להם בשפה רפה ובכובד ראש והן מתעטפין ויושבין כאבלים וכמנודין כבני אדם הנזופין למקום עד שירחמו עליהם מן השמים","אמר ר' אלעזר אין אדם חשוב רשאי ליפול על פניו אלא אם כן נענה כיהושע בן נון שנאמר (יהושע ז, י) ויאמר ה' אל יהושע קום לך למה זה אתה נופל על פניך","ואמר ר' אלעזר אין אדם חשוב רשאי לחגור שק אלא אם כן נענה כיהורם בן אחאב שנאמר (מלכים ב ו, ל) ויהי כשמוע המלך את דברי האשה ויקרע את בגדיו והוא עובר על החומה וירא העם והנה השק על בשרו וגו'","ואמר ר' אלעזר לא הכל בקריעה ולא הכל בנפילה משה ואהרן בנפילה יהושע וכלב בקריעה משה ואהרן בנפילה דכתיב (במדבר יד, ה) ויפל משה ואהרן על פניהם יהושע וכלב בקריעה דכתיב (במדבר יד, ו) ויהושע בן נון וכלב בן יפנה קרעו בגדיהם","מתקיף לה ר' זירא ואיתימא ר' שמואל בר נחמני אי הוה כתיב יהושע כדקאמרת השתא דכתיב ויהושע הא והא עביד","ואמר ר' אלעזר לא הכל בקימה ולא הכל בהשתחויה מלכים בקימה ושרים בהשתחויה מלכים בקימה דכתיב (ישעיהו מט, ז) כה אמר ה' גואל ישראל קדושו"],[[0,"גזר תליסר תעניתא","כדאמרינן במתניתין (דף טו:) שלש ראשונות ושלש אמצעיות ושבע אחרונות ולשאר פורעניות עביד להו ולא לגשמים:"],[1,"לגרמיה","לעצמו דרש שלא אמר אלא לפי שהוא לא היה רוצה להתענות:"],[1,"לא שנו","דאין גוזרים יותר משלש עשרה:"],[1,"כשאמרו","להתענות שלש ראשונות ושלש אמצעיות ושבע אחרונות:"],[2,"לא מן השם הוא זה","שאין זה טעם שאין מניחין בשביל טורח אלא שכבר יצא זמנה של רביעה של יורה שהרי מרחשון עבר על כולן לסוף התעניות שמקצתן היו בכסליו כדקתני מתניתין ואיכא למשמע מדרבי שמעון דבשאר מיני פורעניות דכל שעתא הוי זימנייהו למיבטלי אפילו טפי גזרינן ורבי דאמר אין מטריחין סתמא אכולהו קאמר ואנא דאמרי כרבי:"],[3,"ובשומע תפלה","אמרינן לשאילת מטר כיחיד השואל צרכיו בשומע תפלה דהא דאמרינן שאלה בברכת השנים אפי' ביחיד משום דזמן צבור הוא אבל במילתא אחריתי דהוי ליחיד ולא לצבור כהכא דבתקופת תמוז לאו זמן שאילת צבור הוא בשומע תפלה הוא דמדכר ליה ולא בברכת השנים כדאמרינן במסכת ע\"ז (דף ח.) ובברכות (דף לא.) אם היה לו חולה בתוך ביתו מזכיר עליו בברכת החולים ולבסוף מוקמינן והלכתא בשומע תפלה כך שמעתי:"],[4,"אימתי","הוא סדר תעניות:"],[4,"בזמן שהשנים כתיקנן","שהיא קציר בניסן וזריעה במרחשון ואין סדר השנים משתנה:"],[4,"וישראל שרוין על אדמתן","שמנהג ארץ ישראל בכך:"],[4,"הכל לפי השנים","אם צריכה אותה שנה למטר כגון שנה שחונה שצריכה לגשמים הרבה:"],[4,"לפי המקומות","כגון נינוה דאפי' בתקופת תמוז בעו מטרא. לא גרסינן לפי הזמן שלא ירדו עדיין גשמים:"],[6,"מטין","שלא יראו בני אדם ויצטערו אלא לעת ערב פותחין הואיל ולאו לכבוד שבת הוא ובחמישי מותרין לפתוח לגמרי:"],[6,"או דילמא","פותחין כל היום והכי משמע מתניתין בשני מטין ובה' היה פתוח כדרכו כל היום לגמרי מפני כבוד השבת:"],[7,"איצטבא","כסא דהשתא אין החנות פתוחה לרשות הרבים ואם הוא פתוח אינו נראה כל כך:"],[7,"פותח כדרכו","אפי' בשני:"],[8,"ה\"ג תנא בנין בנין של שמחה נטיעה נטיעה של שמחה","בנין דקתני מתניתין לא בנין הצריך לו אלא בנין הצריך לשמחה דבדבר שמחה ממעטינן:"],[8,"בית חתנות","לעשות חופתו:"],[8,"אבוורנקי של מלכים","שכך היו נוהגין כשנולד בן למלך היו נוטעין אילן לשמו ויום שממליכין אותו עושין לו כסא ממנו לישנא אחרינא אילן גדול המיסך על הארץ לטייל המלך תחתיו ודומה לו בעירובין (דף כה:) ההוא אבוורנקא דהוה ליה לריש גלותא בבוסתניה:"],[8,"של מלכים","דרך מלכים נוטעין אותו לצל הוא נוטעו כמו כן לצל היא והיא נטיעה של שמחה:"],[9,"ששאל בשלום","תלמיד חכם מחזיר לו משום איבה ובשפה רפה:"],[9,"אבל ומנודה חייבין בעטיפה","דכתיב ועל שפם יעטה במועד קטן (דף טו.):"],[10,"רשאי ליפול על פניו","לבזות עצמו בפני הצבור שאם לא יענה יחרפוהו כך שמעתי אלא אם כן יודעין בו שהוא חשוב כיהושע שאמר לו הקב\"ה קום לך למה זה אתה נופל על פניך:"],[11,"אלא אם כן נענה","שיודעין הן שנענה כיהורם יהורם רשע היה אלא שהתענה על רעב שהיה בימיו ונענה דכתיב (מלכים ב ז׳:ט״ז) ויהי סאה סולת בשקל וסאתים שעורים בשקל:"],[12,"לא הכל","נענין (בתפלה) ולא הכל נענין בקריעה דיהושע וכלב שלא היו חשובין כמשה ואהרן לא זכו ליענות אלא בקריעה ומקרא בעלמא קא דריש:"],[13,"ויהושע בן נון","כתיב בתריה דההוא דויפל וי\"ו מוסיף על ענין ראשון:"],[14,"ולא הכל בקימה","לקראת ישראל לעתיד לבא מלכים יראו וקמו שרים וישתחוו:"]],[[0,"","רבי יהודה נשיאה גזר תליסר תעניות. על שאר פורעניות ומיהו קאמר ליה רבי אמי דאין מטריחין דהכי נמי משמע דהוה אשאר מיני פורעניות מדמייתי עלה הא דקאמר רבי יוחנן ל\"ש אלא לגשמים אבל לשאר מינים וכו':"],[2,"","שיצאה זמנה של רביעה. דזמן רביעה דיורה הוי במרחשון ויצא מרחשון:"],[3,"","תני חדא מתענות בראשונות ולא באחרונות ותנא אידך מתענין באחרונות ולא בראשונות ותני אידך לא מתענין לא בראשונות ולא באחרונות נקוט מציעתא בידך. פירש הקונטרס השלש תעניות אמצעיות בידך דבאותן תעניות עוברות ומיניקות מתענות וה\"ק מתענות בראשונות פי' בראשונו' ר\"ל אמצעיות דהם ראשונות לאחרונו' שהיו חמורות אבל לא באחרונות דנפישי ולא מצו עבדי להו והא דקתני באחרונות ולא בראשונות האי אחרונו' היינו אמצעיות וקרי להו אחרונות שהם אחרונות מן הראשונות בתחלה גוזרין שלש תעניות וכן בשניה שלש אבל אין מתענות בראשונות שהם קלות והא דקתני לא בראשונות ולא באחרונות כלומר לא בשלש הראשונות הראשונות ממש ולא בשבע האחרונות האחרונות ממש אלא דווקא באמצעיות:"],[3,"","שלח להו כיחידים דמיתו. פירוש ובשומע תפלה תאמרו תפלת תענית והא דיחיד אומר ותן טל ומטר בברכת השנים אע\"ג שמתפלל בעצמו הואיל וזמן צבור הוא אבל בני נינוה הוו יחידים אפי' בתקופת תמוז צריכין למטרא:"],[4,"","הכל לפי השנים. אם צריכים אותה שנה גשמים שהיא שחונה ואם צריכים גשמים כבני נינוה שואלין ותן טל ומטר בברכת השנים:"]]],[["לבזה נפש למתעב גוי לעבד מושלים מלכים יראו וקמו ושרים בהשתחויה דכתיב שרים וישתחוו מתקיף לה רבי זירא ואיתימא רבי שמואל בר נחמני אי הוה כתיב ושרים ישתחוו כדקאמרת השתא דכתיב שרים וישתחוו הא והא עבוד","אמר רב נחמן בר יצחק אף אני אומר לא הכל לאורה ולא הכל לשמחה צדיקים לאורה וישרים לשמחה צדיקים לאורה דכתיב (תהלים צז, יא) אור זרוע לצדיק ולישרים שמחה דכתיב ולישרי לב שמחה:","\u0001הדרן עלך מאימתי\u0002","מתני׳ \u0001סדר\u0002 תעניות כיצד מוציאין את התיבה לרחובה של עיר ונותנין אפר מקלה על גבי התיבה ובראש הנשיא ובראש אב בית דין וכל אחד ואחד נותן בראשו","הזקן שבהן אומר לפניהן דברי כבושין אחינו לא נאמר באנשי נינוה וירא אלהים את שקם ואת תעניתם אלא (יונה ג, י) וירא אלהים את מעשיהם כי שבו מדרכם הרעה ובקבלה הוא אומר (יואל ב, יג) וקרעו לבבכם ואל בגדיכם","עמדו בתפלה מורידין לפני התיבה זקן ורגיל ויש לו בנים וביתו ריקם כדי שיהא לבו שלם בתפלה","ואומר לפניהן עשרים וארבעה ברכות י\"ח שבכל יום ומוסיף עליהן עוד שש ואלו הן זכרונות ושופרות (תהלים קכ, א) אל ה' בצרתה לי קראתי ויענני (תהלים קכא, א) אשא עיני אל ההרים וגו' (תהלים קל, א) ממעמקים קראתיך ה' (תהלים קב, א) תפלה לעני כי יעטוף","ר' יהודה אומר לא היה צריך לומר זכרונות ושופרות אלא אומר תחתיהן (מלכים א ח, לז) רעב כי יהיה בארץ דבר כי יהיה (ירמיהו יד, א) אשר היה דבר ה' אל ירמיהו על דברי הבצרות","ואומר חותמיהן על הראשונה הוא אומר מי שענה את אברהם בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה ברוך אתה ה' גואל ישראל על השניה הוא אומר מי שענה את אבותינו על ים סוף הוא יענה אתכם וישמע קול צעקתכם היום הזה ברוך אתה ה' זוכר הנשכחות","על השלישית הוא אומר מי שענה את יהושע בגלגל הוא יענה אתכם וישמע בקול צעקתכם היום הזה ברוך אתה ה' שומע תרועה על הרביעית הוא אומר מי שענה את שמואל במצפה הוא יענה אתכם וישמע בקול צעקתכם היום הזה ברוך אתה ה' שומע צעקה על החמישית הוא אומר מי שענה את אליהו בהר הכרמל הוא יענה אתכם וישמע בקול צעקתכם היום הזה ברוך אתה ה' שומע תפלה","על הששית הוא אומר מי שענה את יונה ממעי הדגה הוא יענה אתכם וישמע בקול צעקתכם היום הזה ברוך אתה ה' העונה בעת צרה על השביעית הוא אומר מי שענה את דוד ואת שלמה בנו בירושלים הוא יענה אתכם וישמע בקול צעקתכם היום הזה ברוך אתה ה' המרחם על הארץ:","מעשה"],[[0,"לבזה נפש למתעב גוי לעבד מושלים","לישראל הבזוים ומתועבים ועבדים מושלין בהן:"],[1,"ה\"ג לא הכל לאורה ולא הכל לשמחה דכתיב אור זרוע לצדיק ולישרי לב שמחה","ישרים לשמחה דישרים עדיפי מצדיקים:"],[3,"פרק שני","סדר תענית כיצד"],[3,"","מתני' סדר תעניות כיצד כו':"],[3,"ברחובה של עיר","בגלוי וכי הך דאמרינן במסכת מגילה (דף כה:) בני העיר שמכרו רחובה של עיר והתם מפרש בהדיא אמר ר' זירא הואיל והעם מתפללים בו בתעניות ובמעמדות:"],[3,"אפר מקלה","אפר ממש ולא עפר אפר סתם הוא עפר דכשם שאפר קרוי עפר דכתיב (במדבר י״ט:י״ז) מעפר שרפת החטאת כך עפר קרוי אפר סתם והיינו דקתני אפר מקלה אפר שריפה אי הוה תני אפר סתם הוה משמע עפר ואפר מקלה גנאי יותר מעפר סתם ובגמרא מפרש מאי טעמא נותנין אותו:"],[4,"כבושין","לשון עצירה כמו מכבש בלע\"ז פריש\"א שכובשין את הלבבות להחזירם למוטב ואלו הן דברי כבושין אחינו כו':"],[4,"ובקבלה","שהנביא מצוה לישראל (עמדו בתפלה) והקשה תוספות מאן דהו מאי שנא בהאי קרא דכתיב ביונה וירא האלהים את מעשיהם וגו' ולא קרי ליה דברי קבלה ובהאי קרא דוקרעו לבבכם קרי ליה קבלה ופריק איהו כל מקום שהנביא מצוה ומודיע ומזהיר את ישראל קרי ליה קבלה ובכל דוכתא דלא איתפקד נביא כי האי וירא האלהים שהוא כמספר והולך דיליף מיניה אגב אורחיה מילתא לא קרינן ליה קבלה:"],[5,"ורגיל","רגיל להתפלל ותפלתו שגורה בפיו ולא יטעה שכל חזן שטועה סימן רע לשולחיו:"],[5,"וביתו ריקם","משמע דהוא עני ואין לו מחיה בביתו ובגמרא מפרש טעמא אחרינא וגופו נקי מעבירות שלא חטא ולא יצא עליו שום שם רע בשום עבירה כו':"],[6,"זכרונות ושופרות","כל הפסוקים שאומרים בראש השנה:"],[6,"אל ה' בצרתה לי כו'","כולן הן מזמורים:"],[8,"ואומר חותמיהן","על כל פרשה ופרשה אחר זכרונות חתימת זכרונות ואחר שופרות חתימת שופרות וכן אחר כולם מעין הפרשה כדמפרש ואזיל:"],[8,"על הראשונה","בפעם ראשונה הוא אומר מי שענה לאברהם כו' בגואל ישראל היה מתחיל להאריך והולך ואומר לכולן שש ברכות:"],[8,"על השניה","זו היא ברכה ראשונה של שש ברכות כדאמרינן בגמרא והיאך דגואל ישראל זו היא ברכה עצמה של שמונה עשרה ואינה מאותן שש אלא שבה היה מתחיל להוסיף ולהאריך על הזכרונות הוא אומר זוכר הנשכחות ועל השופרות שומע תרועה והיא שניה למנינה ועל אל ה' בצרתה לי והיא שלישית למנין שש שומע צעקה שלישית וכן כולן:"],[8,"ומי שענה את אבותינו על ים סוף","לפיכך אומרה בזכרונות לפי שהיו ישראל נשכחים במצרים כמה שנים ונתייאשו מן הגאולה וזכרם המקום וגאלם דכתיב (שמות ו׳:ה׳) ואזכור את בריתי:"],[9,"ובשופרות היה אומר מי שענה את יהושע בגלגל","לפי שנענה בשופרות ביריחו וזהו בעוד שהיו ישראל בגלגל:"],[9,"ואליהו בהר הכרמל","כנגד אשא עיני אל ההרים וכן כולן לפי ענין המזמורים אליהו נענה בהר הכרמל מעין אשא עיני אל ההרים ושמואל במצפה דכתיבי קראי ומעין אל ה' בצרתה לי:"],[10,"ממעי הדגה","מעין ממעמקים קראתיך ה' ועונה בעת צרה שכן כתיב ביונה קראתי מצרה לי (יונה ב׳:ג׳) ובשמואל כתיב ויזעק אל ה' (שמואל א ו) ובאליהו כתיב (מלכים א יח) ענני זו תפלה:"],[10,"ועל השביעית","מפרש בגמרא מאי שביעית מי שענה דוד ויהי רעה בימי דוד שלש שנים שנה אחר שנה (שמואל ב כא):"],[10,"ושלמה","כשהכניס הארון לבית קדש הקדשים אי נמי רעב כי יהיה בארץ וגו' (מלכים א ח׳:ל״ז) ולפיכך חותם מרחם על הארץ שהן התפללו על ארץ ישראל ותפלה לעני כי יעטוף על דוחק גשמים נופל וכתיב ביה (שם) בהעצר שמים:"]],[[1,"","אור זרוע לצדיק ולישרי לב שמחה. פירוש ואין לומר כדלעיל ולישרים האי והאי שמחה ואורה א\"כ דאמרינן דלישרי לב קאי אהא דלעיל כמו כן אמרינן דצדיקים קאי אהא דאבתריה כיון דסמוך צדיק לישרי לב ובודאי יש הפרש בין זה לזה דאם לא כן לערבינהו ולכתוב לצדיקים ולישרי לב אורה ושמחה אבל ההיא דלעיל לא הוו מלכים ושרים כי הדדי אלא יראו וקמו בינייהו וכמו יראו וקמו דהוי קודם שרים קאי על מלכים דלעיל קאי נמי אשרים דכתיב אבתריה אבל הכא אין לפרש אלא אור זרוע לצדיקים ולישרי לב שמחה:"],[3,"","ונותנין אפר על גבי כו'. ואותו אפר הוי מעצם אדם שהרי הוא האפר הוי לזכרון העקידה ובעקידה היה עצמות:"]]],[["בימי רבי חלפתא ור' חנניא בן תרדיון שעבר אחד לפני התיבה וגמר את הברכה כולה ולא ענו אחריו אמן תקעו הכהנים ותקעו מי שענה את אברהם אבינו בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה הריעו בני אהרן הריעו מי שענה את אבותינו על ים סוף הוא יענה אתכם וישמע בקול צעקתכם היום הזה","וכשבא דבר אצל חכמים אמרו לא היינו נוהגין כן אלא בשער מזרח ובהר הבית","שלש תעניות הראשונות אנשי משמר מתענין ולא משלימין ואנשי בית אב לא היו מתענין כלל שלש שניות אנשי משמר מתענין ומשלימין ואנשי בית אב מתענין ולא משלימין שבע אחרונות אלו ואלו מתענין ומשלימין דברי רבי יהושע","וחכמים אומרים שלש תעניות הראשונות אלו ואלו לא היו מתענין כלל שלש שניות אנשי משמר מתענין ולא משלימין ואנשי בית אב לא היו מתענין כלל שבע אחרונות אנשי משמר מתענין ומשלימין ואנשי בית אב מתענין ולא משלימין","אנשי משמר מותרין לשתות יין בלילות אבל לא בימים ואנשי בית אב לא ביום ולא בלילה אנשי משמר ואנשי מעמד אסורין מלספר ומלכבס ובחמישי מותרין מפני כבוד השבת","כל הכתוב במגילת תענית דלא למספד לפניו אסור לאחריו מותר רבי יוסי אומר לפניו ולאחריו אסור","דלא להתענאה לפניו ולאחריו מותר ר' יוסי אומר לפניו אסור לאחריו מותר","אין גוזרין תענית על הצבור בתחילה בחמישי שלא להפקיע השערים אלא שלש תעניות הראשונות שני וחמישי ושני ושלש שניות חמישי שני וחמישי ר' יוסי אומר כשם שאין הראשונות בחמישי כך לא שניות ולא אחרונות","אין גוזרין תענית על הצבור בראשי חדשים בחנוכה ובפורים ואם התחילו אין מפסיקין דברי רבן גמליאל אמר רבי מאיר אף על פי שאמר רבן גמליאל אין מפסיקין מודה היה שאין משלימין וכן תשעה באב שחל להיות בערב שבת:","\u0001גמ׳\u0002 סדר תעניות כיצד מוציאין את התיבה כו' ואפילו בקמייתא ורמינהו שלש תעניות ראשונות ושניות נכנסים לבית הכנסת ומתפללין כדרך שמתפללין כל השנה כולה","ובשבע אחרונות מוציאין את התיבה לרחובה של עיר ונותנין אפר על גבי התיבה ובראש הנשיא ובראש אב בית דין וכל אחד ואחד נוטל ונותן בראשו רבי נתן אומר אפר מקלה הן מביאין אמר רב פפא כי תנן נמי מתניתין אשבע אחרונות תנן:","ובראש הנשיא והדר תני כל אחד ואחד (נוטל ונותן) בראשו איני (והתנן) רבי אומר בגדולה מתחילין מן הגדול ובקללה מתחילין מן הקטן","בגדולה מתחילין מן הגדול שנאמר (ויקרא י, ו) ויאמר משה אל אהרן ולאלעזר ולאיתמר ובקללה מתחילין מן הקטן (דאמר מר) בתחלה נתקלל נחש ואחר כך נתקללה חוה ואח\"כ נתקלל אדם","הא חשיבותא לדידהו דאמרי להו אתון חשיביתו למיבעי עלן רחמי אכ\"ע:","(כל אחד ואחד (נוטל ונותן) בראשו אמר רב אדא) וכל אחד ואחד (נוטל ונותן) בראשו נשיא ואב בית דין נמי נשקלו אינהו ונינחו בראשייהו מאי שנא דשקיל איניש אחרינא ומנח להו אמר רבי אבא דמן קסרי אינו דומה מתבייש מעצמו"],[[0,"בימי רבי חלפתא בצפורי","אביו של רבי יוסי דאמרינן בסנהדרין (דף לב:) אחר רבי יוסי בצפורי [אחר רבי חנניא בן תרדיון] בסיכני:"],[0,"וגומר כל הברכה","כל אותה ברכה עצמה:"],[0,"ה\"ג ולא ענו אחריו אמן תקעו בני אהרן תקעו","חזן הכנסת אומר להן על כל ברכה וברכה והוא השמש ולא שליח צבור:"],[1,"לא היינו נוהגין","שלא לענות אמן:"],[1,"אלא בשער מזרח ובהר הבית","כלומר בזמן שבית המקדש קיים כשמתפללין בהר הבית נכנסין בדרך שער המזרח לפי שלא היו עונין אמן במקדש כדאמרינן בגמרא (דף טז:) ואין לומר לא היו נוהגין כן לתקוע אלא במקדש דודאי תוקעין בגבולים כדמוכח בכולה הך מסכת ומסכת ראש השנה (דף כו: כז.):"],[2,"אנשי משמר","של אותה שבת:"],[2,"ולא משלימין","שעדיין אינן חמורין כל כך ובגמרא (דף יז.) מפרש שמא תכבד העבודה על אנשי בית אב שהיו עובדין אותו היום ובאים הן לסייעם ואם היו מתענים לא היה להם כח לעמוד בעבודה:"],[2,"אנשי בית אב","המשמרה מתחלקת לשבעה בתי אבות כנגד שבעת ימי השבוע בית אב ליום:"],[4,"מותרין לשתות יין","לאו גבי תענית איתמר אלא אגב דמיירי בבני משמר מייתי לה:"],[4,"בלילות","אין לחוש שמא תכבד העבודה שהרי ראו מבערב שפסקו הקרבנות ולא כבדה העבודה שיביאו רוב קרבנות ולא יספיקו בני בית אב של אותו היום וצריכין אלו לסייען והרי אינן ראויין לעבודה משום שכרות:"],[4,"אנשי בית אב אסורין בין ביום ובין בלילה","לפי שהיו מעלין כל הלילה אברים ופדרים שפקעו מעל המזבח א\"נ לא גמרו ביום גומרים בלילה אבל אנשי משמר אינן צריכין לסייע בלילה להפך במזלג דבית אב יכול להספיק לבד היפוך המערכה:"],[4,"אנשי [מעמד]","אחד כהנים ולוים וישראלים הקבועים ועומדין ומתפללין על קרבן אחיהם שיקבל לרצון ועומדים לשם בשעת עבודה דהיאך קרבנו של אדם קרב והוא אינו עומד על גביו וכולהו מפרש בפרק אחרון (דף כו.):"],[4,"אסורים לספר ולכבס","משנכנסו למשמרתם כל אותה שבת אלא מסתפרין קודם לכן וטעמא מפרש בגמרא:"],[4,"ובחמישי","של משמרתן מותרים דרך רוב בני אדם להסתפר בחמישי ולא בערב שבת מפני הטורח:"],[5,"כל הכתוב במגילת תענית דלא למיספד","דאית יומיא דלא להתענאה ומקצתהון דחמירי טפי דלא למיספד ואותן שהן חמורים ואסורים בהספד לפניו אסור בהספד דילמא אתי למיעבד ביו\"ט גופיה:"],[5,"ולאחריו מותר","דכיון שעבר יום לא חיישינן ואותן שאינן חמורין ליאסר בהספד אלא דלא להתענאה בין לפניו כו':"],[7,"שלא להפקיע את השערים","כשרואין בעלי חניות שקונין למוצאי יום חמישי שתי סעודות גדולות אחת לליל חמישי ואחת לשבת סבורים שבא רעב לעולם ומייקרים ומפקיעים השער אבל משהתחילו להתענות יודעין שאינו אלא מפני התענית:"],[8,"בראשי חדשים","דאיקרי מועד:"],[8,"ואם התחילו","שקיבלו תענית מקודם לכן ונכנס בהן ראש חדש אין מפסיקין דאף על גב דאקרי מועד לא כתיב ביה יום משתה ושמחה:"],[8,"שאין משלימין","להתענות כל היום אלא אוכלין סמוך לערב מגילת תענית נכתבה בימי חכמים אע\"פ שלא היו כותבין הלכות והיינו דקתני כל הכתוב במגילת תענית כאילו היה מקרא:"],[9,"אפילו בקמייתא","מוציאין את התיבה בתמיה:"],[10,"ה\"ג בגמרא ונותנין אפר על גבי התיבה","ולא גרסינן אפר מקלה אפר שריפה עדיף משום אפרו של יצחק כדלקמן:"],[10,"כי קתני נמי מתניתין","סדר תעניות כיצד בסדר תעניות אחרונות קא מיירי:"],[11,"בגדולה","מצוה בעלמא שלא לפורענות וידבר משה אל אהרן ואל אלעזר וגו':"],[14,"דשקיל איניש אחרינא כו'","דקתני ונותנין ע\"ג התיבה כו' ועל ראש הנשיא כו' דמשמע על ידי אחר וגבי שאר כל אדם לא תני נותנין אלא כל אחד ואחד (נוטל) כו':"]],[[9,"","ואפילו בקמייתא. כלומר ואפי' בג' תעניות הראשונות ובג' שניות קאמר במתני' דמוציאין את התיבה לרחובה של עיר ואומר כ\"ד ברכות כו' ורמינהו והתניא ראשונות ושניות נכנסין כו' . פי' ומתפללין בה כדרך כל השנה כולה כלומר שיאמר י\"ח ברכות כדרך שמתפללין כל השנה וקשה דהא לעיל בפ\"ק (תענית דף יג:) קאמרינן אין בין ג' תעניות שניות לשלש ראשונות אלא שבאלו מתפללין ומותרין בעשיית מלאכה ובאלו אסורין בעשיית מלאכה הא לענין עשרים וארבעה זה וזה שוין דבין בראשונות בין באמצעיות היו אומרים כ\"ד ועוד קשה דאמרינן לעיל ואיבעית אימא באמצעיות נמי לא מצלו כ\"ד ואמאי לא מייתי לה סיועא מהא דהכא וי\"ל דהא דקאמר הכא ומתפללין כדרך כל השנה לאו בעשרים וארבע ברכות קאמר אלא קאמר שמתפללין כדרך כל השנה שלא היו מוציאין את התיבה לרחובה של עיר:"]]],[["למתבייש מאחרים והיכא מנח להו אמר רבי יצחק במקום תפילין שנאמר (ישעיהו סא, ג) לשום לאבילי ציון לתת להם פאר תחת אפר:","רחוב תיבה ושקים אפר אפר קבורה ומוריה סימן: למה יוצאין לרחוב ר' חייא בר אבא אמר לומר זעקנו בצנעא ולא נענינו נבזה עצמנו בפרהסיא","ריש לקיש אמר גלינו גלותינו מכפרת עלינו מאי בינייהו איכא בינייהו דגלי מבי כנישתא לבי כנישתא","ולמה מוציאין את התיבה לרחובה של עיר אמר ר' יהושע בן לוי לומר כלי צנוע היה לנו ונתבזה בעוונינו","ולמה מתכסין בשקים אמר ר' חייא בר אבא לומר הרי אנו חשובין כבהמה ולמה נותנין אפר מקלה על גבי תיבה אמר רבי יהודה בן פזי כלומר (תהלים צא, טו) עמו אנכי בצרה ריש לקיש אמר (ישעיהו סג, ט) בכל צרתם לו צר אמר ר' זירא מריש כי הוה חזינא להו לרבנן דיהבי אפר מקלה על גבי תיבה מזדעזע לי כוליה גופאי","ולמה נותנין אפר בראש כל אחד ואחד פליגי בה ר' לוי בר חמא ור' חנינא חד אמר הרי אנו חשובין לפניך כאפר וחד אמר כדי שיזכור לנו אפרו של יצחק מאי בינייהו איכא בינייהו עפר סתם","למה יוצאין לבית הקברות פליגי בה ר' לוי בר חמא ור' חנינא חד אמר הרי אנו חשובין לפניך כמתים וחד אמר כדי שיבקשו עלינו מתים רחמים מאי בינייהו איכא בינייהו קברי עכו\"ם","מאי (דברי הימים ב ג, א) הר המוריה פליגי בה ר' לוי בר חמא ור' חנינא חד אמר הר שיצא ממנו הוראה לישראל וחד אמר הר שיצא ממנו מורא לעובדי כוכבים:","הזקן שבהן אומר לפניהן דברי כבושין: ת\"ר אם יש זקן אומר זקן ואם לאו אומר חכם ואם לאו אומר אדם של צורה אטו זקן דקאמרי אף על גב דלאו חכם הוא אמר אביי הכי קאמר אם יש זקן והוא חכם אומר זקן והוא חכם ואם לאו אומר חכם ואם לאו אומר אדם של צורה","אחינו לא שק ותענית גורמים אלא תשובה ומעשים טובים גורמים שכן מצינו באנשי נינוה שלא נאמר בהם וירא האלהים את שקם ואת תעניתם אלא (יונה ג, י) וירא האלהים את מעשיהם כי שבו מדרכם הרעה","(יונה ג, ח) ויתכסו שקים האדם והבהמה מאי הוו עבדי אסרא הבהמות לחוד ואת הוולדות לחוד אמרו לפניו רבונו של עולם אם אין אתה מרחם עלינו אין אנו מרחמים על אלו","(יונה ג, ח) ויקראו אל אלהים בחזקה מאי אמור אמרו לפניו רבונו של עולם עלוב ושאינו עלוב צדיק ורשע מי נדחה מפני מי","(יונה ג, ח) וישובו איש מדרכו הרעה ומן החמס אשר בכפיהם מאי ומן החמס אשר בכפיהם אמר שמואל אפילו גזל מריש ובנאו בבירה מקעקע כל הבירה כולה ומחזיר מריש לבעליו","אמר רב אדא בר אהבה אדם שיש בידו עבירה ומתודה ואינו חוזר בה למה הוא דומה לאדם שתופס שרץ בידו שאפי' טובל בכל מימות שבעולם לא עלתה לו טבילה זרקו מידו כיון שטבל בארבעים סאה מיד עלתה לו טבילה","שנאמר (משלי כח, יג) ומודה ועוזב ירוחם ואומר (איכה ג, מא) נשא לבבינו אל כפים אל אל בשמים:","עמדו בתפלה מורידין לפני התיבה זקן כו': תנו רבנן עמדו בתפלה אע\"פ שיש שם זקן וחכם אין מורידין לפני התיבה אלא אדם הרגיל (איזהו רגיל) ר' יהודה אומר מטופל ואין לו ויש לו יגיעה בשדה וביתו ריקם","ופרקו נאה ושפל ברך ומרוצה לעם ויש לו נעימה וקולו ערב ובקי לקרות בתורה ובנביאים ובכתובים ולשנות במדרש בהלכות ובאגדות ובקי בכל הברכות כולן ויהבו ביה רבנן עינייהו בר' יצחק בר אמי"],[[0,"למתבייש מאחרים","דאיכא עגמת נפש טפי ומשום חשיבותם הם מתביישים מאחרים אבל שאר בני אדם דלא חשיבי לא מתביישי בנתינת אחרים וסגי להו בנתינת עצמן:"],[0,"פאר תחת אפר","ש\"מ במקום תפילין דכתיב בהו (יחזקאל כ״ד:י״ז) פארך חבוש עליך ואמרינן (ברכות דף יא.) אלו תפילין ומתרגמינן נמי טוטפתך הויין עלך והיכא מניחין תפילין במקוֹם שמוחו של תינוק רופף:"],[1,"בצינעא","בבית הכנסת:"],[2,"גלינו","שיצאנו מכניסתנו:"],[2,"גלותינו","תהא מכפרת עלינו:"],[2,"דגלו מבי כנישתא לבי כנישתא אחריתא","גלות איכא פרהסיא ליכא:"],[3,"נתבזה בעוונינו","וידוי:"],[4,"[ולמה מתכסין]","חוגרות שקין תנינן בירושלמי שהיו חוגרות שקין ויוצאין לבית הקברות ותוקעין בקרנות ובעי ליה מיבעיא שקין למה ובית הקברות למה ותקיעת שופר למה:"],[4,"כבהמה","דמשער בהמה נינהו מנוצה של עזים:"],[5,"עפר סתם","שאינו אפר מקלה זכירת אפרו של יצחק ליכא סתם לא גרסינן אלא איכא בינייהו עפר:"],[6,"קברי עכו\"ם","במקום שאין קברי ישראל לבקש רחמים אפי' על עצמן ליכא כל שכן עלינו:"],[7,"מאי הר המוריה וכו'","איידי דאיירי בפלוגתא דרבי לוי ור\"ח תנא נמי הא פלוגתא מאי הר מוריה דאברהם קרא למקום העקידה הר יראה וכתיב (בראשית כ״ב:ב׳) אל ארץ המוריה:"],[7,"חד אמר הר שיצא הוראה","תורה לישראל כי מציון תצא תורה (ישעיהו ב׳:ג׳) יורו משפטיך ליעקב (דברים ל״ג:י׳) ולשכת הגזית שבה עמדו הנביאים המוכיחים לישראל:"],[7,"מורא לעובדי כוכבים","ששומעין גדולות ישראל וירושלים ומתפחדים עליהם שמעתי לישנא אחרינא הר המוריה הר סיני מורא לעובדי כוכבים במתן תורה דכתיב (תהילים ע״ו:ט׳) ארץ יראה ושקטה:"],[8,"אע\"ג דלאו חכם","אלא עם הארץ בתמיהה הא ודאי חכם עדיף:"],[8,"אם יש זקן והוא חכם","אומר זקן והוא חכם:"],[8,"אדם של צורה","בעל קומה שישמעו ויקבלו דבריו להמריך את הלב:"],[10,"אם אין אתה מרחם כו'","כלומר כשם שאתה אומר לרחם על אלו דכתיב (תהילים קמ״ה:ט׳) ורחמיו על כל מעשיו כן תרחם עלינו:"],[11,"מאי אמור","אנשי נינוה דכתיב בחזקה דמשמע בכח וניצוח דין:"],[11,"מי נדחה מפני מי","הוי אומר צדיק מפני רשע:"],[12,"מריש","קורה:"],[12,"בירה","מגדל:"],[13,"שיש בידו עבירה","גזל:"],[13,"ואינו חוזר בו","לשלם את הגזל למה הוא דומה וכו':"],[14,"נשא לבבנו אל כפים","עם הכפים צריך לישא הלב לשמים כלומר שיחזור מקלקולו:"],[15,"מטופל ואין לו","יש לו טפלים ואין לו במה להתפרנס שלבו דואג עליו [והוא צריך לקרות מקירות לבו עליהן]:"],[15,"ויש לו יגיעה","שמתכוין יותר בתפלת הגשמים:"],[16,"ופרקו נאה","מפרש לקמן:"],[16,"ושפל ברך","עניו:"],[16,"ומרוצה לעם","נוח לבריות ומסכימין לתפלתו:"],[16,"נעימה","בסומי קלא שמושך הלב:"],[16,"ורגיל לקרות כו'","שיהו הפסוקים של תפלה סדורין בפיו:"]],[[0,"","במקום תפילין. פירוש לתת האפר במקום הפאר דאילו התפילין נקראו פאר כדכתיב לשום לאבילי ציון לתת להם פאר וגו':"],[2,"","איכא בינייהו דגלו מבי כנישתא לבי כנישתא. פירוש למ\"ד משום גלות איכא ולמ\"ד משים פרהסיא ליכא דהא בי כנישתא הוי כמו בצנעא:"],[4,"","אפר מקלה. פירוש אותו אפר הוה מדבר הנשרף מעצמות אדם כדי לזכור עקידת יצחק דאלמלא שלא היה בא אלא כדי לומר שהרי אנו לפניך כאפר כמו כן מהני עפר סתם והיינו פירוש איכא בינייהו עפר סתם:"],[5,"","איכא בינייהו דגלו מבי כנישתא לבי כנישתא. פירוש למ\"ד משום גלות איכא ולמ\"ד משים פרהסיא ליכא דהא בי כנישתא הוי כמו בצנעא:"],[6,"","יוצאין לבית הקברות. מכאן נוהגין בכל מקום לילך לבית הקברות בט' באב שהרי ט\"ב הוי תענית צבור כמו שהיו עושין מפני הגשמים:"],[7,"","הר שיצאה ממנו הוראה לישראל. י\"מ דזה ירושלם שנקרא על שם אברהם שקראוהו הר ה' יראה (בראשית כב) והעיר היה נקרא כבר שלם כדכתיב (שם יד) ומלכי צדק מלך שלם ונקרא ירושלם על שם יראה ועל שם שלם לכך אין אנו נותנין יו\"ד בירושלם בין למ\"ד למ\"ם על שם שלם וההר נקרא מוריה על שם תורה כדכתיב (ישעיהו ב׳:ג׳) כי מציון תצא תורה וכתיב (דברים ל״ג:י׳) יורו משפטיך ליעקב והוא לשכת הגזית. המוריה זה סיני ונקרא מוריה על שם שממנו יצא מורא לעובדי כוכבים במתן תורה כדכתיב (תהילים ע״ו:ט׳) ארץ יראה ושקטה אי נמי רצה לומר דירושלם נקרא מוריה על שם שיש מורא לעובדי כוכבים על גדולתה ומתפחדים:"],[8,"","אדם שיש לו צורה. פירוש בעל קומה כדי שישמעו דבריו ויקבלו ממנו להמריך הלב ופרקו נאה פירוש כשעמד על פרקו אפילו כשהיה בחור היה בלא שם רע:"]]],[["היינו מטופל ואין לו היינו ביתו ריקם אמר רב חסדא זהו שביתו ריקם מן העבירה: ופרקו נאה אמר אביי זה שלא יצא (לו) שם רע בילדותו","(ירמיהו יב, ח) היתה לי נחלתי כאריה ביער נתנה עלי בקולה על כן שנאתיה מאי נתנה עלי בקולה אמר מר זוטרא בר טוביה אמר רב ואמרי לה אמר רבי חמא אמר רבי אלעזר זה שליח צבור (היורד לפני התיבה שאינו הגון):","ואומר לפניהם עשרים וארבע ברכות שמונה עשרה שבכל יום ומוסיף עליהן עוד שש: הני שש שבע הוויין כדתנן על השביעית הוא אומר ברוך מרחם על הארץ אמר רב נחמן בר יצחק מאי שביעית שביעית לארוכה","כדתניא בגואל ישראל מאריך ובחותמה הוא אומר מי שענה את אברהם בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה ברוך גואל ישראל והן עונין אחריו אמן וחזן הכנסת אומר להם תקעו בני אהרן תקעו","וחוזר ואומר מי שענה את אבותינו על ים סוף הוא יענה אתכם וישמע בקול צעקתכם היום הזה ברוך זוכר הנשכחות והן עונין אחריו אמן וחזן הכנסת אומר להם הריעו בני אהרן הריעו וכן בכל ברכה וברכה באחת אומר תקעו ובאחת אומר הריעו:","במה דברים אמורים בגבולין אבל במקדש אינו כן לפי שאין עונין אמן במקדש ומנין שאין עונין אמן במקדש","שנאמר (נחמיה ט, ה) קומו ברכו את ה' אלהיכם מן העולם עד העולם ויברכו שם כבודך ומרומם על כל ברכה ותהלה יכול על כל ברכות כולן לא תהא אלא תהלה אחת ת\"ל ומרומם על כל ברכה ותהלה על כל ברכה תן לו תהלה","ואלא במקדש מהו אומר ברוך ה' אלהים אלהי ישראל מן העולם ועד העולם ברוך גואל ישראל והן עונין אחריו ברוך שם כבוד מלכותו לעולם ועד וחזן הכנסת אומר להם תקעו הכהנים בני אהרן תקעו","וחוזר ואומר מי שענה את אברהם בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה ברוך ה' אלהי ישראל זוכר הנשכחות והם עונים אחריו בשכמל\"ו וחזן הכנסת אומר להם הריעו הכהנים בני אהרן הריעו וכו' וכן בכל ברכה וברכה באחת אומר תקעו ובאחת אומר הריעו עד שגומר את כולן","וכך הנהיג ר' חלפתא בצפורי ור' חנניה בן תרדיון בסיכני וכשבא דבר לפני חכמים אמרו לא היו נוהגין כן אלא בשערי מזרח ובהר הבית","ואית דאמרי כדתניא אומר לפניהן עשרים וארבע ברכות שמונה עשרה שבכל יום ומוסיף עליהן עוד שש ואותן שש היכן אומרן בין גואל לרופא חולי ומאריך בגאולה והן עונין אחריו אמן על כל ברכה וברכה וכך היו נוהגין בגבולין","אבל במקדש היו אומרים ברוך ה' אלהי ישראל מן העולם ועד העולם ברוך גואל ישראל ולא היו עונין אחריו אמן וכל כך למה לפי שאין עונין אמן במקדש ומנין שאין עונין אמן במקדש שנאמר קומו ברכו את ה' אלהיכם מן העולם ועד העולם ויברכו (את) שם כבודך ומרומם על כל ברכה ותהלה על כל ברכה וברכה תן לו תהלה:","תנו רבנן על הראשונות הוא אומר ברוך ה' אלהי ישראל מן העולם ועד העולם ברוך גואל ישראל והן עונין אחריו ברוך שם כבוד מלכותו לעולם ועד וחזן הכנסת אומר תקעו כהנים תקעו וחוזר ואומר מי שענה את אברהם בהר המוריה הוא יענה אתכם וישמע בקול צעקתכם היום הזה (והן תוקעין ומריעין ותוקעין) ועל השניה הוא אומר ברוך ה' אלהי ישראל מן העולם ועד העולם ברוך זוכר הנשכחות והן עונין אחריו ברוך שם כבוד מלכותו לעולם ועד","וחזן הכנסת אומר הריעו בני אהרן הריעו ואומר מי שענה את אבותינו על ים סוף הוא יענה אתכם וישמע בקול צעקתכם היום הזה והם מריעין ותוקעין ומריעין וכן בכל ברכה וברכה באחת אומר תקעו ובאחת אומר הריעו עד שיגמור את הברכות כולן וכך הנהיג ר' חלפתא בצפורי ור' חנניה בן תרדיון בסיכני וכשבא דבר אצל חכמים אמרו לא היו נוהגין כן אלא בשערי מזרח ובהר הבית:","ר' יהודה אומר לא היה צריך לומר זכרונות כו': א\"ר אדא דמן יפו מאי טעמא דר' יהודה לפי שאין אומרים זכרונות ושופרות"],[[0,"היינו מטופל ואין לו היינו ביתו ריקן","היינו כמו (איזהו):"],[0,"ביתו ריקם מן העבירה","שאין חמס וגזל בביתו:"],[0,"ופרקו נאה","אפילו כשעמד על בחרותו היה נאה בלי שם רע:"],[1,"זה המעמיד חזן שאינו הגון לפני התיבה","רשע שהקב\"ה שונא אותו יותר מכולן והוא נותן בקולו לפניו:"],[2,"הוא אומר לפניהן","אותו הזקן הרגיל ומאריך בגאולה כדקתני מתני':"],[2,"שביעית לארוכה","שביעית לאותה ברכה שהתחיל להאריך בה ואותה אינה מן התוספת אלא מי\"ח הברכות היא כדתניא בגואל ישראל הוא מאריך:"],[5,"בד\"א","דהן עונין אחריו אמן בגבולין:"],[5,"אבל במקדש","אומר אותו הזקן לאחר הפרשיות מי שענה את אברהם הוא יענה אתכם וישמע קול צעקתכם ביום הזה בא\"י אלהי ישראל מן העולם ועד העולם ברוך גואל ישראל והן עונים אחריו בשכמל\"ו וכן בכל ברכות שבמקדש:"],[5,"לפי שאין עונין אמן במקדש","כדיליף לקמן מקרא:"],[5,"מניין שאין עונין אמן במקדש","דכתיב בתפלת עזרא בבית שני קומו וברכו את ה' אלהיכם והיינו ברוך ה' אלהי ישראל כו':"],[6,"ויברכו שם כבודך","היינו שעונין אחריו בשכמל\"ו כך הוא הפסוק ויברכו שם כבודך ומרומם על כל ברכה ותהלה: ה\"ג יכול על כל הברכות כולן תהלה אחת ת\"ל על כל ברכה על כל ברכה תן לו תהלה:"],[6,"","ה\"ג יכול על כל הברכות כולן תהלה אחת ת\"ל על כל ברכה על כל ברכה תן לו תהלה:"],[7,"חזן הכנסת","לא אותו זקן ניהו וחוזר חזן הכנסת ואומר להן מי שענה כו' אע\"פ שאמרו אותו זקן:"],[7,"כשמריעין","תחלה הוא אומר להן הריעו בני אהרן וכשתוקעין תחלה הוא אומר להן תקעו בני אהרן כו':"],[9,"וכך הנהיג","כל מנהג זה רבי חלפתא בצפורי:"],[9,"לא היו נוהגין כך","שיהו עונין אחריו ברוך שם כבוד מלכותו לעולם ועד אלא עונין אמן בגבולין:"],[10,"ואית דאמרי כדתני' כו'","כלומר ואיכא דמתני הכי:"],[13,"וכן הנהיג","מנהג זה אמקדש קאי:"]],[[2,"","ברוך מרחם על הארץ. דגבי דוד ושלמה שייך לומר על הארץ דדוד ושלמה התפללו על הארץ דוד גבי מלאך המות בגורן ארונה ושלמה בתפלה דקאמר רעב כי יהיה בארץ ועוד יש לומר משום דאתקין בהמ\"ק בארץ ולא קשיא הא דחשיב יונה מקמי דוד אע\"ג שהיה קודם משום דבעי למיחתם על הארץ כדמפרש בגמרא:"],[2,"","מאי שביעית שביעית לארוכה. פירוש שמתחילין להאריך ולומר בקשות ותחינות בתוך ברכה של גואל ישראל אבל מ\"מ אינה בכלל הנוספות בימי תענית דלא היו מוסיפין רק ששה ועל כל הברכות יש טעם על מה הם חותמות בכך הראשונה של גואל אינה מן המנין ובה אומרים מי שענה לאברהם לפ' שהיה ראשון לנצולין שניצול מנמרוד ובשניה שהיא ראשונה מן הששה הנוספות אמר מי שענה לאבותנו על ים סוף וחותם ברוך זוכר הברית ולפיכך אומרה בזכרונות לפי שהיו במצרים ונתייאשו מן הגאולה ועליו נאמר (שמות ו׳:ה׳-ו׳) ואזכור את בריתי וכן בשלישית שהיא שניה מן המנין שומע תרועה ביהושע שנענה ביריחו דהיינו בעוד ישראל בגלגל בשופרות היה אומר מי שענה ליהושע בגלגל לפי שנענה בשופרות על הרביעית והיא שלישית מן המנין מי שענה לשמואל וכו' ובשמואל כתיב צעקה ותפלה וגבי אליהו כתיב תפלה ענני ה' ענני ואמרינן בגמרא דצעקה גבי שמואל ותפלה גבי אליהו וי\"א תפלה גבי שמואל וצעקה גבי אליהו דהא דכתיב ענני גבי אליהו הוא צעקה שמואל במצפה מעין אל ה' בצרתה לי לאליהו בהר הכרמל כנגד אשא עיני אל ההרים וכן כולם:"]]],[["אלא בראש השנה וביובלות ובשעת מלחמה:","על הראשונה הוא אומר מי שענה את אברהם כו': תנא יש מחליפין צעקה לאליהו ותפלה לשמואל בשלמא גבי שמואל כתיב ביה תפלה וכתיב ביה צעקה","אלא גבי אליהו תפלה כתיב צעקה לא כתיב (מלכים א יח, לז) ענני ה' ענני לשון צעקה היא:","על הששית הוא אומר מי שענה את יונה כו' על השביעית הוא אומר מי שענה את דוד כו': מכדי יונה בתר דוד ושלמה הוה מאי טעמא מקדים ליה ברישא משום דבעי למיחתם מרחם על הארץ תנא משום סומכוס אמרו ברוך משפיל הרמים:","שלש תעניות הראשונות אנשי משמר מתענין ולא משלימין כו': תנו רבנן מפני מה אמרו אנשי משמר מותרין לשתות יין בלילות אבל לא בימים שמא תכבד העבודה על אנשי בית אב ויבואו ויסייעו להם","מפני מה אמרו אנשי בית אב לא ביום ולא בלילה מפני שהן עסוקין תמיד בעבודה","מכאן אמרו כל כהן שמכיר משמרתו ומשמרת בית אב שלו ויודע שבתי אבותיו קבועין שם אסור לשתות יין כל אותו היום במכיר משמרתו ואין מכיר משמרת בית אב שלו ויודע שבתי אבותיו קבועין שם אסור לשתות יין כל אותה שבת","אינו מכיר משמרתו ומשמרת בית אב שלו ויודע שבתי אבותיו קבועין שם אסור לשתות יין כל השנה","רבי אומר אומר אני אסור לשתות יין לעולם אבל מה אעשה שתקנתו קלקלתו אמר אביי כמאן שתו האידנא כהני חמרא כרבי:","אנשי משמר ואנשי מעמד אסורים לספר ולכבס ובחמישי מותרין מפני כבוד השבת: מאי טעמא אמר רבה בר בר חנה אמר ר' יוחנן כדי שלא יכנסו למשמרתם כשהן מנוולין","ת\"ר מלך מסתפר בכל יום כהן גדול מערב שבת לערב שבת כהן הדיוט אחת לשלשים יום מלך מסתפר בכל יום מ\"ט אמר רבי אבא בר זבדא אמר קרא (ישעיהו לג, יז) מלך ביפיו תחזינה עיניך כהן גדול מע\"ש לערב שבת מ\"ט אמר רב שמואל בר יצחק הואיל ומשמרות מתחדשות","כהן הדיוט אחת לשלשים יום מנלן אתיא פרע פרע מנזיר כתיב הכא (יחזקאל מד, כ) וראשם לא יגלחו ופרע לא ישלחו וכתיב התם (במדבר ו, ה) קדוש יהיה גדל פרע שער ראשו מה להלן שלשים אף כאן שלשים","ונזיר גופיה מנלן אמר רב מתנה סתם נזירות שלשים יום מנלן אמר קרא יהיה בגימטריא תלתין הוי א\"ל רב פפא לאביי ודילמא ה\"ק רחמנא לא לירבו כלל אמר ליה אי הוה כתב לא ישלחו פרע כדקאמרת השתא דכתיב ופרע לא ישלחו פרע ליהוי שלוחי הוא דלא לישלחו","אי הכי אפילו האידנא נמי דומיא דשתויי יין מה שתויי יין בזמן ביאה הוא דאסור שלא בזמן ביאה שרי אף הכא נמי","והתניא רבי אומר אומר אני כהנים אסורין לשתות יין לעולם אבל מה אעשה שתקנתו קלקלתו ואמר אביי כמאן שתו האידנא כהני חמרא"],[[0,"אלא בראש השנה","כדאמרינן בר\"ה (דף טז.) אמרו לפני מלכיות וזכרונות וכו':"],[0,"וביובל","ביום הכפורים של יובל כדתנן התם (דף כו:) שוה היובל לר\"ה לתקיעה ולברכות כו':"],[0,"ובשעת מלחמה","דכתיב (במדבר י) וכי תבאו מלחמה בארצכם על הצר הצורר אתכם וגו' ולא ידעינן מנא איתפריש דאומר ברכות ופסוקי מלכיות זכרונות ושופרות בשעת מלחמה:"],[1,"צעקה לאליהו","על מי שענה את אליהו חותם שומע צעקה ובשמואל שומע תפלה דכתיב ביה תפלה (שמואל א ז׳:ה׳) קבצו את כל ישראל המצפתה ואתפלל בעדכם:"],[1,"צעקה","דכתיב (שם טו) ויחר לשמואל ויזעק אל ה' כל הלילה ואיכא למימר במצפה הוה ההיא צעקה דבתר פרשת קבצו כל ישראל המצפתה כתיב בפרשת נחמתי כי המלכתי את שאול וגו' כך שמעתי:"],[2,"גבי אליהו","במעשה דהר הכרמל כתיב תפלה דכתיב ענני ה' ענני דמשמע לשון בקשה ותפלה ולא לשון צעקה ומשני ענני ה' ענני לשון צעקה הוא כך שמעתי:"],[3,"יונה בתר דוד ושלמה","דהוה בימי אמציהו בסדר עולם:"],[3,"דבעי למחתם","בסוף כל ברכות ברוך מרחם על הארץ ולהכי בעי באותה חתימה דוד ושלמה שהן התפללו על ארץ ישראל כך שמעתי אי נמי משום דאינהו תקון בית המקדש דהוא עיקר הארץ כך שמעתי:"],[3,"ברוך משפיל הרמים","היו אומרים במקום ברוך מרחם שהכניעם במטר ששבו בתשובה:"],[6,"מכאן אמרו","מדקתני הכא דאפילו אנשי משמר שלא היו עובדין באותו היום כלל אפילו הכי אסורין לשתות יין:"],[6,"כהן","בזמן הזה:"],[6,"המכיר משמרתו","היודע מאיזו משמרת הוא מיהויריב או מידעיה או אחת מכ\"ד משמרות שיודע שמות אבותיו ואבות אבותיו עד יהויריב ויודע איזה יום ואיזה שבת היו עובדים:"],[6,"קבועין","שיודע ודאי שבית אב שלו עובד במקדש לפי שהרבה היו מבתי אבות הכהנים שלא הוקבעו שוב אמר לי רבי קבועין שלא נתחלל בית אב שלו להיות מגואל מן הכהונה ויודע שראוי בית אב שלו לעבוד:"],[6,"אסור לשתות יין כל אותו היום","ותו לא שמא יבנה בית המקדש ותכבד העבודה ויהיה זה צריך לעבוד:"],[6,"מכיר משמרתו","שיודע איזה שבת בשנה עובדין:"],[6,"ואינו יודע מאיזה בית אב","דעכשיו אינו מכיר באיזה יום בשבת עובדין ויודע שבתי אבותיו קבועין אסור כל אותה שבת מספיקא בכולהו גרסינן ויודע שבתי אבותיו קבועין הן דאם אינו יודע שבתי אבותיו קבועין לעבוד מותר הוא לשתות יין כל השנה ולא חיישינן שמא יבנה ושמא בית אב שלו יעבדו היום:"],[8,"רבי אומר אומר אני כהן אסור כו'","כלומר אי חיישינן לשמא יבנה יהא אסור לעולם אפי' המכיר משמרתו ומשמרת בית אבותיו דחיישינן שמא ישתנה סדר משמרות ושמא יעבדו כולם לחנוכת הבית בבת אחת ונמצא זה צריך לעבוד אבל מה אעשה שתקנתו קלקלתו דהוי כמה שנים שלא חזרה בירה וקלקלה זו תקנתו לשתות יין בהדיא ולשמא יבנה לא חיישינן:"],[9,"כשהן מנוולין","שלא יהו סומכין על יום אחד מימי שבת ואין מסתפרין בשבת שעברה:"],[10,"מסתפר בכל יום","מצוה:"],[10,"מערב שבת לערב שבת","ולא ישהה מלגלח יותר:"],[10,"ומשמרות מתחדשות","בכל שבת ושבת ומשמרה שלא ראתהו עד עכשיו ובאה לראותו הדבר נאה שתראהו ביופיו:"],[12,"לא לירבו כלל","אלא יסתפרו בכל יום דהכי משמע ופרע דהיינו שלשים לא ישלחו אלא יגלחו:"],[12,"שלוחי לא משלחי","הכי משמע פרע שגדלו אינן רשאין לגדל עוד:"],[13,"אי הכי","כיון דמקרא מפקת לה האידנא נמי לא לישלחו ומשני כיין דומיא דיין דכתיב בסמוך להאי ופרע לא ישלחו ויין לא ישתו כל כהן:"],[13,"מה יין בזמן ביאה הוא דאסור","דכתיב (יחזקאל מד) בבואם אל החצר וגו' בזמן שבית המקדש קיים שבאין שם לעבוד:"],[13,"שלא בזמן ביאה","כגון האידנא שהבית חרב ולא זמן ביאה היא:"],[14,"והתניא רבי אומר אומר אני כו' ואמר אביי כו' מכלל דרבנן אסרי","דחיישינן לשמא יבנה ומצי נמי מייתי רישא דברייתא מפני מה אמרו אנשי משמר כו' ואייתי סיפא בלשון קצרה ודייק מינה מכלל דרבנן אסרי:"]],[[6,"","ויודע שבתי אבותיו קבועין לשם אסור לשתות יין וכו'. פירוש אסור לשתות יין חוץ לסעודתו אבל בסעודתו מותר דיין שבתוך הסעודה אינו משכר:"],[9,"","ובחמישי מותרין מפני כבוד השבת מאי טעמא. פי' מאי טעמא אין הכהנים מותרין להסתפר אלא דווקא בחמישי בשבת כדי שלא יכנסו למשמר כשהן מנוולין פי' ולא ימתינו עד יום אחד מימי השבוע הבא ויסתפרו קודם שיכנסו למשמרת דאם לא יסתפרו קודם יהיו אסורין כל השבוע הבא עד יום החמישי ומתוך זה שאסרו לספר כל השבוע הבא יסתפרו קודם שיכנסו למשמרתם ולא יהיו מנוולים:"],[10,"","כהן גדול מסתפר מע\"ש לערב שבת וכהן הדיוט אחד לשלשים יום כהן גדול מסתפר מע\"ש לערב שבת וכהן הדיוט אחד לשלשים יום. פירוש שאינו יכול להשהות יותר והאי דקאמר בסמוך השתא דכתיב פרע לא ישלחו פרע ליהוי פי' פרע ליהוי עד שלשים יום אם ירצה:"],[12,"","לא לירבו כלל. פירוש ואפילו עד ל' יום וקשה דאם כן ג\"ש דפרע למה לי וי\"ל דשמא ר\"ל לא לירבו עד ל' יום אלא יגלח בכ\"ט:"],[12,"","שלוחי לא משלחו. יותר משלשים יום:"]]],[["כרבי מכלל דרבנן אסרי מ\"ט מהרה יבנה בית המקדש ובעינן כהן הראוי לעבודה וליכא הכא אפשר דמספר ועייל","אי הכי שתוי יין נמי אפשר דגני פורתא ועייל כדרמי בר אבא דאמר רמי בר אבא דרך מיל ושינה כל שהוא מפיגין את היין לאו מי איתמר עלה אמר רב נחמן אמר רבה בר אבוה לא שנו אלא כששתה שיעור רביעית אבל שתה יותר מרביעית כל שכן שדרך מטרידתו ושינה משכרתו","רב אשי אמר שתויי יין דמחלי עבודה גזרו בהו רבנן פרועי ראש דלא מחלי עבודה לא גזרו בהו רבנן","מיתיבי ואלו שהן במיתה שתויי יין ופרועי ראש בשלמא שתויי יין בהדיא כתיב בהו (ויקרא י, ט) יין ושכר אל תשת אלא פרועי ראש מנלן","דכתיב (יחזקאל מד, כ) וראשם לא יגלחו ופרע לא ישלחו וכתיב בתריה ויין לא ישתו כל כהן בבאם אל החצר הפנימית ואיתקוש פרועי ראש לשתויי יין מה שתויי יין במיתה אף פרועי ראש במיתה","ומינה אי מה שתויי יין דמחלי עבודה אף פרועי ראש דמחלי עבודה (לא כי איתקוש למיתה הוא דאיתקוש אבל לאחולי עבודה לא איתקוש)","א\"ל רבינא לרב אשי הא מקמי דאתא יחזקאל מאן אמרה א\"ל וליטעמיך הא דאמר רב חסדא דבר זה מתורת משה לא למדנו ומדברי קבלה למדנו (יחזקאל מד, ט) כל בן נכר ערל לב וערל בשר לא יבוא אל מקדשי (לשרתני) הא מקמי דאתא יחזקאל מאן אמרה","אלא גמרא גמיר לה ואתא יחזקאל ואסמכה אקרא הכא נמי גמרא גמיר לה ואתא יחזקאל ואסמכה אקרא (כי גמירי הלכה למיתה לאחולי עבודה לא גמירי):","כל הכתוב במגילת תענית דלא למיספד לפניו אסור לאחריו מותר: תנו רבנן אלין יומיא דלא להתענאה בהון ומקצתהון דלא למיספד בהון מריש ירחא דניסן ועד תמניא ביה איתוקם תמידא דלא למיספד בהון מתמניא ביה עד סוף מועדא איתותב חגא דשבועיא דלא למיספד בהון","אמר מר מריש ירחא דניסן עד תמניא ביה איתוקם תמידא דלא למיספד למה לי מריש ירחא לימא מתרי בניסן ור\"ח גופיה יו\"ט הוא ואסור אמר רב לא נצרכה אלא לאסור יום שלפניו","ושלפניו נמי תיפוק ליה דהוה ליה יום שלפני ראש חדש ר\"ח דאורייתא הוא ודאוריית' לא בעי חיזוק","דתניא הימים האלה הכתובין במגילת תענית לפניהם ולאחריהם אסורין שבתות וימים טובים הן אסורין לפניהן ולאחריהן מותרין ומה הפרש בין זה לזה הללו דברי תורה ודברי תורה אין צריכין חיזוק הללו דברי סופרים ודברי סופרים צריכין חיזוק","אמר מר מתמניא ביה עד סוף מועדא איתותב חגא דשבועיא דלא למיספד למה לי עד סוף מועד לימא עד המועד ומועד גופיה יום טוב הוא ואסור אמר רב פפא כדאמר רב לא נצרכא"],[[0,"כרבי הא רבנן מיסר אסרי","אפילו שלא בזמן ביאה:"],[0,"ומשני מאי טעמא כו' והכא כו'","מאי טעמא תירוצא הוא כלומר דטעמא מאי גזור רבנן ביין שמא יבנה כו' אבל גבי פרועי ראש לא גזרו דאפשר דמסתפר מיד והדר עייל לבית המקדש לעבודה:"],[1,"","דרך מיל ושינה כל שהוא כו':"],[1,"ושינה משכרתו","והאי שינוי איכא בהך מיהא:"],[2,"שתוי יין דמחלי עבודה","דכתיב יין ושכר אל תשת וסמיך ליה ולהבדיל בין הקדש ובין החול בין עבודה קדושה למחולל' דאי עביד עבודה שתוי יין חילל:"],[2,"פרועי ראש","דלא כתיב ביה חלל דלא נראה חילול:"],[3,"ואילו שבמיתה","בידי שמים במסכת סנהדרין באלו הן הנשרפין (דף פג.):"],[3,"שתויי יין","במיתה דכתיב יין ושכר אל תשת בבואכם אל אהל מועד ולא תמותו דהיינו מיתה בידי שמים מדלא כתיב יומת ואמר בשלמא כו':"],[5,"ה\"ג ומינה מה שתויי יין מחלי עבודה אף פרועי ראש מחלי עבודה","קשיא לא גרס:"],[5,"מחלי עבודה","חולין היא כל עבודתו שעבד:"],[5,"אף פרועי ראש","עבודתם מחוללת דלכל מילי איתקוש ותיובתא דרב אשי דאמר פרועי ראש לא מחלי עבודה:"],[6,"דרב חסדא","בפרק שני דזבחים וקא בעי התם כהן ערל שמתו אחיו מחמת מילה מהו ואמר רב חסדא כו' ערל לב וערל בשר:"],[7,"הלכתא גמירי לה","מסיני:"],[7,"כי גמירי הלכה למיתה","לאחולי עבודה לא גמירי:"],[8,"דלא להתענאה בהון","שכולן אסורין בתענית ומקצתהון שיש בהן קצת חמורין כ\"כ שבהספד נמי אסורין:"],[8,"מריש ירחא דניסן עד תמניא ביה","דכל שמונה ימים נשאו ונתנו בדבר עד שנצחו את הצדוקין ועשו אותם יום טוב ודבר זה מפורש במנחות בפרק רבי ישמעאל ובמגילת תענית המצויה אצלנו:"],[8,"מריש ירחא דניסן ועד תמניא ביה איתוקם תמידא דלא למיספד","שהיו הצדוקים אומרים יחיד מתנדב ומביא תמיד מאי דרוש את הכבש אחד תעשה בבקר ואת הכבש השני תעשה בין הערביים מאי אהדרו להו את קרבני לחמי לאשי תשמרו להקריב לשון רבים הוא שיהו כולן באין מתרומת הלשכה:"],[8,"איתוקם תמידא ואיתותב חגא דשבועיא","בענינים רבים חלקו בייתוסין עם חכמים ומפורשין במנחות ובמגילת תענית [פ\"א] וה\"ג התם בפ' ר' ישמעאל (מנחות ס\"ה.) ת\"ר אלין יומיא דלא להתענאה בהון ומקצתהון דלא למיספד בהון מריש ירחא דניסן עד תמניא ביה איתוקם תמידא דלא למיספד ומתמניא ביה עד סוף מועדא איתותב חגא דשבועיא דלא למיספד:"],[8,"איתוקם תמידא דלא למיספד","גרסינן ולא גרסינן להתענאה כדמוכח בסמוך דקתני לא נצרכה אלא לאסור את שלפניו ואי גרסינן להתענאה א\"כ היינו רבי יוסי דאמר לפניו אסור והא ליכא למימר דרבי יוסי היא דקא פריך כמאן כרבי יוסי בתמיהה מכלל דכרבנן פסיקא ליה:"],[8,"מתמניא ביה כו' עד דלא למיספד","שהיו בייתוסים אומרים עצרת אחר השבת הוא שהעומר מתחיל אחד בשבת שנאמר וספרתם לכם ממחרת השבת ניטפל להן רבן יוחנן בן זכאי וא\"ל שוטים מניין לכם ולא היה אדם שהחזירו דבר חוץ מזקן אחד שהיה מפטפט כנגדו ואמר משה רבינו אוהב ישראל היה ויודע שעצרת יום אחד הוא עמד ותיקנה אחר שבת כדי שיהיו מתענגים שני ימים וכו' ודחו אותן והלכו להן בייתוסים מכח הפסוקין על כרחן וחזרו בהן (ע\"כ הג'):"],[8,"חגא דשבועיא דלא למיספד","במגילת תענית [פ\"א] מפרש מאי איתוקם:"],[9,"ור\"ח יו\"ט הוא","דכתיב קרא עלי מועד והוי ראש חודש אב בהאי מסכתא לקמן(כט.):"],[12,"עד סוף מועדא","פסח:"]],[[0,"","מכלל דרבנן אסרי. פי' מכלל דרבנן אסרי לשתות יין משום דשמא יבנה ביהמ\"ק ובעינן כהן ראוי לעבוד וליכא ומשני אפשר דמספר ועייל:"],[0,"","בעינן כהנים הראויים לעבודה וליכא. וא\"ת והלא בלא יין נמי אסורין בעבודה דטמאי מתים נינהו וצריכין הזאה ג' [וז'] ואמאי אסרי להו יין וי\"ל דמ\"מ מותרין בעבודת צבור דטומאה הותרה בצבור:"],[2,"","שתויי יין דמחללי עבודה. פי' דכתיב יין ושכר אל תשת וגו' ולהבדיל בין הקודש ובין החול:"],[2,"","פרועי ראש דלא מחלי עבודה. פי' דלא כתיב בסמוך ולהבדיל וגו': (דבר תורה):"],[6,"","דבר זה מתורת משה לא למדנו. וא\"ת נילף מק\"ו ומה בעל מום שמותר באכילת קדשים כדדרשינן במסכת קדושין פרק האיש מקדש (קידושין דף נג.) וכל מנחת מחבת וכל מרחשת לכהנים יהיה איש כאחיו ואפ\"ה בעל מום אסור לעבוד עבודה ערל שאסור באכילת קדשים דדרשינן פרק הערל (יבמות דף ע.) בג\"ש תושב ושכיר מפסח דערל אסור בו אינו דין שאסור לעבודה וי\"ל דחלל יוכיח שאינו אוכל בקדשים ואפ\"ה כשר לעבודה וכדאמר פרק האומר (קדושין דף סו:) מדכתיב ברך ה' חילו ופועל ידיו תרצה דמשמע אפילו [חולין שבו] הוא רוצה בעבודתו אי נמי מבעל מום לא מצי יליף דאיכא למיפרך מה לבעל מום שכן עשו בו קריבין כמקריבים שכל הקריבין פסולים שהם בעלי מומים כמו המקריב תאמר בערל שלא עשה בו קריבין כמקריבין דמה ערלות שייך בבהמה:"],[8,"","מריש ירחא דניסן ועד תמניא (דהא) [ביה] איתוקם תמידא. פי' כדמפרש במגילת תענית [פ\"א] שהיו הבייתוסים אומרים שיחיד מתנדב תמיד משום דכתיב תעשה את הכבש אחד תעשה בבקר תעשה משמע יחיד והדרי להו את קרבני לחמי לאשי תשמרו להקריב לשון רבים:"]]],[["אלא לאסור יום שלפניו ה\"נ לא נצרכה אלא לאסור יום שלאחריו כמאן כרבי יוסי דאמר בין לפניו בין לאחריו אסור אי הכי בעשרים ותשעה נמי מאי איריא דהוי יומא דמקמי יומא דמיתוקם תמידא תיפוק ליה דה\"ל יומא דבתר עשרין ותמניא ביה","דתניא בעשרים ותמני' ביה אתת בשורתא טבתא ליהודאי דלא יעידון מן אורייתא שפעם אחת נגזרה גזירה על ישראל שלא יעסקו בתורה ושלא ימולו את בניהם ושיחללו שבתות מה עשה יהודה בן שמוע וחביריו הלכו ונטלו עצה ממטרוניתא אחת שכל גדולי רומי מצויין אצלה","אמרה להם עמדו והפגינו בלילה הלכו והפגינו בלילה אמרו אי שמים לא אחים אנחנו לא בני אב אחד אנחנו לא בני אם אחת אנחנו מה נשתנינו מכל אומה ולשון שאתם גוזרין עלינו גזירות רעות ובטלום ואותו היום עשאוהו יו\"ט","אמר אביי לא נצרכה אלא לחדש מעובר","רב אשי אמר אפילו תימא לחדש חסר כל שלאחריו בתענית אסור בהספד מותר וזה הואיל ומוטל בין שני ימים טובים עשאוהו כיו\"ט עצמו ואפילו בהספד נמי אסור","אמר מר מתמניא ביה ועד סוף מועדא איתותב חגא דשבועיא דלא למיספד למה לי למימר מתמניא ביה לימא מתשעה ביה ותמניא גופיה אסור דה\"ל יומא דאיתוקם ביה תמידא","כיון דאילו מקלע (ליה) מילתא ובטליניה לשבעה תמניא גופיה אסור דה\"ל יומא קמא דאיתותב ביה חגא דשבועיא","השתא דאתית להכי עשרים ותשעה נמי כיון דאילו מיקלע מילתא ובטליניה לעשרים ותמניא עשרין ותשעה גופיה אסור דה\"ל יומא דמקמי יומא דאיתוקם תמידא","איתמר ר' חייא בר אסי אמר רב הלכה כר' יוסי ושמואל אמר הלכה כר' מאיר","ומי אמר שמואל הכי והתניא רשב\"ג אומר ומה תלמוד לומר בהון בהון שתי פעמים לומר לך שהן אסורין לפניהן ולאחריהן מותרין ואמר שמואל הלכה כרבן שמעון בן גמליאל","מעיקרא סבר כיון דליכא תנא דמיקל כרבי מאיר אמר הלכה כרבי מאיר כיון דשמעיה לרבן שמעון דמיקל טפי אמר הלכה כרבן שמעון בן גמליאל","וכן אמר באלי אמר רבי חייא בר אבא א\"ר יוחנן הלכה כרבי יוסי א\"ל רבי חייא לבאלי אסברא לך כי אמר ר' יוחנן הלכה כרבי יוסי אדלא להתענאה","ומי אמר רבי יוחנן הכי והאמר ר' יוחנן הלכה כסתם משנה ותנן אע\"פ שאמרו מקדימין ולא מאחרין"],[[0,"לאסור את שלפניו","להכי נקט מריש ירחא דניסן לאסור את יום שלפני ר\"ח בתענית כדתניא בסמוך לפניהן אסורין דאי משום ר\"ח לא היה נאסר כדמפרש דדברי תורה אין צריכין חיזוק:"],[0,"כמאן כר' יוסי","דמתני' דאמר אף לאחריו בתמיהה ושבקת רבנן אי הכי דאליבא דר' יוסי מוקמת לה למגילת תענית כ\"ט באדר נמי דקתרצת לעיל דאדהכי נקט ריש ירחא דניסן דהיינו יום שלשים דאדר הסמוך לניסן לעולם חסר מכ\"ט יום הוא משום דקא בעי למיסר יום כ\"ט תיפוק ליה דבלאו הכי הוי אסור יום כ\"ט דה\"ל יום דבתר כ\"ח שהוא י\"ט כו' ואסור יום שלאחריו כר' יוסי ואמאי נקט ריש ירחא לאסור את שלפניו:"],[1,"דלא יעידון","שלא יהו צריכין ליבטל מתלמוד תורה שנגזר עליהן שלא יעסקו בתורה:"],[2,"הפגינו","צעקו כך מתרגמינן בתהלים כל לשון שועה וצעקה לשון פגינה:"],[2,"אי שמים","גרסינן אהה ה' להקב\"ה היו צועקים על אותם שגזרו עליהם גזרות קשות והיו אומרים להם לפני הקב\"ה וכי לא אחיכם וכו':"],[3,"לא נצרכה אלא לחדש מעובר","בשנה מעוברת שיש בה שני אדר והאחד חסר דהשתא כי הוה אדר שני מלא הוה יום שלשים לפני ר\"ח ניסן א\"נ דעברוה לאדר כגון שלא נראה החדש יום ל' דמשום יו\"ט דכ\"ח לא מיתסר אלא כ\"ט:"],[4,"רבא אמר אפילו תימא חדש חסר","ואהכי נקט מריש ירחא דאי הוה אסר ליה ליום כ\"ט משום בתר כ\"ח לא הוה אסר ליה אלא בתענית לחודיה:"],[4,"דכל שלאחריו כו'","כלומר כל שאסור משום אחר י\"ט בתענית הוא דאסור הא בהספד מותר ואהכי נקט מריש ירחא דלהוי האי כ\"ט דנקט מוטל בין שני ימים משום דאי מיתסר משום דלפני יו\"ט אימור לא איתסר בהספד דהאי דנקט כל שלאחריו כו' לאו משום דלפניו נמי אסור בהספד אלא איידי דפריך דליתסר יום כ\"ט משום בתר כ\"ח הוא דמיהדר ליה כל שלאחריו כו':"],[5,"לימא מתשעה ותמניא גופיה","י\"ט הוא דהא הוה ליה מהנך ימים טובים דאיתוקם בהו תמידא כדכתיב ביה מריש ירחא עד תמניא:"],[6,"ה\"ג דאי איקלע מילתא ובטליני' לשבעה תמניא גופיה אסור דהוה ליה יומא דאיתותב חגי דשבועיא","דאי איקלע מילתא שאם נגזר גזירה וצריכין להתענות תוך אלו ימים טובים דתמיד ובטלו אותן להתענות בכולן שאין לבטלה לחצאין:"],[6,"אכתי יומא תמניא אסור משום חגא דשבועיא","ואי קשיא אכתי לימא תשעה ואפילו אם אירע מילתא דבטלי אכתי הוא אסור תמניא גופיה משום קמא יומא דחג שבועיא דהוה יום שלפניו לאו פירכא הוא דהא יו\"ט גופיה בטיל ואנא ליקום וליגזור קמיה יומא דאיתותב חגא דשבועיא וכה\"ג מתרץ לקמן ביום טוריינוס:"],[7,"כ\"ט נמי","דתרצת לה לעיל לא נצרכה כו' להכי נקט בריש ירחא דאי מיקלע כו':"],[8,"כרבי יוסי","דאמר בין לפניו בין לאחריו אסור:"],[8,"כר\"מ","סתם מתניתין דקתני לאחריו מותר:"],[9,"מה ת\"ל בהון בהון","דלא להתענאה בהון ומקצתהון דלא למספד בהון וקא דריש לה כדדייק לקמן בהון משמע מיעוט:"],[9,"","ואמר שמואל גרס:"],[9,"הלכה כרבן שמעון","דמדרבנן נינהו ולא מחמרינן כולי האי:"],[11,"באלי","שם חכם:"],[11,"ה\"ג כי אמר רבי יוחנן הלכה אדלא להתענאה","דימים הכתובים במגילת תענית דלא להתענאה לפניהן אסורים ולאחריו מותרין כרבי יוסי ולא כר\"מ דאמר אף לפניהם מותר אבל אדלא למספד דאין הלכה כרבי יוסי [דאמר] לפניו ולאחריו אסור אלא כר\"מ דאמר לפניו אסור ולאחריו מותר:"],[12,"ומי א\"ר יוחנן הכי","דלפניו מיהא אסור כרבי יוסי:"],[12,"מקדימין","שקראו קודם זמנה:"]],[[2,"","הלכו והפגינו. הפיגו לשון נהי וצעקה. אי שמים גרסינן פירוש שמים להקב\"ה היו צועקין למה יאמרו הגוים איה אלהיכם ולהם אמרו וכי לאו אחיכם אנחנו וכו':"],[3,"","לא נצרכה אלא לחדש מעובר. פירוש דעברוה לאדר שלא נראה הלבנה עד יום ל' והוי ר\"ח ניסן יום ל\"א פירוש וא\"כ האי כ\"ט לא מצינו לאוסרו משום יום שלפני ר\"ח ניסן דיום ל' מפסיק בינתים משום הכי איצטריך לאוסרו משום יום שלאחר עשרים ותמניא:"],[7,"","דאילו אי איקלע וכו'. שום גזרה מריש ירחא וכו' תמניא גופיה אסור דה\"ל וכו' והקשה הקונטרס אכתי לימא תשעה ואפילו אי מיקלע שום גזרה ובטלינא לז' ימים וכו' אכתי אסור תמניא גופיה משום דהוי יומא דמקמי יומא דאיתותב חגא דשבועיא ותירץ הקונטרס הא לאו פירכא דהא מיו\"ט גופיה דתמיד מבטלינן ליה ואנא ניקום ונגזור משום קמי יומא דאיתותב חגא דשבועיא וכי האי מתרצינן לקמן ביום טוריינוס:"],[8,"","רב אמר הלכה כר' יוסי דאמר לפניו אסור אבל לאחריו מותר. וא\"ת כיון דאמר הלכה כר' יוסי היאך אנו מתענין לפני הפורים דאי משום דבטלה מגילת תענית מ\"מ אחנוכה ואפורים לא בטלו וי\"ל דהא דאמר חנוכה ופורים לא בטלו ר\"ל הדינין שלהם לעשותן י\"ט ודלא להתענאה בהון אבל בדינים דלפניהם בטלו עוד י\"ל דכיון דיום שלפני הפורים שנתבטל מיו\"ט דידהו שהיו רגילין לעשות בהן ונתבטלו יו\"ט שלהם ה\"נ יש לנו לומר שיבטלו משום טעם לפני הפורים דה\"נ אמרינן בסמוך גבי יום שלפני נקנור וכו' וכן גבי יו\"ט טוריינוס דכיון דבטלו מיום שלהם לא יאסרו משום יו\"ט הבא אחריהם דאסורים משום יום שלפניהם כמו כן ה\"נ דכיון דיום שלפני הפורים נתבטל משום עצמו ומותר להתענות לא יאסר משום יום שלפני הפורים:"]]],[["מותרין בהספד ותענית אימת אילימא בני חמיסר וקא קרו ליה בארביסר ומי שרי","והכתיב במגילת תענית יום ארבעה עשר בו ויום חמשה עשר בו יומי פוריא אינון דלא למיספד בהון ואמר רבא לא נצרכא אלא לאסור את של זה בזה ואת של זה בזה","ואלא בני ארביסר וקא קרי ליה בתליסר יום ניקנור הוא ואלא בני ארביסר וקא קרי ליה בתריסר יום טוריינוס הוא","אלא לאו דקא קרו ליה בחדיסר וקתני מותר בהספד ובתענית","לא בני ארבעה עשר וקא קרו ליה בתריסר ודקאמרת יום טריינוס הוא יום טריינוס גופיה בטולי בטלוהו הואיל ונהרגו בו שמעיה ואחיה אחיו כי הא דרב נחמן גזר תעניתא בתריסר אמרו ליה רבנן יום טוריינוס הוא אמר להו יום טוריינוס גופיה בטולי בטלוהו הואיל ונהרגו בו שמעיה ואחיה אחיו","ותיפוק ליה דהוה ליה יום שלפני ניקנור אמר רב אשי השתא איהו גופיה בטלוהו משום יום ניקנור ניקום ונגזר","מאי ניקנור ומאי טוריינוס דתניא ניקנור אחד מאפרכי יוונים היה ובכל יום ויום היה מניף ידו על יהודה וירושלים ואומר אימתי תפול בידי וארמסנה וכשגברה מלכות בית חשמונאי ונצחום קצצו בהונות ידיו ורגליו ותלאום בשערי ירושלים ואמרו פה שהיה מדבר בגאוה וידים שהיו מניפות על ירושלים תעשה בהם נקמה","מאי טוריינוס אמרו כשבקש טוריינוס להרוג את לולינוס ופפוס אחיו בלודקיא אמר להם אם מעמו של חנניה מישאל ועזריה אתם יבא אלהיכם ויציל אתכם מידי כדרך שהציל את חנניה מישאל ועזריה מיד נבוכדנצר אמרו לו חנניה מישאל ועזריה צדיקים גמורין היו וראויין היו ליעשות להם נס ונבוכדנצר מלך הגון היה וראוי ליעשות נס על ידו","ואותו רשע הדיוט הוא ואינו ראוי ליעשות נס על ידו ואנו נתחייבנו כליה למקום ואם אין אתה הורגנו הרבה הורגים יש לו למקום והרבה דובין ואריות יש לו למקום בעולמו שפוגעין בנו והורגין אותנו אלא לא מסרנו הקדוש ברוך הוא בידך אלא שעתיד ליפרע דמינו מידך","אעפ\"כ הרגן מיד אמרו לא זזו משם עד שבאו דיופלי מרומי ופצעו את מוחו בגיזרין:","אין גוזרין תענית על הצבור בתחלה בחמישי כו' אין גוזרין תענית בראשי חדשים כו': וכמה הויא התחלה רב אחא אמר שלש רבי אסי אמר אחת","אמר רב יהודה אמר רב זו דברי רבי מאיר שאמר משום רבן (שמעון בן) גמליאל אבל חכמים אומרים מתענה ומשלים דרש מר זוטרא משמיה דרב הונא הלכה מתענה ומשלים:","\u0001הדרן עלך סדר תעניות כיצד\u0002","מתני׳ \u0001סדר\u0002 תעניות אלו האמור ברביעה ראשונה אבל צמחים ששנו מתריעין עליהן מיד וכן שפסקו גשמים בין גשם לגשם ארבעים יום מתריעין עליהן מפני שהיא מכת בצורת","ירדו לצמחין אבל לא ירדו לאילן לאילן ולא לצמחין לזה ולזה אבל לא לבורות לשיחין ולמערות מתריעין עליהן מיד וכן עיר שלא ירדו עליה גשמים דכתיב (עמוס ד, ז) והמטרתי על עיר אחת ועל עיר אחת לא אמטיר חלקה אחת תמטר וגו'"],[[0,"מותרין בהספד ובתענית","בני ט\"ו קריאת המגילה דכרכין קודם זמנה כדמפרש התם בי\"א בי\"ב בי\"ג בי\"ד בט\"ו שהכפרים מקדימין ליום הכניסה מותרין אותן ימים שקראוה קודם זמנה בהספד ותענית:"],[0,"בני חמיסר","דהיינו כרכים המוקפין חומה מימות יהושע בן נון וקא קרי בארביסר כגון שהלך לכפר וקרא עמהן דפרוז בן יומו נקרא פרוז כדאמרינן במגילה (דף יט.):"],[0,"מי שרי","י\"ד אפילו לבני ט\"ו בהספד ותענית:"],[1,"ואמר רבא לא נצרכה","לכתוב במגילת תענית לגזור ההספד ותענית לבני י\"ד בי\"ד ולבני ט\"ו בט\"ו דהא קרא כתיב בהדיא להיות עושים את ימי הפורים האלה וגו':"],[1,"אלא לאסור את של זה בזה","כגון בני ט\"ו (דקרו) בי\"ד ובני י\"ד בט\"ו:"],[2,"בני ארביסר","נינהו כפרים ועיירות:"],[2,"וקא קרי בי\"ג","כגון שחל י\"ד בג' בשבת ומקדימין ליום הכניסה:"],[2,"יום ניקנור הוא","לקמן מפרש ואסור בהספד ותענית:"],[2,"אלא בני י\"ד וקרו בי\"ב","שחל י\"ד ברביעי בשבת והקדימו ליום הכניסה דהיינו י\"ב:"],[2,"טוריינוס","בסמוך מפרשה:"],[3,"בחדיסר","שחל להיות י\"ד באחד בשבת וכפרים מקדימין ליום הכניסה דהוו י\"א ושמע מינה דאע\"ג שהוא יום שלפני טוריינוס שרי בהספד ותענית:"],[4,"שמעיה ואחיה","חסידים היו ולא פירש מי הם דאותו שאכלו האריה עידו היה ולא שמעיה:"],[6,"איפרכי","דוכוס:"],[7,"לוליינוס ופפוס אחיו","צדיקים גמורים היו:"],[7,"בלודקי'","היא לוד והיינו דאמרינן בכל דוכתא (ב\"ב דף י:) הרוגי לוד אין כל בריה יכולה לעמוד במחיצתן בגן עדן ויש אומרין שנהרגו על בתו של מלך שנמצאת הרוגה ואמרו היהודים הרגוה וגזרו גזרה על שונאיהן של ישראל ועמדו אלו ופדו את ישראל ואמרו אנו הרגנוה והרג המלך לאלו בלבד:"],[7,"","אם מעמו כו':"],[8,"נתחייבנו הריגה","על חטא חייבי מיתות בית דין:"],[9,"דיופלין","שני שרים וכן מטרופולין של מלכים לשון שרים:"],[9,"בגזירין","מקלות כמו גזירי עצים:"],[10,"וכמה הויא התחלה","שאינו מפסיק לאחר מכאן:"],[10,"רבי אחא ורבי יוסי","אמוראי נינהו דלאו אורחא דתנאי לאשתעויי בגמרא כי האי גוונא:"],[10,"שלש","תעניות שני וחמישי ושני:"],[11,"זו דברי ר\"מ","ואדברי ר\"מ דמתני' קאי דקתני אין משלימין:"],[11,"מתענה ומשלים","עד חשיכה:"],[13,"מתני' סדר תעניות אלו","האמור בפ' ראשון (דף י.) שבתחילה יחידים מתענין סדר תעניות ואחר כך צבור הולכין ומתענין עד י\"ג אם לא נענו:"],[13,"ברביעה ראשונה","אם עבר זמן רביעה ראשונה של יורה ולא ירדו גשמים מתענין והולכין כסדר הזה:"],[13,"אבל צמחים ששנו","שנשתנו ממנהגן תחת חטה יצא חוח תחת שעורה באשה שלא היו חטים בשבולים או שינוי אחר מתריעין עליהן מיד אפילו בראשונות שכל חומר האחרונות נוהג בהן:"],[13,"בין גשם לגשם","בין רביעה ראשונה לשניה סימן בצורת היא:"],[14,"ירדו לצמחים אבל לא לאילן","מפרש בגמ':"],[14,"לבורות שיחין ומערות","בבבא בתרא מפרש מאי בור ומאי שיח ומאי מערה וכולן בית כניסיות מי גשמים לשתיה:"],[14,"שלא ירדו עליה גשמים דכתיב והמטרתי על עיר אחת ועל עיר אחת לא אמטיר וגו'","כגון שהמטיר בעיר זו ובחבירתה לא המטיר דקללה היא:"]],[[11,"","הלכה מתענה ומשלים. פי' הא דקפסק הלכה מתענה ומשלים אר\"ח קאי דאי אחנוכה ואפורים אינו יכול להתענות דיום משתה ושמחה כתיב:"],[13,"","מתריעין עליהם מיד ומתענין כמו כן. ואפילו בראשונות שחומר האחרונות נוהגין בו ואם תאמר הא דמתריעין משמע דמתריעין ומתענין אמאי צריך לפרש במתני' בסמוך אותה העיר מתענה ומתרעת כיון דסתם מתריעות משמע תרוייהו ויש לומר משום דבעי לאפלוגי ר' עקיבא בסיפא דקאמר מתריעות ולא מתענות:"]]],[["אותה העיר מתענה ומתרעת וכל סביבותיה מתענות ולא מתריעות רבי עקיבא אומר מתריעות ולא מתענות וכן עיר שיש בה דבר או מפולת אותה העיר מתענה ומתרעת וכל סביבותיה מתענות ולא מתריעות רבי עקיבא אומר מתריעות ולא מתענות","איזהו דבר עיר המוציאה חמש מאות רגלי ויצאו ממנה ג' מתים בג' ימים זה אחר זה הרי זה דבר פחות מכאן אין זה דבר","על אלו מתריעין בכל מקום על השדפון ועל הירקון ועל הארבה ועל החסיל ועל החיה רעה ועל החרב מתריעין עליה מפני שהיא מכה מהלכת","מעשה שירדו זקנים מירושלים לעריהם וגזרו תענית על שנראה כמלא פי תנור שדפון באשקלון ועוד גזרו תענית על שאכלו זאבים שני תינוקות בעבר הירדן רבי יוסי אומר לא על שאכלו אלא על שנראו:","על אלו מתריעין בשבת על עיר שהקיפוה נכרים או נהר ועל הספינה המיטרפת בים ר' יוסי אומר לעזרה ולא לצעקה שמעון התימני אומר אף על הדבר ולא הודו לו חכמים:","על כל צרה שלא תבא על הצבור מתריעין עליהן חוץ מרוב גשמים מעשה שאמרו לו לחוני המעגל התפלל שירדו גשמים אמר להם צאו והכניסו תנורי פסחים בשביל שלא ימוקו התפלל ולא ירדו גשמים","מה עשה עג עוגה ועמד בתוכה ואמר לפניו רבש\"ע בניך שמו פניהם עלי שאני כבן בית לפניך נשבע אני בשמך הגדול שאיני זז מכאן עד שתרחם על בניך התחילו גשמים מנטפין אמר לא כך שאלתי אלא גשמי בורות שיחין ומערות התחילו לירד בזעף אמר לא כך שאלתי אלא גשמי רצון ברכה ונדבה","ירדו כתיקנן עד שיצאו ישראל מירושלים להר הבית מפני הגשמים באו ואמרו לו כשם שהתפללת עליהם שירדו כך התפלל שילכו להן אמר להם צאו וראו אם נמחית אבן הטועין","שלח לו שמעון בן שטח אלמלא חוני אתה גוזרני עליך נידוי אבל מה אעשה לך שאתה מתחטא לפני המקום ועושה לך רצונך כבן שהוא מתחטא על אביו ועושה לו רצונו ועליך הכתוב אומר (משלי כג, כה) ישמח אביך ואמך ותגל יולדתך:","(מתני') היו מתענין וירדו להם גשמים קודם הנץ החמה לא ישלימו לאחר הנץ החמה ישלימו ר\"א אומר קודם חצות לא ישלימו לאחר חצות ישלימו","מעשה שגזרו תענית בלוד וירדו להם גשמים קודם חצות אמר להם ר' טרפון צאו ואכלו ושתו ועשו יו\"ט ויצאו ואכלו ושתו ועשו יום טוב ובאו בין הערבים וקראו הלל הגדול:","\u0001גמ׳\u0002 סדר תעניות האלו האמור ברביעה ראשונה ורמינהי רביעה ראשונה ושניה לשאול שלישית להתענות","אמר רב יהודה ה\"ק סדר תעניות האמור אימתי בזמן שיצאה רביעה ראשונה ושניה ושלישית ולא ירדו גשמים אבל ירדו גשמים ברביעה ראשונה וזרעו ולא צמחו אי נמי צמחו וחזרו ונשתנו מתריעין עליהן מיד","אמר רב נחמן דוקא נשתנו אבל יבשו לא פשיטא נשתנו תנן לא צריכא דאקון מהו דתימא אקנתא מילתא היא קמשמע לן:","וכן שפסקו גשמים בין גשם לגשם כו': מאי מכת בצורת אמר רב יהודה אמר רב מכה המביאה לידי בצורת אמר רב נחמן נהרא אנהרא"],[[0,"ה\"ג אותה העיר מתענה ומתרעת וכל סביבותיה מתענות ולא מתריעות","ולפיכך מתענות שאותה העיר שלא ירדו עליה גשמים תלך לקנות התבואה באותה העיר ויהיה בה רעב:"],[0,"או מפולת","שחומותיה והבתים נופלין ברוח:"],[2,"מתריעים בכ\"מ","אם יראו באספמיא מתריעין בבבל בבבל מתריעין באספמיא כדקתני טעמא בסיפא מפני שהיא מכה מהלכת אם במקום אחד היא מתריעין עליה כל השומעין כדי שלא תבא עליהן:"],[2,"שדפון","בתבואות:"],[2,"ירקון","חולי:"],[2,"חיה רעה","משכלת בני אדם:"],[2,"חרב","חיילות ההולכין להרוג ולהשחית בכל מקום:"],[3,"מלא תנור","מפרש בגמרא:"],[3,"לעריהם","בא\"י:"],[3,"באשקלון","בארץ פלשתים:"],[3,"ועל שאכלו זאבים","שהיא חיה רעה ומכה מהלכת היא:"],[3,"שנראו","ובאו בעיר:"],[4,"מתריעין","בעננו:"],[4,"המטורפת","מלשון טרף אבבא (ברכות דף כח.) ומלשון ביצה טרופה (עדיות פ\"ב מ\"ד) כו' כדמפרש בפרק שלמעלה (דף יד.):"],[4,"שמעון התימני","מתמנה היה:"],[5,"שלא תבא","לישנא מעליא נקט:"],[5,"מרוב גשמים","לאו כגון שירדה על עיר אחת ועל עיר אחת לא ירדה ששם ודאי שתיהן לקללה כדאמר רב יהודה (לעיל תענית ו:) תמטר מקום מטר שמקלקל תבואה אלא כבר ירדו וטורח הם לבני אדם אבל אינן מקלקלין תבואות וטעמא מפרש בגמרא למה אין מתריעין:"],[5,"תנורי פסחים","שהם בחצרות ושל חרס הן ומטלטלין אותן שלא ימוקו בגשמים:"],[6,"גשמי בורות","שיפוע גשמים למלאות בורות:"],[6,"ונדבות","רצון ועין יפה:"],[7,"אבן הטועין","אבן טועין היתה בירושלים וכל מי שאבדה לו אבידה כו' בבבא מציעא (דף כח:):"],[8,"לנדות","על כבוד הרב:"],[8,"מתחטא","פורפיי\"ש בלע\"ז ישמח אביך ואמך ותגל יולדתך:"],[9,"קודם הנץ החמה לא ישלימו","דאכתי לא חל עלייהו תענית כי נחתי גשמים:"],[9,"קודם חצות","דחצות זמן אכילה היא מחצות ואילך חל התענית כיון שלא סעדו בשעת סעודה:"],[10,"ועשו יו\"ט","מתוך שמחה:"],[10,"הלל הגדול","הודו לאלהי האלהים כי לעולם חסדו ומפני שנאמר בו נותן לחם לכל בשר כדאמרינן בשילהי פסחים (דף קיח.):"],[11,"גמ' רביעה ראשונה ושניה לשאול","שאף על פי שלא ירדו גשמים לא בראשונה ולא בשניה לא היו מתענין אלא שואלין וקשיין מתני' דקתני סדר תעניות אלו האמור ברביעה ראשונה וברייתא אהדדי:"],[12,"הכי קאמר כו'","וכגון רביעה ראשונה שניה ושלישית דכולי יורה קרי ליה רביעה כך שמעתי:"],[13,"דוקא נשתנו","דכי נשתנו ודאי הוא דמתריעין מיד דצריך להתפלל עליה שיחזיר ביופי כתקנן:"],[13,"אבל יבשו","לא צריך דמכאן ואילך לא יועיל והוא תפלת שוא אפילו יבשו כשהן חטין עדיין דקין אפילו הכי לא מתריעין:"],[13,"","הכי גרסינן פשיטא שנו תנן לא צריכא דאקון מהו דתימא כו':"],[13,"דאקון","שעלו בקנה שנתקנו מעט לאחר שנתייבשו:"],[13,"מהו דתימא אקנתא מילתא היא","דהואיל ונתקנו מעט אם יתפלל מועיל להם קא משמע לן רב נחמן דאקנא לאו מילתא ל\"א אבל יבשו לא דממילא חוזרין:"],[13,"לא צריכא דאקון","שעלו בקנה מהו דתימא אקנתא מילתא היא דכיון שעלו בקנה ועדיין לא בשלו כל צרכן ודאי אי לא מתריעין תו לא גדלי קמשמע לן דלאו מילתא היא דאף על גב דאקון אכתי גדלי טפי:"],[14,"נהרא אנהרא בצורתא","בשאין תבואה בעיר אחת ויש בעיירות אחרות ואפשר להביא מזה לזה דרך נהר בספינה:"]],[[13,"","לא צריכא דאקון. פי' לאחר שעלו בקנה נתייבשו מהו דתימא אקנתא מילתא היא פי' דהואיל ועלו בקנה ולא נתבשלו כל צורכם ליבעי התרעה קמ\"ל דלאו מילתא היא:"],[14,"","נהרא אנהרא בצורתא. פי' (. הכי) בשאין תבואה בעיר ויש הרבה בשאר עיירות ויכולין להביא מזו לזו היינו מקרי בצורת ולא מקרי רעב ומאחר שיכולין להביא ע\"י הנהר דליכא אלא טרחא זעירא ומהאי כלומר מדבר מועט כזה אין מתריעין מדינתא אמדינתא פירוש שצריך להוציא ממדינה למדינה אחרת ע\"י חמורים וסוסים ואז מתריעין דאי אפשר להביא בשפע כ\"כ כמו בספינות ל\"א נהרא אנהרא כלומר אם יבש הנהר זה וצריך להסב נהר אחר לכאן אי נמי צריך להמתין עד שיגדל הנהר האחר ויבא בכאן זה בצורת ולא מתריעין מדינתא אמדינתא אם יבשו כל הנהרות שבזו העיר וצריכין להביא מים מעיר אחרת כפנא וקשה דבמתני' משמע דאבצורת מתענין דקתני מתריעין עליהן מפני שהיא מכת בצורת ויש לומר דמכת בצורת דמתני' הוי כמו דכפנא כאשר פירשתי שתחת חטה יצא חוח ומשום הכי מתריעין אע\"ג דעדיין אינו רק בצורת הואיל וסופו רעב מתריעין אע\"ג דאכתי לא הוו כפנא אבל לעולם אין מתריעין על מכת בצורת אי לא מצי לבא לידי רעב ולהכי קאמר הכא דנהרא אנהרא דלא הוי אלא כי בצורתא ולא מתריעין:"]]],[["בצורתא מדינתא אמדינתא כפנא וא\"ר חנינא סאה בסלע ושכיחא בצורתא ארבעה ולא שכיחא כפנא","א\"ר יוחנן לא שנו אלא בזמן שהמעות בזול ופירות ביוקר אבל מעות ביוקר ופירות בזול מתריעין עליה מיד דא\"ר יוחנן נהירנא כד הוו קיימי ד' סאין בסלע והוו נפישי נפיחי כפן בטבריא מדלית איסר:","ירדו לצמחין אבל לא לאילן: בשלמא לצמחים ולא לאילן משכחת לה דאתא ניחא ולא אתיא רזיא לאילן ולא לצמחין דאתיא רזיא ולא אתיא ניחא","לזה ולזה אבל לא לבורות ולא לשיחין ומערות משכחת לה דאתיא רזיא וניחא מיהו טובא לא אתיא אלא הא דתניא ירדו לבורות לשיחין ולמערות אבל לא לזה ולזה היכי משכחת לה דאתיא בשפיכותא","ת\"ר מתריעין על האילנות בפרוס הפסח על הבורות ושיחין ומערות אפילו בפרוס החג ועל כולן אם אין להן מים לשתות מתריעין עליהן מיד","ואיזהו מיד שלהן שני וחמישי ושני ועל כולן אין מתריעין עליהן אלא באפרכיא שלהן","ואסכרא בזמן שיש בה מיתה מתריעין עליה בזמן שאין בה מיתה אין מתריעין עליה ומתריעין על הגובאי בכל שהוא רבי שמעון בן אלעזר אומר אף על החגב","ת\"ר מתריעין על האילנות בשאר שני שבוע על הבורות ועל השיחין ועל המערות אפילו בשביעית רשב\"ג אומר אף על האילנות בשביעית מפני שיש בהן פרנסה לעניים","תניא אידך מתריעין על האילנות בשאר שני שבוע על הבורות על השיחין ועל המערות אפילו בשביעית רבן שמעון בן גמליאל אומר אף על האילנות מתריעין על הספיחין בשביעית מפני שיש בהן פרנסה לעניים","תניא א\"ר אלעזר בן פרטא מיום שחרב בית המקדש נעשו גשמים צימוקין לעולם יש שנה שגשמיה מרובין ויש שנה שגשמיה מועטין יש שנה שגשמיה יורדין בזמנן ויש שנה שאין גשמיה יורדין בזמנן","שנה שגשמיה יורדין בזמנן למה הוא דומה לעבד שנתן לו רבו פרנסתו בא' בשבת נמצאת עיסה נאפית כתיקנה ונאכלת כתיקנה שנה שאין גשמיה יורדין בזמנן למה הוא דומה לעבד שנתן לו רבו פרנסתו בע\"ש נמצאת עיסה נאפית שלא כתיקנה ונאכלת שלא כתיקנה","שנה שגשמיה מרובין למה הוא דומה לעבד שנתן לו רבו פרנסתו בבת אחת נמצאו ריחים טוחנות מן הכור מה שטוחנות מן הקב ונמצאת עיסה אוכלת מן הכור כמו אוכלת מן הקב","שנה שגשמיה מועטין למה הוא דומה לעבד שנתן לו רבו פרנסתו מעט מעט נמצאו ריחיים מה שטוחנות מן הכור טוחנות מן הקב נמצאת עיסה כמה שנאכלת מן הכור אוכלת מן הקב","ד\"א בזמן שגשמיה מרובין למה הוא דומה לאדם שמגבל את הטיט אם יש לו מים רבים מים אינן כלין והטיט מגובל יפה אם יש לו מים מועטין מים כלים והטיט אינו מתגבל יפה","ת\"ר פעם אחת עלו כל ישראל לרגל לירושלים ולא היה להם מים לשתות הלך נקדימון בן גוריון אצל אדון אחד אמר לו הלויני שתים עשרה מעיינות מים לעולי רגלים ואני אתן לך שתים עשרה עינות מים ואם איני נותן לך הריני נותן לך שתים עשרה ככר כסף וקבע לו זמן","כיון שהגיע הזמן ולא ירדו גשמים בשחרית שלח לו שגר לי או מים או מעות שיש לי בידך שלח לו עדיין יש לי זמן כל היום כולו שלי הוא בצהרים שלח לו שגר לי או מים או מעות שיש לי בידך שלח לו עדיין יש לי שהות ביום במנחה שלח לו שגר לי או מים או מעות שיש לי בידך שלח לו עדיין יש לי שהות ביום לגלג עליו אותו אדון אמר כל השנה כולה לא ירדו גשמים"],[[0,"בצורתא","בצורת היא זו ולא רעב הואיל ויכולין לישא בספינות:"],[0,"מדינתא אמדינתא","וצריכין להוליך ממדינה למדינה על ידי חמרים:"],[0,"כפנא","רעב ורעב קשה מבצורת לפי שאי אפשר להביא בשופי מ\"ר לשון אחר נהרא אנהרא אם יבש מעיין זה וצריך להסב מעיין אחר בכאן אי נמי להמתין עד שיגדל נהר אחרת ויבא כאן בצורת הוא זה:"],[0,"מדינתא אמדינתא","אם יבשו כל הנהרות שבתוך העיר וצריכין להביא מים מעיר אחרת כפנא רעב הוא זה תקיפא מבצורתא:"],[0,"סאה בסלע ושכיחא","כי זבני סאה של חיטין בסלע דהיינו יוקר ומצויה לקנות בכל עת בצורתא:"],[1,"מעות ביוקר","אין מעות מצויות להן:"],[1,"נהירנא","אני זוכר:"],[1,"מדלית איסר","מאין מעות:"],[2,"דאתיא ניחא","ואמרינן בפירקא דלעיל (תענית דף ג:) מיטרא ניחא לפירי ולתבואה ומיטרא רזיא לאילני דאתיא ניחא לפירי ואתיא רזא לאילנות:"],[3,"בשפיכתא","בכח גדול יותר מדאי דאינה טובה לא לזה ולא לזה שוב אמר רבי שפיכותא מטר דק ועבה יותר מדאי לאילני לא מהניא דלאו רזיא היא לצמחים נמי לא שהגשמים מרובין באין ושוטפין אותן:"],[4,"בפרוס הפסח","בימי הפסח על בורות שיחין ומערות אם לא ירדו להן גשמים:"],[4,"אפילו בפרוס החג","להשקות זרעים ואת בהמתם:"],[4,"אם אין להם לשתות מתריעין וכו'","אפילו בפרוס החג דימות החמה נינהו אפילו הכי מתריעין משום דכולן צריכות לשתות:"],[5,"וכולן","כל אלו:"],[5,"בהיפרכיא שלהן","באותו מלכות שכלו שם מי בורות שיחין ומערות:"],[6,"ואסכרא","בוצמל\"ע בלע\"ז פעמים שנקבע בתוך פיו של אדם ומת לשון כי יסכר פי דוברי שקר (תהילים ס״ג:י״ב) והיא סרונכה מיתה משונה:"],[6,"בזמן שיש בה מיתה","שהיא משולחת מהלכת ומתים בה:"],[6,"על הגובאי","שמכלה את התבואה כל שהוא אפילו לא נראה אלא קצת בידוע שעתידין לבוא לרוב אבל חגב כל שהוא מצוי הוא ואינו מכלה כל כך כארבה:"],[7,"בשאר שני שבוע","דשמיטה אבל בשמיטה לא דהפקר נינהו:"],[7,"אפילו בשביעית","כל שעה צריכין לשתיה ואע\"פ שהגשמים מועילין לקרקע בשביעית:"],[8,"רבן שמעון בן גמליאל אומר","מתריעין על האילנות ואף על הספיחין של שביעית שאינן חשובין כל כך:"],[9,"צמוקין","שיורדין בקושי מלשון ושדיים צומקים (הושע ט):"],[10,"למה הוא דומה","פרנסתו של כל השבת כולה:"],[10,"נאפת כתקנה","שיש לו פנאי לאפותה:"],[11,"פרנסתו בבת אחת","פרנסת כל השנה וטוחן אותה ביחד:"],[11,"נמצאת רחיים במה שאוכלת מן הכור כו'","שכן דרך שמשתייר מן הקמח ברחיים וכן כשהגשמים יורדין מרובים ומרביעין את הארץ ומה שהיו טרשים בולעים מן הרוב בולעין מן המיעוט ומה שהרוח מנשבת ובולעת מן הרוב בולעת מן המיעוט:"],[12,"נמצאת עיסה","עריבה שלשין בה את הבצק שמשתייר בשוליה מן העיסה אף גשמים כשיורדין מעט מעט נבלעין בטרשי' ואין מרביעין את הארץ:"],[13,"ה\"ג מימיו מרובין אינן כלין וטיט מתגבל יפה מימיו מועטין הטיט אינו מתגבל יפה","מים אינן כלין ויוכלו לגבל טיט הרבה כמה שירצה:"],[14,"נקדימון בן גוריון","עשיר גדול היה:"],[14,"ואני אתן לך י\"ב מעיינות מים","כלומר שירדו גשמים ויתמלאו כל המעיינות מים אותן מעיינות לא היו נובעין מים כל כך ואינן מתמלאין מאיליהן כשאר מעיינות:"]],[[1,"","נהירנא. פירוש (זכור) אני:"],[5,"","בהפרכיא שלהן. פי' באותו מלכות:"],[7,"","רבן שמעון בן גמליאל אומר אף על האילנות בשביעית מפני שיש בהם פרנסה לעניים. פי' הם הספיחים היוצאין מהן וצ\"ל דסבר כמ\"ד (פסחים דף נא:) ספיחי זרעים אסור דהיינו ר' עקיבא מדקאמר על האילנות ולא קאמר על הספיחים:"]]],[["ועכשיו ירדו גשמים נכנס לבית המרחץ בשמחה עד שהאדון נכנס בשמחתו לבית המרחץ נקדימון נכנס לבית המקדש כשהוא עצב נתעטף ועמד בתפלה","אמר לפניו רבונו של עולם גלוי וידוע לפניך שלא לכבודי עשיתי ולא לכבוד בית אבא עשיתי אלא לכבודך עשיתי שיהו מים מצויין לעולי רגלים מיד נתקשרו שמים בעבים וירדו גשמים עד שנתמלאו שתים עשרה מעינות מים והותירו","עד שיצא אדון מבית המרחץ נקדימון בן גוריון יצא מבית המקדש כשפגעו זה בזה אמר לו תן לי דמי מים יותר שיש לי בידך אמר לו יודע אני שלא הרעיש הקב\"ה את עולמו אלא בשבילך אלא עדיין יש לי פתחון פה עליך שאוציא ממך את מעותיי שכבר שקעה חמה וגשמים ברשותי ירדו","חזר ונכנס לבית המקדש נתעטף ועמד בתפלה ואמר לפניו רבונו של עולם הודע שיש לך אהובים בעולמך מיד נתפזרו העבים וזרחה החמה באותה שעה אמר לו האדון אילו לא נקדרה החמה היה לי פתחון פה עליך שאוציא ממך מעותיי תנא לא נקדימון שמו אלא בוני שמו ולמה נקרא שמו נקדימון שנקדרה חמה בעבורו","תנו רבנן שלשה נקדמה להם חמה בעבורן משה ויהושע ונקדימון בן גוריון בשלמא נקדימון בן גוריון גמרא יהושע נמי קרא דכתיב (יהושע י, יג) וידם השמש וירח עמד וגו' אלא משה מנלן","אמר רבי אלעזר אתיא אחל אחל כתיב הכא (דברים ב, כה) אחל תת פחדך וכתיב התם (יהושע ג, ז) אחל גדלך","רבי שמואל בר נחמני אמר אתיא תת תת כתיב הכא אחל תת פחדך וכתיב התם (יהושע י, יב) ביום תת ה' את האמרי","רבי יוחנן אמר אתיא מגופיה דקרא (דברים ב, כה) אשר ישמעון שמעך ורגזו וחלו מפניך אימתי רגזו וחלו מפניך בשעה שנקדמה לו חמה למשה:","וכן עיר שלא ירדו עליה גשמים כו': אמר רב יהודה אמר רב ושתיהן לקללה","(איכה א, יז) היתה ירושלם לנדה ביניהם אמר רב יהודה אמר רב לברכה כנדה מה נדה יש לה היתר אף ירושלים יש לה תקנה","(איכה א, א) היתה כאלמנה אמר רב יהודה לברכה כאלמנה ולא אלמנה ממש אלא כאשה שהלך בעלה למדינת הים ודעתו לחזור עליה","(מלאכי ב, ט) וגם אני נתתי אתכם נבזים ושפלים אמר רב יהודה לברכה דלא מוקמי מינן לא רישי נהרי ולא גזיריפטי","(מלכים א יד, טו) והכה ה' את ישראל כאשר ינוד הקנה במים אמר רב יהודה אמר רב לברכה דאמר רבי שמואל בר נחמני אמר רבי יונתן מאי דכתיב (משלי כז, ו) נאמנים פצעי אוהב ונעתרות נשיקות שונא טובה קללה שקילל אחיה השילוני את ישראל יותר מברכה שבירכן בלעם הרשע","אחיה השילוני קללן בקנה אמר להם לישראל והכה ה' את ישראל כאשר ינוד הקנה מה קנה זה עומד במקום מים וגזעו מחליף ושרשיו מרובין ואפילו כל הרוחות שבעולם באות ונושבות בו אין מזיזות אותו ממקומו אלא הולך ובא עמהן דממו הרוחות עמד הקנה במקומו","אבל בלעם הרשע בירכן בארז שנאמר (במדבר כד, ו) כארזים (עלי מים) מה ארז זה אינו עומד במקום מים ואין גזעו מחליף ואין שרשיו מרובין אפילו כל הרוחות שבעולם נושבות בו אין מזיזות אותו ממקומו כיון שנשבה בו רוח דרומית עוקרתו והופכתו על פניו ולא עוד אלא שזכה קנה ליטול הימנו קולמוס לכתוב בו ספר תורה נביאים וכתובים","תנו רבנן לעולם יהא אדם רך כקנה ואל יהא קשה כארז מעשה שבא רבי אלעזר (בן ר') שמעון ממגדל גדור מבית רבו והיה רכוב על החמור ומטייל על שפת נהר ושמח שמחה גדולה והיתה דעתו גסה עליו מפני שלמד תורה הרבה"],[[0,"ועכשיו ירדו גשמים","בתמיה:"],[3,"","בוני שמו:"],[3,"נקדרה","זרחה לשון מקדיר שהיתה חמה קודרת ברקיע וזורחת פירטוצ\"ר בלע\"ז:"],[4,"הכי גרסינן","נקדימון בן גוריון הא דאמרן:"],[5,"אתיא אחל אחל","כתיב במלחמת יהושע (יהושע ג׳:ז׳) אחל גדלך ובמלחמת משה כתיב (דברים ב׳:כ״ה) אחל תת פחדך מה יהושע נקדמה לו חמה במלחמתו כדכתיב בהדיא אף משה כן שכן דרך הכתובין למד סתום מן המפורש ברמז בדיבור דומה לחבירו וגזירה שוה אחת מן י\"ג מדות שניתנו לו למשה מסיני ובתחילת סיפרא מפורש:"],[8,"שתיהן לקללה","אקרא קאי האי דכתיב על עיר אחת אמטיר ועל עיר אחת לא אמטיר שניהם לקללה אותה שימטיר עליה רוב גשמים שמקלקלין את התבואה ואת שלא ימטיר אין גשמים ואין תבואה גדילה אשר לא תמטיר עליה מוסב הדבר על העב שהעב בלשון נקיבה דכתיב (מלכים א יח מד) הנה עב קטנה ככף איש עולה מים:"],[10,"ולא אלמנה גמורה","דהא לא כתיב אלמנה אלא היתה כאלמנה כאשה העומדת באלמנות חיות על בעלה שהלך ועתיד לחזור:"],[11,"דלא מוקמי מינן רישי נהרי","מוכסין:"],[11,"גזיריפטי","סרדיוטין מרוב בזיון:"],[12,"ונעתרות נשיקות שונא","נעתרות לשון הפך כדאמרינן במסכת סוכה (דף יד.) ויעתר לו מה עתר זה מהפך את התבואה פורקא בלע\"ז אי נמי נעתרות לשון רבוי וייתור אינקרי\"ש בלע\"ז כמו העתרתם עלי דבריכם (יחזקאל ל״ה:י״ג):"],[13,"ואפילו כל הרוחות","שאינן קשות:"],[14,"בירכן בארז","כארזים עלי מים (במדבר כ״ד:ו׳):"],[14,"ארז זה אינו עומד במקום מים כו'","ואע\"ג דכתיב בקרא כארזים עלי מים ההוא לאו בלעם קאמר ליה דבלעם אמר כארזים והמלאך השיבו עלי מים וכן כולהו דבלעם אמר כנחלים דזימנין מתייבשין וקאמר ליה המלאך נטיו דאין יבישין לעולם והיינו דכתיב ויהפוך ה' אלהיך לך את הקללה לברכה על ידי מלאך שהושיבו על ידי מלאך:"],[14,"רוח דרומית","היא קשה כדאמרינן (ב\"ב ד' כה:) אילמלא בן נץ שמעמידה אין כל בריה יכולה לעמוד מפניה שנאמר המבינתך יאבר נץ יפרש כנפיו לתימן:"],[15,"ומטייל","לשמוח:"]],[[3,"","נקדרה. כמו מקדר בהרים (עירובין נח.) כלומר שמנקב הרקיע:"],[11,"","גזיריפטי. פירוש סרדיוטין ושוטרי העם במקל:"],[12,"","ונעתרות נשיקות שונא. פירוש כלומר נאמנים פצעי אוהב וחילופיהן בשונא ונעתרות לשון הפוך בעתר פורק\"א בלע\"ז שמהפכין בה את התבואה והכי פשטיה דקרא פצעי אוהב נאמנים שהוא עושה לטובה אפילו כשמכה חבירו מתכוין לטובה ונשיקות שונא הם להיפך שעושה הכל לרעה וי\"מ פשטיה דקרא הכי נאמנים פצעי אוהב ונעתרות נשיקות שונא כלומר ונעתרות לשון ריבוי כלומר נשיקות שונא דומים הם למשא כלומר הם מרובות ולמשא לעולם וי\"מ הכי כשאוהבים עושים מריבה ושונאים זה את זה השנאה נאמנה והכי פירוש נאמנים פצעי אוהב הפצעים זהו השנאה שבין אוהבים הם נאמנות ונעתרות נשיקות שונא פי' דכששונאים עושים שלום זה לזה השלום והפשרה שביניהן אמנה וקיימת והיינו נעתרות נשיקות שונא כלומר נשיקות שונא נעתרות:"],[14,"","מה ארז זה. פירוש דאע\"ג דכתיב ביה בקרא עלי מים ההוא לאו בלעם קאמר ליה אלא מלאך וכן כולהו בלעם אמר כנחלים ומלאך אמר נטיו דאינן מתייבשים וכן עלי נהר:"]]],[["נזדמן לו אדם אחד שהיה מכוער ביותר אמר לו שלום עליך רבי ולא החזיר לו אמר לו ריקה כמה מכוער אותו האיש שמא כל בני עירך מכוערין כמותך אמר לו איני יודע אלא לך ואמור לאומן שעשאני כמה מכוער כלי זה שעשית כיון שידע בעצמו שחטא ירד מן החמור ונשתטח לפניו ואמר לו נעניתי לך מחול לי אמר לו איני מוחל לך עד שתלך לאומן שעשאני ואמור לו כמה מכוער כלי זה שעשית","היה מטייל אחריו עד שהגיע לעירו יצאו בני עירו לקראתו והיו אומרים לו שלום עליך רבי רבי מורי מורי אמר להם למי אתם קורין רבי רבי אמרו לו לזה שמטייל אחריך אמר להם אם זה רבי אל ירבו כמותו בישראל אמרו לו מפני מה אמר להם כך וכך עשה לי אמרו לו אעפ\"כ מחול לו שאדם גדול בתורה הוא","אמר להם בשבילכם הריני מוחל לו ובלבד שלא יהא רגיל לעשות כן מיד נכנס רבי אלעזר בן רבי שמעון ודרש לעולם יהא אדם רך כקנה ואל יהא קשה כארז ולפיכך זכה קנה ליטול הימנה קולמוס לכתוב בו ספר תורה תפילין ומזוזות:","וכן עיר שיש בה דבר או מפולת כו': תנו רבנן מפולת שאמרו בריאות ולא רעועות שאינן ראויות ליפול ולא הראויות ליפול","הי ניהו בריאות הי ניהו שאינן ראויות ליפול הי ניהו רעועות הי ניהו ראויות ליפול לא צריכא דנפלו מחמת גובהייהו אי נמי דקיימן אגודא דנהרא","כי ההיא אשיתא רעועה דהואי בנהרדעא דלא הוה חליף רב ושמואל תותה אע\"ג דקיימא באתרה תליסר שנין יומא חד איקלע רב אדא בר אהבה להתם אמר ליה שמואל לרב ניתי מר נקיף אמר ליה לא צריכנא האידנא דאיכא רב אדא בר אהבה בהדן דנפיש זכותיה ולא מסתפינא","רב הונא הוה ליה ההוא חמרא בההוא ביתא רעיעא ובעי לפנוייה עייליה לרב אדא בר אהבה להתם משכי' בשמעתא עד דפנייה בתר דנפק נפל ביתא ארגיש רב אדא בר אהבה איקפד","סבר לה כי הא דאמר רבי ינאי לעולם אל יעמוד אדם במקום סכנה ויאמר עושין לי נס שמא אין עושין לו נס ואם תימצי לומר עושין לו נס מנכין לו מזכיותיו אמר רב חנן מאי קרא דכתיב (בראשית לב, יא) קטנתי מכל החסדים ומכל האמת","מאי הוה עובדיה דרב אדא בר אהבה כי הא דאתמר שאלו תלמידיו (את רבי זירא ואמרי לה) לרב אדא בר אהבה במה הארכת ימים אמר להם מימי לא הקפדתי בתוך ביתי ולא צעדתי בפני מי שגדול ממני","ולא הרהרתי במבואות המטונפות ולא הלכתי ד' אמות בלא תורה ובלא תפילין ולא ישנתי בבית המדרש לא שינת קבע ולא שינת עראי ולא ששתי בתקלת חברי ולא קראתי לחבירי בהכינתו ואמרי לה בחניכתו","אמר ליה רבא לרפרם בר פפא לימא לן מר מהני מילי מעלייתא דהוה עביד רב הונא אמר ליה בינקותיה לא דכירנא בסיבותיה דכירנא דכל יומא דעיבא הוו מפקין ליה בגוהרקא דדהבא וסייר לה לכולה מתא וכל אשיתא דהוות רעיעתא הוה סתר לה אי אפשר למרה בני לה ואי לא אפשר בני לה איהו מדידיה","וכל פניא דמעלי שבתא הוה משדר שלוחא לשוקא וכל ירקא דהוה פייש להו לגינאי זבין ליה ושדי ליה לנהרא וליתביה לעניים זמנין דסמכא דעתייהו ולא אתו למיזבן ולשדייה לבהמה קסבר מאכל אדם אין מאכילין לבהמה","ולא ליזבניה כלל נמצאת מכשילן לעתיד לבא","כי הוה ליה מילתא דאסותא הוי מלי כוזא דמיא ותלי ליה בסיפא דביתא ואמר כל דבעי ליתי ולישקול ואיכא דאמרי מילתא דשיבתא הוה גמיר והוה מנח כוזא דמיא ודלי ליה ואמר כל דצריך ליתי וליעול דלא לסתכן","כי הוה כרך ריפתא הוה פתח לבביה ואמר כל מאן דצריך ליתי וליכול אמר רבא כולהו מצינא מקיימנא לבר מהא דלא מצינא למיעבד"],[[0,"נזדמן לו אדם","יש ספרים שכתוב בהן אליהו זכור לטוב והוא נתכוון להוכיחו שלא ירגיל בדבר:"],[3,"","ה\"ג מפולת שאמרו בריאות ולא רעועות שאינן ראויות ליפול ולא שראויות ליפול הי ניהו בריאות והי ניהו שאינן ראויות ליפול הי ניהו רעועות והי ניהו ראויות ליפול לא צריכא דקיימן אגודא דנהרא – מפולת שיש שם רוח חזק שמפיל החומות מפולת שאמרו מתריעין עליהן בבריאות קאמרינן שיהו החומות בריאות ואף על פי כן נופלות מכח נשיבת הרוח אבל אם היו החומות הנופלות רעועות אין מתריעין עליהן וכשאינן ראויות ליפול מתריעין עליהן ולא בראויות ליפול:"],[4,"לא צריכא","הא דקתני שאינן רעועות וראויות ליפול אלא כגון דקאי אגודא דנהרא על שפת הנהר שאע\"פ שהיא בריאה ראויה היא ליפול שהמים מפילין אותה שמקלקלין את הקרקע ושוחקין את היסוד:"],[5,"","כי ההיא אשיתא רעועה כו':"],[5,"באתרה","במקומה אף על גב דאינה ראויה ליפול דהא קמה באתרה כולי האי אפילו הכי כיון דרעועה היא לא הוו חלפי תותה אלא היה מקיף סביבותיה:"],[7,"מנכין","ממעטין:"],[8,"ה\"ג לא הקפדתי בתוך ביתי ולא הלכתי בלא תורה","דכל שעתא הוה גריס:"],[9,"בהכינתו","שמכנים לו בני אדם כגון שם לווי:"],[9,"חניכתו","כמו חניכת אבות בגיטין עד י' דורות (גיטין דף פח.):"],[10,"ביומא דעיבא","יום המעונן דהוי רוח מנשבת ומסתפי דלא תפיל חומות:"],[10,"בגוהרקא","תיבה תלויה בעגלה ושרות יושבות בהן:"],[10,"וסייר","בודק תרגום פוקד (שמות לד) מסער כמו האי טבחא דלא סר סכינא קמיה חכם:"],[10,"","כי הוה ליה מילתא דאסותא רמי ליה אכוזא דמיא כו' לא גרסינן:"],[11,"זבין ליה ושדי ליה בנהרא","להכי זבין להו דאי הוה משתייר מידי לגננין אזלא לאיבוד דמכמשא בשבת ונמצא מכשילן לעתיד לבא דלא מייתי ירקי לסעודת שבת:"],[11,"דסמכא דעתייהו","שנסמכין עניים לאותו ירק ואומרים אין אנו צריכין לקנות ושמא ישתייר שם כלום ואין להם מה לאכול בשבת:"],[11,"אין מאכילין אותן לבהמה","משום ביזוי אוכלין ומחזי כבועט בטובה שהשפיע הקב\"ה בעולם אי נמי משום דחסה תורה על ממונן של ישראל וזרק לנהר והולכין למקום אחר ומוצאין אותם בני אדם ואוכלין אותן כך שמעתי:"],[13,"מילתא דשיבתא","מנהג שדים שמזיקין למי שיאכל ואינו נוטל ידיו דשיבתא כהך דגרסינן במסכת יומא (דף עז:) אמר אביי משום שיבתא והוה תלי ליה לההוא כוזא דמיא כי היכי דלימשו ידייהו מינה:"],[14,"בר מהא","חוץ מזו דכל מאן דבעי הוה עייל ואכל:"]],[[0,"","נזדמן לו אדם אחד שהוא מכוער ביותר. במסכת דרך ארץ מפרש דאותו אדם היינו אליהו ולטוב נתכוין כדי שלא ירגיל בדבר:"],[4,"","לא צריכא דנפלי מחמת גובהייהו. פי' דהוו בריאות ולא היו ראויות ליפול אלא מחמת גובהן:"],[5,"","אמר ליה דאיכא רב אדא בהדן דנפיש זכותיה. וצ\"ל דתרי רב אדא הוו דהא רב אדא בר אהבה הוה בימי רבא דמצינו בכמה מקומות אמר רב אדא בר אהבה אמר רבא והא רב אדא בר אהבה דהכא משמע דהוה חבר לרב ולשמואל מדקאמר ליה שמואל לרב וקאמר ליה הא איכא רב אדא בהדן ואנן ידענא דרב יהודה היה תלמיד דרב ושמואל ורבא הוה נולד ביום שמת רב יהודה ורב אדא היה תלמיד דרבא א\"כ ע\"כ צ\"ל דתרי רב אדא הוו:"],[9,"","בהכינתו. פירוש בכינוי שמכנין אותו בן אדם לגנאי בחניכתו פי' כינוי שם משפחתו שם לווי כמו שם חניכת אבות בגיטין עד עשרה דורות (גיטין דף פח.) כגון רבי אברהם אבן עזרא שכל בני משפחתו היו נקראים כך ודוקא לגנאי אבל לשבח מותר:"]]],[["משום דנפישי בני חילא דמחוזא","אילפא ור' יוחנן הוו גרסי באורייתא דחיקא להו מילתא טובא אמרי ניקום וניזיל וניעבד עיסקא ונקיים בנפשין (דברים טו, ד) אפס כי לא יהיה בך אביון אזלו אותבי תותי גודא רעיעא הוו קא כרכי ריפתא אתו תרי מלאכי השרת","שמעיה רבי יוחנן דאמר חד לחבריה נישדי עלייהו האי גודא ונקטלינהו שמניחין חיי עולם הבא ועוסקין בחיי שעה אמר ליה אידך שבקינהו דאיכא בהו חד דקיימא ליה שעתא רבי יוחנן שמע אילפא לא שמע אמר ליה ר' יוחנן לאילפא שמע מר מידי אמר ליה לא אמר מדשמעי אנא ואילפא לא שמע ש\"מ לדידי קיימא לי שעתא","אמר ליה רבי יוחנן איהדר ואוקי בנפשאי (דברים טו, יא) כי לא יחדל אביון מקרב הארץ ר' יוחנן הדר אילפא לא הדר עד דאתא אילפא מליך רבי יוחנן","אמרו לו אי אתיב מר וגריס לא הוה מליך מר אזל תלא נפשיה באסקריא דספינתא אמר אי איכא דשאיל לי במתניתא דר' חייא ורבי אושעיא ולא פשטינא ליה ממתני' נפילנא מאסקריא דספינתא וטבענא","אתא ההוא סבא תנא ליה האומר תנו שקל לבניי בשבת והן ראויין לתת להם סלע נותנין להם סלע ואם אמר אל תתנו להם אלא שקל אין נותנין להם אלא שקל","אם אמר מתו ירשו אחרים תחתיהם בין שאמר תנו בין שאמר אל תתנו אין נותנין להם אלא שקל א\"ל הא מני ר\"מ היא דאמר מצוה לקיים דברי המת","אמרו עליו על נחום איש גם זו שהיה סומא משתי עיניו גידם משתי ידיו קיטע משתי רגליו וכל גופו מלא שחין והיה מוטל בבית רעוע ורגלי מטתו מונחין בספלין של מים כדי שלא יעלו עליו נמלים פעם אחת [היתה מטתו מונחת בבית רעוע] בקשו תלמידיו לפנות מטתו ואח\"כ לפנות את הכלים אמר להם בניי פנו את הכלים ואח\"כ פנו את מטתי שמובטח לכם כל זמן שאני בבית אין הבית נופל פינו את הכלים ואחר כך פינו את מטתו ונפל הבית","אמרו לו תלמידיו רבי וכי מאחר שצדיק גמור אתה למה עלתה לך כך אמר להם בניי אני גרמתי לעצמי שפעם אחת הייתי מהלך בדרך לבית חמי והיה עמי משוי ג' חמורים אחד של מאכל ואחד של משתה ואחד של מיני מגדים בא עני אחד ועמד לי בדרך ואמר לי רבי פרנסני אמרתי לו המתן עד שאפרוק מן החמור לא הספקתי לפרוק מן החמור עד שיצתה נשמתו","הלכתי ונפלתי על פניו ואמרתי עיני שלא חסו על עיניך יסומו ידיי שלא חסו על ידיך יתגדמו רגליי שלא חסו על רגליך יתקטעו ולא נתקררה דעתי עד שאמרתי כל גופי יהא מלא שחין אמרו לו אוי לנו שראינוך בכך אמר להם אוי לי אם לא ראיתוני בכך","ואמאי קרו ליה נחום איש גם זו דכל מילתא דהוה סלקא ליה אמר גם זו לטובה זימנא חדא בעו לשדורי ישראל דורון לבי קיסר אמרו מאן ייזיל ייזיל נחום איש גם זו דמלומד בניסין הוא שדרו בידיה מלא סיפטא דאבנים טובות ומרגליות אזל בת בההוא דירה בליליא קמו הנך דיוראי ושקלינהו לסיפטיה ומלונהו עפרא (למחר כי חזנהו אמר גם זו לטובה)","כי מטא התם [שרינהו לסיפטא חזנהו דמלו עפרא] בעא מלכא למקטלינהו לכולהו אמר קא מחייכו בי יהודאי [אמר גם זו לטובה] אתא אליהו אדמי ליה כחד מינייהו א\"ל דלמא הא עפרא מעפרא דאברהם אבוהון הוא דכי הוה שדי עפרא הוו סייפיה גילי הוו גירי דכתיב (ישעיהו מא, ב) יתן כעפר חרבו כקש נדף קשתו","הויא חדא מדינתא דלא מצו למיכבשה בדקו מיניה וכבשוה עיילו לבי גנזיה ומלוהו לסיפטיה אבנים טובות ומרגליות ושדרוהו ביקרא רבה","כי אתו ביתו בההוא דיורא אמרו ליה מאי אייתית בהדך דעבדי לך יקרא כולי האי אמר להו מאי דשקלי מהכא אמטי להתם סתרו לדירייהו ואמטינהו לבי מלכא אמרו ליה האי עפרא דאייתי הכא מדידן הוא בדקוה ולא אשכחוה וקטלינהו להנך דיוראי:","אי זו היא דבר עיר המוציאה חמש מאות רגלי כו': ת\"ר עיר המוציאה חמש מאות ואלף רגלי כגון כפר עכו ויצאו הימנה תשעה מתים בשלשה ימים זה אחר זה הרי זה דבר","ביום אחד או בד' ימים אין זה דבר ועיר המוציאה חמש מאות רגלי כגון כפר עמיקו ויצאו ממנה שלשה מתים בג' ימים זה אחר זה הרי זה דבר"],[[0,"משום דנפישי בני מחוזא","דאיכא עניי טפי וקא מיכלי קרנא:"],[1,"דחיקא להו","עניות:"],[1,"כי לא יהיה בך אביון","בך בעצמך:"],[2,"חיי העולם הבא","תורה:"],[2,"חיי שעה","עולם הזה זה סחורה:"],[2,"קיימא ליה שעתא","עתיד להתגדל ואין זמנו למות:"],[2,"שמע מינה","מדאנא שמעתיה איהדר איזיל לתורתי:"],[3,"עד דאתא אילפא","ממקום שהלך שם לסחורה:"],[3,"מלך רבי יוחנן","מינוהו ראש ישיבה עליהן מנהג הוא מי שהוא ראש ישיבה היו מגדלין אותו משלהן ומעשירין אותו כדאמרינן לגבי כהן גדול בסיפרא וביומא (דף יח.) והכהן הגדול מאחיו גדלוהו משל אחיו:"],[4,"אמרו לו","אנשי המקום לאילפא:"],[4,"אי אתיב מר וגריס","אם היית יושב ועוסק בתורה היינו ממליכין אותך כמו שעשינו לר' יוחנן דאילפא הוי גמיר טפי מר' יוחנן:"],[4,"תלא נפשיה באסקריא","כלונס עץ ארוך תקוע בלב הספינה שמניחין עליה מכסה וילו\"ן בלע\"ז:"],[4,"דשאיל לי כו'","כלומר אף על גב דעבדי עיסקא גריסנא אנא טפי מיניה:"],[4,"דבי ר' חייא ודבי ר' אושעיא","דהוו מסדרי מתניתא על פי רבינו הקדוש שהיה רבם:"],[4,"ולא פשיטנא ליה ממתני'","דאשכחנא משנה כוותיה דההיא ברייתא:"],[5,"תנא ליה","שנה לפניו כלומר בעא מיניה:"],[5,"האומר תנו שקל לבניי","מי שמת והניח ממונו ביד איש נאמן ואמר תנו שקל חצי סלע לבניי להוצאה בשבוע:"],[5,"וראויין לתת להן סלע","שיש לו בנים הרבה ואין מסתפקין לשבת בפחות מסלע:"],[5,"נותנין להם סלע","דאי הוה בדעתיה דלא למיתן להו אלא שקל היה מצוה אל תתנו להן אלא שקל והאי דקאמר תנו להן שקל ולא אמר תנו סלע משום דבעי לזרוזינהו כדאמרן בכתובות (דף ע.) כדי לזרזן במשא ובמתן כדי שיטרחו וילמדו דרך ארץ וירויחו:"],[6,"אם מתו ירשו אחרים תחתיהן","אע\"ג דאמר תנו שקל ולא אמר אל תתנו אלא שקל גלי בדעתיה דלא בעי למיתב להו אלא שקל בשבת כי היכי דאי מתו ירשו אחרים תחתיהן:"],[6,"אמר ליה","אילפא:"],[6,"הא מני","דקתני אע\"ג דלא ספקי בבציר מסלע לא יהבינן להו אלא שקל ר\"מ היא דאמר במסכת כתובות במתני' (דף סט:) מצוה לקיים דברי המת דאי לאו מצוה מן הדין נותנין להן כל הראוי להן שהרי כל הממון שלהן הוא ואין בו לאותן אחרים כלום אלא לאחר מיתתן אם יש מותר יש להן ואם לאו לא יטלו ומתוך שרוצין אנו לקיים דבריו שירשו אחרים תחתיהם אנו מקמצין את הממון כדי שיהא שם מותר:"],[7,"והיה מטתו מונחת כו'","רגלי המטה מונחין בספלים מלאים מים שלא יעלו אליו נמלים דרך רגלי המטה מפני שהיה גידם ואם היו עולים אינו יכול ליטלם בידיו ולזורקן:"],[10,"דסלקי ליה","כל המאורע לו אפילו רעה:"],[10,"בת בההיא דיורא","לן לילה אחת באותו המלון:"],[10,"לסיפטיה","ארגז שלו:"],[11,"לכולהו","שונאיהן של ישראל:"],[11,"כחד מינייהו","כאחד משרי קיסר:"],[11,"מעפרא דאברהם הוא","כשנלחם עם המלכים:"],[11,"גילי","קשין:"],[13,"ביתו","לנו במלון:"],[14,"ה\"ג עיר גדולה המוציאה אלף וחמש מאות רגלי יצאו הימנה תשעה מתים וכו'","אלף וחמש מאות איש דהיינו פי שלשה בעיר קטנה:"],[15,"כפר עמיקו שלשה מתים בשלשה ימים","מת אחד בכל יום:"]],[[4,"","אמרו ליה לאילפא אי יתיב מר לא הוה מלך מר. פי' כלומר לא היית מולך לראש ישיבה וי\"מ בניחותא דמר קאי אר' יוחנן כלומר אי יתיב מר לא הוה מליך ר' יוחנן:"]]],[["ביום אחד או בארבעה ימים אין זה דבר","דרוקרת עיר המוציאה חמש מאות רגלי הוה ויצאו ממנה שלשה מתים ביום אחד גזר רב נחמן בר רב חסדא תעניתא אמר רב נחמן בר יצחק כמאן כר\"מ","דאמר ריחק נגיחותיו חייב קירב נגיחותיו לא כ\"ש","א\"ל רב נחמן בר רב חסדא לרב נחמן בר יצחק ליקום מר ליתי לגבן א\"ל תנינא רבי יוסי אומר לא מקומו של אדם מכבדו אלא אדם מכבד את מקומו שכן מצינו בהר סיני שכל זמן שהשכינה שרויה עליו אמרה תורה (שמות לד, ג) גם הצאן והבקר אל ירעו אל מול ההר ההוא נסתלקה שכינה ממנו אמרה תורה (שמות יט, יג) במשוך היובל המה יעלו בהר","וכן מצינו באהל מועד שבמדבר שכל זמן שהוא נטוי אמרה תורה (במדבר ה, ב) וישלחו מן המחנה כל צרוע הוגללו הפרוכת הותרו זבין והמצורעים ליכנס שם","אמר ליה אי הכי ניקום אנא לגבי מר אמר ליה מוטב יבא מנה בן פרס אצל מנה בן מנה ואל יבא מנה בן מנה אצל מנה בן פרס","בסורא הוות דברתא בשיבבותיה דרב לא הוות דברתא סברו מיניה משום זכותיה דרב דנפיש איתחזי להו בחילמא רב דנפישא זכותיה טובא הא מילתא זוטרא ליה לרב אלא משום ההוא גברא דשייל מרא וזבילא לקבורה","בדרוקרת הוות דליקתא ובשיבבותיה דרב הונא לא הוות דליקתא סבור מינה בזכותא דרב הונא דנפיש איתחזי להו בחילמא האי זוטרא ליה לרב הונא אלא משום ההיא איתתא דמחממת תנורא ומשיילי לשיבבותיה","אמרו ליה לרב יהודה אתו קמצי גזר תעניתא אמרו ליה לא קא מפסדן אמר להו זוודא אייתו בהדייהו","אמרו ליה לרב יהודה איכא מותנא בחזירי גזר תעניתא נימא קסבר רב יהודה מכה משולחת ממין אחד משולחת מכל המינין לא שאני חזירי דדמיין מעייהו לבני אינשי","אמרו ליה לשמואל איכא מותנא בי חוזאי גזר תעניתא א\"ל והא מרחק אמר ליכא מעברא הכא דפסיק ליה","אמרו ליה לרב נחמן איכא מותנא בארעא דישראל גזר תעניתא אמר אם גבירה לוקה שפחה לא כל שכן","טעמא דגבירה ושפחה הא שפחה ושפחה לא והא אמרו ליה לשמואל איכא מותנא בי חוזאי גזר תעניתא שאני התם כיון דאיכא שיירתא דלווי ואתיא בהדיה","אבא אומנא הוה אתי ליה שלמא ממתיבתא דרקיעא כל יומא ולאביי כל מעלי יומא דשבתא לרבא כל מעלי יומא דכיפורי הוה קא חלשא דעתיה דאביי משום דאבא אומנא אמרו ליה לא מצית למיעבד כעובדיה","ומאי הוו עובדיה דאבא אומנא דכי הוה עביד מילתא הוה מחית גברי לחוד ונשי לחוד ואית ליה לבושא דאית ביה קרנא דהוות בזיעא כי כוסילתא כי הוות אתיא ליה איתתא הוה מלביש לה כי היכי דלא ניסתכל בה ואית ליה דוכתא דצניעא דשדי ביה פשיטי דשקיל דאית ליה שדי ביה דלית ליה לא מיכסיף","כי הוה אתרמי ליה צורבא מרבנן אגרא מיניה לא שקיל ובתר דקאי יהיב ליה פשיטי ואמר ליה זיל בריא נפשך יומא חד שדר אביי זוגא דרבנן למיבדקיה אותבינהו ואכלינהו ואשקינהו ומך להו ביסתרקי בליליא"],[[0,"ביום אחד אין זה דבר","דאקראי בעלמא הוא:"],[1,"","כפר עכו דרוקרת נ\"א דיוקרא עיר ששמה יו\"ד והיא קטנה על שם שיו\"ד קטנה באותיות:"],[1,"","ה\"ג יצאו הימנה ג' מתים בג' ימים:"],[2,"ריחק נגיחותיו","בשור מועד קאי בבבא קמא בפרק כיצד הרגל מועדת אי זהו תם ואי זהו מועד כל שהעידו בו ג' ימים דברי ר' יהודה ר' מאיר אומר כל שהעידו בו ג' פעמים ביום אחד ר' יהודה סבר כתיב או נודע כי שור נגח הוא מתמול שלשום מתמול תרי שלשום תלת הרי ג' ימים ור\"מ סבר ריחק נגיחותיו כשנגח בג' ימים זה אחר זה חייב קירב נגיחותיו שנגח ג' פעמים ביום אחד לא כל שכן:"],[3,"ליקום מר להכא","דרב נחמן בר יצחק הוה יתיב בין גברי דלא חשיבי כולי האי וקאמר ליה רב נחמן בר רב חסדא ליקום מר מהתם וליתי ליתיב גבאי:"],[3,"תנינא","תני אנא שונה אני ברייתא זו רבי יוסי אומר כו':"],[3,"לא מקומו של אדם מכבדו","ואם אלך ואשב שם אין המקום מכבדני:"],[3,"גם הצאן והבקר אל ירעו","דמשום שכינה היה הר סיני מכובד ומקודש:"],[3,"אל מול ההר ההוא","מדכתיב ההוא משמע כל זמן שהוא בגדולתו שהשכינה עליו נסתלקה השכינה במשוך היובל וגו' ואע\"ג דהאי קרא בלוחות הראשונות כתיב לא נסתלקה שכינה עד לוחות האחרונות שניתנו ביום הכפורים וגם כל ימות החורף שעסקו במלאכת המשכן שהתה שכינה בהר ומשם ניתנו כל המצות בקולי קולות ולפידים ביום קבלת עשרת הדברות עד אחד בניסן שהוקם המשכן ונסעה וזזה שכינה מן ההר וישבה לה על הכפורת ושם באהל מועד נשנית התורה כללותיה ופרטותיה ועל אותה שעה היה מתיר להם בלוחות הראשונות לעלות כדאמרינן במסכת ביצה (דף ה.) כל דבר שבמנין צריך מנין אחר להתירו ובראש קונטרס רומי אתה מוצא תשובת רבים בכך:"],[3,"במשוך היובל","בסיום השופר כשתסתלק השכינה דרך הוא להאריך ולמשוך התקיעה בשעת סיום:"],[4,"הוגללו הפרוכת","שהיו נגללין בשעת נסיעתן היו נוסעין כולן ובאין זבים ומצורעים ונכנסין במחנה:"],[5,"פרס","חצי מנה ולשון פרוסה כמו פרס פריסת מלכותך (דניאל ה) שאביו של רב נחמן בר רב חסדא גדול מיצחק אביו של רב נחמן מדמיתקרי בר רב חסדא ואידך רב נחמן בר יצחק מכלל שלא נסמך:"],[6,"דברתא","דבר:"],[6,"בשיבבותיה","בשכונתו:"],[6,"איתחזי להו בחילמא","להנך אינשי דסברי משום זכותיה דרב הוא:"],[6,"הא זוטר ליה לרב","נס זה קטן הוא לפי גדולת רב:"],[6,"מרא","פושיי\"ר בלע\"ז:"],[6,"זבילי","פלי\"א בלע\"ז:"],[6,"לקבורה","ומשום זכותיה דקבורה מדדו בו מדה כנגד מדה:"],[7,"ומשיילא לשיבבותיה","ומשאילתו לשכנותיה לאחר שהסיקתו משלה לפיכך נמדדת השכר בה במדה:"],[8,"קמצא","ארבה שמכלה את התבואה:"],[8,"לא קא מפסדא","לא בעינן למיגזר תעניתא:"],[8,"זוודא אייתו בהדייהו","בתמיה וכי צידה הביאו עמם שלא יפסידו את התבואה:"],[9,"מעייהו","בני מעיין שלהן שאין להן כרס הפנימי כשאר בהמה וסימן רע הוא:"],[10,"בי חוזאי","מקום במלכות בבל:"],[10,"גזר תעניתא","בעירו:"],[10,"הא מרחק","ואין לחוש שמא יבא עד כאן:"],[10,"אמר להו וכי מעברא פסיק להו","וכי מעברות ושאר מחיצות מפסיקין לפני הדבר שלא יבא:"],[11,"שפחה לא כל שכן","ויש לחוש שמא ישתלח עד כאן:"],[12,"הא שפחה ושפחה","שתי עיירות של חוצה לארץ כגון בי חוזאי ונהרדעא דאתריה דשמואל:"],[12,"שיירתא","דאזלי מבי חוזאי לנהרדעא:"],[12,"דלווי","מתלוה ובא עמהן:"],[13,"אבא אומנא","מקיז דם:"],[13,"שלמא מרקיעא","בת קול אומרת לו שלום עליך:"],[14,"כי הוה עביד מילתא","כשהיה מקיז דם לבני אדם:"],[14,"ודנשים לחודייהו","לצניעותא:"],[14,"דאית ביה קרנא","וינטוש\"א שהיה תקוע בו הקרן שהוא מקיז בו ולנשים הוי מלביש לה:"],[14,"ולא מכסיף","דלאחר שהכה לא הוה ידע מאן רמי (בכסילתיה) פשיטי להתם ומאן דלא רמי:"],[15,"בריא נפשך","תבריא עצמך. למיבדקיה. לבדקו במעשיו:"],[15,"למיבדקיה","לבדקו במעשיו:"],[15,"ומך להו בסתרקי","קיפל תחתיהן תכשיטי צמר טפיד\"ו בלע\"ז לישן בהן:"]],[[5,"","יבא מנה בן פרס. כלומר מוטב שיבא גדול בן הדיוט דפרס לא הוה אלא חצי מנה ואל יבא מנה בן מנה דהיינו רב חסדא דהיה מנה כלומר שהיה חשוב ופרס היינו יצחק אבוה דרב נחמן דלא מיקרי רב יצחק:"],[8,"","אמר ליה זוודא אייתי בהדייהו. פירוש וכי צידה הביאו עמהם שיהו אוכלות כלומר אי אפשר שלא יאכלו התבואה והזרעים:"],[9,"","אמרו ליה לרב יהודה איכא מותנא בחזירי גזר תעניתא וכו' עד שאני חזירי דדמו מעייהו לבני אינשי. פירוש שבני מעיו של חזיר דומין למעים של בני אדם ויש לחוש שיהא על בני אדם מכאן נראה שאם יהיה דבר על עובדי כוכבים שיש לחוש ויש להתענות דהא הכא חזינן דגזר תעניתא מדבר שהיה בחזירין משום דדמו מעייהו לבני אדם וכל שכן דנכרים דדמו לישראל:"],[11,"","גבירה לוקה. פי' זו ארץ ישראל:"]]],[["לצפרא כרכינהו ושקלינהו וקמו ונפקו להו לשוקא ואשכחינהו א\"ל לשיימיה מר היכי שוו א\"ל הכי והכי א\"ל ודלמא שוו טפי א\"ל בהכי שקלינהו אמרו ליה דידך ניהו ושקלינהו מינך","אמרו ליה במטותא מינך במאי חשדתינן א\"ל אמינא פדיון שבויים איקלע להו לרבנן ואכסיפו למימר לי אמרו ליה השתא נשקלינהו מר אמר להו מההוא שעתא אסחתינהו מדעתאי לצדקה","הוה קא חלשא דעתיה דרבא משום דאביי אמרו ליה מסתייך דקא מגנית אכולה כרכא","ר' ברוקא חוזאה הוה שכיח בשוקא דבי לפט הוה שכיח אליהו גביה א\"ל איכא בהאי שוקא בר עלמא דאתי א\"ל לא אדהכי והכי חזא לההוא גברא דהוה סיים מסאני אוכמי ולא רמי חוטא דתכלתא בגלימיה א\"ל האי בר עלמא דאתי הוא","רהט בתריה א\"ל מאי עובדך א\"ל זיל האידנא ותא למחר למחר א\"ל מאי עובדך א\"ל זנדוקנא אנא ואסרנא גברי לחוד ונשי לחוד ורמינא פורייאי בין הני להני כי היכי דלא ליתו לידי איסורא כי חזינא בת ישראל דיהבי נכרים עלה עינייהו מסרנא נפשאי ומצילנא לה יומא חד הוות נערה מאורסה גבן דיהבו בה נכרים עינייהו שקלי דורדייא דחמרא ושדאי לה בשיפולה ואמרי דיסתנא היא","א\"ל מאי טעמא לית לך חוטי ורמית מסאני אוכמי א\"ל עיילנא ונפיקנא ביני נכרים כי היכי דלא לידעו דיהודאה אנא כי הוו גזרי גזירתא מודענא להו לרבנן ובעו רחמי ומבטלי לגזירתייהו ומאי טעמא כי אמינא לך אנא מאי עובדך ואמרת לי זיל האידנא ותא למחר א\"ל בההיא שעתא גזרי גזירתא ואמינא ברישא איזיל ואשמע להו לרבנן דלבעי רחמי עלה דמילתא","אדהכי והכי אתו הנך תרי אתי א\"ל הנך נמי בני עלמא דאתי נינהו אזל לגבייהו אמר להו מאי עובדייכו אמרו ליה אינשי בדוחי אנן מבדחינן עציבי אי נמי כי חזינן בי תרי דאית להו תיגרא בהדייהו טרחינן ועבדינן להו שלמא:","על אלו מתריעין בכל מקום כו' ת\"ר על אלו מתריעין בכל מקום על השדפון ועל הירקון ועל ארבה וחסיל ועל חיה רעה ר' עקיבא אומר על השדפון ועל הירקון בכל שהוא ארבה וחסיל אפילו לא נראה בא\"י אלא כנף אחד מתריעין עליהן:","ועל חיה וכו' ת\"ר חיה רעה שאמרו בזמן שהיא משולחת מתריעין עליה אינה משולחת אין מתריעין עליה אי זו היא משולחת ואי זו היא שאינה משולחת נראית בעיר משולחת בשדה אינה משולחת ביום משולחת בלילה אינה משולחת","ראתה שני בני אדם ורצתה אחריהן משולחת נחבאת מפניהן אינה משולחת טרפה שני בני אדם ואכלה אחד מהן משולחת אכלה שניהן אינה משולחת עלתה לגג ונטלה תינוק מעריסה משולחת","הא גופה קשיא אמרת נראתה בעיר משולחת לא שנא ביום ולא שנא בלילה והדר אמרת ביום משולחת בלילה אינה משולחת","לא קשיא הכי קאמר נראתה בעיר ביום משולחת בעיר בלילה אינה משולחת אי נמי בשדה [אפילו] ביום [אינה] משולחת (בשדה בלילה אינה משולחת)","ראתה שני בני אדם ורצתה אחריהן משולחת הא עומדת אינה משולחת והדר אמרת נחבאת מפניהן אינה משולחת הא עומדת משולחת","לא קשיא כאן בשדה הסמוכה לאגם כאן בשדה שאינה סמוכה לאגם","טרפה שני בני אדם כאחד ואכלה אחד מהן משולחת שניהם אינה משולחת והא אמרת אפילו רצתה אמר רב פפא כי תני ההיא באגמא:","גופא עלתה לגג ונטלה תינוק מעריסה משולחת פשיטא אמר רב פפא ככוכי דציידי:","על החרב וכו' ת\"ר חרב שאמרו אינו צריך לומר חרב שאינו של שלום אלא אפילו חרב של שלום שאין לך חרב של שלום יותר מפרעה נכה ואעפ\"כ נכשל בה המלך יאשיהו שנאמר"],[[0,"לצפרא כרכינהו","רבנן לביסתרקי דאבא אומנא ואייתינהו לשוקא לזבנינהו:"],[0,"אמרו ליה","לאבא אומנא לשיימינהו מר והב לן דמייהו והיו בודקין אותו אם יחשדם כגזלנין או אם יהא שם אותם פחות מכדי דמיהם:"],[1,"במאי חשדתינן","כשלקחנום:"],[1,"וכסיפא","לכו מילתא למימר לי לאלתר ליתן אותם ואהכי אתו למיגני גבאי למיעבד כולי האי:"],[1,"לשקלינהו מר","שלא היינו רוצין אלא לנסותך:"],[2,"חלשא דעתיה דרבא אדאביי","דלרבא לא אתי שלמא אלא ממעלי יומא דכיפורי למעלי יומא דכיפורי ולאביי כל מעלי שבתא:"],[2,"אכולא כרכא","על כל בני עירך:"],[3,"רב ברוקא חוזאה","שהיה מבי חוזאי:"],[3,"דבי לפט","מקום:"],[3,"א\"ל","רב ברוקא לאליהו מי איכא בהאי שוקא כו':"],[3,"מסאני אוכמי","מנעלים שחורים שלא כמנהג היהודים:"],[3,"ולא רמי חוטא","לא הטיל ציצית בטליתו:"],[3,"אמר ליה","אליהו לרב ברוקא האי בר עלמא דאתי הוא:"],[4,"קרא ליה","רב ברוקא לההוא גברא:"],[4,"זנדוקנא","שומר בית האסורין:"],[4,"רמינא פורייאי כו'","מטיל אני מטתי בין אנשים לנשים:"],[4,"דיהבי נכרים עינייהו עלה","בעלי בית האסורים:"],[4,"איתרמי נערה כו'","דהויא בבית הסוהר:"],[4,"דורדיא דחמרא","שמרים של יין האדומים כדם:"],[4,"בשיפולה","בשולי בגדיה:"],[4,"דיסתנא","דרך נשים לה ומאוסה היא והוא לשון פרסי:"],[6,"אמר ליה","אליהו לרב ברוקא הני נמי בני עלמא דאתי נינהו:"],[6,"בדוחי","שמחים ומשמחים בני אדם:"],[6,"טרחינן","במילי דבדיחותא בינייהו:"],[6,"עד דעבדי שלמא","שהן דברים שאדם אוכל פירותיהן בעולם הזה והקרן קיימת וכו' הבאת שלום בין אדם לחבירו:"],[7,"שדפון וירקון","כיון שנראה כל שהוא מתריעין ומלא תנור דמתניתין להתענות אי נמי מעשה היה כך:"],[7,"כנף אחד","עוף אחד של אותו מין כעין צפור כל כנף (בראשית ז׳:י״ד):"],[8,"משולחת","מן השמים:"],[8,"בשדה אינה משולחת","דהיינו אורחה:"],[9,"טרפה שני בני אדם","ולא אכלה אלא אחד מהם ודאי משולחת דכיון דלא היתה רעבה אלא לאחד מאי טעמא קטלה ליה לאידך:"],[9,"שניהן אינה משולחת","שמפני הרעב אכלתם:"],[9,"עלתה לגג","רגילין היו להשתמש כל תשמישיהן בגגות שלא היו משופעים אלא חלקים ושוין והוא הדין לבית שתחתיו:"],[9,"עריסה","ברצו\"ל בלע\"ז:"],[11,"הכי קאמר","האי דקתני נראתה בעיר כו' הכי קאמר נראתה בעיר כגון שנראתה ביום דסתם נראתה ביום משמע אבל בלילה אינה משולחת והאי דקתני נראתה ביום אשדה קאי דאם נראתה בשדה ביום אינה משולחת:"],[12,"הא עמדה","בשדה דלא רצתה ולא נחבאת:"],[13,"בשדה הסמוכה לאגם","עמדה אינה משולחת דכיון דסמוכה לאגם היינו רביתה ולא ברחה סברה אי אתי בתראי עריקנא לאגם מיד:"],[13,"בשדה שאינה סמוכה לאגם","עמדה משולחת דכיון דלאו מקום רביתה הוא וקיימא ודאי משולחת גזירה היא:"],[13,"אגם","מרשי\"ק בלע\"ז הסמוך לעיר והוא מלא קוצים:"],[14,"כי תניא ההיא","דאכלה אין רצתה לא באגם דכיון דהיינו דוכתה סמכה אדעתה ורהטא אבתרייהו:"],[15,"ככוכא דציידי","כוך קטן של ציידין שיחפרו למארב העופות ואף על גב דלאו בנין קבוע הוא ולא הוה כיישוב הויא משולחת:"],[16,"אין צריך לומר חרב שאינו של שלום","שמתריעין עליה אלא אפילו חרב של שלום העוברת דרך אותו מלכות לילך להלחם במקום אחרת:"]],[[9,"","טרפה שני בני אדם אכלה אחד מהן משולחת. והוא הדין לא אכלה אחד מהם משולחת שהרי אם אכלה שניהם אינה משולחת דהא דאכלה שניהם לא הוי מטעם משולחת אלא מטעם דהיא רעיבה והא דנקט אכלה אחד מהם רבותא הוי דאע\"ג דאכלה אחד מהן הוי משולחת:"]]],[["(דברי הימים ב לה, כא) וישלח אליו מלאכים לאמר מה לי ולך מלך יהודה לא עליך אתה היום כי אל בית מלחמתי ואלהים אמר לבהלני חדל לך מאלהים אשר עמי ואל ישחיתך","מאי אלהים אשר עמי אמר רב יהודה אמר רב זו ע\"ז אמר הואיל וקא בטח בע\"ז יכילנא ליה","(דברי הימים ב לה, כג) ויורו היורים למלך יאשיהו ויאמר המלך לעבדיו העבירוני כי החליתי מאד מאי כי החליתי מאד אמר רב יהודה אמר רב מלמד שעשו כל גופו ככברה","אמר ר' שמואל בר נחמני אמר רבי (יוחנן) מפני מה נענש יאשיהו מפני שהיה לו לימלך בירמיהו ולא נמלך מאי דרש (ויקרא כו, ו) וחרב לא תעבור בארצכם","מאי חרב אילימא חרב שאינה של שלום והכתיב ונתתי שלום בארץ אלא אפילו של שלום והוא אינו יודע שאין דורו דומה יפה","כי הוה ניחא נפשיה חזא ירמיהו שפוותיה דקא מרחשן אמר שמא ח\"ו מילתא דלא מהגנא אמר אגב צעריה גחין ושמעיה דקא מצדיק עליה דינא אנפשיה אמר (איכה א, יח) צדיק הוא ה' כי פיהו מריתי פתח עליה ההיא שעתא (איכה ד, כ) רוח אפינו משיח ה':","מעשה וירדו זקנים מירושלים לעריהם כו' איבעיא להו כמלא תנור תבואה או דלמא כמלא תנור פת","תא שמע כמלא פי תנור ועדיין תיבעי להו ככיסויא דתנורא או דלמא כי דרא דריפתא דהדר ליה לפומא דתנורא תיקו:","ועוד גזרו תענית על שאכלו זאבים כו' אמר עולא משום ר' שמעון בן יהוצדק מעשה ובלעו זאבים שני תינוקות והקיאום דרך בית הרעי ובא מעשה לפני חכמים וטיהרו את הבשר וטמאו את העצמות:","על אלו מתריעין בשבת כו': תנו רבנן עיר שהקיפוה נכרים או נהר ואחד ספינה המיטרפת בים ואחד יחיד שנרדף מפני נכרים או מפני לסטין ומפני רוח רעה על כולן יחיד רשאי לסגף את עצמו בתענית","רבי יוסי אומר אין היחיד רשאי לסגף את עצמו בתענית שמא יצטרך לבריות ואין הבריות מרחמות עליו אמר רב יהודה אמר רב מ\"ט דרבי יוסי דכתיב (בראשית ב, ז) ויהי האדם לנפש חיה נשמה שנתתי בך החייה:","שמעון התימני אומר אף על הדבר כו': איבעיא להו לא הודו לו חכמים בשבת אבל בחול הודו לו או דלמא לא הודו לו כלל","ת\"ש דתניא מתריעין על הדבר בשבת ואצ\"ל בחול ר' חנן בן פיטום תלמידו של ר' עקיבא משום רבי עקיבא אומר אין מתריעין על הדבר כל עיקר:","על כל צרה שלא תבא על הצבור כו': ת\"ר על כל צרה שלא תבא על הצבור מתריעין עליה חוץ מרוב גשמים מ\"ט אמר ר' יוחנן לפי שאין מתפללין על רוב הטובה","ואמר רבי יוחנן מניין שאין מתפללין על רוב הטובה שנאמר (מלאכי ג, י) הביאו את כל המעשר אל בית האוצר וגו' מאי עד בלי די אמר רמי בר רב (יוד) עד שיבלו שפתותיכם מלומר די","אמר רמי בר רב יוד ובגולה מתריעין עליה תניא נמי הכי שנה שגשמיה מרובין אנשי משמר שולחין לאנשי מעמד תנו עיניכם באחיכם שבגולה שלא יהא בתיהם קבריהם","שאלו את ר' אליעזר עד היכן גשמים יורדין ויתפללו שלא ירדו אמר להם כדי שיעמוד אדם בקרן אפל וישכשך רגליו במים והתניא ידיו רגליו כידיו קאמינא","אמר רבה בר בר חנה לדידי חזיא לי קרן אפל דקם ההוא טייעא כי רכיב גמלא ונקיט רומחא בידיה מתחזי איניבא","ת\"ר (ויקרא כו, ד) ונתתי גשמיכם בעתם לא שכורה ולא צמאה אלא בינונית שכל זמן שהגשמים מרובין מטשטשין את הארץ ואינה מוציאה פירות דבר אחר"],[[0,"","וישלח אליו מלאכים לאמר מה לי ולך מלך יהודה לא עליך אתה היום כי אל בית מלחמתי ואלהים אמר לבהלני חדל לך מאלהים אשר עמי וגו' לא עליך אני הולך היום – יאשיה יצא לקראתו למלחמה ולא נתנו לעבור בארצו ושלח לו פרעה נכה מלאכים לאמר כו':"],[1,"מאן אלהים","דקאמר ליה פרעה נכה חדל לך מאלהים אשר עמי:"],[2,"מלמד","מדכתיב ויורו המורים דמשמע יריות רבות יורו המורים:"],[2,"","אמר רב יהודה אמר רב מלמד שעשו כל גופו ככברה:"],[4,"הא כתיב ונתתי שלום בארץ","ולמאי הלכתא כתביה רחמנא לאידך קרא וחרב לא תעבור בארצכם אלא אפי' חרב של שלום:"],[4,"שאין דורו דומה יפה","בעיני המקום:"],[6,"איבעיא להו כמלא תנור תבואה","דהיינו שיעור גדול יותר ממלא תנור פת דשיעור קטן הוא שאין דרך למלאות כל חלל התנור פת אלא בדפנות מדביקין אותו:"],[7,"ת\"ש","דקתני חדא כי האי לישנא כמלא פי התנור דהיינו פת דאילו תבואה לא מצי קיימא על פי התנור:"],[7,"או דלמא כי דרא דריפתא","שורה של לחם הדבוקין זה אצל זה בפי התנור אי נמי שמדביקין זה למעלה מזה עד פי התנור:"],[8,"ובלען","כשהן שלימין:"],[8,"וטהרו את הבשר","שאינו מטמא טומאת מת דנתעכל ונתבטל תוך מעיו וכגון ששהו ימי עיכול ופירשא בעלמא הוא:"],[8,"וטימאו את העצמות","דלא מתעכלו:"],[9,"מפני רוח רעה","שנכנס בו רוח שידה ורץ והולך ושמא יטבע בנהר או יפול וימות:"],[9,"לסגף","לענות נפש מתרגמינן לסגפא נפש (במדבר ל׳:י״ד):"],[10,"יצטרך לבריות","כי אין בו כח להרויח ולהתפרנס מיגיעו:"],[10,"דכתיב לנפש חיה","החייה:"],[12,"חנן בן פטום אומר אין מתריעין על הדבר","אפי' בחול דגזירה היא:"],[14,"רמי בר רב יוד","חכם ששמו יוד:"],[15,"ובגולה","בבל שהיא במצולה:"],[15,"מתריעין על רוב גשמים","שלא ירדו:"],[15,"אנשי משמר ואנשי מעמד","מפרש בשלשה פרקים לקמן (תענית דף כו.):"],[15,"תנו עיניכם","התבוננו בתפלתכם בתעניות עליהם שלא ירדו רוב גשמים:"],[15,"שלא יהו בתיהם קבריהן","שעמוקה היא ונטבעים בתיהם במים:"],[16,"קרן אפל","שן סלע גבוה וכך שמו:"],[16,"וישכשך רגליו במים","כלומר לעולם אין מתפללין:"],[16,"והתניא ידו","עד שישכשך ידו:"],[16,"רגלו כידו","וכיון דיכול לשכשך ברגלו אי שוחה יכול לשכשך בידו נמי:"],[17,"טייעא","סוחר ישמעאל:"],[17,"ומיתחזי","האי טייעא וגמליה ורומחא לרבה בר בר חנה דהוה על קרן אפל:"],[17,"איניבא","תולעת ל\"א כי אנבא לינדינ\"א בלע\"ז:"],[18,"לא שכורה","לא שתויה יותר מדאי שמטשטשין את הארץ:"]],[[6,"","כמלא תנור תבואה או דלמא כמלא תנור פת. כמלא תנור תבואה הוי פי' כמלא חלל התנור תבואה דהיינו יותר ממלא תנור פת תא שמע כמלא פי תנור פת ואם כן מיירי בפת:"],[7,"","ועדיין תבעי לך כמלא פי תנור כמלא עגול פי תנור. דהיינו שורה של לחם סביבות פי התנור או דלמא כי דרא דריפתא ואהדר ליה לפומיה דתנורא שורות שורות של לחם זו למעלה מזו עד פי התנור:"],[8,"","וטהרו את הבשר. פירוש לפי שנתעכלו במעי הזאבים וטמאו את העצמות דלא מיעכלו:"],[9,"","ועל כולן רשאי לסגף עצמו בתענית. פי' לענות נפש מתרגמינן לסגפא נפש:"],[10,"","ר' יוסי אומר אין היחיד רשאי לסגף. ונ\"ל דהני תנאי ל\"פ בהא דמיירי הני אמוראי בפרקין דלעיל (תענית דף יא:) אם נקרא חוטא או נקרא קדוש וכו' דהאמוראי פליגי במצי לצעורי נפשיה והני תנאי פליגי בדלא מצי לצעורי נפשיה:"],[15,"","לאנשי משמר. פי' דהיינו אנשי מעמד דיש בישראל שהיו נחלקים למעמדות להתפלל שיתפללו על אחיהם שבגולה פי' לפי שגגותיהם שוים ונימוקים מחמת גשמים:"],[16,"","קרן אפל. פי' שם מקום:"],[17,"","אינבא. פירוש לנד\"א בלע\"ז מחמת גובהו של הר:"]]],[["בעתם בלילי רביעיות ובלילי שבתות","שכן מצינו בימי שמעון בן שטח שירדו להם גשמים בלילי רביעיות ובלילי שבתות עד שנעשו חטים ככליות ושעורים כגרעיני זיתים ועדשים כדינרי זהב וצררו מהם דוגמא לדורות להודיע כמה החטא גורם שנאמר (ירמיהו ה, כה) עונותיכם הטו אלה וחטאתיכם מנעו הטוב מכם","וכן מצינו בימי הורדוס שהיו עוסקין בבנין בהמ\"ק והיו יורדין גשמים בלילה למחר נשבה הרוח ונתפזרו העבים וזרחה החמה ויצאו העם למלאכתן וידעו שמלאכת שמים בידיהם:","מעשה ששלחו לחוני המעגל וכו': ת\"ר פעם אחת יצא רוב אדר ולא ירדו גשמים שלחו לחוני המעגל התפלל וירדו גשמים התפלל ולא ירדו גשמים עג עוגה ועמד בתוכה כדרך שעשה חבקוק הנביא שנאמר (חבקוק ב, א) על משמרתי אעמדה ואתיצבה על מצור וגו'","אמר לפניו רבונו של עולם בניך שמו פניהם עלי שאני כבן בית לפניך נשבע אני בשמך הגדול שאיני זז מכאן עד שתרחם על בניך התחילו גשמים מנטפין אמרו לו תלמידיו רבי ראינוך ולא נמות כמדומין אנו שאין גשמים יורדין אלא להתיר שבועתך","אמר לא כך שאלתי אלא גשמי בורות שיחין ומערות ירדו בזעף עד שכל טפה וטפה כמלא פי חבית ושיערו חכמים שאין טפה פחותה מלוג אמרו לו תלמידיו רבי ראינוך ולא נמות כמדומין אנו שאין גשמים יורדין אלא לאבד העולם","אמר לפניו לא כך שאלתי אלא גשמי רצון ברכה ונדבה ירדו כתיקנן עד שעלו כל העם להר הבית מפני הגשמים אמרו לו רבי כשם שהתפללת שירדו כך התפלל וילכו להם אמר להם כך מקובלני שאין מתפללין על רוב הטובה","אעפ\"כ הביאו לי פר הודאה הביאו לו פר הודאה סמך שתי ידיו עליו ואמר לפניו רבש\"ע עמך ישראל שהוצאת ממצרים אינן יכולין לא ברוב טובה ולא ברוב פורענות כעסת עליהם אינן יכולין לעמוד השפעת עליהם טובה אינן יכולין לעמוד יהי רצון מלפניך שיפסקו הגשמים ויהא ריוח בעולם מיד נשבה הרוח ונתפזרו העבים וזרחה החמה ויצאו העם לשדה והביאו להם כמהין ופטריות","שלח לו שמעון בן שטח אלמלא חוני אתה גוזרני עליך נידוי שאילו שנים כשני אליהו שמפתחות גשמים בידו של אליהו לא נמצא שם שמים מתחלל על ידך","אבל מה אעשה לך שאתה מתחטא לפני המקום ועושה לך רצונך כבן שמתחטא על אביו ועושה לו רצונו ואומר לו אבא הוליכני לרחצני בחמין שטפני בצונן תן לי אגוזים שקדים אפרסקים ורמונים ונותן לו ועליך הכתוב אומר (משלי כג, כה) ישמח אביך ואמך ותגל יולדתך","תנו רבנן מה שלחו בני לשכת הגזית לחוני המעגל (איוב כב, כח) ותגזר אומר ויקם לך ועל דרכיך נגה אור","ותגזר אומר אתה גזרת מלמטה והקדוש ברוך הוא מקיים מאמרך מלמעלה ועל דרכיך נגה אור דור שהיה אפל הארת בתפלתך","כי השפילו ותאמר גוה דור שהיה שפל הגבהתו בתפלתך ושח עינים יושיע דור ששח בעונו הושעתו בתפלתך ימלט אי נקי דור שלא היה נקי מלטתו בתפלתך ונמלט בבור כפיך מלטתו במעשה ידיך הברורין","אמר ר' יוחנן כל ימיו של אותו צדיק היה מצטער על מקרא זה (תהלים קכו, א) שיר המעלות בשוב ה' את שיבת ציון היינו כחולמים אמר מי איכא דניים שבעין שנין בחלמא","יומא חד הוה אזל באורחא חזייה לההוא גברא דהוה נטע חרובא אמר ליה האי עד כמה שנין טעין אמר ליה עד שבעין שנין אמר ליה פשיטא לך דחיית שבעין שנין אמר ליה האי [גברא] עלמא בחרובא אשכחתיה כי היכי דשתלי לי אבהתי שתלי נמי לבראי","יתיב קא כריך ריפתא אתא ליה שינתא נים אהדרא ליה משוניתא איכסי מעינא ונים שבעין שנין כי קם חזייה לההוא גברא דהוה קא מלקט מינייהו אמר ליה את הוא דשתלתיה א\"ל בר בריה אנא אמר ליה שמע מינה דניימי שבעין שנין חזא לחמריה דאתיילידא ליה רמכי רמכי","אזל לביתיה אמר להו בריה דחוני המעגל מי קיים אמרו ליה בריה ליתא בר בריה איתא אמר להו אנא חוני המעגל לא הימנוהו אזל לבית המדרש שמעינהו לרבנן דקאמרי נהירן שמעתתין כבשני חוני המעגל דכי הוי עייל לבית מדרשא כל קושיא דהוו להו לרבנן הוה מפרק להו אמר להו אנא ניהו לא הימנוהו ולא עבדי ליה יקרא כדמבעי ליה חלש דעתיה בעי רחמי ומית אמר רבא היינו דאמרי אינשי או חברותא או מיתותא","אבא חלקיה בר בריה דחוני המעגל הוה וכי מצטריך עלמא למיטרא הוו משדרי רבנן לגביה ובעי רחמי ואתי מיטרא זימנא חדא איצטריך עלמא למיטרא שדור רבנן זוגא דרבנן לגביה למבעי רחמי דניתי מיטרא אזול לביתיה ולא אשכחוהו אזול בדברא ואשכחוהו דהוה קא רפיק יהבו ליה שלמא"],[[0,"דכתיב בעתם","זהו בלילי רביעיות ובלילי שבתות דאין טורח לבני אדם דאינם הולכין לדרכים בלילי רביעיות מפני אגרת בת מחלת בפסחים (דף קיב:):"],[1,"שכן מצינו","כלומר ושמא תאמר אין סיפק בגשמים של ב' לילות בשבת מצינו בימי שמעון בן שטח כו':"],[1,"וצררו","קשרו ואצרו:"],[2,"הורדוס","סתר בנין דעזרא ובנה בנין יפה ממנו בב\"ב (דף ד.):"],[3,"עוגה","שורה עגולה כמו עוגה שהיא עגולה:"],[3,"כדרך שעשה חבקוק","כדמפרש בתרגום של תפלת חבקוק על משמרתי אעמדה כמין בית האסורים עשה וישב:"],[4,"ראינוך ולא נמות","נראה אותך ולא נמות בניחותא השתדל שלא נמות ברעב מפני עצירת גשמים:"],[7,"פר הודאה","להתודות עליו ועשה לו סמיכה והביאו שלמים חוני בזמן הבית היה:"],[7,"כמהין ופטריות","בוליי\"ץ בלע\"ז שיצאו מלחלוח הגשמים וידעו כי של ברכה היו:"],[8,"אלמלא חוני אתה","ואדם גדול:"],[8,"לנדות","שמנדין על כבוד הרב שהטיח דברים ואמר לא כך שאלתי:"],[8,"שאלמלא היו שנים כשני אליהו","גזירת עצירת גשמים:"],[8,"ומפתח של גשמים בידו של אליהו","גרסינן:"],[8,"לא נמצא שם שמים מתחלל","בתמיה שאליהו נשבע חי ה' אם יהיה השנים האלה טל ומטר כי אם לפי דברי (מלכים א י'ז:י') ואתה נשבע שאין אתה זז עד שירדו גשמים:"],[8,"נמצא שם שמים מתחלל על ידך","דזה או זה בא לידי שבועת שוא:"],[9,"מתחטא","לשון חטא כלומר הוי הולך וחוטא:"],[10,"לשכת הגזית","סנהדרין:"],[11,"דור שהיה אפל","מרוב צער שלא ירדו גשמים:"],[12,"הושעת בתפלתך","מן המיתה שהבאת עליהם שובע:"],[13,"של אותו צדיק","חוני המעגל היה מצטער על המקרא הזה:"],[13,"שיר המעלות","לשון עילוי:"],[13,"היינו כחולמים","כחלום נדמה גלות בבל שהיה שבעים שנה:"],[13,"שבעין שני בחלמא","בתמיה מי איתא דניים שבעין שנין בחלמיה ויש אדם ישן שבעים שנה בשינה אחת:"],[14,"עד שבעין שנין","לא טעין פירא בטעינא קמייתא:"],[14,"","הכי גרסי' אנא עלמא בחרובא אשכחתיה כי היכי דשתלי לי אבהתיי אנא נמי אישתיל לבראי:"],[15,"יתיב","חוני המעגל וקא כריך רפתא:"],[15,"אהדרא ליה משוניתא","עלתה סביבותיו שן סלע:"],[15,"ואיכסי מעינא דאינשי","ולא אשכחוהו התם:"],[15,"רמכי רמכי","וולדי וולדות באלו השנים דניים מעוברת זכר היתה וחזר ובא עליה והולידו:"],[16,"אמר להו","שאל להון בנו של חוני המעגל קיים הוא:"],[16,"נהירנא לן הנך שמעתתא","מוגהת לנו שמועה זו כאילו למדנוה בחייו של חוני המעגל שהיה מפרקה לנו ומגיה לנו יפה יפה:"],[16,"או חברותא או מיתותא","ולא גרסינן הכא כחברי דאיוב אלא בבבא בתרא (דף טז:) גבי מעשה דאיוב אם אין חביריו של אדם נוהגין בו כבוד כבתחילה נוח לו שימות אי נמי משום הנך בריוני לא כתוב בספרינו:"],[17,"רפיק בדברא","עודר בשדה:"]],[[0,"","בלילי רביעיות ובלילי שבתות. פי' שלא היו בני אדם הולכין בדרכים באותן לילות מפני אגרת בת מחלת כדמפרש במסכת פסחים (דף קיב:):"]]],[["ולא אסבר להו אפיה בפניא כי הוה מנקט ציבי דרא ציבי ומרא בחד כתפא וגלימא בחד כתפא כולה אורחא לא סיים מסאני כי מטי למיא סיים מסאניה כי מטא להיזמי והיגי דלינהו למניה כי מטא למתא נפקא דביתהו לאפיה כי מיקשטא כי מטא לביתיה עלת דביתהו ברישא והדר עייל איהו והדר עיילי רבנן יתיב וכריך ריפתא ולא אמר להו לרבנן תו כרוכו פלג ריפתא לינוקי לקשישא חדא ולזוטרא תרי","אמר לה לדביתהו ידענא דרבנן משום מיטרא קא אתו ניסק לאיגרא וניבעי רחמי אפשר דמרצי הקדוש ברוך הוא וייתי מיטרא ולא נחזיק טיבותא לנפשין סקו לאיגרא קם איהו בחדא זויתא ואיהי בחדא זויתא קדים סלוק ענני מהך זויתא דדביתהו כי נחית אמר להו אמאי אתו רבנן אמרו ליה שדרי לן רבנן לגבי דמר למיבעי רחמי אמיטרא אמר להו ברוך המקום שלא הצריך אתכם לאבא חלקיה","אמרו ליה ידעינן דמיטרא מחמת מר הוא דאתא אלא לימא לן מר הני מילי דתמיהא לן מאי טעמא כי יהיבנא למר שלמא לא אסבר לן מר אפיה אמר להו שכיר יום הואי ואמינא לא איפגר ומאי טעמא דרא מר ציבי אחד כתפיה וגלימא אחד כתפיה אמר להו טלית שאולה היתה להכי שאלי ולהכי לא שאלי","מאי טעמא כולה אורחא לא סיים מר מסאניה וכי מטי למיא סיים מסאניה אמר להו כולה אורחא חזינא במיא לא קא חזינא מ\"ט כי מטא מר להיזמי והיגי דלינהו למניה אמר להו זה מעלה ארוכה וזה אינה מעלה ארוכה","מאי טעמא כי מטא מר למתא נפקא דביתהו דמר כי מיקשטא אמר להו כדי שלא אתן עיני באשה אחרת מאי טעמא עיילא היא ברישא והדר עייל מר אבתרה והדר עיילינן אנן אמר להו משום דלא בדקיתו לי","מאי טעמא כי כריך מר ריפתא לא אמר לן איתו כרוכו משום דלא נפישא ריפתא ואמינא לא אחזיק בהו ברבנן טיבותא בחנם מאי טעמא יהיב מר לינוקא קשישא חדא ריפתא ולזוטרא תרי אמר להו האי קאי בביתא והאי יתיב בבי כנישתא","ומאי טעמא קדים סלוק ענני מהך זויתא דהוות קיימא דביתהו דמר לעננא דידיה משום דאיתתא שכיחא בביתא ויהבא ריפתא לעניי ומקרבא הנייתה [ואנא יהיבנא] זוזא ולא מקרבא הנייתיה אי נמי הנהו ביריוני דהוו בשיבבותן [אנא] בעי רחמי דלימותו והיא בעיא רחמי דליהדרו בתיובתא [ואהדרו]","חנן הנחבא בר ברתיה דחוני המעגל הוה כי מצטריך עלמא למיטרא הוו משדרי רבנן ינוקי דבי רב לגביה ונקטי ליה בשיפולי גלימיה ואמרו ליה אבא אבא הב לן מיטרא אמר לפני הקב\"ה רבש\"ע עשה בשביל אלו שאין מכירין בין אבא דיהיב מיטרא לאבא דלא יהיב מיטרא ואמאי קרי ליה חנן הנחבא מפני שהיה מחביא עצמו בבית הכסא","אמר ליה רבי זריקא לרב ספרא תא חזי [מה] בין תקיפי דארעא דישראל לחסידי דבבל חסידי דבבל רב הונא ורב חסדא כי הוה מצטריך עלמא למיטרא אמרי ניכניף הדדי וניבעי רחמי אפשר דמירצי הקדוש ברוך הוא דייתי מיטרא","תקיפי דארעא דישראל כגון ר' יונה אבוה דרבי מני כי הוה מצטריך עלמא למיטרא הוה עייל לביתיה ואמר להו הבו לי גואלקי ואיזיל ואייתי לי בזוזא עיבורא כי הוה נפיק לברא אזיל וקאי בדוכתא עמיקתא דכתיב (תהלים קל, א) ממעמקים קראתיך ה' וקאי בדוכתא צניעא ומכסי בשקא ובעי רחמי ואתי מיטרא כי הוה אתי לביתיה אמרי ליה אייתי מר עיבורא אמר להו אמינא הואיל ואתא מיטרא השתא רווח עלמא","ותו רבי מני בריה הוו קא מצערי ליה דבי נשיאה אישתטח על קברא דאבוה אמר ליה אבא אבא הני מצערו לי יומא חד הוו קא חלפי התם אינקוט כרעא דסוסוותייהו עד דקבילו עלייהו דלא קא מצערו ליה","ותו רבי מני הוה שכיח קמיה דרבי יצחק בן אלישיב אמר ליה עתירי דבי חמי קא מצערו לי אמר ליענו ואיענו אמר קא דחקו לי אמר ליעתרו ואיעתרו","אמר לא מיקבלי עלי אינשי ביתי א\"ל מה שמה חנה תתייפי חנה ונתייפת אמר ליה קא מגנדרא עלי א\"ל אי הכי תחזור חנה לשחרוריתה וחזרה חנה לשחרוריתה","הנהו תרי תלמידי דהוו קמיה דרבי יצחק בן אלישיב אמרו ליה ניבעי מר רחמי עלן דניחכים טובא אמר להו עמי היתה ושלחתיה","רבי יוסי בר אבין הוה שכיח קמיה דר' יוסי דמן יוקרת שבקיה ואתא לקמיה דרב אשי"],[[0,"לא אסבר להו אפיה","לא החזיר להם פניו:"],[0,"בפניא","לפנות ערב כשהלך לביתו:"],[0,"דלינהו למניה","הגביה בגדיו אחר כתיפיו כדי שלא יקרעו:"],[0,"כי מיקשטא","בתכשיטין:"],[1,"לאיגרא","עלייה:"],[1,"זויתא","זוית:"],[1,"מזויתא דדביתהו","מאותו הרוח שאשתו שם עלו העבים תחלה שהיא נענית תחלה:"],[2,"לא אפגר","לא אתבטל ממלאכתי כמו יומא דמיפגרי רבנן (שבת דף קכט:):"],[2,"מ\"ט דרת","מדוע נשאת הטלית על כתף אחת ולא נתת בכתף תחת המשאוי:"],[2,"להכי שאלה לי","להתעטף בה:"],[2,"ולהכי לא שאלה לי","להטיל עליה קוצין לקרעה:"],[3,"במיא לא חזינן","מה דאית בה ושמא ישכנו דג או נחש:"],[4,"דלא בדקיתו לי","אם כשרים אם פריצים דאמר מר (במס' דרך ארץ רבה פ\"ה) כל אדם יהי בעיניך כלסטים:"],[5,"טובת הנאה חנם","דאינהו לא הוו קא אכלי דליכא ריפתא וקא מחזקינן בהו טובה חנם:"],[5,"ינוקא קאי בבי כנישתא","קמי רביה ולא אתי כולי יומא:"],[6,"דאיתתא שכיחא בביתא","כל יומא וכי מיצטריך ענייא מידי אזלה ויהבה:"],[6,"ועוד דמקרבא הנייתה","שדבר אכילה היא נותנת לעני והוא בלא טורח ממה שהיתה נותנת מעות ויטריח העני עד שיקנה:"],[6,"אי נמי","אהכי קדים ענני דידה:"],[6,"משום ביריוני","בורים עמי הארץ:"],[7,"ינוקי דבי רב","להמריך לבו ויתכוין בתפלתו:"],[7,"בשיפולי","בשולי בגדיו:"],[7,"אבא אבא","כך רגילים לקרותו כיתום שאמר אבי אבי:"],[7,"שאין מכירין","בין חוני לאבא כסבורין עלי שאני אביהן:"],[7,"ה\"נ שהיה מחבא","ולא גרסי' שהיה מחבא בבית הכסא כי הוה בעי רחמי אמיא היה מחבא עצמו מרוב ענוה ומאן דגרס בית הכסא כלומר מתחבא בבגדיו כשהוא נכנס להסך את רגליו מרוב צניעות:"],[8,"רב הונא ורב חסדא","חסידי דבבל מפרסמין את הדבר ושל ארץ ישראל צנועין ולא מודיעין שבא המטר בשבילם:"],[8,"תא ליכניף אהדדי","אלמא משום חד מינייהו לא אתי מיטרא:"],[9,"תקיפי דארץ ישראל רבי יונה","וקא חזינן דמחמתיה אתי מיטרא:"],[9,"גואלקא","טשק\"א בלע\"ז:"],[9,"ואייתי בזוזא עיבורא","דגן משום כפנא שאפילו לבני ביתו לא היה מודיע:"],[9,"אייתי לן מר מעיבורא","דבעית למיזבן:"],[9,"רווחא עלמא","דליהוי שובע ואהכי לא זבני ביוקרא דהשתא:"],[10,"הוו קא חלפי","דבי נשיאה:"],[10,"התם","עלויה מערתא דרבי יונה:"],[10,"אינקוט","נדבקו בקרקע שעל גבי מערה ולא היו יכולין לזוז ממקומן:"],[11,"עתירי דבי חמי","עשירים של בית חמי:"],[11,"ליענו","יהיו עניים:"],[11,"קא דחקי לי","ליתן להן פרנסה:"],[12,"לא מקבלי עלי אינשי ביתי","אין אשתי מקובלת עלי שאינה יפה:"],[12,"מגנדרא","מתגדלת עלי מתוך גבהות יופיה. מגנדרא מלשון מקום הניחו לי אבותי להתגדר בו (חולין דף ז.):"],[13,"עמי היתה ושלחתיה","דבר זה היה בידי שכל מה שאני מבקש היו נותנין לי ועכשיו אין תפלתי מקובלת כל כך:"],[14,"דמן דיוקרת","מקום:"]],[]],[["יומא חד שמעיה דקא גריס אמר שמואל השולה דג מן הים בשבת כיון שיבש בו כסלע חייב א\"ל ולימא מר ובין סנפיריו אמר ליה ולא סבר לה מר דההיא רבי יוסי בן רבי אבין אמרה אמר ליה אנא ניהו","א\"ל ולאו קמיה דר' יוסי דמן יוקרת הוה שכיח מר א\"ל (הין) א\"ל ומ\"ט שבקיה מר ואתא הכא אמר ליה גברא דעל בריה ועל ברתיה לא חס עלי דידי היכי חייס","בריה מאי היא יומא חד הוו אגרי ליה אגירי בדברא נגה להו ולא אייתי להו ריפתא אמרו ליה לבריה כפינן הוו יתבי תותי תאינתא אמר תאנה תאנה הוציאי פירותיך ויאכלו פועלי אבא אפיקו ואכלו","אדהכי והכי אתא אבוה אמר להו לא תינקטו בדעתייכו דהאי דנגהנא אמצוה טרחנא ועד השתא הוא דסגאי אמרו ליה רחמנא לישבעך כי היכי דאשבען ברך אמר להו מהיכא אמרו הכי והכי הוה מעשה אמר לו בני אתה הטרחת את קונך להוציא תאנה פירותיה שלא בזמנה יאסף שלא בזמנו","ברתיה מאי היא הויא ליה ברתא בעלת יופי יומא חד חזיא לההוא גברא דהויא כריא בהוצא וקא חזי לה אמר לו מאי האי אמר ליה רבי אם ללוקחה לא זכיתי לראותה לא אזכה אמר לה בתי קא מצערת להו לברייתא שובי לעפריך ואל יכשלו ביך בני אדם","הויא ליה ההוא חמרא כדהוו אגרי לה כל יומא לאורתא הוו משדרי לה אגרה אגבה ואתיא לבי מרה ואי טפו לה או בצרי לה לא אתיא יומא חד אינשו זוגא דסנדלי עלה ולא אזלה עד דשקלונהו מינה והדר אזלה","אלעזר איש בירתא כד הוו חזו ליה גבאי צדקה הוו טשו מיניה דכל מאי דהוה גביה יהיב להו יומא חד הוה סליק לשוקא למיזבן נדוניא לברתיה חזיוהו גבאי צדקה טשו מיניה","אזל ורהט בתרייהו אמר להו אשבעתיכו במאי עסקיתו אמרו ליה ביתום ויתומה אמר להן העבודה שהן קודמין לבתי שקל כל דהוה בהדיה ויהב להו פש ליה חד זוזא זבן ליה חיטי ואסיק שדייה באכלבא","אתא דביתהו אמרה לה לברתיה מאי אייתי אבוך אמרה לה כל מה דאייתי באכלבא שדיתיה אתיא למיפתח בבא דאכלבא חזת אכלבא דמליא חיטי וקא נפקא בצינורא דדשא ולא מיפתח בבא מחיטי אזלא ברתיה לבי מדרשא אמרה ליה בא וראה מה עשה לך אוהבך אמר לה העבודה הרי הן הקדש עליך ואין לך בהן אלא כאחד מעניי ישראל","ר' יהודה נשיאה גזר תעניתא בעי רחמי ולא אתא מיטרא אמר כמה איכא משמואל הרמתי ליהודה בן גמליאל אוי לו לדור שכן נתקע אוי לו למי שעלתה בימיו כך חלש דעתיה ואתא מיטרא","דבי נשיאה גזר תעניתא ולא אודעינהו לרבי יוחנן ולריש לקיש לצפרא אודעינהו אמר ליה ריש לקיש לרבי יוחנן הא לא קבילנא עלן מאורתא אמר ליה אנן בתרייהו גררינן","דבי נשיאה גזר תעניתא ולא אתא מיטרא תנא להו אושעיא זעירא דמן חברייא (במדבר טו, כד) והיה אם מעיני העדה נעשתה לשגגה","משל לכלה שהיא בבית אביה כל זמן שעיניה יפות אין כל גופה צריכה בדיקה עיניה טרוטות כל גופה צריכה בדיקה","אתו עבדיה ורמו ליה סודרא בצואריה וקא מצערו ליה אמרו (ליה) בני מאתיה שבקיה דהא נמי מצער לן כיון דחזינן דכל מיליה לשום שמים לא אמרי ליה מידי ושבקינן ליה אתון נמי שבקוהו","רבי גזר תעניתא ולא אתא מיטרא נחית קמיה אילפא ואמרי לה רבי אילפי אמר משיב הרוח ונשא זיקא מוריד הגשם ואתא מיטרא אמר ליה מאי עובדך אמר ליה דיירנא בקוסטא דחיקא דלית ביה חמרא לקידושא ואבדלתא טרחנא ואתינא חמרא לקידושא ואבדלתא ומפיקנא להו ידי חובתייהו","רב איקלע לההוא אתרא גזר תעניתא ולא אתא מיטרא נחית קמיה שליחא דצבורא אמר משיב הרוח ונשב זיקא אמר מוריד הגשם ואתא מיטרא אמר ליה מאי עובדך אמר ליה מיקרי דרדקי אנא ומקרינא לבני עניי כבני עתירי וכל דלא אפשר ליה לא שקלינא מיניה מידי ואית לי פירא דכוורי וכל מאן דפשע משחדינא ליה מינייהו ומסדרינן ליה ומפייסינן ליה עד דאתי וקרי","רב נחמן גזר תעניתא בעא רחמי ולא אתא מיטרא אמר שקלוה לנחמן חבוטו מן גודא לארעא חלש דעתיה ואתא מיטרא","רבה גזר תעניתא בעי רחמי ולא אתא מיטרא אמרו ליה והא רב יהודה כי הוה גזר תעניתא אתא מיטרא אמר להו מאי אעביד אי משום תנויי אנן עדיפינן מינייהו דבשני דרב יהודה כל תנויי"],[[0,"יומא חד שמעיה","רב אשי לרבי יוסי בר אבין ל\"א יומא חד שמעיה רבי יוסי בר אבין לרב אשי דקא גריס אמר שמואל השולה דג מן הים בשבת כיון דיבש בו כסלע אע\"פ שהוא מפרכס לאחר כן ובעוד שהוא מפרכס השליכו במים חייב משום נטילת נשמה שהיא אב מלאכה דתנן (שבת דף עג.) השוחטו כו' אמר ליה רבי יוסי ובין סנפיריו דודאי לא חי וכשאין מחוסר צידה עסקינן כגון שצדו בתוך הסל והניחו במים לחיות כדרך שעושין הדייגין:"],[0,"א\"ל","רב אשי ולא סבר לה מר דהאי ובין סנפיריו רבי יוסי בר אבין אמרה כלומר מ\"ט לא אמרת ליה משמיה שכל האומר דבר בשם אומרו מביא גאולה לעולם:"],[0,"סנפיריו","שפורח בהן:"],[3,"לא תנקטו לי בדעתייכו","אל תחשדוני שלא הבאתי לכם מזונות עד עכשיו:"],[3,"דסגאי","שטרחתי ואיחרתי:"],[4,"דהוה כריא בהוצא","סותר גדר העצים כדי להסתכל דרך הנקב:"],[4,"אמר ליה רבי יוסי מאי האי","מה אתה מעיין כאן:"],[5,"אינשו","שכחו:"],[6,"טשו מפניו","היו מתחבאים:"],[7,"ביתום ויתומה","לזווג זה לזו:"],[7,"העבודה","שבועה:"],[7,"אכלבא","אוצר של חטים:"],[8,"אוהבך","הקב\"ה:"],[8,"אלא כאחד מעניי ישראל","משום דמעשה נסים הוא ואסור לאדם להנות ממעשה נסים כדאמר לעיל (תענית דף כ:) ואם עושין לו נס מנכין לו מזכיותיו:"],[9,"רבי יהודה נשיאה","היה בנו של רבן גמליאל בר רבי:"],[9,"לשמואל הרמתי","שיורדין גשמים בשבילו דכתיב הלא קציר חטים היום ועכשיו באין כל ישראל והטילו על ר' יהודה בן גמליאל דצווח וליכא דמשגח ביה:"],[9,"שנתקע","תקוע:"],[10,"והא לא קבלינן מאתמול","בהדייהו:"],[10,"גרירין","(גרירינן) גרורין ומשוכין אנו אחריהן וכמי שקבלנו עלינו:"],[11,"זעירא דמן חבריא","צעיר שבישיבה והאי דקרי ליה הכי משום דאושעיא אחרינא הוה התם:"],[11,"מעיני העדה","זקנים מאירי עיני העם:"],[12,"בזמן שעיניה יפות אין כל גופה וכו'","דודאי כל גופה יפה:"],[12,"אין עיניה יפות כו'","הואיל והנהו דבי נשיאה דהוו עיני העדה רשעים דלת העם אין צריכין לבדוק מה מעשיהם לכך לא משגחו בהו מן שמים:"],[13,"אתו עבדי דריש גלותא וקא מצערו ליה","לאושעיא:"],[13,"אמרו ליה בני מתא","לעבדי דבי נשיאה:"],[13,"מצער לן","מחרף ומגדף אותנו:"],[14,"נחית קמיה","לפני התיבה:"],[14,"נשא","כמו נשב:"],[14,"בקוסטא דחיקא","בכפר דחוק שיש בו עניות ביותר:"],[15,"פירא דכוורי","מחילות של דגים:"],[15,"כל מאן דפשע","דלא בעי מיקרי משחדינא ליה כו':"],[15,"ומסדרינא ליה ומפייסינא ליה","מתקנן כסדר:"]],[[0,"","השולה דג מן הים. שולה כמו מגביה כיון שיבש בו כסלע שעדיין הוא מפרכס ובשעה שמפרכס חזר והשליכו לים חייב משום נטילת נשמה שהיא אב מלאכה דתנן (שבת דף עג.) השוחטו והמפשיטו גבי אבות מלאכות:"]]],[["בנזיקין הוה ואנן קא מתנינן בשיתא סדרין וכי הוה מטי רב יהודה בעוקצין האשה שכובשת ירק בקדירה ואמרי לה זיתים שכבשן בטרפיהן טהורין אמר הויי' דרב ושמואל קא חזינא הכא","ואנן קא מתנינן בעוקצין תליסר מתיבתא ואילו רב יהודה כי הוה שליף חד מסאנא אתי מיטרא ואנן קא צווחינן כולי יומא וליכא דאשגח בן אי משום עובדא אי איכא דחזא מידי לימא אבל מה יעשו גדולי הדור שאין דורן דומה יפה","רב יהודה חזא הנהו בי תרי דהוו קא פרצי בריפתא אמר שמע מינה איכא שבעא בעלמא יהיב עיניה הוה כפנא אמרו ליה רבנן לרב כהנא בריה דרב נחוניא שמעיה מר דשכיח קמיה ניעשייה דליפוק בפתחא דסמוך לשוקא עשייה ונפק לשוקא חזא כנופיא","אמר להו מאי האי אמרו ליה אכוספא דתמרי קיימי דקא מזדבן אמר שמע מינה כפנא בעלמא אמר ליה לשמעיה שלוף לי מסאניי שלף ליה חד מסאנא ואתא מיטרא כי מטא למישלף אחרינא אתא אליהו ואמר ליה אמר הקדוש ברוך הוא אי שלפת אחרינא מחריבנא לעלמא","אמר רב מרי ברה דבת שמואל אנא הוה קאימנא אגודא דנהר פפא חזאי למלאכי דאידמו למלחי דקא מייתי חלא ומלונהו לארבי והוה קמחא דסמידא אתו כולי עלמא למיזבן אמר להו מהא לא תיזבנון דמעשה נסים הוא למחר אתיין ארבי דחיטי דפרזינא","רבא איקלע להגרוניא גזר תעניתא ולא אתא מיטרא אמר להו ביתו כולי עלמא בתעניתייכו למחר אמר להו מי איכא דחזא חילמא לימא אמר להו ר' אלעזר מהגרוניא לדידי אקריון בחלמי שלם טב לרב טב מריבון טב דמטוביה מטיב לעמיה אמר שמע מינה עת רצון היא מבעי רחמי בעי רחמי ואתי מיטרא","ההוא גברא דאיחייב נגדא בבי דינא דרבא משום דבעל כותית נגדיה רבא ומית אשתמע מילתא בי שבור מלכא בעא לצעורי לרבא אמרה ליה איפרא הורמיז אימיה דשבור מלכא לברה לא ליהוי לך עסק דברים בהדי יהודאי דכל מאן דבעיין ממרייהו יהיב להו","אמר לה מאי היא בעין רחמי ואתי מיטרא אמר לה ההוא משום דזימנא דמיטרא הוא אלא לבעו רחמי האידנא בתקופת תמוז וליתי מיטרא שלחה ליה לרבא כוין דעתך ובעי רחמי דליתי מיטרא בעי רחמי ולא אתי מיטרא","אמר לפניו רבונו של עולם (תהלים מז, ב) אלהים באזנינו שמענו אבותינו ספרו לנו פועל פעלת בימיהם בימי קדם ואנו בעינינו לא ראינו אתא מיטרא עד דשפוך מרזבי דצפורי לדיגלת אתא אבוה איתחזי ליה בחלמיה ואמר ליה מי איכא דמיטרח קמי שמיא כולי האי אמר ליה שני דוכתיך שני דוכתיה למחר אשכחיה דמרשם פורייה בסכיני","רב פפא גזר תעניתא ולא אתא מיטרא חלש ליביה שרף פינכא דדייסא ובעי רחמי ולא אתא מיטרא אמר ליה רב נחמן בר אושפזתי אי שריף מר פינכא אחריתי דדייסא אתי מיטרא איכסיף וחלש דעתיה ואתא מיטרא","ר' חנינא בן דוסא הוה קא אזיל באורחא אתא מיטרא אמר לפניו רבונו של עולם כל העולם כולו בנחת וחנינא בצער פסק מיטרא כי מטא לביתיה אמר לפניו רבונו של עולם כל העולם כולו בצער וחנינא בנחת אתא מיטרא","אמר רב יוסף מאי אהניא ליה צלותא דכהן גדול לגבי רבי חנינא בן דוסא דתנן היה מתפלל תפלה קצרה בבית החיצון מאי מצלי רבין בר אדא ורבא בר אדא דאמרי תרוייהו משמיה דרב יהודה יהי רצון מלפניך ה' אלהינו שתהא השנה הזו גשומה ושחונה שחונה מעלייתא היא אדרבה גריעותא היא","אלא אם שחונה תהא גשומה וטלולה ואל יכנס לפניך תפלת עוברי דרכים רב אחא בריה דרבא מסיים משמיה דרב יהודה לא יעדי עביד שולטן מדבית יהודה ואל יהו עמך ישראל צריכין להתפרנס זה מזה ולא לעם אחר","אמר רב יהודה אמר רב בכל יום ויום בת קול יוצאת ואומרת כל העולם כולו ניזון בשביל חנינא בני וחנינא בני דיו בקב חרובים מע\"ש לע\"ש הוה רגילא דביתהו למיחמא תנורא כל מעלי דשבתא ושדייא אקטרתא"],[[0,"ה\"ג בנזיקין הוה","למודם לא היה גדול אלא בסדר נזיקין:"],[0,"שכובשת ירק בקדירה","במסכת [טהרות] היא בפ' שני (מ\"א) גבי ידות מיירי דקיי\"ל (עוקצין פ\"א משנה א) כל ידות האוכלין אם נגעה טומאה בהן נטמא גם האוכל הצריך לידות דיד מכניס ומוציא כדאמרינן בהעור והרוטב (חולין דף קיח.) מכל האוכל לרבות הידות וקתני התם אשה שהיא כובשת ירק דידות שלהן טהורין דכשהיא עוצרת אותם הידות משתברות וא\"א ליטול הירקות בידות שלהן שנשמט ונפסק האוכל מן היד מחמת כבישה:"],[0,"כובשת","שול\"ץ בלע\"ז עוצרת שיצא המשקה שלהן ויבשו דרך אשה בכך כובשת ירק ממים שישתמרו לזמן מרובה:"],[0,"ואמרי לה","כי מטא לאידך בפרק שני (דעוקצין משנה א) זיתים שכבשן בטרפיהן כתרגומו עלה טרפא (בראשית ח) עלין שלהן דהיינו ידות:"],[0,"טהורין","העלין והקלחין:"],[0,"טהורין","הידות להביא טומאה לאוכל דתו לא חזי למהוי בית יד:"],[0,"הוויות דרב ושמואל","עומק גדול ולא הוה נהירא ליה:"],[1,"תליסר מתיבתא","שלש עשרה ישיבות איכא בהך מתא דגמרי מסכת עוקצין:"],[1,"כי הוה שליף חד מסאנא","משום עינוי:"],[1,"דחזא מידי","חס ושלום בעובדי בישי:"],[2,"פרצי בריפתא","זורקים אותם זה לזה:"],[2,"ניעשייה","יעשנו שיצא לחוץ:"],[3,"אכוספא דתמרי","על כלי מלא תמרים או פסולת של תמרים:"],[4,"קאימנא אנהר פפא","ההוא יומא דעבד רב יהודה הכי:"],[4,"חלא","חול:"],[4,"דסמידא","סולת והן עצמן מוכרין אותו:"],[4,"אמר להו מעשה נסים כו'","ובמה דאפשר להתרחק ממעשה נסים יותר טוב ונכון:"],[4,"דפרזינא","מקום:"],[5,"אקרון","הקרוני הייתי קורא בחלומי:"],[6,"נגדא","מלקות:"],[6,"איפרא הורמיז","כך שמה איפרא חן יופי שדים היה לה:"],[7,"מאי היא","מאי עביד להו:"],[7,"אמרה ליה","דכל אימת דבעי מיטרא:"],[7,"זימנא דמיטרא הוא","ואפילו לא בעו נמי אתי מיטרא:"],[7,"שלחה ליה לרבא","דרחמא ליה לרבא:"],[8,"אבותינו ספרו לנו פועל פעלת בימיהם בימי קדם","שהיית מפליא להם נסים:"],[8,"עד דשפיך מרזבי דציפורי","שקילחו מים מן המרזיבות עד ששוטפין בחוצות ויורדין ושופכין:"],[8,"לדיגלת","לנהר חדקל:"],[8,"אשני מטתך","אל תשכב במטתך הלילה:"],[8,"בסכיני","שרצו שדים להורגו וחתכו את מטתו והיינו דאמרי' בשחיטת חולין בפרק הזרוע (חולין דף קלג.) וליקריוה לרבא רבא נזוף היה לא מצינו לו נזיפה בכל הש\"ס אלא בזה המעשה כשביקש הגשמים בתמוז שלא לצורך:"],[9,"","הכי גרסינן ר\"פ גזר תעניתא חלש לביה טעים מידי בעא רחמי ולא אתא מיטרא:"],[9,"אי שריף מר חדא פינכא דדייסא","מלשון שורפה חיה (ע\"ז דף כט:) פינכא מלא כף כמו מלחיך פינכי (פסחים דף מט.) דייסא טריי\"ס בלע\"ז ולחוכא קאמר ליה הכי משום דטעים ברישא והדר בעא רחמי:"],[10,"רבי חנינא בן דוסא","תנא הוא:"],[10,"כל העולם כולו בצער","שמבקשין מים לשדותיהן:"],[10,"בנחת","שאני יושב בביתי ואיני צריך לגשמים לפי שאין לי שדות:"],[11,"מאי אהניא ליה צלותיה דכהן גדול","כשהיה מתפלל תפלה קצרה ביום הכפורים שהיה אומר אל יכנס לפניך תפלת עוברי דרכים דר' חנינא מבטל ליה לצלותיה דכהן גדול שאעפ\"כ שמע הקב\"ה תפלתו ופסיק מיטרא:"],[11,"שחונה","חמה כמו חמותי ראיתי אור (ישעיהו מ״ד:ט״ז) תירגם יונתן בן עוזיאל שחינת:"],[12,"אם שחונה תהא גשומה","כשהיא חמה צריכה הארץ לגשמים מאד ותדיר:"],[13,"בת קול יוצאת ואומרת כל העולם כולו","ולא גרסי' מהר חורב:"],[13,"קב חרובים מערב שבת לערב שבת","כל השבת היה ניזון בכך חסר לחם היה ומתגלגל היה בחרובין:"],[13,"אקטרתא","דבר שמעלה עשן כקיטור הכבשן:"]],[]],[["משום כיסופא הוה לה הך שיבבתא בישתא אמרה מכדי ידענא דלית להו ולא מידי מאי כולי האי אזלא וטרפא אבבא איכספא ועיילא לאינדרונא","איתעביד לה ניסא דחזיא לתנורא מלא לחמא ואגנא מלא לישא אמרה לה פלניתא פלניתא אייתי מסא דקא חריך לחמיך אמרה לה אף אנא להכי עיילי תנא אף היא להביא מרדה נכנסה מפני שמלומדת בנסים","אמרה ליה דביתהו עד אימת ניזיל ונצטער כולי האי אמר לה מאי נעביד בעי רחמי דניתבו לך מידי בעא רחמי יצתה כמין פיסת יד ויהבו ליה חד כרעא דפתורא דדהבא (חזאי) בחלמא עתידי צדיקי דאכלי אפתורא דדהבא דאית ליה תלת כרעי (ואת) אוכלת אפתורא דתרי כרעי","(אמרה ליה) ניחא לך דמיכל אכלי כולי עלמא אפתורא דמשלם ואנן אפתורא דמחסר אמרה ליה ומאי נעביד בעי רחמי דנשקלינהו מינך בעי רחמי ושקלוהו תנא גדול היה נס אחרון יותר מן הראשון דגמירי דמיהב יהבי מישקל לא שקלי","חד בי שמשי חזייה לברתיה דהוות עציבא אמר לה בתי למאי עציבת אמרה ליה כלי של חומץ נתחלף לי בכלי של שמן והדלקתי ממנו אור לשבת אמר לה בתי מאי איכפת לך מי שאמר לשמן וידלוק הוא יאמר לחומץ וידלוק תנא היה דולק והולך כל היום כולו עד שהביאו ממנו אור להבדלה","ר' חנינא בן דוסא הוו ליה הנך עיזי אמרו ליה קא מפסדן אמר אי קא מפסדן ניכלינהו דובי ואי לא כל חדא וחדא תיתי לאורתא דובא בקרנייהו לאורתא אייתי כל חדא וחדא דובא בקרנייהו","הוה ליה ההיא שיבבתא דקא בניא ביתא ולא מטו כשורי אתיא לקמיה אמרה ליה בניתי ביתי ולא קמטו כשוראי אמר לה מה שמך אמרה ליה איכו אמר איכו נימטו כשוריך","תנא הגיעו עד שיצאו אמה לכאן ואמה לכאן ויש אומרין סניפין עשאום תניא פלימו אומר אני ראיתי אותו הבית והיו קורותיו יוצאות אמה לכאן ואמה לכאן ואמרו לי בית זה שקירה ר' חנינא בן דוסא בתפלתו","ור' חנינא בן דוסא מהיכן הוו ליה עזים והא עני הוי ועוד אמרו חכמים אין מגדלין בהמה דקה בא\"י אמר רב פנחס מעשה ועבר אדם אחד על פתח ביתו והניח שם תרנגולין ומצאתן אשתו של ר' חנינא בן דוסא","ואמר לה אל תאכלי מביציהן והרבו ביצים ותרנגולין והיו מצערין אותם ומכרן וקנה בדמיהן עזים פעם אחת עבר אותו אדם שאבדו ממנו התרנגולין ואמר לחבירו בכאן הנחתי התרנגולין שלי שמע ר' חנינא אמר לו יש לך בהן סימן אמר לו הן נתן לו סימן ונטל את העזין והן הן עיזי דאייתו דובי בקרנייהו","רבי אלעזר בן פדת דחיקא ליה מילתא טובא עבד מלתא ולא הוה ליה מידי למטעם שקל ברא דתומא ושדייה בפומיה חלש לביה ונים אזול רבנן לשיולי ביה חזיוהו דקא בכי וחייך ונפק צוציתא דנורא מאפותיה","כי אתער אמרו ליה מ\"ט קבכית וחייכת אמר להו דהוה יתיב עמי הקב\"ה ואמרי ליה עד מתי אצטער בהאי עלמא ואמר לי אלעזר בני ניחא לך דאפכיה לעלמא מרישא אפשר דמתילדת בשעתא דמזוני","אמרי לקמיה כולי האי ואפשר אמרי ליה דחיי טפי או דחיינא א\"ל דחיית אמרי לקמיה א\"כ לא בעינא","אמר לי בהאי אגרא דאמרת לא בעינא יהיבנא לך לעלמא דאתי תליסרי נהרוותא דמשחא אפרסמון דכיין כפרת ודיגלת דמענגת בהו אמרי לקמיה האי ותו לא אמר לי ולחברך מאי יהיבנא אמרי ליה ואנא מגברא דלית ליה בעינא מחיין באסקוטלא אפותאי ואמר לי אלעזר ברי גירי בך גירי","ר' חמא בר חנינא גזר תעניתא ולא אתא מיטרא אמרו ליה והא רבי יהושע בן לוי גזר תעניתא ואתי מיטרא אמר להו הא אנא הא בר ליואי אמרו ליה דניתי וניכוין דעתין איפשר דתברי ציבורא לבייהו דאתי מיטרא בעון רחמי ולא אתי מיטרא","אמר להו ניחא לכו שיבא מטר בשבילנו אמרו ליה הן אמר רקיע רקיע כסי פניך לא איכסי אמר כמה עזין פני רקיע איכסי ואתא מיטרא","לוי גזר תעניתא ולא אתא מיטרא אמר לפניו רבונו של עולם עלית וישבת במרום ואין אתה מרחם על בניך אתא מיטרא ואיטלע אמר רבי אלעזר לעולם אל יטיח אדם דברים כלפי מעלה שהרי אדם גדול הטיח דברים כלפי מעלה ואיטלע ומנו לוי","והא גרמא ליה והא לוי אחוי קידה קמיה דרבי ואיטלע הא והא גרמא ליה","רבי חייא בר לולייני שמעינהו להנך ענני דקאמרי ניתו וניתבי מיא בעמון ומואב אמר לפניו רבונו של עולם כשנתת תורה לעמך ישראל חזרת על כל אומות העולם ולא קיבלוה ועכשיו אתה נותן להם מטר שדו הכא שדיוה אדוכתיהו","דרש רבי חייא בר לולייני מאי דכתיב (תהלים צב, יג) צדיק כתמר יפרח כארז בלבנון ישגה אם נאמר תמר למה נאמר ארז ואם נאמר ארז למה נאמר תמר אילו נאמר תמר ולא נאמר ארז הייתי אומר מה תמר"],[[0,"משום כיסופא","שהיו שכינותיה אופות עיסה לכבוד שבת והיא אינה עושה כלום:"],[1,"אגנא","עריבה:"],[1,"מסא","עתר שמוציאין בו הלחם מרדה פאלי\"א בלע\"ז ומרדה ומסא חדא מילתא היא:"],[1,"תנא אף היא להביא מרדה נכנסה","פל\"א בלע\"ז על שם שרודין בה פת מן התנור שלא היתה שואלת מפני שרגילה בניסין:"],[2,"חזיא","דביתהו בחלמא:"],[3,"מישקל לא שקלי","בתר דיהבי:"],[4,"","כל היכא דתני בי שמשי היינו ערב שבת לא שמעתי טעם:"],[4,"במנא דחלא","בכלי שיש בו החומץ ושמתי החומץ בנר ויכבה הנר:"],[4,"עד שנטלו ממנו אור להבדלה","הדליק ממנו נר אחר ליהנות בו ונר של מעשה נסים כיבה כי היכי דעבד רב יהודה (לעיל תענית דף כד:) בחלא דהוה סמידא:"],[5,"קא מפסדי לן","שדות:"],[5,"דובים","וזאבים בשדות:"],[6,"ולא מטו כשורי","אין הקורות מגיעות מכותל לכותל:"],[6,"איכו נימטו כשוריך","יאריכו הקורות:"],[7,"סניפין היו","הקורות של חליות היו במעשה נס נדבקו להן חתיכות קטנות לאורכן:"],[10,"ר\"א בן פדת","אמורא היה והוא הנקרא מרא דארעא דא\"י במסכת נדה (דף כ:) בעל הוראות היה והוא שימש רבי יוחנן אחרי מות ריש לקיש והיה דחוק ועני:"],[10,"עבד מילתא","הקיז דם:"],[10,"ברא דתומא","בן השום צלע של שום:"],[10,"חלש ליביה","נתעלפה:"],[10,"צוציתא","ניצוץ:"],[10,"מאפותיה","ממצחו:"],[12,"כולי האי ואפשר","בתמיה כולי האי עבדת ואכתי הך ספיקא דלמא לא מיתרמינא בשעתא דמזוני:"],[12,"דחיי נפישא או דחיינא","ימי חיי שחייתי כבר הם רבים ממה שאני עתיד לחיות:"],[12,"אמר דחיית","מה שכבר חיית מרובים ממה שאתה עתיד לחיות והיינו דקא בכי כי אמר שכינה הכי והאי דחייך משום י\"ג נהרוותא לרחוץ בהן ולטייל בהן מזה לזה:"],[12,"אי הכי לא בעינא","דתיחרביה לעלמא:"],[13,"ותו לא","וכי אין אתה נותן לי דברים אחרים:"],[13,"א\"ל ולחברך מאי קא יהבינא","אנא מגברא דלית ליה בעינא לא גריס בספר רבי ובספר שלי כתוב:"],[13,"באסקטולא אפותאי","היינו צוציתא דנפק מיניה שמדביק אצבע צרדא עם הגודל ומכה בצפורן האצבע:"],[13,"איגרו בך גירי","כלומר הכיתי בחיצי לחדווה בעלמא אמר כן:"],[14,"הא אנא והא בר ליואי","הוא איש אחד ואני איש אחד הוא עדיף מינאי:"],[14,"דתברי","שוברים:"],[15,"שיבא מטר בשבילנו","מקבלים אתם עליכם ומסכימין לדעת אחד:"],[15,"כמה עזין","דלא כסין מצבורא:"],[17,"לוי אחוי קידה","נועץ שני גודליו בארץ ושוחה ונושק את הרצפה:"],[17,"הא והא גרמא ליה","החטא גרם לו שנצלע בקידה:"]],[[17,"","הא והא גרמו ליה. פי' הראב\"ד הא כדעבד דאחוי הקידה קמי רבי איטלע והא דהטיח דברים כלפי מעלה גרמא ליה דאיטלע:"]]],[["אין גזעו מחליף אף צדיק ח\"ו אין גזעו מחליף לכך נאמר ארז אילו נאמר ארז ולא נאמר תמר הייתי אומר מה ארז אין עושה פירות אף צדיק ח\"ו אין עושה פירות לכך נאמר תמר ונאמר ארז","וארז גזעו מחליף והתניא הלוקח אילן מחבירו לקוץ מגביהו מן הקרקע טפח וקוצץ בסדן השקמה שני טפחים בבתולת השקמה שלשה טפחים בקנים ובגפנים מן הפקק ולמעלה בדקלים ובארזים חופר למטה ומשריש לפי שאין גזעו מחליף","הכא במאי עסקינן בשאר מיני ארזים כדרבה בר הונא דאמר רבה בר הונא עשרה מיני ארזים הן שנאמר (ישעיהו מא, יט) אתן במדבר ארז שיטה והדס וגו'","ת\"ר מעשה ברבי אליעזר שגזר שלש עשרה תעניות על הצבור ולא ירדו גשמים באחרונה התחילו הצבור לצאת אמר להם תקנתם קברים לעצמכם געו כל העם בבכיה וירדו גשמים","שוב מעשה בר' אליעזר שירד לפני התיבה ואמר עשרים וארבע ברכות ולא נענה ירד רבי עקיבא אחריו ואמר אבינו מלכנו אין לנו מלך אלא אתה אבינו מלכנו למענך רחם עלינו וירדו גשמים הוו מרנני רבנן יצתה בת קול ואמרה לא מפני שזה גדול מזה אלא שזה מעביר על מדותיו וזה אינו מעביר על מדותיו","ת\"ר עד מתי יהו הגשמים יורדין והצבור פוסקין מתעניתם כמלא ברך המחרישה דברי רבי מאיר וחכמים אומרים בחרבה טפח בבינונית טפחיים בעבודה שלשה טפחים","תניא רבי שמעון בן אלעזר אומר אין לך טפח מלמעלה שאין תהום יוצא לקראתו שלשה טפחים והא תניא טפחיים לא קשיא כאן בעבודה כאן בשאינה עבודה","א\"ר אלעזר כשמנסכין את המים בחג תהום אומר לחבירו אבע מימיך קול שני ריעים אני שומע שנאמר (תהלים מב, ח) תהום אל תהום קורא לקול צנוריך וגו'","אמר רבה לדידי חזי לי האי רידיא דמי לעיגלא (תלתא) ופירסא שפוותיה וקיימא בין תהומא תתאה לתהומא עילאה לתהומא עילאה א\"ל חשור מימיך לתהומא תתאה א\"ל אבע מימיך שנא' (שיר השירים ב, יב) הנצנים נראו בארץ וגו':","היו מתענין וירדו גשמים קודם הנץ החמה כו': ת\"ר היו מתענין וירדו להם גשמים קודם הנץ החמה לא ישלימו לאחר הנץ החמה ישלימו דברי ר' מאיר ר' יהודה אומר קודם חצות לא ישלימו לאחר חצות ישלימו","רבי יוסי אומר קודם ט' שעות לא ישלימו לאחר ט' שעות ישלימו שכן מצינו באחאב מלך ישראל שהתענה מתשע שעות ולמעלה שנאמר (מלכים א כא, כט) הראית כי נכנע אחאב וגו'","ר' יהודה נשיאה גזר תעניתא וירדו להם גשמים לאחר הנץ החמה סבר לאשלומינהו א\"ל רבי אמי קודם חצות ואחר חצות שנינו שמואל הקטן גזר תעניתא וירדו להם גשמים קודם הנץ החמה כסבורין העם לומר שבחו של צבור הוא","אמר להם אמשול לכם [משל] למה הדבר דומה לעבד שמבקש פרס מרבו אמר להם תנו לו ואל אשמע קולו","שוב שמואל הקטן גזר תעניתא וירדו להם גשמים לאחר שקיעת החמה כסבורים העם לומר שבחו של צבור הוא אמר להם שמואל לא שבח של צבור הוא אלא אמשול לכם משל למה הדבר דומה לעבד שמבקש פרס מרבו ואמר להם המתינו לו עד שיתמקמק ויצטער ואחר כך תנו לו","ולשמואל הקטן שבחו של צבור היכי דמי אמר משיב הרוח ונשב זיקא אמר מוריד הגשם ואתא מיטרא:","מעשה וגזרו תענית בלוד כו': ונימא הלל מעיקרא אביי ורבא דאמרי תרווייהו לפי שאין אומרים הלל"],[[0,"ואין גזעו מחליף","אם נפסק:"],[0,"אף צדיק","אין לו זכר צדיק אין גזעו מחליף אינו בתחיית המתים:"],[0,"צדיק אינו עושה פירות","אין לו שכר לעתיד:"],[1,"בתולת השקמה","נטיעה שלא נקצצה מעולם:"],[1,"סדן","שכבר הזקין טרונ\"ק בלע\"ז שנקצץ וחוזר ומתעבה והוא מלשון סדנא בסדניה יתיב (פסחים דף כח.):"],[1,"שני טפחים","שכבר גזעו מחליף:"],[1,"מן הפקק","קשר התחתון:"],[2,"מיני ארזים","שנאמר אתן במדבר ארז שטה והדס וגו'. ובציר להו תלת ובראש השנה (דף כג.) מפרש הוסיפו עליהם אלונים אלמונים אלמוגים:"],[3,"מעשה ברבי אליעזר בן הורקנוס","י\"ג תעניות שהתענו והלכו עד שגמרו י\"ג כדתנן (לעיל תענית דף יב:) עברו אלו ולא נענו כו':"],[3,"התחילו הצבור לצאת","מבית הכנסת:"],[3,"קברים תקנתם","בתמיה אין לכם אלא לכו קברו עצמכם מפני הרעב:"],[3,"געו","צעקו כמו אם יגעה שור על בלילו (איוב ו׳:ה׳) הלוך וגעו (שמואל א ו):"],[5,"ויהיו הצבור פוסקין מתעניתם","דתנן (שם) עברו אלו ולא נענו ב\"ד גוזרין עוד כו' אבל נענו שוב אין צריכין להתענות והני מילי צבור אבל יחיד שהיה מתענה על החולה ונתרפא או על צרה ועברה הרי מתענה ומשלים כדאמרן לעיל (תענית דף י:) כך שמעתי:"],[5,"כמלא ברך המחרישה","אם טשטשו הגשמים בעומק הקרקע כשיעור שורת מענית המחרישה:"],[5,"ברך","הוא הכלי שחורשין בו ומבריכין אותו סמוך לקרקע כשחורשין בו כלומר מילא התלם שיראו המים בתלם מחרישתו שקורין קולטר\"א:"],[5,"בחרבה","קרקע יבישה טפח כיון דחריבה היא ונכנסו בה הגשמים טפח ודאי רוב גשמים ירדו:"],[5,"בעבודה","חרושה כגון שדה ניר הנכנסים בה גשמים הרבה ג' טפחים דאפי' בגשמים מועטין נכנסין בה בטפח או בטפחיים:"],[6,"אין לך כל טפח","כשנכנסו הגשמים בעומק הקרקע טפח תהום עולה ומתגבר ג' טפחים ואע\"ג דסומכא דארעא אלפא גרמידי בפרק החליל (סוכה דף נג:) אפ\"ה רטיבותא מהנייא:"],[6,"והתניא","תהום יוצא לקראתו ב' טפחים:"],[6,"הא דקתני טפחיים ותו לא בעבודה","דאע\"ג דנכנסו טפח בקרקע פורתא הוא דנחית ואהכי לא נפיק בהו לקבליה שלשה טפחים אלא פורתא טפחיים:"],[6,"בשאינה עבודה","דכי נכנסו בה טפח טפי הוא דנחית ונפיק תהום לקיבליה ג' טפחים:"],[7,"אבע","לשון נחל נובע:"],[7,"קול שני ריעים","ניסוך המים וניסוך היין:"],[7,"תהום אל תהום קורא","מים עליונים ומים תחתונים:"],[7,"צנוריך","אותן שני ספלים:"],[8,"האי רידיא","מלאך הממונה על הגשמים כך שמו:"],[8,"דמי לעיגלא","ול\"ג תלתא:"],[8,"בין תהומא עילאה לתתאה","בין הרקיע לאוקיינוס היכא דנשקי ארעא ורקיע:"],[8,"תהומא עלאה","מים העליונים:"],[8,"חשור מימיך","ברקיע:"],[8,"אבע מימיך","למטה בקרקע:"],[8,"הנצנים נראו בארץ","כלומר כשמנסכין מים בחג שהניסוכין נראו בארץ שאין באין אלא משנה לחבירתה כנץ זה שאינו יוצא אלא משנה לשנה ועת הזמיר הגיע זמירות החג אז קול התור מלאך דומה לשור תרגום שור תור שבשעה שמנסכין מים בחג הוא אומר כן לשון אחר כמשמעו הנצנים נראו והזמיר הגיע בשעה שקול התור נשמע:"],[10,"שכן מצינו כו'","כלומר שאין לך אדם בעולם שאין תענית חל עליו מט' שעות ואילך אפי' בני מלכים שדרכן לאכול בט' שעות שעד ג' שעות הן ישנים במטותיהן ושוהין ששה שעות ואוכלין וכדאמרינן בפסחים (דף קז:) אפי' אגריפס המלך שרגיל לאכול בט' שעות ביום לא יאכל עד שתחשך שנאמר הראית כי נכנע אחאב מפני ואחאב לא חלה תעניתו עליו אלא מט' שעות ואילך ועד ט' שעות היה יכול לאכול שלא גמר בדעתו להתענות אלא שבא אליהו אותו היום שנכנס בכרם נבות היזרעאלי ואמר ליה הרצחת וגם ירשת וגו' (מלכים א כ״א:י״ט) ילקו הכלבים וגו' (שם) וכתיב ויצום שהתענה אותו היום:"],[11,"","הכי גרסינן שמואל הקטן גזר תעניתא וירדו גשמים קודם הנץ החמה:"],[11,"שבח צבור הוא","שעדיין לא קראו ונענו:"],[12,"","למה הדבר דומה וכו':"]],[]],[["אלא על נפש שבעה וכרס מלאה איני והא רב פפא איקלע לבי כנישתא דאבי גובר וגזר תענית וירדו להם גשמים עד חצות ואמר הלל ואחר כך אכלו ושתו שאני בני מחוזא דשכיחי בהו שכרות:","\u0001הדרן עלך סדר תעניות אלו\u0002","מתני׳ \u0001בשלשה\u0002 פרקים בשנה כהנים נושאין את כפיהן ארבע פעמים ביום בשחרית במוסף במנחה ובנעילת שערים בתעניות ובמעמדות וביום הכפורים","אלו הן מעמדות לפי שנאמר (במדבר כח, ב) צו את בני ישראל את קרבני לחמי וכי היאך קרבנו של אדם קרב והוא אינו עומד על גביו","התקינו נביאים הראשונים עשרים וארבעה משמרות על כל משמר ומשמר היה מעמד בירושלים של כהנים של לוים ושל ישראלים","הגיע זמן המשמר לעלות כהנים ולוים עולים לירושלים וישראל שבאותו משמר מתכנסין לעריהן וקוראין במעשה בראשית (ואנשי המעמד היו מתענין ארבעה ימים בשבוע מיום ב' ועד יום חמישי ולא היו מתענין ערב שבת מפני כבוד השבת ולא באחד בשבת כדי שלא יצאו ממנוחה ועונג ליגיעה ותענית וימותו)","ביום הראשון בראשית ויהי רקיע בשני יהי רקיע ויקוו המים בשלישי יקוו המים ויהי מאורות ברביעי יהי מאורות וישרצו המים בחמישי ישרצו המים ותוצא הארץ בששי ותוצא הארץ ויכלו השמים","פרשה גדולה קורין אותה בשנים והקטנה ביחיד בשחרית במוסף ובמנחה נכנסין וקורין על פיהן כקורין את שמע ערב שבת במנחה לא היו נכנסין מפני כבוד השבת","כל יום שיש בו הלל אין מעמד בשחרית קרבן מוסף אין בנעילה קרבן עצים אין במנחה דברי ר' עקיבא","אמר לו בן עזאי כך היה רבי יהושע שונה קרבן מוסף אין במנחה קרבן עצים אין בנעילה חזר רבי עקיבא להיות שונה כבן עזאי","זמן עצי כהנים והעם תשעה באחד בניסן בני ארח בן יהודה בעשרים בתמוז בני דוד בן יהודה בחמשה באב בני פרעוש בן יהודה בשבעה בו בני יונדב בן רכב בעשרה בו בני סנאה בן בנימן בחמשה עשר בו בני זתוא בן יהודה","ועמהם כהנים ולוים וכל מי שטעה בשבטו ובני גונבי עלי ובני קוצעי קציעות","בעשרים בו בני פחת מואב בן יהודה בעשרים באלול בני עדין בן יהודה באחד בטבת שבו בני פרעוש שניה באחד בטבת לא היה בו מעמד שהיה בו הלל וקרבן מוסף וקרבן עצים","חמשה דברים אירעו את אבותינו בשבעה עשר בתמוז וחמשה בתשעה באב בשבעה עשר בתמוז"],[[0,"אלא בנפש שבעה","מתוך שכתוב בו נותן לחם לכל בשר (תהילים קל״ו:כ״ה) נאה להאמר על השבע:"],[0,"דאבי גובר","שם אדם או מקום:"],[0,"דשכיח בהו","יין ושכרות ופשעי ולא יאמרו הלל:"],[2,"מתני' בשלשה פרקים במוסף","מפרש בגמרא:"],[2,"נעילת שערים","מפורש בברכות ירושלמי בפרק תפלת השחר אימתי נעילה יש אומרים נעילת שערי מקדש וי\"א נעילת שערי שמים שנועלים אותן לעת ערב בגמר תפלה ונוהגין היו להתפלל תפלת נעילה בכל תעניתם כדרך שמתפללין ביוהכ\"פ:"],[3,"אלו הן מעמדות","המתענין מתפללין בעריהם שיתקבל ברצון קרבן אחיהם כדלקמן:"],[3,"לפי שנאמר צו את בני ישראל וגו'","שהתמיד בא מן השקלים של כל ישראל ואי אפשר שיהו כל ישראל עומדין על גבי קרבנם ומינו מעמדות להיות במקומם:"],[4,"נביאים הראשונים","שמואל ודוד בגמרא מפרש:"],[4,"על כל משמר","ארבעה ועשרים משמרות של כהנים היו ושמואל ודוד תיקנום ועל כל משמר היה מעמד בירושלים שקבועין ועומדין בעיר ועומדין על קרבן אחיהם ולבד אלו הדרים בירושלים היו מעמדות בכל עיר שישראל נחלקו לכ\"ד מעמדות כנגד ארבעה ועשרים משמרות כדתניא בברייתא של מ\"ט מדות והיינו דתנן היה מעמד בירושלים כהנים לוים וישראלים:"],[4,"כהנים ולוים","של משמר היו עולים בירושלים כהנים לעבודה ולוים לשיר ומכל המעמדות היו קבועין בירושלים לעמוד על קרבן אחיהם:"],[5,"והשאר היו מתכנסין לעריהם","ומתפללין על קרבן אחיהם שיתקבל ברצון ומתענין ומוציאין ספר תורה ביום תעניתם:"],[5,"וקורין במעשה בראשית","ובגמרא מפרש טעמא:"],[6,"ביום הראשון","של שבוע:"],[6,"קורין בראשית כו'","פרשה ראשונה ופרשת יהי רקיע לפי שאין בפרשת בראשית לבדה תשעה פסוקים כדי קריאת כהן לוי ישראל וכן כולן:"],[6,"בששי ותוצא הארץ עד ויכולו","לפי שבפרשת תוצא הארץ אין בה אלא שמונה פסוקים לפיכך אומר ויכולו:"],[7,"פרשה גדולה","שבפרשיות הללו קורין אותה בשנים כגון פרשה ראשונה של בראשית יש בה חמשה פסוקים היו קורין אותה בשנים כדאמרינן בגמרא יהי רקיע באחד וביום השני יהי רקיע באחד יקוו בשנים שיש בה ה' פסוקים ביום השלישי יקוו באחד שאין בה אלא ה' פסוקים ויהי מאורות בשנים שיש בה ו' פסוקים:"],[7,"וקורין אותה על פיהן","כל אחד בפני עצמו ובעי בגמרא מאי קאמר מעיקרא קתני פרשה קטנה כו' דמשמע דבספר תורה קורין והדר תנא על פיהם. פרשה בנעילה ליכא:"],[8,"כל יום שיש בו הלל אין בו מעמד שחרית","אותן שהיו בירושלים לא היו מתפללין על קרבן אחיהם שיש בו הלל לפי שאין להן פנאי לעשות מעמדם שקורין את הלל ומפני ההלל היו דוחין את המעמד:"],[8,"קרבן מוסף","יום שיש בו קרבן מוסף בירושלים אין מעמד בנעילה בירושלים וכל שכן במנחה הסמוכה למוסף לפי שהיו טרודין במוסף שיש בו להקריב בהמות יותר מתמיד שהוא אחד אין לך מוסף בלא שתי בהמות ולא היה להם פנאי כלל שהכהנים של מעמד טרודים במוסף וישראל שבהן היו טרודים לחטוב עצים ולשאוב מים ודוחה אפי' מעמד דנעילה:"],[8,"קרבן עצים","בגמרא מפרש כגון אחד מט' זמנים ואותו יום שהיה בו קרבן עצים אפילו לא היה בו מוסף היה נדחה מעמד של מנחה מפני קרבן עצים מפני שקרבן עצים קודם למנחה ודוחה מעמד הסמוך לו [ולא] של נעילה:"],[9,"כך היה רבי יהושע דורש קרבן מוסף אין במנחה","וטעמא מפרש בגמרא:"],[10,"זמן עצי כהנים והעם","שמתנדבים עצים:"],[10,"תשעה","באלו הט' זמנים היו הכהנים והעם מתנדבים להביא עצים והיו מקריבין קרבן אותו היום ואפילו היו עצים הרבה למערכה היו אלו מתנדבין ומקריבין באלו תשעה זמנים:"],[10,"בני ארח בן יהודה","שכשעלו בני הגולה הם התנדבו תחילה באחד בניסן וספק להם עצים עד כ' בתמוז שהתנדבו בני דוד ארח שמואל ומשבט יהודה היה:"],[10,"בני דוד","ממשפחת דוד המלך:"],[10,"","סנאה בן בנימין זתוא בן יהודה בני גונבי עלי ובני קוצעי קציעות משפחה אחת הן ובגמ' מפרש אמאי מיקרו הכי:"],[12,"בני עדין באחד בטבת שבו שבו בני פרעוש שניה","ובגמרא מפרש אמאי קבעו להן אלו הזמנים:"],[12,"באחד בטבת","שהיה ר\"ח [וחנוכה] לא היה בו מעמד כו':"]],[[0,"","שאני בני מחוזא דשכיחי בהו שכרות. ולהכי היו אומרים הלל הגדול קודם שיאכלו וישתו ובפסוקי דזמרה נוהגין לומר שחרית ודווקא בפסוקי דזמרה קודם התפלה אבל בשעת תפלה אין אומרים אותו אלא בנפש שבעה ובכרס מלאה:"],[8,"","בכל יום שיש בו הלל אין בו מעמד שחרית. פי' דהיינו חנוכה דבשאר יום טוב לא משכחת לה בלא קרבן מוסף:"],[8,"","קרבן מוסף אין בו נעילה. פירוש יום שקרבין בו מוסף אין בו נעילה לפי שטרודין הם במוסף ואין להם פנאי לומר נעילה:"],[8,"","קרבן עצים אין בו מנחה. משום דעד המנחה היו טרודים בקרבן העצים אבל יש בו נעילה דכל כך לא היו מאחרים עד שעת נעילה דאמר בן עזאי כך היה וכו':"]]],[["נשתברו הלוחות ובטל התמיד והובקעה העיר ושרף אפוסטמוס את התורה והעמיד צלם בהיכל","בתשעה באב נגזר על אבותינו שלא יכנסו לארץ וחרב הבית בראשונה ובשניה ונלכדה ביתר ונחרשה העיר","משנכנס אב ממעטין בשמחה שבת שחל תשעה באב להיות בתוכה אסור מלספר ומלכבס ובחמישי מותרין מפני כבוד השבת ערב תשעה באב לא יאכל אדם שני תבשילין לא יאכל בשר ולא ישתה יין רבן שמעון בן גמליאל אומר ישנה רבי יהודה מחייב בכפיית המטה ולא הודו לו חכמים","אמר רבן שמעון בן גמליאל לא היו ימים טובים לישראל כחמשה עשר באב וכיוה\"כ שבהן בנות ירושלים יוצאות בכלי לבן שאולין שלא לבייש את מי שאין לו כל הכלים טעונין טבילה","ובנות ירושלים יוצאות וחולות בכרמים ומה היו אומרות בחור שא נא עיניך וראה מה אתה בורר לך אל תתן עיניך בנוי תן עיניך במשפחה (משלי לא, ל) שקר החן והבל היופי אשה יראת ה' היא תתהלל ואומר (משלי לא, לא) תנו לה מפרי ידיה ויהללוה בשערים מעשיה","וכן הוא אומר (שיר השירים ג, יא) צאינה וראינה בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו וביום שמחת לבו ביום חתונתו זה מתן תורה וביום שמחת לבו זה בנין בית המקדש שיבנה במהרה בימינו:","\u0001גמ׳\u0002 בשלשה פרקים בשנה כהנים נושאין את כפיהם כו': תעניות ומעמדות מי איכא מוסף חסורי מיחסרא והכי קתני בשלשה פרקים כהנים נושאין את כפיהן כל זמן שמתפללין ויש מהן ארבעה פעמים ביום שחרית ומוסף מנחה ונעילת שערים ואלו הן שלשה פרקים תעניות ומעמדות ויום הכפורים","א\"ר נחמן אמר רבה בר אבוה זו דברי רבי מאיר אבל חכמים אומרים שחרית ומוסף יש בהן נשיאת כפים מנחה ונעילה אין בהן נשיאת כפים","מאן חכמים ר' יהודה היא דתניא שחרית ומוסף מנחה ונעילה כולן יש בהן נשיאת כפים דברי ר\"מ ר\"י אומר שחרית ומוסף יש בהן נשיאת כפים מנחה ונעילה אין בהן נשיאת כפים רבי יוסי אומר נעילה יש בה נשיאת כפים מנחה אין בה נשיאת כפים","במאי קמיפלגי רבי מאיר סבר כל יומא טעמא מאי לא פרשי כהני ידייהו במנחתא משום שכרות האידנא ליכא שכרות","רבי יהודה סבר שחרית ומוסף דכל יומא לא שכיח שכרות לא גזרו בהו רבנן מנחה ונעילה דכל יומא שכיחא שכרות גזרו בהו רבנן","רבי יוסי סבר מנחה דאיתה בכל יומא גזרו בה רבנן נעילה דליתה בכל יומא לא גזרו בה רבנן","אמר רב יהודה אמר רב הלכה כרבי מאיר ורבי יוחנן אמר נהגו העם כרבי מאיר ורבא אמר מנהג כרבי מאיר","מאן דאמר הלכה כרבי מאיר דרשינן לה בפירקא מאן דאמר מנהג מידרש לא דרשינן אורויי מורינן ומאן דאמר נהגו אורויי לא מורינן ואי עביד עביד ולא מהדרינן ליה","ורב נחמן אמר הלכה כרבי יוסי והלכה כרבי יוסי והאידנא מ\"ט פרשי כהני ידייהו במנחתא דתעניתא כיון דבסמוך לשקיעת החמה קא פרשי כתפלת נעילה דמיא","דכולי עלמא מיהת שכור אסור בנשיאת כפים מנהני מילי אמר רבי יהושע בן לוי משום בר קפרא למה נסמכה פרשת כהן מברך לפרשת נזיר לומר מה נזיר אסור ביין אף כהן מברך אסור ביין","מתקיף לה אבוה דרבי זירא ואמרי לה אושעיא בר זבדא אי מה נזיר אסור בחרצן אף כהן מברך אסור בחרצן א\"ר יצחק אמר קרא לשרתו ולברך בשמו מה משרת מותר בחרצן אף כהן מברך מותר בחרצן"],[[0,"נשתברו הלוחות","בגמ' מפרש:"],[0,"ובטל התמיד","לפי שגזרה המלכות גזרה מלהקריב עוד:"],[0,"והועמד צלם בהיכל","שהעמידו מנשה כדמפורש בתרגום ירושלמי בפרשת השמים כסאי וגו' (ישעיהו סו):"],[1,"על אבותינו","דור המדבר אם יראה איש באנשים האלה הדור הרע הזה את הארץ וגו' (דברים א׳:ל״ה):"],[1,"ביתר","עיר גדולה והיו ישראל דרין בה במסכת גיטין פרק הניזקין (גיטין דף נז.) אשקא דריספק חרב ביתר:"],[2,"שבת שחל תשעה באב כו'","שבוע:"],[2,"בחמישי מותרין","אם חל תשעה באב בערב שבת מותרין לכבס בחמישי וכשחל ט' באב בד' בשבת לא איצטריך למיתני דמותרין כדאמרינן בגמרא לא שנו אלא לפניו כו':"],[2,"שני תבשילין","בשר ודגים או בשר וביצים שעליו או דג וביצה שעליו כדאמר בפרק ערבי פסחים (פסחים דף קיד:):"],[2,"ישנה","בגמרא מפרש:"],[2,"כפיית המטה","על פניה ולא יישן עליה:"],[3,"שאולין","שכולן שואלות זו מזו אפילו עשירות כדי שלא לבייש כו':"],[3,"טעונין טבילה","קודם שילבשום לפי שאין כל אחת בקיאה בחברתה שמא נדה היתה:"],[4,"וחולות","כמו לחול במחולות (שופטים כא):"],[5,"במלך שלמה","במלך שהשלום שלו:"],[5,"אמו","כנסת ישראל:"],[5,"זה מתן תורה","יום הכפורים שניתנו בו לוחות האחרונות:"],[6,"גמ' כל זמן שמתפללין","דהיינו שחרית ומנחה ונעילה:"],[6,"יש מהן ארבעה פעמים ביום","יום הכפורים שיש בו מוסף:"],[9,"כל יומא מאי טעמא לא פרשי כהני ידייהו במנחה","דכל יומא שכיחא ביה שכרות שכבר סעד וזימנין דמשכא סעודתיה ומשתכר ופריש ידיה בהדי חמריה וכהן שתוי יין אסור לישא את כפיו שנאמר יין ושכר אל תשת בבואכם וגו' (ויקרא י׳:ט׳) ונשיאת כפים מעין עבודה כדלקמן:"],[9,"האידנא","בתעניות ובמעמדות לא שכיחא שכרות ובמעמדות נמי מתענין כדלקמן (תענית דף כז:):"],[10,"גזרינן","תענית אטו שאר ימים:"],[11,"נעילה דליתה בכל יומא","אלא ביום התענית:"],[13,"דדרשינן בפירקא","הלכה כרבי מאיר דבעינן דליקום כוותיה עלמא:"],[13,"אורויי אורינן","כרבי מאיר אי אתו לקמן אבל בפירקא לא דרשינן דלא פשיטא ליה כולי האי דתיהוי הלכה כר\"מ ומ\"ד נהגו משמע הן נהגו מאליהן אבל אינו עיקר ומנהג משמע תורת מנהג יש בדבר ומנהג כשר הוא:"],[14,"ורב נחמן אמר הלכה כרבי יוסי והלכה כרבי יוסי","גמרא קא פסיק ומהדר סתמא ומוקי לה הלכה כרבי יוסי ואהכי קא פריך ואלא האידנא כו':"],[14,"כיון דסמוך לשקיעת החמה וכו'","שמאחרין עד שקיעת החמה ומתפללין כל שעה ואינן הולכין לבית הכנסת משש שעות ומחצה ולמעלה כמו שהיו עושין לאותן הימים:"],[14,"כתפלת נעילה דמיא","דהשתא ליכא למיגזר משום מנחה דכל יומא דמנחתא כי הא ליתא בכל יומא:"],[15,"שכור מיהא אסור בנשיאת כפים","דאפילו ר\"מ לא קאמר אלא משום דהאידנא לאו שכרות הוא:"],[15,"פרשת כהן מברך","כה תברכו את בני ישראל אמור להם (במדבר ו׳:כ״ג):"],[16,"מה משרת כו'","עובד עבודה דלא מיתסר אלא שתויי יין ממש דכתיב יין ושכר אל תשת וגו' הא בחרצן מותר:"]],[[10,"","מנחה ונעילה דכל יומא שכיחי בהו שכרות גזרו רבנן. אפילו ביומא דתענית דלית בהו שכרות וקשיא דהכא משמע דבמנחה שייכא שכרות ובפ\"ק דשבת (דף י. ושם) קאמר בהדיא דבמנחה לא שייכא שכרות וי\"ל דהא דקאמר התם דבמנחה לא שייכא שכרות ר\"ל לגבי ערבית שכרות דמנחה לאו כלום (לגבי שבת) דיותר שכיח שכרות בערבית (יותר) מבמנחה אבל לעולם במנחה שייך שכרות לגבי שחרית ומוסף:"],[13,"","ומאן דאמר נהגו אורויי נמי לא מורינן. פירשנו בפ\"ק דראש השנה (דף טו: ד\"ה וכי):"],[14,"","והאידנא נהוג עלמא דפרסי כהני ידייהו במנחה סמוך לשקיעת החמה. ולכך לא נהגו העם לומר נשיאת כפים במנחה ביום הכפורים לפי שמתפללין מנחה בעוד היום גדול אבל במנחה בשאר תעניות יש נשיאת כפים אבל מכל מקום בנעילה ביום הכפורים יש נשיאת כפים:"]]],[["אי מה משרת בעל מום לא אף כהן מברך בעל מום לא הא איתקש לנזיר","ומאי חזית דמקשת לקולא אקיש לחומרא אסמכתא נינהו מדרבנן ולקולא:","אלו הן מעמדות לפי שנאמר צו את בני ישראל כו': מאי קאמר ה\"ק אלו הן מעמדות ומה טעם תיקנו מעמדות לפי שנאמר (במדבר כח, ב) צו את בני ישראל ואמרת אליהם את קרבני לחמי לאשי","והיאך קרבנו של אדם קרב והוא אינו עומד על גביו התקינו נביאים הראשונים עשרים וארבעה משמרות על כל משמר ומשמר היה מעמד בירושלים של כהני' ושל לוים ושל ישראלים הגיע זמן משמר לעלות כהנים ולוים עולין לירושלים","ת\"ר עשרים וארבעה משמרות בארץ ישראל ושתים עשרה ביריחו שתים עשרה ביריחו נפישן להו טובא אלא שתים עשרה מהן ביריחו הגיע זמן המשמר לעלות חצי המשמר היה עולה מארץ ישראל לירושלים וחצי המשמר היה עולה מיריחו כדי שיספקו מים ומזון לאחיהם שבירושלים","אמר רב יהודה אמר שמואל כהנים ולוים וישראלים מעכבין את הקרבן במתניתא תנא ר\"ש בן אלעזר כהנים ולוים וכלי שיר מעכבין את הקרבן במאי קמיפלגי מר סבר עיקר שירה בפה ומר סבר עיקר שירה בכלי","אמר רב חמא בר גוריא אמר רב משה תיקן להם לישראל שמונה משמרות ארבעה מאלעזר וד' מאיתמר בא שמואל והעמידן על שש עשרה בא דוד והעמידן על עשרים וארבעה שנאמר (דברי הימים א כו, לא) בשנת הארבעים למלכות דוד נדרשו וימצא בהם גבורי החיל ביעזר גלעד","מיתיבי משה תיקן להם לישראל שמונה משמרות ארבעה מאלעזר וארבעה מאיתמר בא דוד ושמואל והעמידן על עשרים וארבע שנאמר (דברי הימים א ט, כב) המה יסד דוד ושמואל הרואה באמונתם הכי קאמר מיסודו של דוד ושמואל הרמתי העמידום על עשרים וארבע","תניא אידך משה תיקן להם לישראל שש עשרה משמרות שמונה מאלעזר ושמונה מאיתמר וכשרבו בני אלעזר על בני איתמר חלקום והעמידום על עשרים וארבע שנאמר (דברי הימים א כד, ד) וימצאו בני אלעזר רבים לראשי הגברים מן בני איתמר ויחלקום לבני אלעזר ראשים לבית אבות ששה עשר ולבני איתמר לבית אבותם שמונה ואומר (דברי הימים א כד, ו) בית אב אחד אחוז לאלעזר ואחוז אחוז לאיתמר","מאי ואומר וכי תימא כי היכי דנפישי בני אלעזר הכא נמי דנפישי בני איתמר שמנה מעיקרא ארבעה הוו ת\"ש בית אב אחד אחוז לאלעזר ואחוז אחוז לאיתמר תיובתא דרב חמא בר גוריא","אמר לך רב חמא בר גוריא תנאי היא ואנא דאמרי כי האי תנא דאמר שמונה","ת\"ר ארבעה משמרות עלו מן הגולה ואלו הן ידעיה [חרים] פשחור ואימר עמדו נביאים שביניהם"],[[2,"מאי קאמר","דקא בעי מאי ניהו מעמדות ומייתי קרא את קרבני לחמי לאשי וגו':"],[2,"הכי קאמר אלו הן מעמדות","דלקמן וטעמא מאי תקון מעמדות לפי שנאמר צו את בני ישראל ואמרת אליהם את קרבני לחמי לאשי וגו':"],[4,"ה\"ג תנו רבנן כ\"ד משמרות היו בא\"י וי\"ב ביריחו י\"ב ביריחו בתמיה נפישי להו טובא אלא אימא וי\"ב מהן ביריחו","ברישא משמע לבד הכ\"ד שבעיירות א\"י היו י\"ב ביריחו דהוו להו ל\"ו וי\"ב מהן משמע שמאותן הכ\"ד היו י\"ב ביריחו:"],[4,"ה\"ג הגיע זמן המשמר חצי המשמר עולה לירושלים וחצי המשמר עולה ליריחו כדי שיספקו מים ומזון לאחיהם שבירושלים","כלומר כיצד היו י\"ב ביריחו כשהגיע זמן המשמר לעלות לירושלים בשבת מתחלקים אנשי המשמר חציין הולכין לירושלים לעבודה וחציין הולכין ליריחו הסמוכה לירושלים ומתקנין שם מים ומזון לאחיהם וכך עושין כל הכ\"ד משמרות נמצא י\"ב ביריחו לשון אחר נהירא לי:"],[5,"מעכבין את הקרבן","אם אין מעמד מכולן בירושלים כדתנן (לעיל תענית דף כו.) על כל משמר היה מעמד בירושלים של כהנים לוים וישראלים כיון דכולהו בעלים בעינן דליהוי כמוהו על גבי עבודה:"],[5,"וכלי שיר מעכבין את הקרבן","פלוגתא בשילהי מסכת סוכה (דף נ:) ובערכין (דף יא.) מפורשת:"],[5,"עיקר שירה בפה","וכלי לבסומי קלא בעלמא וכיון דאיכא לוים לא מעכב משום כלי שיר:"],[5,"עיקר שירה בכלי","אבוב וכן בפרק החליל (שם):"],[6,"ארבעה מאלעזר","מבניו של אלעזר שעשה מהן ד' משמרות וגמרא גמר לה:"],[7,"המה יסד דוד ושמואל הרואה באמונתם","ותיובתא דרב חמא דאמר שמואל העמידם על י\"ו ודוד העמידן על כ\"ד דהא שמעי' מינה דתרוייהו בהדי הדדי תקנינהו:"],[7,"מיסודו של שמואל הרמתי","שהעמידן על י\"ו בא דוד והעמידן על כ\"ד אית ספרים שכתוב בהן מיסודו של שמואל ודוד העמידום על כ\"ד כלומר שניהם הועילו בדבר ושמואל העמידם על י\"ו ודוד על כ\"ד:"],[8,"","וימצאו בני אלעזר רבים לראשי הגברים מבני איתמר ויחלקו בני אלעזר ראשים לבית אבותם ששה עשר ולבני איתמר ראשים לבית אבותם שמונה ואומר בית אב אחד אחוז לאלעזר ואחוז אחוז לאיתמר – וימצאו בני אלעזר רבים לראשי הגברים כלומר ראשי הגברים של בני אלעזר היו רבים מאיתמר והאי וימצאו משמע דקודם לכן היו קבועים ועכשיו הוסיפו עליהן ויחלקום לי\"ו בית אב אחד אחוז שהיה מתחילה לאלעזר דהיינו ח' אחוז אחד בגורל דהיינו נמי ח' והוו להו י\"ו:"],[8,"ואחוז אחוז לאיתמר","מה שהיה מתחילה אחוז לאיתמר אחוזים עתה כבתחילה שלא הרבו עליהם שום בית אב:"],[9,"מאי ואומר","וכי תימא מעיקרא הוו ד' לאלעזר וד' לאיתמר:"],[9,"וכי היכי דנפישי בני אלעזר הכי נמי נפישי בני איתמר","ומיהו בני אלעזר נפישי טפי דהא לאיתמר לא אוקמינהו אלא על ח' ודאלעזר על י\"ו:"],[9,"תא שמע ואחוז אחוז לאיתמר","אלמא כדקיימי קיימי ושמע מינה דמשה תיקן להם י\"ו ח' מזה וח' מזה וקשיא לרב חמא דאמר ד' וד' והא דכתב לעיל ובשנת הארבעים וגו' המה יסד במה שהוסיפו עליהן עד כ\"ד משתעי [אבל] משה תיקן להם י\"ו משמרות:"],[10,"תנאי היא","דהא איכא תנא דלעיל דקתני משה תיקן להן ח' משמרות משניהן ואנא קאימנא כוותיה:"],[11,"עלו מן הגולה","בבית שני והשאר לא עלו שהרבה מישראל נשתיירו ולא רצו לעלות:"],[11,"פשחור ואימר","ומבעיא לי דפשחור לא כתיב גבי כ\"ד משמרות (דברי הימים א כד):"]],[[0,"","אי מה משרת בעל מום לא אף מברך בעל מום לא. פי' כיון דילפינן ג\"ש ממשרת נימא כמו משרת דמשרת בעל מום לא אף מברך וכו' ומשני הא איתקש לנזיר וכו' מכאן נראה דבעל מום מברך ברכת כהנים מדקא חזינן דהש\"ס רוצה ללמוד מברך ממשרת ולבעל מום ודחינן ליה אם כן נראה דלענין נשיאת כפים כהן בעל מום נושא כפיו ומכאן יש להוכיח דכהן שהמיר דתו נושא כפיו וכשר לישא כפיו ולקרות בתורה כמו שלא המיר וראיה מהא דכהנים ששימשו בבית חוניו לא ישמשו במקדש אבל נוטלים חלק עם אחיהם כמו בעלי מומין מדקאמר שהם כבעלי מומין משמע דכל עבודה שבעל מום ראוי לעשות יעשו וכהן בעל מום נושא כפיו:"],[1,"","ומאי חזית דאקשת לקולא אקיש לחומרא. פי' מאי חזית דמקשת כהן לנזיר להקל ולומר כמו שנזיר הוי בעל מום כמו כן כהן בעל מום כשר ואקשת למשרת מה משרת מותר בחרצן אף כהן מברך מותר בחרצן אקשה לחומרא פירוש ונימא דכמו שנזיר אסור בחרצן אף כהן אסור בחרצן וכמו כהן משרת אסור בעל מום אף כהן מברך בעל מום אסור ומשני אסמכתא וכו':"],[5,"","מר סבר עיקר שירה בפה. ולכך הכל כשרים אפילו פסולים אפילו ממזרים לומר שירה דלא הוי אלא בפה ולמאן דאמר עיקר שירה בכלי אם כן צריך שיהו כהנים או לוים דהא הכלי זמר היה קדוש:"]]],[["וחלקום והעמידום על עשרים וארבעה בללום ונתנום בקלפי בא ידעיה ונטל חלקו וחלק חבריו שש בא [חרים] ונטל חלקו וחלק חבריו שש וכן פשחור וכן אימר","וכן התנו נביאים שביניהם שאפי' (יהוידיב) ראש משמרת עולה לא ידחה ידעיה ממקומו אלא ידעיה עיקר (ויהוידיב) טפל לו:","וישראל שבאותו משמר מתכנסין בעריהן וקורין במעשה בראשית: מנהני מילי א\"ר יעקב בר אחא אמר רב אסי אלמלא מעמדות לא נתקיימו שמים וארץ שנאמר (בראשית טו, ב) ויאמר ה' אלהים במה אדע כי אירשנה","אמר אברהם רבש\"ע שמא ישראל חוטאין לפניך אתה עושה להם כדור המבול וכדור הפלגה א\"ל לאו אמר לפניו רבש\"ע הודיעני במה אירשנה א\"ל (בראשית טו, ט) קחה לי עגלה משולשת ועז משולשת וגו'","אמר לפניו רבש\"ע תינח בזמן שבית המקדש קיים בזמן שאין בית המקדש קיים מה תהא עליהם אמר לו כבר תקנתי להם סדר קרבנות בזמן שקוראין בהן לפני מעלה אני עליהם כאילו הקריבום לפני ואני מוחל להם על כל עונותיהם","ת\"ר אנשי משמר היו מתפללין על קרבן אחיהם שיתקבל ברצון ואנשי מעמד מתכנסין לבית הכנסת ויושבין ד' תעניות בשני בשבת בשלישי ברביעי ובחמישי בשני על יורדי הים בשלישי על הולכי מדברות","ברביעי על אסכרא שלא תיפול על התינוקות בחמישי על עוברות ומיניקות עוברות שלא יפילו מיניקות שיניקו את בניהם ובערב שבת לא היו מתענין מפני כבוד השבת ק\"ו בשבת עצמה","באחד בשבת מ\"ט לא אמר ר' יוחנן מפני הנוצרים ר' שמואל בר נחמני אמר מפני שהוא שלישי ליצירה","ריש לקיש אמר מפני נשמה יתירה דאמר ריש לקיש נשמה יתירה ניתנה בו באדם בע\"ש במוצאי שבת נוטלין אותה ממנו שנאמר (שמות לא, יז) שבת וינפש כיון ששבת וי אבדה נפש:","ביום הראשון בראשית ויהי רקיע: תנא בראשית בשנים יהי רקיע באחד בשלמא יהי רקיע באחד תלתא פסוקי הוו אלא בראשית בשנים (מ\"ט) ה' פסוקי הויין (ותנן) הקורא בתורה אל יפחות מג' פסוקים","רב אמר דולג ושמואל אמר פוסק ורב דאמר דולג מ\"ט לא אמר פוסק קסבר כל פסוקא דלא פסקיה משה אנן לא פסקינן ליה","ושמואל אמר פוסק ומי פסקינן והאמר רבי חנינא קרא צער גדול היה לי אצל ר' חנינא הגדול ולא התיר לי לפסוק אלא לתינוקות של בית רבן הואיל ולהתלמד עשוין ושמואל התם טעמא מאי משום דלא אפשר הכא נמי לא אפשר","ושמואל אמר פוסק מ\"ט לא אמר דולג גזירה משום הנכנסין וגזירה משום היוצאין","מיתיבי פרשה של ששה פסוקים קורין אותה בשנים ושל חמשה [ביחיד ואם] הראשון קורא ג' השני קורא שנים מפרשה זו ואחד מפרשה אחרת וי\"א ג' לפי שאין מתחילין בפרשה פחות משלשה פסוקין","למ\"ד דולג לידלוג ולמאן דאמר פוסק ליפסוק שאני התם"],[[0,"וחלקום","לכ\"ד וכתבו כנוי של כל אחד ואחד בחלק:"],[0,"בללום ונתנום בקלפי","כתבו על כ\"ד חתיכות קלף ראשי משמרות שחלקו מאותן ד':"],[0,"בא ידעיה","משמרה של ידעיה בא אחד מהן ונוטל חלקו וחלק ה' חתיכות קלף דהוו להו שש ומי שהיה עולה בידו ראשון היה לשבת ראשונה שבסדר שהיו עולין בידו זו אחר זו כך היו עובדין בשבתותיהן זו אחר זו:"],[1,"וכך התנו","שאפי' יהויריב שהיה במקדש ראשון ראשון למשמרות עולה מן הגולה:"],[1,"לא ידחה ידעיה","הואיל ומתחלה לא עלה יהויריב אלא כל משמרות הנעשות מידעיה קודמות לעבודה ליהויריב ויהויריב בא ועובד אחריהן במקום משמר אחר וששה דידעיה עושין אותן ה' שלא להרבות במשמרות:"],[2,"א\"ר אסי לפי שאלמלא מעמדות","עיסקי קרבנות שישראל עושין הן היו כלים בחטאן ומשהן כלין שמים וארץ העומדים בזכותן אין מתקיימין כו':"],[3,"כאנשי דור המבול","שמאחר שהן כלין אין העולם מתקיים והואיל שעל עיסקי קרבן העולם עומד לכך קורין אנשי מעמד בעריהן במעשה בראשית:"],[4,"כבר תקנתי להם כו'","כל זמן שקורין בהן כו' מהיכא יליף לה להאי גמגום:"],[5,"ת\"ר אנשי משמר מתפללין על קרבן אחיהן","תמידים שבכל יום:"],[5,"אנשי משמר","אותן כ\"ד שהיו בעריהן:"],[5,"בשני על יורדי הים","דכתיב בשני (בראשית א׳:ו׳) יהי רקיע בתוך המים וצריך להזכיר ולרצות על הדבר:"],[5,"בשלישי על הולכי מדברות","דכתיב ותראה היבשה תהי ראויה יבשה להולכיה שלא יזוקו מפני חיות רעות:"],[6,"ברביעי על האסכרא","שבו נתלו המאורות וכתיב ביה (שם) יהי מאורות מארת כתיב:"],[6,"ועל עוברות כו'","דכתיב ביה (שם) ישרצו המים שרץ נפש חיה:"],[7,"מפני הנוצרים","שעושים אותו יום טוב שלהם:"],[7,"שלישי ליצירה","דאדם נברא ביום ששי ובכל יום שלישי הוי חלוש כדכתיב (שם לד) ויהי ביום השלישי בהיותם כואבים:"],[8,"נשמה יתירה","שנוטלין אותה ממנו והוי חלש:"],[8,"נשמה יתירה","שמרחיבים דעתו לאכילה ושתיה:"],[8,"כיון ששבת","שנח ושמר את השבת:"],[8,"ווי אבדה נפש","וינפש דורש בנוטריקון ווי נפש:"],[9,"בראשית בשנים","כהן ולוי קורין ביום תענית בראשית:"],[9,"תלתא פסוקי הווי","וסגיא בהו לחד גברא:"],[10,"רב אמר דולג","הראשון קורא שלשה פסוקים והשני מתחיל בפסוק שסיים בו הראשון והשנים עמו הרי שלשה ומשום אין משיירין בפרשה פחות משלשה פסוקים ליכא משום דלא אפשר:"],[10,"פוסק","מפסיק הפסוק לשנים ראשון קורא שני פסוקים וחצי ולוי משלים חצי אותו הפסוק שקרא הכהן עם שנים הנותרים:"],[11,"ר' חנינא קרא","שהיה בעל מקרא ויודעה בגירסא ובקי בטעמיה:"],[11,"צער גדול","הרבה טרחתי וחזרתי עליו שיתיר לי לפסוק הפסוק לשנים לצורך תינוקות שלומדים לפני שאינן יכולין לקרוא פסוק כולו:"],[11,"הכי נמי לא אפשר","גבי ס\"ת ובדילוג אי אפשר משום הנכנסין והיוצאין אם שני דולג ומתחיל בפסוק שסיים בו הראשון בני אדם הנכנסין שלא שמעו קריאת הראשון סבורין לומר שלא קרא הראשון אלא שני פסוקים ונפיק מיניה חורבא וכשהראשון קורא ג' פסוקים ואינו משייר אלא שנים איכא גזרת יוצאין דסברי האי שני דסגיא ליה בשני פסוקים:"],[13,"מיתיבי פרשה של ששה פסוקים","אשאר ימות השנה קאי:"],[13,"ויש אומרים שלשה","מפרשה אחריתי:"],[14,"הכי גרסינן למאן דאמר דולג לידלוג למ\"ד פוסק ליפסוק","כלומר פרשה של חמשה פסוקין אמאי קורא שני שלשה פסוקין בפרשה אחרת לידלוג או ליפסוק:"]],[[10,"","רב אמר דולג. פי' הראשון קורא מראש הפרשה ג' פסוקים והשני שאין לו כי אם שני פסוקים מדלג פסוק אחד וקורא ממה שקרא הראשון וכן נמי בראשי חדשים מדלגין והקשה ה\"ר יהודה בר נתן ואמאי מדלגין אמאי אינו קורא למעלה בפרשה דהא בשבת בחוש\"מ קורא הוא מראה אתה אומר אלי (שמות ל״ג:י״ב) אע\"פ שעיקר הפרשה אינה מתחלת כי אם מפסל לך (שם לד) וי\"ל דמ\"ה הוא קורא ראה בפרשה של מעלה לפי שכל אותה הפרשה משתעי בחד עניינא אבל פרשה דר\"ח לעיל מינה לא משתעי כלל מחד עניינא ולכך אינו קורא בפרשה של מעלה אלא דולג ומזה ראיה למנהגנו אהא דלא קרינן בכל שבת ושבת פרשה של שבת כמו שאנו עושין בי\"ט שאנו קורין פרשיות לפי המאורע לפי שאין בפרשה של שבת שלשה פסוקים דאין לומר שנדלג לעיל דלא הוי מחד עניינא:"],[12,"","גזרה משום הנכנסין והיוצאין. פי' שהנכנסין שלא ראו הראשונים שקרא ג' פסוקים ויראו השני שקורא פסוק אחד מלמעלה יאמרו שהראשון לא קרא אלא שני פסוקים והיוצאין כשהראשון קורא שלשה פסוקים ואינו משייר אלא שני פסוקים איכא גזירת יוצאין דסברי האי שני סגיא ליה בשני פסוקים:"]]],[["דאית ליה רווחא:","פרשה גדולה קורין אותה בשנים בשחרית ובמוסף ובמנחה קורין על פיהן כו': איבעיא להו היכי קאמר בשחרית ובמוסף קורין אותה בספר ובמנחה קורין אותה על פה כקורין את שמע או דלמא הכי קתני בשחרית קורין אותה בספר ובמוסף ובמנחה קורין אותה על פה כקורין את שמע","תא שמע דתניא בשחרית ובמוסף נכנסין לבית הכנסת וקורין כדרך שקורין כל השנה ובמנחה יחיד קורא אותה על פה אמר ר' יוסי וכי יחיד יכול לקרות דברי תורה על פה בצבור אלא כולן נכנסין וקורין אותה על פה כקורין את שמע:","כל יום שיש בו הלל אין בו מעמד כו': מה הפרש בין זה לזה הללו דברי תורה והללו דברי סופרים:","זמן עצי כהנים והעם כו' ת\"ר למה הוצרכו לומר זמן עצי כהנים והעם אמרו כשעלו בני הגולה לא מצאו עצים בלשכה ועמדו אלו והתנדבו משלהם","וכך התנו נביאים שביניהן שאפי' לשכה מלאה עצים יהיו אלו מתנדבין משלהן שנאמר (נחמיה י, לה) והגורלות הפלנו על קרבן העצים הכהנים הלוים והעם להביא לבית אלהינו לבית אבותינו לעתים מזומנים שנה בשנה לבער על מזבח ה' אלהינו ככתוב בתורה:","ועמהם כהנים ולוים וכל מי כו': תנו רבנן מה היו בני גונבי עלי ובני קוצעי קציעות","אמרו פעם אחת גזרה המלכות גזירה על ישראל שלא יביאו עצים למערכה ושלא יביאו בכורים לירושלים והושיבו פרוזדאות על הדרכים כדרך שהושיב ירבעם בן נבט שלא יעלו ישראל לרגל","מה עשו כשרין (שבאותו הדור ויראי חטא) הביאו סלי בכורים וחיפום בקציעות ונטלום ועלי על כתפיהן וכיון שהגיעו אצל פרוזדאות אמרו להם להיכן אתם הולכין אומרין להם לעשות שני עיגולי דבילה במכתשת שלפנינו ובעלי שעל כתפינו כיון שעברו מהן עיטרום בסלים והביאום לירושלים","תנא הן הן בני סלמאי הנתופתי ת\"ר מה הן בני סלמאי הנתופתי אמרו פעם אחת גזרה המלכות גזירה על ישראל שלא יביאו עצים למערכה והושיבו פרוזדאות על הדרכים כדרך שהושיב ירבעם בן נבט על הדרכים שלא יעלו ישראל לרגל","מה עשו יראי חטא שבאותו הדור הביאו גזיריהן ועשו סולמות והניחו על כתפיהם והלכו להם כיון שהגיעו אצלן אמרו להם להיכן אתם הולכין אמרו להם להביא גוזלות משובך שלפנינו ובסולמות שעל כתפינו כיון שעברו מהן פירקום והביאום והעלום לירושלים","ועליהם ועל כיוצא בהם הוא אומר (משלי י, ז) זכר צדיק לברכה ועל ירבעם בן נבט וחבריו נאמר ושם רשעים ירקב:","בעשרים בו בני פחת מואב בן יהודה: תנא בני פחת מואב בן יהודה הן הן בני דוד בן יהודה דברי ר' מאיר רבי יוסי אומר הן הן בני יואב בן צרויה:","בעשרים באלול בני עדין בן יהודה וכו' תנו רבנן בני עדין בן יהודה הן הן בני דוד בן יהודה דברי רבי יהודה רבי יוסי אומר הן הן בני יואב בן צרויה:","באחד בטבת שבו בני פרעוש שניה כו': מני מתני' לא ר' מאיר ולא רבי יהודה ולא רבי יוסי אי ר\"מ ליתני שבו בני דוד בן יהודה שניה","אי רבי יהודה ליתני שבו בני דוד בן יהודה שניה אי רבי יוסי ליתני שבו בני יואב בן צרויה שניה","לעולם ר' יוסי ותרי תנאי אליבא דר' יוסי:","באחד בטבת לא היה בו מעמד כו': אמר ליה מר קשישא בריה דרב חסדא לרב אשי"],[[0,"דאית ליה רווחא","שיכול לקרות מפרשה אחרת אבל הכא לית ליה רווחא דהא לא מצי למיקרי אלא בראשית ויהי רקיע:"],[3,"מה הפרש בין זה לזה","מאי שנא דקרבן עצים דחי מעמד דנעילה ומעמד דמנחה לא דחי:"],[3,"הללו דברי תורה","מנחה כדאמרי' בברכות (דף כו.) יצחק אבינו תיקן תפלת מנחה שנאמר ויצא יצחק לשוח בשדה לפנות ערב ודנעילה מדברי סופרים. וצריכין חיזוק לא גרסינן הכא:"],[4,"עמדו אלו","זמן דקתני במתני' אהכי הוצרכו למנות משום ההיא תקנה דעבוד להו הנך נביאים כי היכי דלא לידחינהו מאתרייהו:"],[7,"בכורים","אדם נכנס לתוך שדהו ורואה אשכול שביכר תאנה שביכרה קושר עליה גמי ועושה אותה בכורים:"],[7,"פרוזדאות","שומרים:"],[8,"בקציעות","תאנים יבשים כותשין אותן ועושין מהן עגולין:"],[8,"ה\"ג והעלי על כתפיהן","(בוכיא):"],[8,"במכתשת שלפנינו","שהוא במקום אחר לפני בסמוך וזהו גונבי עלי על שם שמתגנבין מן הפרוזדאות על עסקי עלי:"],[9,"הן הן בני סלמאי הנתופתי","כעין מעשה זה עשו:"],[12,"הן הן בני דוד בן יהודה","דוד מלך ישראל ואהכי קרו ליה פחת מואב שבא מרות המואביה:"],[12,"יואב בן צרויה","שבא מרות המואביה כי צרויה אם יואב אחות דוד היתה שנאמר (דברי הימים א ב׳:ט״ז) ואחיותיהם צרויה ואביגיל:"],[13,"בני עדין הן הן בני דוד","להכי קרי ליה בספר שמואל (ב כג) עדינו העצני שבשעה שעוסק בתורה מעדן עצמו כתולעת וכשיוצא למלחמה מתקשה כעץ:"],[13,"הן הן בני יואב בן צרויה","פלוגתא היא (במס' חגיגה) חד אמר עדינו העצני זה דוד וחד אמר זה יואב:"],[14,"ליתני שבו בני דוד שניה","דהא קאמר ר' מאיר פחת מואב היינו דוד:"],[15,"ולר' יהודה","בני עדין היינו דוד ובמתניתין קתני בהדיא בני דוד והדר קתני בני פחת מואב דלר\"מ ול' יהודה בני עדין היינו דוד שבו שניה מיבעי ליה:"],[15,"ולר' יוסי","דאמר פחת מואב ועדין היינו יואב שבו שניה מיבעי ליה:"],[16,"לעולם ר' יוסי ותרי תנאי אליבא דר' יוסי","דמאן דאמר בני עדין בן יהודה היינו בני יואב לא סבר לה דבני פחת מואב היינו יואב ולהכי לא קתני שבו בני יואב שניה ולא סבירא ליה נמי דהן הן בני דוד דאם כן שבו בני דוד שניה מיבעי ליה למיתני אלא משפחה אחרת הן ומאן דאמר בני פחת מואב היינו בני יואב לא סבירא ליה דבני עדין היינו יואב אלא משפחה אחרת הן:"]],[[3,"","מה הפרש בין זה לזה. כלומר מה הפרש בין קרבן מוסף לקרבן עצים דקרבן מוסף דוחה מנחה וקרבן עצים לא דחי מנחה:"],[3,"","הללו דברי תורה. מוסף ולהכי קדחי מנחה דהוי מדברי תורה אבל קרבן עצים דהוי מדברי סופרים והלכך לא דחיא אלא נעילה דהויא מדברי סופרים אבל לא דחיא מנחה דהויא מדברי תורה:"],[12,"","בני פחת מואב וכו' הן הן בני דוד. ולכך נקראו בני פחת שבאו מרות המואביה:"],[12,"","הן הן בני יואב בן צרויה. פירוש דצרויה היתה אחות דוד כדכתיב (דברי הימים א ב׳:ט״ז) ואחיותיהם צרויה והם באים מזרע רות המואביה:"],[14,"","אי ר\"מ. דקאמר בני פחת מואב בן יהודה הן הן בני דוד בן יהודה ליתני במתניתין כי קאמר בעשרים כו' בני פחת מואב בן יהודה היה ה\"ל למיתני בני דוד בן יהודה שבו שניה כמו שאומר שבו בני פרעוש שניה אי ר' יהודה דקאמר בני עדין בן יהודה הן הן בני דוד בן יהודה ליתני שבו בני דוד בן יהודה שניה אי ר' יוסי ליתני שבו בני יואב שניה ומשני תרי תנאי ואליבא דר' יוסי וקשיא אמאי לא מוקי אליבא דר\"מ ותרי תנאי אליבא דר\"מ שהרי טפי יש לן לאוקמא כר\"מ דסתמא דמתני' כר' מאיר ונראה לי דלהכי מוקי לה כרבי יוסי משום דרבי יוסי נימוקו עמו ומסתברא כוותיה בכל מקום ואפילו מחביריו:"]]],[["מאי שנא הלל דדחי דידיה ומאי שנא מוסף דלא דחי דידיה","א\"ל רב אשי השתא דלאו דידיה דחי דידיה לא כל שכן אמר ליה הכי קאמינא לך לא לידחי אלא דידיה","אמר ליה איכא ר' יוסי דקאי כוותך דתניא ר' יוסי אומר כל יום שיש בו מוסף יש בו מעמד מעמד דמאי אילימא מעמד דשחרית הא תנא קמא נמי הכי קאמר אלא מעמד דמוסף דידיה נמי לא דחי","אלא דמנחה קרבן עצים דחי אלא לאו דנעילה שמע מינה דידיה דחי דלאו דידיה לא דחי שמע מינה","וליתני נמי באחד בניסן לא היה בו מעמד מפני שיש בו הלל וקרבן מוסף וקרבן עצים אמר רבא זאת אומרת הלילא דבריש ירחא לאו דאורייתא","דאמר רבי יוחנן משום רבי שמעון בן יהוצדק שמונה עשר יום בשנה יחיד גומר בהן את הלל ואלו הן שמונת ימי החג ושמונת ימי חנוכה ויום טוב הראשון של פסח ויום טוב (ראשון) של עצרת ובגולה עשרים ואחד יום ואלו הן תשעת ימי החג ושמונת ימי חנוכה ושני ימים הראשונים של פסח וב' ימים טובים של עצרת","רב איקלע לבבל חזינהו דקא קרו הלילא בריש ירחא סבר לאפסוקינהו כיון דחזא דקא מדלגי דלוגי אמר שמע מינה מנהג אבותיהם בידיהם תנא יחיד לא יתחיל ואם התחיל גומר:","ה' דברים אירעו את אבותינו בשבעה עשר בתמוז כו': נשתברו הלוחות מנלן דתניא בששה לחדש ניתנו עשרת הדברות לישראל רבי יוסי אומר בשבעה בו מאן דאמר בששה ניתנו בששה ניתנו ובשבעה עלה משה","מ\"ד בשבעה בשבעה ניתנו ובשבעה עלה משה דכתיב (שמות כד, טז) ויקרא אל משה ביום השביעי וכתיב (שמות כד, יח) ויבא משה בתוך הענן ויעל אל ההר ויהי משה בהר ארבעים יום וארבעים לילה עשרים וארבעה דסיון ושיתסר דתמוז מלו להו ארבעין","בשיבסר בתמוז נחית אתא ותברינהו ללוחות וכתיב (שמות לב, יט) ויהי כאשר קרב אל המחנה וירא את העגל וישלך מידיו את הלוחות וישבר אותם תחת ההר:","בטל התמיד גמרא:","הובקעה העיר בי\"ז הוה והכתיב (ירמיהו נב, ו) בחדש הרביעי בתשעה לחדש ויחזק הרעב בעיר וכתיב בתריה (ירמיהו נב, ז) ותבקע העיר וגו'","אמר רבא לא קשיא כאן בראשונה כאן בשניה דתניא בראשונה הובקעה העיר בתשעה בתמוז בשניה בשבעה עשר בו:","שרף אפוסטמוס את התורה גמרא:","העמיד צלם בהיכל מנלן דכתיב (דניאל יב, יא) ומעת הוסר התמיד ולתת שקוץ שומם","וחד הוה והכתיב (דניאל ט, כז) ועל כנף שקוצים משומם אמר רבא תרי הוו ונפל חד על חבריה ותבריה ליה לידיה ואשתכח דהוה כתיב"],[[0,"מאי שנא הלל דדחי דידיה","מעמד דשחרית:"],[0,"ומאי שנא מוסף דלא דחי דידיה","דקתני יום שיש בו מוסף אין בו מנחה ולא קתני אין בו מוסף דלא דחי דידיה אלא דמנחה:"],[1,"הכי קאמינא","הכי קא בעינא למימר:"],[1,"אלא דידיה","דמוסף:"],[2,"ה\"ג רבי יוסי אומר כל יום שיש בו מוסף יש בו מעמד","ואתנא קמא פליג דאמר יום שיש בו מוסף אין בו נעילה ואתא ר' יוסי למימר דיש בו מעמד אע\"פ שיש בו מוסף:"],[3,"אלא לאו דנעילה הוא","דאמר ר' יוסי דיש בו מעמד ואין מוסף דוחה אותו:"],[4,"באחד בניסן","דאית ביה הלל דראש חדש:"],[4,"קרבן עצים","(קרבן מוסף) דבני ארח בן יהודה:"],[4,"זאת אומרת","מדלא קתני נמי באחד בניסן אלמא הלל דראש חדש לא דחי ליה למעמד שמע מינה דלאו דאורייתא הוה אלא מנהגא כדלקמן:"],[5,"יחיד","כלומר אפי' יחיד גומר בהן את ההלל שכל אחד ואחד חייב לגמור בו את ההלל במסכת ערכין מפורש מאי שנא דגומר כל ימי החג ובפסח לא גומר אלא יום ראשון משום דחג הסוכות חלוק בקרבנותיו וכל אחד ואחד כחג בפני עצמו דמי:"],[5,"ובגולה","שעושין שני ימים טובים משום ספיקא:"],[6,"דמדלגי דלוגי","כגון אנן דמדלגין לא לנו ה' לא לנו ונתחיל מן ה' זכרנו יברך:"],[6,"מנהג אבותיהם בידיהן","אבל הלל דחנוכה כגון באחד בטבת ודאי דחי דכיון דנביאים תיקנוהו שיהו אומרים אותו על כל פרק ופרק ועל כל צרה שלא תבא עליהן כשנגאלין יהו אומרין אותו על גאולתן כדאורייתא דמי:"],[6,"לא יתחיל","אינו צריך להתחיל בראש חדש:"],[7,"ר' יוסי אומר בשבעה","וטעמייהו מקרא במסכת שבת בפרק ר\"ע:"],[7,"בשבעה עלה משה","לקבל הלוחות כלומר ודאי ליכא מאן דפליג עלה דמתני' דקתני דבי\"ז בתמוז נשתברו הלוחות מכלל דכולהו סבירא להו דבשבעה עלה ולאו מקרא נפקא לן דבשבעה עלה דהאי דכתיב וישכון כבוד ה' על הר סיני ויכסהו הענן ששת ימים ויקרא אל משה ביום השביעי איכא מאן דדריש ליה במסכת יומא כי אחר מתן תורה הוה משבעה בסיון עד י\"ז בתמוז איכא מ' יום כ\"ד דסיון שהוא מלא וי\"ו דתמוז הרי מ' יום שעמד משה בהר:"],[10,"גמרא","כך קיבלנו מאבותינו:"],[14,"ומעת הוסר התמיד לתת שקוץ שומם וגו'","דבעת שהוסר ונתבטל התמיד באותו היום נתן שקוץ שומם דהיינו הועמד צלם בהיכל:"],[15,"ה\"ג והא כתיב על כנף שקוצים","כלומר הא כתיב קרא אחרינא דכתיב ביה שקוצים דמשמע תרי:"],[15,"תרי הוו","שהעמידן מנשה בהיכל:"],[15,"ונפל חד על חבריה וקטעיה לידיה","והנקטע לא קא חשיב והיינו דכתיב שקוץ אחד:"],[15,"אשתכח דכתיב","על ההוא צלם הכי:"]],[[5,"","ויום טוב הראשון של פסח. הוא גומר הלל אבל שמונה ימי פסח לא משום דלא דמי לחנוכה וסוכות דחנוכה דינא הוא לגמור הלל דכל הח' ימים היה הנס מתגדל והיה כל חד וחד יום טוב וכן בסוכות כל יומא ויומא הוי י\"ט לעצמו לפי שפרי החג מתמעטין והולכין אבל פסח אינו משתנה לא מקרבנות ולא מיום טוב לכך אין גומרים בו ההלל אלא יום הראשון והאידנא דגומרין תרי יומי משום דעבדינן אותו מספק הוי חד יומא לענין קריאת הלל וכן ביום שני של עצרת וכן יום של שמחת תורה ומש\"ה יש לנו כ\"א יום לגמור הלל:"],[6,"","אמר שמע מינה מנהג אבותיהם בידיהם. י\"מ דאמנהג לא מברכינן מהכא וכן משמע בסוכה בפרק לולב וערבה (סוכה דף מד:) דקאמר אמר אביי הוה קאימנא קמיה דר' יצחק ואייתי ההיא ערבה לקמיה שקל חביט חביט ולא בריך קסבר ערבה מנהג נביאים היא אלמא אמנהג לא מברכינן אבל רבינו תם פסק דמברכינן דאי איתא דלא מברכינן אם כן מאי קאמר בגמרא כיון דשמעינהו דמדלגי ואזלי שמע מינה מנהג אבותיהם בידיהם וכי לא היה לו להכיר אי משום מנהג קרו ליה לא מברכי אי איתא דאמנהג לא מברכינן ואי מברכי לא מנהג הוא וכי תימא דלא בא בתחילת קריאת הלל הא לא מצי אמרת דהא רב איקלע לבבל קאמר דאי איתא דבאמצע תפלה בא הוה ליה למימר איקלע לבי כנישתא ומדלא אמר מדלא ברכי מנהג הוא שמע מינה דאמנהגא נמי מברכינן וההיא דסוכה דמשמע דאמנהגא לא מברכינן היינו דווקא אמנהג דערבה דלא הוי אלא מנהג טלטול בעלמא ואמנהג דטלטול לא מברכינן אבל בשאר מנהג כמו קריאת הלל ואחריני כמו אותו מנהג ודאי מברכינן וכן הלכה למעשה ולפי זה יש ליזהר שלא לדבר באמצע ההלל כיון שבירך דאם כן הוי מפסיק ונראה דאין יחיד מחויב לקרוא ההלל אכן אם רוצה לחייב עצמו הרשות בידו:"],[15,"","ואשתכח דכתיב עילויה על אותו יד פירוש מצאו כתוב על היד שנחתכה מן הצלם אנת צבי לאחרובי ביתיה כלומר ביתו של הקב\"ה אשלמת ליה כלומר וכחך נתת לו ויש מפרשים דהכתיבה הוה על הצלם השלם וה\"ק אשכחי' עליה על הצלם השלם אנת צבי לאיחרובי ביתיה כלומר אתה רצית להחריב ביתו של הקדוש ברוך הוא וידך אשלמת ליה לכך שלמתי את ידך להקדוש ברוך הוא שחתכתי:"]]],[["אנת צבית לחרובי ביתא ידך אשלימת ליה","בתשעה באב נגזר על אבותינו שלא יכנסו לארץ מנלן דכתיב (שמות מ, יז) ויהי בחדש הראשון בשנה השנית באחד לחדש הוקם המשכן ואמר מר שנה ראשונה עשה משה את המשכן שניה הקים משה את המשכן ושלח מרגלים וכתיב (במדבר י, יא) ויהי בשנה השנית בחדש השני בעשרים בחדש נעלה הענן מעל משכן העדות","וכתיב (במדבר י, לג) ויסעו מהר ה' דרך שלשת ימים אמר רבי חמא בר חנינא אותו היום סרו מאחרי ה' וכתיב (במדבר יא, ד) והאספסוף אשר בקרבו התאוו תאוה וישובו ויבכו גם בני ישראל וגו' וכתיב (במדבר יא, כ) עד חדש ימים וגו' דהוו להו עשרין ותרתין בסיון","וכתיב (במדבר יב, טו) ותסגר מרים שבעת ימים דהוו להו עשרין ותשעה בסיון וכתיב (במדבר יג, ב) שלח לך אנשים","ותניא בעשרים ותשעה בסיון שלח משה מרגלים וכתיב (במדבר יג, כה) וישובו מתור הארץ מקץ ארבעים יום הני ארבעים יום נכי חד הוו","אמר אביי תמוז דההיא שתא מלויי מליוה דכתיב (איכה א, טו) קרא עלי מועד לשבור בחורי","וכתיב (במדבר יד, א) ותשא כל העדה ויתנו את קולם ויבכו העם בלילה ההוא אמר רבה אמר ר' יוחנן (אותו היום ערב) תשעה באב היה אמר להם הקב\"ה אתם בכיתם בכיה של חנם ואני קובע לכם בכיה לדורות","חרב הבית בראשונה דכתיב (מלכים ב כה, ח) ובחדש החמישי בשבעה לחדש היא שנת תשע עשרה [שנה] למלך נבוכדנצר מלך בבל בא נבוזראדן רב טבחים עבד מלך בבל ירושלם וישרוף את בית ה' וגו' וכתיב (ירמיהו נב, יב) ובחדש החמישי בעשור לחדש היא שנת תשע עשרה [שנה] למלך נבוכדנצר מלך בבל בא נבוזראדן רב טבחים עמד לפני מלך בבל בירושלם וגו'","ותניא אי אפשר לומר בשבעה שהרי כבר נאמר בעשור ואי אפשר לומר בעשור שהרי כבר נאמר בשבעה הא כיצד בשבעה נכנסו נכרים להיכל ואכלו וקלקלו בו שביעי שמיני","ותשיעי סמוך לחשכה הציתו בו את האור והיה דולק והולך כל היום כולו שנאמר (ירמיהו ו, ד) אוי לנו כי פנה היום כי ינטו צללי ערב והיינו דאמר רבי יוחנן אלמלי הייתי באותו הדור לא קבעתיו אלא בעשירי מפני שרובו של היכל בו נשרף ורבנן אתחלתא דפורענותא עדיפא","ובשניה מנלן דתניא מגלגלין זכות ליום זכאי וחובה ליום חייב","אמרו כשחרב בית המקדש בראשונה אותו היום ערב תשעה באב היה ומוצאי שבת היה ומוצאי שביעית היתה ומשמרתה של יהויריב היתה והלוים היו אומרי' שירה ועומדין על דוכנם ומה שירה היו אומרים (תהלים צד, כג) וישב עליהם את אונם וברעתם יצמיתם ולא הספיקו לומר יצמיתם ה' אלהינו עד שבאו נכרים וכבשום וכן בשניה","נלכדה ביתר גמרא","נחרשה העיר תניא כשחרב טורנוסרופוס הרשע את ההיכל נגזרה גזרה על רבן גמליאל להריגה בא אדון אחד ועמד בבית המדרש ואמר בעל החוטם מתבקש בעל החוטם מתבקש שמע רבן גמליאל אזל טשא מינייהו","אזל לגביה בצנעא א\"ל אי מצילנא לך מייתית לי לעלמא דאתי א\"ל הן א\"ל אשתבע לי אשתבע ליה סליק לאיגרא נפיל ומית וגמירי דכי גזרי גזירתא ומית חד מינייהו מבטלי לגזרתייהו יצתה בת קול ואמרה אדון זה מזומן לחיי העולם הבא","תנו רבנן משחרב הבית בראשונה נתקבצו כיתות כיתות של פרחי כהונה ומפתחות ההיכל בידן ועלו לגג ההיכל ואמרו לפניו רבונו של עולם הואיל ולא זכינו להיות גזברין נאמנים יהיו מפתחות מסורות לך וזרקום כלפי מעלה ויצתה כעין פיסת יד וקיבלתן מהם והם קפצו ונפלו לתוך האור","ועליהן קונן ישעיהו הנביא (ישעיהו כב, א) משא גיא חזיון מה לך איפוא כי עלית כולך לגגות תשואות מלאה עיר הומיה קריה עליזה חלליך לא חללי חרב ולא מתי מלחמה אף בהקב\"ה נאמר (ישעיהו כב, ה) מקרקר קיר ושוע אל ההר:","משנכנס אב ממעטין בשמחה כו' אמר רב יהודה בריה דרב שמואל בר שילת משמיה דרב כשם שמשנכנס אב ממעטין בשמחה כך משנכנס אדר מרבין בשמחה"],[[0,"אנת צבית לאחרובי ביתיה וידך אשלימת ליה","הצלם אומר לחבירו אתה רצית להחריב ביתו של מקום שהטית ישראל אחריך ואני עשיתי בך נקמה ושילמתי לך ידי ל\"א אנת צבית לאחרובי ביתא וידך [אושלית] לי לשון שאילת [כלים] כלומר ועלה בידי:"],[2,"ואמר רבי חמא בר חנינא אותו היום וכו'","מהר לשון מהר עכשיו כשתטול י\"ט ימים מחדש אייר קודם עליית הענן פשו להו י' והנהו י' היו בין דרך שלשת ימים וז' דהסגרת מרים וחדש של כ\"ט ימים שאכלו בשר הוה ל\"ט והשתא אשתכח דמשה שלח מרגלים בכ\"ט דסיון:"],[4,"הני ארבעים נכי חד","ב' מסיון וכ\"ט מתמוז הוה ל\"א וח' מאב הוה ל\"ט:"],[10,"","ה\"ג מגלגלין זכות על ידי זכאי:"],[10,"וחובה על ידי חייב","היינו תשעה באב דרגילין להיות בו רעות:"],[11,"מוצאי שבת","יום ראשון:"],[11,"מוצאי שביעית","שמינית:"],[11,"דוכן","מקום עשוי כעין איצטבא ועליו לוים עומדין לשורר:"],[11,"וישב עליהם את אונם וברעתם יצמיתם יצמיתם ה' אלהינו","במזמור אל נקמות ה' והוא שיר של יום רביעי והאי דאמרי ליה ביום ראשון אילייא בעלמא הוה דנפל בפומייהו כדאמרינן בערכין (דף יב.) פי' אילייא קינה שכן תרגום יונתן בן עוזיאל שא קינה (יחזקאל כ״ח:י״ב) טול אילייא וכמו אלי כבתולה חגורת שק על בעל נעוריה (יואל א׳:ח׳) שפירושו קונני ובכי:"],[13,"נחרשה העיר","כדכתיב (מיכה ג׳:י״ב) ציון שדה תחרש שנחרשה כולה ונעשית כשדה חרושה:"],[13,"בעל החוטם","בעל קומה וצורה ל\"א גדול הדור:"],[13,"מתבקש","ליהרג ברמז אמר ליה שלא יכירו בו אנשי המלך:"],[13,"טשא","נחבא כמו טשו במערתא (שבת דף לג:):"],[14,"אזל","האדון אצל רבן גמליאל בצנעא:"],[14,"ומית חד מינייהו","מן היועצין וכסבורין שאירע להן על שהרעו לגזור:"],[16,"גיא חזיון","ירושלים שהכל מסתכלין שם:"],[16,"מקרקר","לשון יללה:"],[16,"קיר ושוע","מקונן וזועק לשון הנה קול שועת בת עמי (ירמיהו ח) קיר כמו קירי דבשחיטת חולין (דף קלט:):"],[16,"אל ההר","בשביל הר ציון ששמם:"],[17,"משנכנס אדר","ימי נסים היו לישראל פורים ופסח:"]],[[2,"","דכתיב עד חדש ימים הוו להו כ\"ב בסיון. פי' חשוב מעשרים ימים של ר\"ח אייר עד סופו תמצא ט' ימים נמצא בכ' בסיון כ\"ט ועד חדש ימים הוי שלשים ימים אם כן לפי זה תמצא מעשרים ושנים לחדש השני דזה אייר חדש שלם עד כ\"ב דסיון וג' ימים שנסעו מהר ה' הרי ל\"ג דל מינייהו ב' ימים דבעשרים בחדש נעלה הענן ואייתר להו שני ימים פשו כ\"ג דל יומא מן שלשה שהאחד מן הג' ימים היה בכלל החדש שאייר חסר פש להו כ\"ב.:"],[5,"","אמר אביי תמוז דההיא שתא מלויי מליוה. ועשו אותו משלשים ימים כדי שיכלו המ' ימים בתשעה באב שלשים יום דתמוז ואחד דסיון דבכ\"ט שלח המרגלים ותשעה באב הרי ארבעים ימים וביום תשעה באב שבו המרגלים מתור הארץ:"],[11,"","וישב עליהם את אונם וברעתם יצמיתם ולא הספיקו לומר יצמיתם ה' אלהינו עד שבאו האויבים וכו'. פי' באותו פסוק יש ב' פעמים יצמיתם ולא הספיקו לומר השני עד שבאו וכבשום ואומר ר\"י אע\"ג דאין אותו פסוק כלל במזמור שיר של מוצ\"ש אירע להם כך שאמרו אותו פסוק ובירושל' מפרש אילייא נקט פירוש אילייא הוי כמו אלי כבתולה דהוי לשון קינה כמו שקורין העולם ריאוני\"א בלע\"ז:"]]],[["אמר רב פפא הלכך בר ישראל דאית ליה דינא בהדי נכרי לישתמיט מיניה באב דריע מזליה ולימצי נפשיה באדר דבריא מזליה","(ירמיהו כט, יא) לתת לכם אחרית ותקוה אמר רב יהודה בריה דרב שמואל בר שילת משמיה דרב אלו דקלים וכלי פשתן (בראשית כז, כז) ויאמר ראה ריח בני כריח שדה אשר ברכו ה' אמר רב יהודה בריה דרב שמואל בר שילת משמיה דרב כריח שדה של תפוחים:","שבת שחל תשעה באב להיות בתוכה אסורין לספר ולכבס: אמר רב נחמן לא שנו אלא לכבס וללבוש אבל לכבס ולהניח מותר ורב ששת אמר אפילו לכבס ולהניח אסור אמר רב ששת תדע דבטלי קצרי דבי רב","מתיב רב המנונא בחמישי מותרים מפני כבוד השבת למאי אילימא לכבס וללבוש מאי כבוד שבת איכא","אלא להניח ובחמישי הוא דשרי אבל השבת כולה אסור לעולם לכבס וללבוש וכשאין לו אלא חלוק אחד דאמר רב אסי א\"ר יוחנן מי שאין לו אלא חלוק אחד מותר לכבסו בחולו של מועד איתמר נמי אמר רבי בנימין אמר ר' אלעזר לא שנו אלא לכבס וללבוש אבל להניח מותר","מיתיבי אסור לכבס לפני תשעה באב אפילו להניח לאחר תשעה באב וגיהוץ שלנו ככיבוס שלהן וכלי פשתן אין בהם משום גיהוץ תיובתא","שלח רב יצחק בר גיורי משמיה דרבי יוחנן אע\"פ שאמרו כלי פשתן אין בהן משום גיהוץ אבל אסור ללובשן בשבת שחל תשעה באב להיות בתוכה","אמר רב לא שנו אלא לפניו אבל לאחריו מותר ושמואל אמר אפילו לאחריו נמי אסור מיתיבי שבת שחל תשעה באב להיות בתוכה אסור לספר ולכבס ובחמישי מותרין מפני כבוד השבת כיצד חל להיות באחד בשבת מותר לכבס כל השבת כולה","בשני בשלישי ברביעי ובחמישי לפניו אסור לאחריו מותר חל להיות בערב שבת מותר לכבס בחמישי מפני כבוד השבת ואם לא כבס בחמישי בשבת מותר לכבס בערב שבת מן המנחה ולמעלה לייט עלה אביי ואיתימא רב אחא בר יעקב אהא","חל להיות בשני ובחמישי קורין שלשה ומפטיר אחד בשלישי וברביעי קורא אחד ומפטיר אחד רבי יוסי אומר לעולם קורין שלשה ומפטיר אחד תיובתא דשמואל","אמר לך שמואל תנאי היא דתניא תשעה באב שחל להיות בשבת וכן ערב תשעה באב שחל להיות בשבת אוכל ושותה כל צרכו ומעלה על שולחנו אפילו כסעודת שלמה בשעתו ואסור לספר ולכבס מר\"ח ועד התענית דברי רבי מאיר רבי יהודה אומר כל החדש כולו אסור רשב\"ג אומר אינו אסור אלא אותה שבת בלבד","ותניא אידך ונוהג אבל מראש חדש ועד התענית דברי ר' מאיר רבי יהודה אומר כל החדש כולו אסור רשב\"ג אומר אינו אסור אלא אותה שבת בלבד","אמר ר' יוחנן ושלשתן מקרא אחד דרשו דכתיב (הושע ב, יג) והשבתי כל משושה חגה חדשה ושבתה מאן דאמר מר\"ח ועד התענית"],[[0,"ניזיל בהדיה","בערכאות שלהן:"],[1,"ונתתי לכם אחרית ותקוה","איידי דאיירי רב יהודה לעיל נקיט ואזיל:"],[1,"דקלים","להתפרנס מהן שיש מהן בבבל הרבה כדאמרינן בפ\"ק (דף ט:) עולא איקלע לבבל חזא מלא צנא דתמרי כו':"],[1,"כלי פשתן","ללבוש:"],[2,"לא שנו","במתני' שכל השבוע אסור לכבס:"],[2,"אפילו לכבס ולהניח","כדי שילבוש לאחר זמן לאחר ט' באב אסור דנראה כמסיח דעתו שעוסק בכיבוס בגדים:"],[2,"אמר רב ששת תדע","דאפי' לכבס ולהניח אסור:"],[2,"קצרי","כך שמם בלשון ישמעאל והם כובסין שמעתי אומרים על שם שמקצרין בגדי צמר כשדורסין אותן ברגליהן במים שקורין פורלוי\"ר והיינו דמתרגמינן עין רוגל (שמואל ב יז) עינא דקצרא:"],[3,"אילימא לכבס וללבוש","מיד בחמישי מאי כבוד שבת איכא:"],[4,"אלא","לאו לכבס ולהניח עד השבת:"],[4,"לעולם לכבס וללבוש","מיד בחמישי:"],[4,"ובמי שאין לו אלא חלוק אחד","דאין לו להחליף ומאי מפני כבוד השבת דאי לא מכבס השתא בחמישי תו לא מצי לכבס ליה:"],[4,"חולו של מועד","שאין לו אלא חלוק אחד דלא סגיא דלא מכבס מפני הכנימה ואפי' כיבס לפני המועד מותר לכבסה במועד:"],[5,"וגיהוץ שלנו","אינו יפה אלא ככיבוס שלהן ואסור לגהץ לפני תשעה באב אפילו להניח לאחר תשעה באב אבל כיבוס שלנו מותר:"],[6,"כלי פשתן אין בהן","ליאסר משום גיהוץ אלא בכלי מילת לושקי\"י בלע\"ז:"],[7,"לא שנו","שאסור ללובשו בשבוע שחל תשעה באב להיות בתוכה אלא בימים שלפני תשעה באב שאם חל ביום רביעי אסור ללובשו ראשון ושני ושלישי:"],[7,"אבל לאחריו","חמישי וששי ושביעי מותר:"],[7,"חל להיות באחד בשבת מותר לכבס כל השבת כולה","דהיינו לאחריו:"],[8,"","חל להיות בשני או בשלישי וברביעי ובחמישי כו':"],[8,"לייט עלה אביי ואיתימא רב אחא בר יעקב אהא","המכבס בתשעה באב אפילו מן המנחה ולמעלה ואדקאי בברייתא מפסיק לה למילתא וקאמר לייט עלה אביי כו':"],[9,"חל להיות בשני כו'","סיפא דההיא ברייתא גופה היא:"],[9,"ומפטיר","מאותן שלשה אחרון מפטיר מתוך שאין מוסיפין בחול יותר מג' אנשים ולא בר\"ח על ד' שאין לנו להוסיף אלא בשבת ובי\"ט כדמפרש במגילה (דף כא.) ולפיכך קורין ג' דזמן ספר תורה הוא ובלאו הכי הוו קרו שלשה שהוא מתקנת עזרא לקרות בשני ובחמישי כהן ולוי וישראל:"],[9,"קורא אחד ומפטיר אחד","אחד קורא והוא עצמו המפטיר קתני מיהת לאחריו מותר תיובתא דשמואל:"],[10,"וכן ערב תשעה באב שחל להיות בשבת","אינו מפסיק סעודתו ואינו ממעט בתבשילין אלא אוכל כל צרכו ומעלה על שולחנו אפי' כסעודת שלמה בשעתו דפלוגתא היא במסכת גיטין בפרק [מי שאחזו] (דף סח:) דאיכא למאן דאמר מלך והדיוט ומלך ואיכא למ\"ד מלך והדיוט כלומר כשנטרד שוב לא חזר למלכותו לפיכך הוצרך לומר בשעתו בשעת מלכו ותקפו שהיה אוכל הוא ושריו ס' כור סולת כו':"],[10,"ועד התענית","אלמא דסבירא ליה לרבי מאיר לפניו אסור לאחריו מותר ורבי יהודה ורבן (גמליאל) סבירא להו דאפילו לאחריו נמי אסור:"]],[[0,"","אמר רב פפא הלכך האי בר ישראל דאית ליה דינא בהדי נכרי לישתמיט וכו'. פירוש משום דאמר לעיל מגלגלין חובה ליום החייב:"],[1,"","של תפוחים. י\"מ תפוחים כריח אתרוגים:"],[2,"","קצרי דבי רב. פירוש כובסין הבגדים ולכך קרי להו קצרי על שם שמקצרין הבגדים ע\"י רחיצת המים:"],[4,"","מי שאין לו אלא חלוק אחד מותר לכבס במועד. (ובטבול יום) ובפ' אלו מגלחין (מו\"ק דף יד.) דקאמר וליטעמיך הא דאמר רבי אסי אמר רבי יוחנן מי שאין לו אלא חלוק אחד וכו' דפריך יאמרו כל החלוקים אסורים לכבס בחול המועד וחלוק זה מותר ומתרץ זה אזורו מוכיח עליו שאין לו אלא חלוק אחד וא\"כ דוקא להם אבל לנו ודאי אסור אפי' אין לנו אלא חלוק אחד שאין אנו אוגדין אזור על חלוקות שלנו ולא הוי אזורו מוכיח עליו וכן צריך ליזהר שלא לכבס המצנפת בחול המועד אע\"ג שאין לנו אלא אחת אבל מ\"מ יש לנשים לכבס בגדי התינוקות כדי לשכוב דהוי כמי שאין לו אלא חלוק אחד שיש רגילות להחליף בגדיהם וכל שעה צריך לו כל בגדיו ועל זה נהגו העולם לכבסם בחול המועד:"],[9,"","בשני ובחמישי קורין שלש ומפטיר אחד. מכאן מוכיח רבינו תם דמפטיר עולה למנין שבעה מדקאמר קורין שלש ומפטיר אחד שמפטיר אחד מן הג' דקא מיבעיא ליה במגילה (דף כג. ושם) מפטיר עולה למנין שבעה או לא משמע מהכא דעולה:"]]],[["מחגה ומ\"ד כל החדש כולו אסור מחדשה ומ\"ד כל השבת כולה אסור משבתה","אמר רבא הלכה כרשב\"ג ואמר רבא הלכה כרבי מאיר ותרוייהו לקולא וצריכא דאי אשמועינן הלכה כר' מאיר הוה אמינא אפי' מר\"ח קמ\"ל הלכה כרשב\"ג","ואי אשמועינן הלכה כרשב\"ג הוה אמינא אפילו לאחריו קמ\"ל הלכה כרבי מאיר:","ערב תשעה באב לא יאכל אדם ב' תבשילין כו': אמר רב יהודה לא שנו אלא משש שעות ולמעלה אבל משש שעות ולמטה מותר ואמר רב יהודה לא שנו אלא בסעודה המפסיק בה אבל בסעודה שאינו מפסיק בה מותר","ותרוייהו לקולא וצריכא דאי אשמעינן בסעודה המפסיק בה הוה אמינא אפי' משש שעות ולמטה קמ\"ל משש שעות ולמעלה ואי אשמעינן משש שעות ולמעלה הוה אמינא אפי' בסעודה שאינו מפסיק בה קמ\"ל בסעודה המפסיק בה","תניא כלישנא קמא תניא כלישנא בתרא תניא כלישנא בתרא הסועד ערב תשעה באב אם עתיד לסעוד סעודה אחרת מותר לאכול בשר ולשתות יין ואם לאו אסור לאכול בשר ולשתות יין","תניא כלישנא קמא ערב תשעה באב לא יאכל אדם שני תבשילין לא יאכל בשר ולא ישתה יין רבן שמעון בן גמליאל אומר ישנה אמר רבי יהודה כיצד משנה אם היה רגיל לאכול שני תבשילין יאכל מין אחד ואם היה רגיל לסעוד בעשרה בני אדם סועד בחמשה היה רגיל לשתות עשרה כוסות שותה חמשה כוסות במה דברים אמורים משש שעות ולמעלה אבל משש שעות ולמטה מותר","תניא אידך ערב תשעה באב לא יאכל אדם שני תבשילין לא יאכל בשר ולא ישתה יין דברי ר\"מ וחכ\"א ישנה וממעט בבשר וביין כיצד ממעט אם היה רגיל לאכול ליטרא בשר יאכל חצי ליטרא היה רגיל לשתות לוג יין ישתה חצי לוג יין ואם אינו רגיל כל עיקר אסור רשב\"ג אומר אם היה רגיל לאכול צנון או מליח אחר סעודתו הרשות בידו","תניא אידך כל שהוא משום תשעה באב אסור לאכול בשר ואסור לשתות יין ואסור לרחוץ כל שאינו משום ט\"ב מותר לאכול בשר ולשתות יין ואסור לרחוץ ר' ישמעאל בר' יוסי אומר משום אביו כל שעה שמותר לאכול בשר מותר לרחוץ","ת\"ר כל מצות הנוהגות באבל נוהגות בט' באב אסור באכילה ובשתיה ובסיכה ובנעילת הסנדל ובתשמיש המטה ואסור לקרות בתורה בנביאים ובכתובים ולשנות במשנה בתלמוד ובמדרש ובהלכות ובאגדות","אבל קורא הוא במקום שאינו רגיל לקרות ושונה במקום שאינו רגיל לשנות וקורא בקינות באיוב ובדברים הרעים שבירמיה ותינוקות של בית רבן בטלין משום שנאמר (תהלים יט, ט) פקודי ה' ישרים משמחי לב","ר' יהודה אומר אף אינו קורא במקום שאינו רגיל לקרות ואינו שונה במקום שאינו רגיל לשנות אבל קורא הוא באיוב ובקינות ובדברים הרעים שבירמיהו ותינוקות של בית רבן בטלים בו משום שנאמר פקודי ה' ישרים משמחי לב:","לא יאכל בשר ולא ישתה יין: תנא אבל אוכל הוא בשר מליח ושותה יין מגתו בשר מליח עד כמה אמר רב חיננא בר כהנא משמיה דשמואל כל זמן (שאינו) כשלמים","ויין מגתו עד כמה כל זמן שהוא תוסס תנא יין תוסס אין בו משום גילוי וכמה תסיסתו ג' ימים","אמר רב יהודה אמר רב כך היה מנהגו של רבי יהודה ברבי אילעאי ערב תשעה באב מביאין לו פת חריבה במלח ויושב"],[[0,"מחגה","כלומר יליף טעמא מן חגה דהיינו ר\"ח שנקרא חג כדאמרי' לעיל (תענית דף כט.) קרא עלי מועד:"],[1,"הלכה כר\"מ","דלפניו אסור ולאחריו מותר:"],[1,"הלכה כרבן שמעון בן גמליאל","דאין איסור נוהג אלא באותה שבת:"],[1,"תרוייהו לקולא","כדמפרש ואזיל דבלפניו מוקי הלכה כר\"מ דלפניו ולא לאחריו ובאותה שבת אבל קודם אותה שבת אפילו לפניו מותר:"],[3,"משש שעות ולמטה","כלפי השחר:"],[3,"המפסיק בה","דשוב אינו אוכל עוד מאותה סעודה ואילך:"],[6,"","ה\"ג כיצד ישנה א\"ר יהודה אם הוא רגיל כו':"],[6,"בעשרה","שהיו סועדין עמו לכבודו:"],[7,"וחכ\"א ישנה","אשני תבשילין קיימי בשר ויין ימעט:"],[7,"מליח","דג או בשר מליח דאין בו טעם כל כך אחר ששהה שלשה ימים במלח כדלקמן כשלמים והנותר מבשר זבח השלמים וגו' טפי לא אשכחן דמקרי בשר:"],[8,"כל שהוא משום ט' באב","כגון סעודה המפסיק בה:"],[8,"כל שאינו משום ט\"ב","כגון סעודה המפסיק בה בתענית צבור אי נמי סעודה שאינו מפסיק בה:"],[8,"ה\"ג ר' ישמעאל בר' יוסי אומר משום אביו כל שעה שמותר לאכול מותר לרחוץ","ולא גרסינן בשר כלומר אפילו בשעת סעודה המפסיק מותר לרחוץ הואיל ומותר לאכול:"],[9,"אסור באכילה ובשתיה","הני אין נוהגין באבל דקא חשיב נמי איסורים שנוהגין בו לבד מהני דנהיגי באבל רחיצה סיכה ונעילה כו':"],[9,"ואסור לקרות בתורה כו'","דכתיב בהו משמחי לב:"],[10,"במקום שאינו רגיל לקרות","דכיון דלא ידע אית ליה צערא:"],[12,"עד כמה","הוי בשר גמור דלא הוי בשר מליח כל זמן שהוא כשלמים שלא שהה במלחו אלא שני ימים ולילה אחד כזמן אכילת שלמים ולהכי נקט כשלמים דבזמן אכילת שלמים אשכחן דאקרי בשר דכתיב (ויקרא ז) והנותר מבשר זבח השלמים וגו' טפי לא אשכחן דמקרי בשר שהטעם נפסל אחרי ב' וג' ימים:"],[13,"יין מגתו","חדש ומתוק ואינו טוב כיין ישן ומשלשל ומזיק:"],[13,"תוסס","רותח:"],[13,"אין בו משום גילוי","שאין נחש שותהו כי יברח מרתיחתו:"]],[[1,"","ותרוייהו לקולא. כלומר תרוייהו כדר\"מ דאמר מר\"ח ועד התענית וכרשב\"ג דאמר אינו אסור אלא אותה שבת בלבד הלכה כתרוייהו לקולא כלומר דאינו אסור אלא אותה שבת בלבד כרשב\"ג ודוקא התענית אבל לאחר התענית מותר דהלכה כר\"מ דאמר דאינו אסור אלא עד התענית ואע\"ג דשלחו משמיה דר' יוחנן דכלי פשתן מותר לכבס במועד מ\"מ החמיר לנו מורינו רש\"י לתת סדינין שלנו לכובס אותה שבוע שהיה בה ט\"ב קודם התענית אבל היכא דחל ט\"ב בה' בשבת מותר לכבס ולספר מחצות ואילך מפני כבוד השבת דאין להמתין עד ערב שבת מפני טורח השבת:"],[3,"","ערב ט\"ב לא יאכל אדם ב' תבשילין. פירוש ב' תבשילין ר\"ל בשתי קדירות כגון שקורין העולם אכלנו ב' מינים שקורין מיישו\"ן אבל אין לאסור לאכול תבשיל שעושין מבצלים ומגבינה ומביצים דאע\"ג דאין רגילין העולם לאכול בצלים חיין כדאמר בעירובין (ד' כט.) אכל בצל והשכים ומת וכו' שקשין לכל גופו של אדם כחרבות אעפ\"כ מאחר שאין עושין מהם תבשיל בעצמו אם לא ישימו או שומן או שום דבר שנותן בהם טעם אינו קרוי תבשיל כדי לאסור הביצים שמשימין עמהם אבל מן גבינה המבושל בקדירה אין חששא לאכול דכל דבר שהוא נאכל כמו שהוא חי כמו חלב כמו גבינה כמו תפוחים אין בהם תורת בשול כלל וכלל:"],[6,"","ואם היה רגיל לסעוד בעשרה יסעוד בחמשה. צריך למעט בכבודו:"],[12,"","ואע\"ג דקאמר הש\"ס דבשר מליח מותר כל זמן שאינו כשלמים כלומר שעבר יותר מב' ימים משחיטתו אפ\"ה לדידן אסור לאכול בשר אפי' מלוח מזמן מרובה כיון דאנו רגילים לאכול בשר מליח וכן צריך למעט בשתייתו שאם היה רגיל לשתות עשרה כוסות משכר או ממשקה אחר לא ישתה כי אם חמשה וצריך לשנות מקומו שהוא רגיל לאכול בו כמו שהיה מנהגו של רבי יהודה בר' אילעאי שישב ואכל ערב ט\"ב בין תנור לכיריים מקום שהיה מנוול:"]]],[["בין תנור לכיריים ואוכל ושותה עליה קיתון של מים ודומה כמי שמתו מוטל לפניו","תנן התם מקום שנהגו לעשות מלאכה בט' באב עושין מקום שנהגו שלא לעשות אין עושין ובכל מקום ת\"ח בטלים רשב\"ג אומר לעולם יעשה כל אדם עצמו כתלמיד חכם תניא נמי הכי רשב\"ג אומר לעולם יעשה אדם עצמו כתלמיד חכם כדי שיתענה","תניא אידך רשב\"ג אומר כל האוכל ושותה בט' באב כאילו אוכל ושותה ביוה\"כ ר\"ע אומר כל העושה מלאכה בתשעה באב אינו רואה סימן ברכה לעולם","וחכ\"א כל העושה מלאכה בט' באב ואינו מתאבל על ירושלים אינו רואה בשמחתה שנא' (ישעיהו סו, י) שמחו את ירושלם וגילו בה כל אוהביה שישו אתה משוש כל המתאבלים עליה מכאן אמרו כל המתאבל על ירושלים זוכה ורואה בשמחתה ושאינו מתאבל על ירושלים אינו רואה בשמחתה תניא נמי הכי כל האוכל בשר ושותה יין בט' באב עליו הכתוב אומר (יחזקאל לב, כז) ותהי עונותם על עצמותם:","רבי יהודה מחייב בכפיית המטה ולא הודו לו חכמים: תניא אמרו לו לרבי יהודה לדבריך עוברות ומניקות מה תהא עליהן אמר להם אף אני לא אמרתי אלא ביכול","תניא נמי הכי מודה ר' יהודה לחכמים בשאינו יכול ומודים חכמים לרבי יהודה ביכול מאי בינייהו איכא בינייהו שאר מטות","כדתניא כשאמרו לכפות המטה לא מטתו בלבד הוא כופה אלא כל המטות כולן הוא כופה אמר רבא הלכתא כתנא דידן ולא הודו לו חכמים כל עיקר:","א\"ר שמעון ב\"ג לא היו ימים טובים לישראל כחמשה עשר באב וכיוה\"כ: בשלמא יום הכפורים משום דאית ביה סליחה ומחילה יום שניתנו בו לוחות האחרונות","אלא ט\"ו באב מאי היא אמר רב יהודה אמר שמואל יום שהותרו שבטים לבוא זה בזה","מאי דרוש (במדבר לו, ו) זה הדבר אשר צוה ה' לבנות צלפחד וגו' דבר זה לא יהא נוהג אלא בדור זה","אמר רב יוסף אמר רב נחמן יום שהותר שבט בנימן לבוא בקהל שנאמר (שופטים כא, א) ואיש ישראל נשבע במצפה לאמר איש ממנו לא יתן בתו לבנימן לאשה מאי דרוש אמר רב ממנו ולא מבנינו","(אמר) רבה בר בר חנה א\"ר יוחנן יום שכלו בו מתי מדבר דאמר מר עד שלא כלו מתי מדבר לא היה דבור עם משה שנאמר (דברים ב, טז) ויהי כאשר תמו כל אנשי המלחמה למות וידבר ה' אלי אלי היה הדבור","עולא אמר יום שביטל הושע בן אלה פרוסדיות שהושיב ירבעם בן נבט על הדרכים שלא יעלו ישראל לרגל ואמר"],[[0,"בין תנור לכיריים","מקום מנוול שבבית:"],[2,"אינו רואה סימן ברכה","מאותה מלאכה:"],[3,"כל האוכל בשר ושותה יין בתשעה באב עליו הכתוב אומר ותהי עונותם על עצמותם","בתשעה באב כלומר בסעודה המפסיק בה:"],[4,"עוברות ומניקות","שאינן יכולות לישן על גבי קרקע:"],[4,"ביכול","שאפשר לו:"],[5,"מאי בינייהו","כיון דזה מודה לו ביכול וזה מודה לו בשאינו יכול:"],[5,"שאר מטות","שבבית שאינו שוכב בהן ר' יהודה דמחייב במתני' בכפיית המטה קמחייב נמי ביכול בשאר מטות ורבנן סברי מטתו כופה ולא שאר מטות וכדתניא גבי אבל:"],[7,"שניתנו בו לוחות אחרונות","שבי\"ז בתמוז ירד משה מן ההר תחלה ושיבר את הלוחות ובי\"ח טחן את העגל ודן את הפושעים ועלה למרום נשתהה שם שמונים יום ארבעים יום עמד בתפלה דכתיב (דברים ט׳:ט׳) ואתנפל לפני ה' ארבעים יום וארבעים לילה וארבעים יום עמד כבראשונה חשוב מי\"ז בתמוז עד יום הכפורים והוו להו שמונים יום שנים עשרה שנשתיירו מתמוז דהוא חסר ושלשים דאב ותשעה ועשרים דאלול הרי אחד ושבעים ותשעה דתשרי הרי שמונים יום וליל צום השלים כנגד לילו של י\"ז תמוז דלא הוה בחושבניה דהא נפק ליה כבר בשעה שעלה השתא הוי להו פ' שלמין לילה ויום ובוקר יום כפור ירד שהוא עשרה בתשרי ואותו היום נקבע ליום כפור להודיע שמחל וניחם על הרעה אשר דבר לעשות לעמו ועל כן נקבע צום כפור בעשרה בתשרי כך שמעתי:"],[8,"שהותרו שבטים לבא זה בזה","דרחמנא אמר וכל בת יורשת נחלה וגו' (במדבר ל״ו:ט׳) וכתיב (שם) ולא תסוב נחלה ממטה למטה אחר כי איש בנחלתו ידבקו בני ישראל ועמדו והתירו דבר זה בחמשה עשר באב:"],[9,"זה הדבר אשר צוה ה' לבנות צלפחד וגו'","זה מיעוט הוא כלו' לא יהיה דבר זה נוהג אלא בדור זה בדור של בנות צלפחד:"],[10,"לבא בקהל","לישא נשים לפי שנשבעו ישראל מלהינשא להם כדכתיב בשופטים (כא):"],[10,"ממנו","מיעוט הוא דכתיב איש ממנו לא יתן בתו לבנימין לא גזרו אלא מהם (ממנו) אבל מבניהם לא גזרו:"],[11,"שכלו מתי מדבר","דתניא כל ארבעים שנה שהיו במדבר בכל ערב תשעה באב היה הכרוז יוצא ואומר צאו לחפור והיה כל אחד ואחד יוצא וחופר לו קבר וישן בו שמא ימות קודם שיחפור ולמחר הכרוז יוצא וקורא יבדלו חיים מן המתים וכל שהיה בו נפש חיים היה עומד ויוצא וכל שנה היו עושין כן ובשנת ארבעים שנה עשו ולמחר עמדו כולן חיים וכיון שראו כך תמהו ואמרו שמא טעינו בחשבון החדש חזרו ושכבו בקבריהן בלילות עד ליל חמשה עשר וכיון שראו שנתמלאה הלבנה בט\"ו ולא מת אחד מהם ידעו שחשבון חדש מכוון וכבר מ' שנה של גזרה נשלמו קבעו אותו הדור לאותו היום יו\"ט:"],[11,"דאמר מר כו'","לפיכך יו\"ט הוא:"],[11,"לא היה הדבור עם משה","ביחוד וחיבה דכתיב וידבר ה' אלי לאמר אלי נתייחד הדיבור ואע\"ג דמקמי הכי כתיבי קראי בהו וידבר איכא דאמרי לא היה פה אל פה אלא בחזיון לילה גמגום:"]],[[2,"","כל העושה מלאכה בתשעה באב אינו רואה סימן ברכה לעולם. כלומר באותה מלאכה שרגיל לעשות בתשעה באב אינו רואה סימן ברכה לעולם וחייב אדם לצער ולמעט בכבודו ובהנאותיו שאם היה רגיל לשכב על שני כרים לא ישכב כי אם על אחד אבל עוברות ומניקות אינן חייבות כולי האי שאינם יכולות להצטער בעצמן ואוכלין סעודה המפסקת מבעוד יום וכן נמי ביום הכפורים (נמי) צריך לסעוד מבע\"י דתוספת יום הכפורים מן התורה כדכתיב (ויקרא כ״ג:כ״א) מערב ועד ערב וכתיב בעצם היום הזה (שם) אבל מכל מקום אין לאסור לשתות משאכל סעודה מפסקת ועדיין הוי היום גדול כדמשמע בירושלמי דר' יוסי איקלע לבצרה אכל סעודה מפסקת אתא לגבי דריש כנישתא והוה סעיד אמר ליה ההוא ריש כנישתא סעוד אצלי אמר ליה אכלית ואפסקית אמר לו אשגח עלי דלא לימרון הדין גברא לא אשגח עליה אכל מכל עיגול פתית ואכל מכל תבשיל ותבשיל חד פת ושתה מכל חבית חד כסא והכי הלכתא אם עדיין היום גדול לאחר שאכל סעודה המפסקת מותר לשתות אפילו ערב יוה\"כ וכל שכן ערב תשעה באב:"],[6,"","אמר רבא הלכה כתנא דידן ולא הודו לו חכמים. פירוש שאין צריך לכפות המטה והאידנא דחיישינן לכשפים לא עבדינן כפיית המטה ואפילו באבל:"],[8,"","יום שהותרו השבטים לבא זה בזה. פירוש דהיינו י\"ט:"],[11,"","יום שבו כלו מתי מדבר. כדאמרי' (במדרש איכה) כל ט' באב היו עושין קבריהן ושוכבין בתוכן ולמחר הכרוז יוצא הבדלו החיים ואותה השנה שכלתה הגזרה קמו כולם והיו סבורים שמא טעו בחודש עד שראו הלבנה מלאה ואז ידעו שכלתה הגזרה ועשו יו\"ט ופרשב\"ם (בב\"ב דף קכא.) כל המ' שנים לא היו מתים אלא בט' באב ובכל ט' באב היו מתים כ\"א אלף ופרוטרוט ומפרש התם דאותו פרוטרוט עולה למ' שנים ט\"ו אלף וי\"מ שהיו מתים בכל יום אך רוב המתים היו לעולם בתשעה באב ובחמשה עשר באב פסקה הגזרה ולא מתו כלל ועשו י\"ט:"]]],[["לאיזה שירצו יעלו","רב מתנה אמר יום שנתנו הרוגי ביתר לקבורה ואמר רב מתנה אותו יום שנתנו הרוגי ביתר לקבורה תקנו ביבנה הטוב והמטיב הטוב שלא הסריחו והמטיב שנתנו לקבורה","רבה ורב יוסף דאמרי תרוייהו יום שפסקו מלכרות עצים למערכה (תניא) רבי אליעזר הגדול אומר מחמשה עשר באב ואילך תשש כחה של חמה ולא היו כורתין עצים למערכה לפי שאינן יבשין","אמר רב מנשיא וקרו ליה יום תבר מגל מכאן ואילך דמוסיף יוסיף ודלא מוסיף (יאסף) (תני רב יוסף) מאי יאסף אמר רב יוסף תקבריה אימיה:","שבהן בנות ירושלים כו': ת\"ר בת מלך שואלת מבת כהן גדול בת כהן גדול מבת סגן ובת סגן מבת משוח מלחמה ובת משוח מלחמה מבת כהן הדיוט וכל ישראל שואלין זה מזה כדי שלא יתבייש את מי שאין לו:","כל הכלים טעונין טבילה אמר רבי אלעזר אפילו מקופלין ומונחין בקופסא:","בנות ישראל יוצאות וחולות בכרמים תנא מי שאין לו אשה נפנה לשם:","מיוחסות שבהן היו אומרות בחור וכו': תנו רבנן יפיפיות שבהן מה היו אומרות תנו עיניכם ליופי שאין האשה אלא ליופי מיוחסות שבהן מה היו אומרות תנו עיניכם למשפחה לפי שאין האשה אלא לבנים מכוערות שבהם מה היו אומרות קחו מקחכם לשום שמים ובלבד שתעטרונו בזהובים","אמר עולא ביראה אמר רבי אלעזר עתיד הקדוש ברוך הוא לעשות מחול לצדיקים והוא יושב ביניהם בגן עדן וכל אחד ואחד מראה באצבעו שנאמ' (ישעיהו כה, ט) ואמר ביום ההוא הנה אלהינו זה קוינו לו ויושיענו זה ה' קוינו לו נגילה ונשמחה בישועתו:","\u0001הדרן עלך בשלשה פרקים וסליקא לה מסכת תענית\u0002"],[[0,"לאיזה שירצה יעלו","הושע בן אלה רשע היה דכתיב (מלכים ב י״ז:ב׳) ויעש הרע בעיני ה' רק לא כמלכי ישראל והיינו דקאמר רק שבטל את הפרוסדאות ואמר לאיזה שירצו יעלו:"],[1,"הרוגי ביתר","בפרק הניזקין (גיטין דף נז.):"],[2,"מלכרות","לפי שהן לחין ומאותו הזמן אין כח בחמה לייבשן וחיישינן מפני התולעת לפי שעץ שיש בו תולעת פסול למערכה כדאמרינן (מדות פרק ב' משנה ה'):"],[3,"יום תבר מגל","שבירת הגרזן שפסק החוטב מלחטוב עצים:"],[3,"מכאן ואילך","מחמשה עשר באב ואילך דמוסיף לילות על הימים לעסוק בתורה יוסיף חיים על חייו:"],[3,"דלא יוסיף","לעסוק בתורה בלילות:"],[3,"תקבריה אימיה","כלומר ימות בלא עתו:"],[4,"בת מלך","אף על פי שהיה לה שואלת מבת כהן גדול כו' שלא לבייש את השואלת מתוך שאין לה:"],[4,"מבת כהן גדול","שהוא קרוב וסמוך למלכות:"],[4,"סגן","כהן חשוב ממונה תחת כהן גדול להיות תחתיו ביום הכפורים אם יארע פסול בכהן גדול ביום הכפורים ישמש זה הסגן תחתיו:"],[4,"משוח מלחמה","הוא הכהן המכריז במלחמה מי האיש הירא ורך הלבב וגו' (דברים כ׳:ח׳):"],[5,"צריכין טבילה","כולן שלא לבייש את שצריכה טבילה:"],[5,"אפילו מקופלין ומונחין בקופס'","אישקוריי\"ן:"],[7,"שאין אשה אלא לבנים","אם בניך יהיו מיוחסין הכל קופצין עליהם בין זכרים בין נקבות:"],[7,"על מנת שתעטרונו בזהובים","שאחרי הנישואין תתנו לנו תכשיטין ומילתא בעלמא הוא דאמרי כלומר ובלבד שתתנו לנו מלבושים נאים:"],[8,"מחול","סביב לשון מחול הכרם (כלאים פרק רביעי משנה א'):"],[8,"מראה באצבעו","ואומר זה ה' קוינו לו ויושיענו זה ה' קוינו לו נגילה ונשמחה בישועתו:"]],[[1,"","תיקנו ביבנה הטוב והמטיב. פירוש בברכת המזון ומש\"ה תקנו יותר על היין הטוב והמטיב טפי מבשאר דברים לפי שהיו [כמו] גדר בכרם ולא נסרחו:"],[3,"","יום תבר מגל. פירוש שמונעין מלכרות עצים למערכה פירוש משום שחלש כחה של חמה ומגדלין התולעים באילנות ועצים מתולעים פסולים למערכה כדאמר [במדות] (פ\"ב מ\"ה) שהכהנים בעלי מומין הם מנקרים העצים ומסירין העצים מתולעים שפסולות למערכה:"],[3,"","דלא מוסיף יאסף. פי' אותו שאינו מוסיף מן הלילות על הימים יאסף:"],[3,"","מאי יאסף תקבריה אימיה. תימה וכי היה מסופק מאי יאסף אלא נראה לומר דלא מוסיף יסיף ומיהא קבעי גמרא מאי יסיף אבל לעולם הוה ידע דיאסף הוא לשון מיתה כדכתיב (בראשית מ״ט:ל״ג) ויגוע ויאסף אל עמיו:"],[8,"","כל אחד ואחד מראה הקדוש ברוך הוא באצבעו שנאמר הנה אלהינו זה קוינו לו וגו' נגילה ונשמחה בישועתו:"]]]]};
